window.__SUM[5]={"LR003642":{"pair":"a -> Mc5r","headline":"Agouti/ASIP weakly inhibits MC5R in one human recombinant study; the mouse pair is projected.","interaction_type":"functional only","direction_and_effect":"Recombinant ASIP has relatively weak effects at hMC5R, with surmountable inhibition of alpha-MSH-stimulated cAMP, and inhibited radiolabeled melanocortin binding to hMCR1-5 [PMID:9058374].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ASIP and human receptor in stably transfected L cells; the dossier pair is mouse and ortholog-inferred [PMID:9058374].","localisation_and_range":"Agouti is flagged secreted [flag].","caveats":"One paper, abstract only; no mouse experiment. Effect is weak.","key_references":[{"PMID":"9058374","why":"ASIP pharmacology at hMC5R"}],"covers":["LR003642"]},"LR003552":{"pair":"ACE -> BDKRB2","headline":"ACE and the B2 bradykinin receptor co-immunoprecipitate in CHO cells; this is a membrane complex, not shown to be agonist-receptor signalling.","interaction_type":"conflicting","direction_and_effect":"ACE is not shown to activate B2. ACE inhibitors resensitised B2 desensitised by bradykinin only when ACE (wild-type or cytoplasm-deleted) was co-expressed; GPI-anchored ACE did not allow resensitisation [PMID:10748135].","molecular_requirements":"Resensitisation needs enzyme and receptor close together on the membrane, and was lost when GPI-ACE was sequestered in cholesterol-rich domains; filipin restored it [PMID:10748135].","affinity_potency":[],"species_and_systems":"Human receptor and ACE expressed in Chinese hamster ovary cells [PMID:10748135].","localisation_and_range":"ACE is flagged secreted and BDKRB2 receptor/transmembrane [flag]; the paper places the interaction on the cell membrane [PMID:10748135].","caveats":"The abstract says co-IP 'suggesting an interaction', and a bridging partner cannot be excluded; one paper, abstract only. BioGRID lists affinity capture-western and FRET records from a different paper [DB:BioGRID].","key_references":[{"PMID":"10748135","why":"ACE/B2 co-IP and membrane-domain dependence of ACE-inhibitor action"}],"covers":["LR000002","LR003552"]},"LR003561":{"pair":"ADAM15 -> ITGB3","headline":"Integrin beta3 appears as the partner of alphav in ADAM15 binding in two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"D-15 specifically interacts with alphavbeta3 [PMID:9516430]; metargidin functions as a cell adhesion molecule via alphavbeta3 and alpha5beta1 [PMID:9914169].","molecular_requirements":"Chain-only evidence: the receptor is the alphavbeta3 heterodimer; changing the RGD flanking sequence also permits alphaIIbbeta3 binding [PMID:9516430].","affinity_potency":[],"species_and_systems":"Bacterially expressed D-15 on cells with recombinant integrins [PMID:9516430]; ADAM15-Fc with human cell lines and purified integrins [PMID:9914169].","localisation_and_range":"ADAM15 flagged not secreted [flag].","caveats":"Abstract only. IntAct lists an ELISA record [DB:IntAct]. One further judged row was abstract-insufficient.","key_references":[{"PMID":"9516430","why":"D-15 binds alphavbeta3 specifically"},{"PMID":"9914169","why":"ADAM15-alphavbeta3 adhesion on U937 cells"}],"covers":["LR000011","LR003561"]},"LR002067":{"pair":"ADAM17 -> IL1R2","headline":"ADAM17 recognises IL-1RII through its extracellular domains; this is a protease-substrate interaction, from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Deletion variants showed that only the extracellular domains of ADAM17 are needed for interaction with the substrates IL-6R and IL-1RII; the membrane-proximal domain is mandatory for recognition of these type-I transmembrane proteins [PMID:22575642].","molecular_requirements":"The membrane-proximal domain of ADAM17 is required; transmembrane and cytoplasmic regions are dispensable [PMID:22575642].","affinity_potency":[],"species_and_systems":"Cell assays with tagged ADAM17 deletion variants; species not reported in our evidence [PMID:22575642].","localisation_and_range":"Both are membrane proteins; ADAM17 flagged not secreted [flag].","caveats":"One paper, abstract only; affinity not reported. Evidence is of substrate recognition, not signalling.","key_references":[{"PMID":"22575642","why":"ADAM17 membrane-proximal domain recognises IL-1RII"}],"covers":["LR002067","LR005393"]},"LR003570":{"pair":"ADAM2 -> ITGB7","headline":"ITGB7 is the beta subunit mediating RPMI 8866 cell adhesion to ADAM2 in human cell-line assays; full text read.","interaction_type":"direct binding","direction_and_effect":"ITGB7 siRNA knockdown reduced RPMI 8866 adhesion to ADAM2 to baseline, and an anti-ITGB7 antibody inhibited adhesion by 86% [PMID:21060781]. Curator label: agonist.","molecular_requirements":"ITGB7 pairs with ITGA9 (novel ITGA9-ITGB7) and ITGA4 in these cells; combined anti-ITGA9 plus anti-ITGA4 inhibited 88% [PMID:21060781].","affinity_potency":[],"species_and_systems":"Human RPMI 8866 cells, recombinant ADAM2 at 50 \u00b5g/ml; ITGB7 mRNA reduced to an average of 23% by siRNA [PMID:21060781].","localisation_and_range":"ADAM2 flagged non-secreted [flag]; adhesion to immobilised ADAM2.","caveats":"Adhesion assays, not purified binding. ITGB7 not detected in mouse oocytes by RT-PCR [PMID:21060781], so relevance to mouse eggs is unsupported; the mouse pair is ortholog-inferred.","key_references":[{"PMID":"21060781","why":"ITGB7 mediates adhesion to ADAM2"}],"covers":["LR000020","LR003570"]},"LR008205":{"pair":"ADAM28 -> ITGA4:ITGB1","headline":"Alpha4beta1 recognises the ADAM28 disintegrin domain in adhesion and soluble binding by human cells; abstract only.","interaction_type":"direct binding","direction_and_effect":"The disintegrin domain of MDC-L (ADAM 28) is recognised by alpha4beta1; Fc fusion supports concentration- and cation-dependent Jurkat adhesion [PMID:11724793].","molecular_requirements":"Both subunits are needed in the tested setting: anti-alpha4 and anti-beta1 each inhibit, and alpha4beta1 transfectants adhere [PMID:11724793].","affinity_potency":[],"species_and_systems":"Human; Jurkat and K562 alpha4beta1 transfectants [PMID:11724793].","localisation_and_range":"ADAM28 flagged secreted [flag]; paper reports it on the lymphocyte surface [PMID:11724793].","caveats":"Abstract read only; the soluble binding result is truncated in our abstract, so no affinity is reported.","key_references":[{"PMID":"11724793","why":"alpha4beta1 recognises ADAM28 disintegrin"}],"covers":["LR008205"]},"LR005019":{"pair":"ADAM7 -> ITGB7","headline":"ADAM7 disintegrin domain is recognised by alpha4beta7 in cell-adhesion assays; abstract only.","interaction_type":"functional only","direction_and_effect":"Alpha4beta7 recognises the disintegrin domains of ADAM7 and ADAM28 but not ADAM33; the authors say this is the first demonstration of a mammalian disintegrin interacting with alpha4beta7 [PMID:15504110].","molecular_requirements":"Beta7 acts as alpha4beta7; recognition is activation-dependent, needing Mn2+ or an activating monoclonal antibody [PMID:15504110].","affinity_potency":[],"species_and_systems":"Human ADAM disintegrin-like domains in cell-adhesion assays [PMID:15504110]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM7 is flagged secreted [flag]; adhesion to immobilised domain.","caveats":"Abstract read only; adhesion assay rather than purified binding.","key_references":[{"PMID":"15504110","why":"Alpha4beta7 recognises ADAM7 disintegrin domain"}],"covers":["LR001631","LR005019"]},"LR002076":{"pair":"ADAMTS13 -> CD163","headline":"ADAMTS13 binds CD163 SRCR domains by SPR and CD163 mediates its macrophage uptake; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance showed ADAMTS13 binding to CD163 scavenger receptor cysteine-rich domains 1-9 and 1-5; anti-CD163 antibody EDHu-1 decreased ADAMTS13 internalisation by macrophages, and CD163-expressing CHO cells rapidly internalised it, so CD163 acts as an endocytic clearance receptor [PMID:29296945].","molecular_requirements":"SRCR domains 1-5 are sufficient for binding in SPR [PMID:29296945]. Uptake was not blocked by an antibody to the mannose receptor CD206 [PMID:29296945].","affinity_potency":[],"species_and_systems":"Human monocyte-derived macrophages, CHO cells expressing CD163, recombinant proteins [PMID:29296945].","localisation_and_range":"Ligand flagged secreted [flag]; CD163 is on macrophages, with uptake from the circulation [PMID:29296945].","caveats":"Abstract-only read; no Kd reported in our evidence. Inhibition by antibody was partial and strongest in CD163-high macrophages [PMID:29296945]. No database support.","key_references":[{"PMID":"29296945","why":"SPR binding and macrophage uptake via CD163"}],"covers":["LR002076","LR005402"]},"LR001635":{"pair":"ADGRE5 -> CD55","headline":"CD97 (ADGRE5) binds CD55 directly: binding, structural and in vivo functional evidence from three papers (abstract only).","interaction_type":"direct binding","direction_and_effect":"CD97 binds CD55 [PMID:11297558]. Blocking the CD55 (monocyte)-CD97 (T cell) interaction inhibited T cell proliferation and interferon-gamma secretion, suggesting bidirectional interaction [PMID:17449467]. In mice, contact with CD55 downregulated CD97 on circulating leukocytes under shear stress, without evidence of receptor signalling [PMID:23447688].","molecular_requirements":"Binding is mediated solely by the CD97 EGF and CD55 SCR domains; Ca(2+)-dependent [PMID:11297558]. The key leukocyte isoform of CD97 binds CD55 [PMID:17449467]. A model of the complex was built from EMR2 (a CD97 homolog) data [PMID:17449467].","affinity_potency":[{"value":"KD 86 microm (low affinity, rapid off-rate)","assay":"binding analysis of CD97-CD55","system":"CD97 and CD55 modular domains","cite":"PMID:11297558"}],"species_and_systems":"Human proteins and cells [PMID:11297558][PMID:17449467]; CD55-deficient mouse leukocytes in vivo [PMID:23447688]. Database records: IntAct, PDB 7DO4, Reactome, UniProt [DB:IntAct][DB:PDB 7DO4][DB:Reactome][DB:UniProt].","localisation_and_range":"Both partners are cell-surface proteins [flag]; interaction is cell-cell (juxtacrine) in the papers [PMID:17449467].","caveats":"All papers read as abstracts only. Affinity is low. The structural model rests on the homolog EMR2, not CD97 itself [PMID:17449467].","key_references":[{"PMID":"11297558","why":"domain dissection and affinity"},{"PMID":"17449467","why":"structure and T cell function"},{"PMID":"23447688","why":"in vivo CD97 downregulation by CD55"}],"covers":["LR001635","LR005023"]},"LR008601":{"pair":"ADGRE5 -> LPAR1","headline":"Supported only by one IntAct co-immunoprecipitation record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Anti-tag co-immunoprecipitation record only; species not stated [DB:IntAct].","localisation_and_range":"LPAR1 is annotated transmembrane and not secreted [flag].","caveats":"Rests solely on one IntAct association record [DB:IntAct]; the curation outcome is still pending. Co-immunoprecipitation does not show a ligand-receptor relationship.","key_references":[],"covers":["LR008601"]},"LR005406":{"pair":"ADGRL1 -> NRXN1","headline":"Latrophilin-1 ectodomain binds neurexins with nanomolar affinity; evidence is one abstract-only paper that covers neurexins as a group.","interaction_type":"direct binding","direction_and_effect":"Direct binding between the extracellular domains of latrophilin-1 (CL1) and neurexins; CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing both formed stable adhesion, so trans-cellular [PMID:22262843].","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1; those with an SS4 insert do not. The olfactomedin-like domain of CL1 mediates binding [PMID:22262843].","affinity_potency":[{"value":"nanomolar affinity (value not given)","assay":"saturation binding","system":"purified ectodomains","cite":"PMID:22262843"}],"species_and_systems":"Purified ectodomains and cell adhesion assays; species not stated beyond curator label human [PMID:22262843]. Pair is ortholog-inferred in both species.","localisation_and_range":"Both partners are membrane proteins [flag]; interaction is trans-cellular, suggesting juxtacrine signalling [PMID:22262843].","caveats":"Abstract only, and the abstract speaks of neurexins generally, so isoform specificity for NRXN1 is not shown in our evidence. Only the SS4-minus form binds [PMID:22262843]. Ligand-receptor direction is not defined, as both are membrane proteins.","key_references":[{"PMID":"22262843","why":"identifies latrophilin-1/neurexin binding"}],"covers":["LR002080","LR005406"]},"LR002085":{"pair":"ADIPOQ -> CDH13","headline":"T-cadherin was expression-cloned as a receptor for hexameric and HMW adiponectin (one abstract-only paper).","interaction_type":"direct binding","direction_and_effect":"T-cadherin is a receptor for hexameric and high-molecular-weight adiponectin but not trimeric or globular species [PMID:15210937]. A signalling effect is not shown; the authors suggest a coreceptor role [PMID:15210937].","molecular_requirements":"Only eukaryotically expressed adiponectin bound; a mutant lacking the N-terminal cysteine needed for hexamer/HMW formation did not bind T-cadherin in co-immunoprecipitation [PMID:15210937]. T-cadherin may need an unidentified signalling receptor [PMID:15210937].","affinity_potency":[],"species_and_systems":"Cloning by panning a C2C12 myoblast cDNA library in Ba/F3 cells with recombinant adiponectin [PMID:15210937]; curator labels species human, which the abstract does not support.","localisation_and_range":"Adiponectin flagged secreted [flag]; T-cadherin is a GPI-anchored extracellular protein [PMID:15210937].","caveats":"Abstract only; no affinity reported. Form-specific: trimeric and globular adiponectin are not bound [PMID:15210937].","key_references":[{"PMID":"15210937","why":"expression cloning of T-cadherin"}],"covers":["LR002085","LR005411"]},"LR005415":{"pair":"AGGF1 -> ITGB1","headline":"Same paper as the ITGA5 pair: AGGF1 acts through integrin alpha5beta1, where beta1 is the partner chain; antibody and pull-down evidence in endothelial cells.","interaction_type":"functional only","direction_and_effect":"Neutralising antibodies identified alpha5beta1 as the AGGF1 receptor on ECs; AGGF1 activates FAK, Src and AKT [PMID:34551592].","molecular_requirements":"Two different anti-beta1 antibodies and an anti-alpha5beta1 antibody disrupted HUVEC binding to AGGF1; the angiogenic-domain deletion mutant failed to precipitate integrin alpha5 and beta1 [PMID:34551592]. Beta1 needs alpha5 in this evidence; CCC scoring should use the pair.","affinity_potency":[{"value":"T1/2 18.7 nM","assay":"half-maximum binding concentration, cell adhesion assay (not a Kd)","system":"HUVEC","cite":"PMID:34551592"}],"species_and_systems":"Human HUVEC, also mouse aortic endothelial cells and a mouse peripheral-artery-disease model [PMID:34551592]. The mouse pair is projected from human.","localisation_and_range":"AGGF1 is flagged secreted [flag]; ITGB1 is flagged not secreted and receptor [flag].","caveats":"One paper. Pull-down in the excerpts shows integrin alpha5 from HUVEC extract; beta1 evidence is antibodies and domain-deletion pull-down. Not purified-protein binding.","key_references":[{"PMID":"34551592","why":"alpha5beta1 as AGGF1 receptor in endothelial cells"}],"covers":["LR002089","LR005415"]},"LR002094":{"pair":"AGRN -> PTPRS","headline":"Agrin binds chicken PTPsigma with high affinity in vitro through its heparan sulfate chains; evidence is avian and glycan-dependent.","interaction_type":"direct binding","direction_and_effect":"Agrin and collagen XVIII were identified as basal lamina ligands of cPTPsigma, interacting with high affinity in vitro [PMID:11865065]. Reactome lists an AGRN:NCAM1, PTPRS complex [DB:Reactome].","molecular_requirements":"The binding is totally dependent on agrin's heparan sulfate chains, and a heparin/heparan sulfate binding site maps to the first immunoglobulin-like domain of cPTPsigma [PMID:11865065].","affinity_potency":[],"species_and_systems":"Chicken protein (cPTPsigma / CRYPalpha) only; no human or mouse experiments in our evidence [PMID:11865065].","localisation_and_range":"Basal lamina (matrix) ligand [PMID:11865065]; PTPRS is flagged secreted and transmembrane [flag].","caveats":"Abstract-only. Because binding is glycan-dependent, other heparan sulfate proteoglycans bind too (collagen XVIII shown), so it is not protein-specific. The affinity is called 'high' but no value is given. Human or mouse relevance is ortholog-inferred.","key_references":[{"PMID":"11865065","why":"In vitro high-affinity, heparan sulfate-dependent binding of agrin to chicken PTPsigma"}],"covers":["LR002094","LR005420"]},"LR005424":{"pair":"ALB -> FCGRT","headline":"Albumin binds FcRn directly with 1:1 stoichiometry and strong pH dependence; supported by one binding paper and structural database records.","interaction_type":"direct binding","direction_and_effect":"FcRn binds and protects albumin, returning it to the extracellular compartment; binding is high affinity at low pH in the acid endosome and weaker at neutral pH [PMID:16605266]. Complex structures are deposited [DB:PDB 4N0F].","molecular_requirements":"Albumin and IgG bind noncooperatively to distinct sites on FcRn; ITC shows 1:1 stoichiometry [PMID:16605266].","affinity_potency":[{"value":"~200-fold lower affinity at neutral than acidic pH","assay":"surface plasmon resonance","system":"human FcRn and albumin (per curator)","cite":"PMID:16605266"}],"species_and_systems":"Curator records human protein and human receptor; recombinant binding assays [PMID:16605266].","localisation_and_range":"Acts in the acidic endosome; FCGRT flagged receptor [flag].","caveats":"Absolute Kd not reported in our evidence. Paper read as abstract only. Mouse pair is ortholog-inferred. FcRn-albumin kinetics are rapid [PMID:16605266].","key_references":[{"PMID":"16605266","why":"SPR and ITC of albumin-FcRn binding and pH dependence"}],"covers":["LR002098","LR005424"]},"LR005028":{"pair":"ALCAM -> CD6","headline":"CD6 and ALCAM engagement is needed for T cell-APC contact and proliferation; binding assays appear in databases.","interaction_type":"functional only","direction_and_effect":"ALCAM-blocking antibodies interfered with DC-T cell conjugate formation, and CD6-blocking antibodies or recombinant ALCAM-Fc inhibited T cell proliferation. CD6 and CD3 crosslinking drove proliferation comparable to CD3/CD28, so CD6 is described as costimulatory [PMID:16352806].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human DC and T cells [PMID:16352806]. Databases list ELISA, light scattering, competition binding and solid phase assays [DB:IntAct] and a reconstituted complex [DB:BioGRID 279128].","localisation_and_range":"Both are membrane proteins acting at the DC-T cell contact zone (juxtacrine); the paper reports stable binding unlike transient ALCAM homophilic contact [PMID:16352806].","caveats":"Verified paper is functional, abstract only; physical binding rests on database records. No affinity in this dossier.","key_references":[{"PMID":"16352806","why":"ALCAM-CD6 needed for DC-T cell contact and proliferation"}],"covers":["LR001640","LR005028"]},"LR001644":{"pair":"ALKAL1 -> ALK","headline":"ALKAL1 is a weak, not potent, ligand of ALK; sources agree it prefers LTK, but one paper shows some ALK activity.","interaction_type":"conflicting","direction_and_effect":"AUG-beta (ALKAL1) is described as LTK-specific and only weakly binding ALK [PMID:26630010]. The 2021 structural study says both ALKAL1 and ALKAL2 strongly activate LTK, but only ALKAL2 potently activates ALK [PMID:34646012]. UniProt states ALKAL1 is not a potent physiological ALK ligand [DB:UniProt].","molecular_requirements":"ALKTG-EGFL-ALKAL1 and ALKAL2 complexes show 1:1 stoichiometry [PMID:34646012]. Charge-reversal mutations in the cytokines lowered affinity for both receptors [PMID:34646012].","affinity_potency":[],"species_and_systems":"Cells expressing ALK or LTK [PMID:26630010]; purified human ALK and cell proliferation assays [PMID:34646012]. IntAct lists co-IP [DB:IntAct Q6UXT8-Q9UM73].","localisation_and_range":"ALKAL1 flagged secreted, ALK transmembrane [flag].","caveats":"The same structural paper reports the conserved C-terminal domains of ALKAL1 and ALKAL2 and full-length ALKAL1 could drive ALK-dependent proliferation [PMID:34646012], so weak activity is not absence. No affinity numbers in our evidence. PMID:26630010 read as abstract only.","key_references":[{"PMID":"26630010","why":"Hierarchy of ALKAL1/ALKAL2 at ALK and LTK"},{"PMID":"34646012","why":"Structures; only ALKAL2 potently activates ALK"}],"covers":["LR001644","LR005032"]},"LR005037":{"pair":"AMELX -> CD63","headline":"Amelogenin interacts with CD63; supported by abstract-level mapping data from one paper.","interaction_type":"direct binding","direction_and_effect":"Amelogenin interacts with CD63 and LAMP1 and moves into CD63/LAMP1-positive vesicles after addition to cultured cells [PMID:17708745]. Effect direction: not reported in our evidence.","molecular_requirements":"The amelogenin region PLSPILPELPLEAW engages CD63 residues 165-205 [PMID:17708745].","affinity_potency":[],"species_and_systems":"Curators recorded human ligand and receptor; the human pair is ortholog-inferred, and cells are described only as cultured cells [PMID:17708745].","localisation_and_range":"Amelogenin is flagged secreted [flag]; the paper proposes interactions at ameloblast secretory surfaces, with endocytic clearance context [PMID:17708745].","caveats":"Abstract-only read of a single paper. The human and mouse pairs are both projected by orthology. No affinity values or database records.","key_references":[{"PMID":"17708745","why":"Amelogenin-CD63 interaction region mapping"}],"covers":["LR001649","LR005037"]},"LR007350":{"pair":"AMH -> ACVR1:AMHR2","headline":"AMH acts on an AMHR2-containing receptor complex; direct binding is documented for the AMHR2 chain, while ACVR1 is database-asserted.","interaction_type":"direct binding","direction_and_effect":"AMH signals through its own dedicated type II receptor AMHR2, described as an exclusive ligand-receptor pair in the TGF-beta family [PMID:32333774]. GtoPdb lists AMH as agonist at both ACVR1 and AMHR2 [DB:GtoPdb]. UniProt says AMHR2 heterodimerises with type I receptors ACVR1 and BMPR1A [DB:UniProt].","molecular_requirements":"AMHR2 is the type II chain carrying specificity; AMH engages AMHR2 at an interface similar to activin/BMP type II binding, with mutational analysis in an AMH-responsive luciferase assay [PMID:32333774]. A structure of AMH with AMHR2 is recorded [DB:PDB 7L0J]. ACVR1 involvement is not resolved by the paper.","affinity_potency":[],"species_and_systems":"Human AMH and AMHR2 receptor mutants in HEK-293T cells luciferase assays per the curators and excerpt [PMID:32333774].","localisation_and_range":"AMH is flagged secreted; the complex is flagged transmembrane [flag]; Reactome places AMH:AMHR2 at the plasma membrane [DB:Reactome].","caveats":"The only confirmed paper concerns AMHR2 and was read as abstract only; it does not test ACVR1. ACVR1 is only database-asserted here. Two further rows are review_only.","key_references":[{"PMID":"32333774","why":"Mutational analysis of AMHR2 binding to AMH"}],"covers":["LR007350"]},"LR003606":{"pair":"ANGPT1 -> TIE1","headline":"ANGPT1 weakly activates TIE1 alone, more strongly via Tie2 heteromers; one phosphorylation paper and one mouse genetics abstract.","interaction_type":"functional only","direction_and_effect":"Native Ang1 and Ang4 induced Tie1 phosphorylation, less efficiently than the soluble chimera COMP-Ang1; this is an agonist effect [PMID:15851516]. In mice, the combined function of angiopoietin-1 and TIE1 is critical for right-hand-side venous development [PMID:11172728].","molecular_requirements":"Overexpressed Tie1 alone was only weakly phosphorylated by COMP-Ang1 in cells without Tie2; Tie2 co-transfection formed Tie1/Tie2 heteromeric complexes, enhanced Tie1 activation and induced phosphorylation of kinase-inactive Tie1 in a ligand-dependent manner [PMID:15851516]. Tie2 acts as a co-receptor for this activation.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in endothelial and transfected cells [PMID:15851516]; mouse genetics [PMID:11172728]. BioGRID lists a protein-peptide ANGPT1-TIE1 record [DB:BioGRID].","localisation_and_range":"ANGPT1 is flagged as secreted [flag]; TIE1 has no localisation flag beyond receptor status.","caveats":"Both papers were read as abstracts. Direct ANGPT1-TIE1 binding is not shown in our evidence: the phosphorylation paper used mostly COMP-Ang1, and the mouse paper reports a genetic interaction and the receptor is called an orphan [PMID:11172728]. Relevance for CCC: TIE1 activation depends on Tie2.","key_references":[{"PMID":"15851516","why":"Ang1-induced Tie1 phosphorylation, amplified by Tie2 heteromers"},{"PMID":"11172728","why":"Mouse genetics: Ang1 and TIE1 jointly needed for right-side venous system"}],"covers":["LR000056","LR003606"]},"LR001653":{"pair":"ANGPTL2 -> LILRB2","headline":"ANGPTL2 binds the immune-inhibitory receptor LILRB2 directly, with functional support in lung cancer cells.","interaction_type":"direct binding","direction_and_effect":"Purified Angptl2 bound LILRB2 by co-IP and surface plasmon resonance, and Angptl2 had higher affinity than most other Angptls on LILRB2-expressing cells [PMID:22660330]. ANGPTL2 bound A549 lung cancer cells through surface LILRB2 and promoted their proliferation, with SHP2/CaMK1/CREB signalling downstream [PMID:26056041].","molecular_requirements":"LILRB2 alone was sufficient in overexpressing cells; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human LILRB2 in 293T and BAF3 cells and cord blood cells [PMID:22660330]; human NSCLC cell lines and tumour samples [PMID:26056041].","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag]; the lung cancer paper describes autocrine or paracrine signalling [PMID:26056041].","caveats":"The only affinity value in the first paper (5.5 \u00b1 1.1 nM half-maximal saturation) was measured for Angptl5, not Angptl2, so none is given here. Tag type or position could affect binding [PMID:22660330]. IntAct records the pair from pull down and FACS [DB:IntAct].","key_references":[{"PMID":"22660330","why":"Direct Angptl2-LILRB2 binding by co-IP, SPR and flow cytometry"},{"PMID":"26056041","why":"ANGPTL2 binds LILRB2 to drive NSCLC proliferation"}],"covers":["LR001653"]},"LR005433":{"pair":"ANGPTL4 -> CDH5","headline":"cANGPTL4 is reported to bind VE-cadherin and decluster it, from a single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"cANGPTL4 associates with VE-cadherin and declusters it after first activating integrin \u03b15\u03b21, disrupting endothelial continuity; curator labels it antagonist [PMID:21841165]. Knockout mice and tumour models show it induces vascular leakiness and lung metastasis [PMID:21841165].","molecular_requirements":"The acting ligand is the C-terminal fibrinogen-like domain (cANGPTL4), a proteolytic fragment, not full-length ANGPTL4 [PMID:21841165]. Binding to VE-cadherin follows a first step through integrin \u03b15\u03b21 and claudin-5 is a third partner; the sequence is temporal [PMID:21841165].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields, with ANGPTL4-knockout versus wild-type mice in vivo [PMID:21841165]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 is flagged secreted and CDH5 transmembrane [flag]; contact with endothelial junctions, acting from tumour-secreted ligand [PMID:21841165].","caveats":"Only one paper, read as abstract only; no affinity reported; binding method not stated in our evidence; fragment, not full-length, is the active form.","key_references":[{"PMID":"21841165","why":"cANGPTL4 binds VE-cadherin, integrin \u03b15\u03b21 and claudin-5 sequentially"}],"covers":["LR002111","LR005433"]},"LR005442":{"pair":"ANGPTL4 -> SDC3","headline":"Support is a computational ligand-receptor prediction from mouse heart scRNA-seq; no binding or functional test.","interaction_type":"database-asserted only","direction_and_effect":"A cell-communication analysis of mouse heart endothelial cells and cardiomyocytes in diabetes lists Angptl4-Sdc3 as one of four significant ligand-receptor pairs [PMID:40296165]. Effect direction is not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse heart single-cell RNA-seq (control and streptozotocin-induced diabetic mice) [PMID:40296165]. Human pair is ortholog-inferred.","localisation_and_range":"ANGPTL4 is flagged secreted [flag]; paracrine from endothelial cells to other cell types in the analysis [PMID:40296165].","caveats":"Inference from expression only; no experiment on this pair. Two further papers were judged abstract_insufficient.","key_references":[{"PMID":"40296165","why":"Predicts Angptl4-Sdc3 signalling in diabetic mouse heart"}],"covers":["LR002120","LR005442"]},"LR012156":{"pair":"APCDD1 -> FZD7:LRP5","headline":"APCDD1 binds LRP5 (not shown for the Frizzled chain) and inhibits Wnt signalling; evidence is one paper, so the FZD7 complex is inferred.","interaction_type":"direct binding","direction_and_effect":"APCDD1 acts as an inhibitor of Wnt/beta-catenin signalling: it reduced WNT3A-induced TOP/FOP reporter activity ~2-fold, including with LRP5/Fzd2, in HEK293T cells, and reduced Wnt activity in chick neural tube and Xenopus embryos [PMID:20393562]. The authors suggest it may prevent formation of the Wnt receptor complex [PMID:20393562].","molecular_requirements":"The extracellular domain of APCDD1 co-precipitated with tagged LRP5 and WNT3A [PMID:20393562]. No FZD7 binding was tested in this paper; the paper reports no interaction with Fzd2, Fzd8 and Dkk4 (data not shown) [PMID:20393562]. So the LRP5 chain carries the evidence and the Frizzled chain of this complex is not supported by it. FZD7 is not mentioned in the excerpts.","affinity_potency":[],"species_and_systems":"Human APCDD1 and LRP5 constructs, recombinant tagged proteins in HEK293T cells (GST pulldown / co-precipitation); functional tests in HEK293T, chick neural tube and Xenopus embryos [PMID:20393562]. Human pair only.","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein; its extracellular domain was used for binding [PMID:20393562]. Acts at the cell surface, likely cell-autonomously [PMID:20393562].","caveats":"Single paper, interaction shown in vitro only [PMID:20393562]. Binding was to LRP5 and WNT3A, not to the full receptor complex. Our record is listed as the combined complex; IntAct and UniProt entries cite the same paper [DB:IntAct] [DB:UniProt].","key_references":[{"PMID":"20393562","why":"Shows APCDD1 co-precipitates LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012156"]},"LR003615":{"pair":"APLN -> APLNR","headline":"Apelin is the classical endogenous agonist of the apelin receptor (APJ), with direct binding and functional evidence from several species.","interaction_type":"direct binding","direction_and_effect":"Apelin is an agonist of APJ. It was isolated from bovine stomach extract by its ability to raise acidification rate in APJ-expressing cells [PMID:9792798]. Radiolabelled apelin analogues bound APJ with high affinity [PMID:10777510][PMID:11336787]. Apelin acts through Gi: acidification was blocked by a Gi inhibitor [PMID:10777510], and it inhibits cAMP production and induces receptor internalisation [PMID:15341513]. GtoPdb lists full agonist action [DB:GtoPdb].","molecular_requirements":"Single-chain GPCR, no co-receptor reported. Apelin-36 and pyroglutamylated apelin-13 differ in dissociation kinetics and signalling duration [PMID:10777510][PMID:11336787]. Leu5 and Arg2/Arg4 of apelin-13 are needed for potency and affinity [PMID:12603839]. For K17F, the first five N-terminal and last two C-terminal residues are dispensable for binding and cAMP inhibition, but full length is needed for maximal internalisation [PMID:15341513].","affinity_potency":[{"value":"pIC50 8.8 to 9.5","assay":"GtoPdb affinity range for the record citing this paper","system":"database record","cite":"PMID:10777510"},{"value":"10(-7) to 10(-10) M","assay":"acidification-rate response to synthetic apelin peptides","system":"cells expressing APJ","cite":"PMID:9792798"}],"species_and_systems":"Human APJ with human apelin [PMID:10777510][PMID:12603839]; rat receptor in CHO cells [PMID:15341513][PMID:11336787]; bovine-derived peptide on human APJ [PMID:9792798]. The mouse pair is a separate, non-inferred interaction record in our database.","localisation_and_range":"Apelin is flagged secreted, non-transmembrane; APLNR is transmembrane [flag]. Apelin forms differ among tissues in rat [PMID:11336787].","caveats":"All papers shown were read as abstracts only. Affinities come mostly from analogue ligands (radioiodinated analogues) rather than native peptide [PMID:10777510][PMID:11336787]. Two further papers were judged abstract_insufficient and one is pending.","key_references":[{"PMID":"9792798","why":"Isolation of apelin as the APJ ligand."},{"PMID":"10777510","why":"Radioligand binding and function of apelin-36 vs apelin-13."},{"PMID":"12603839","why":"Structure-activity of apelin analogues at human APJ."}],"covers":["LR000066","LR003615"]},"LR005451":{"pair":"APOA1 -> ABCA1","headline":"Well supported: apoA-I directly cross-links to ABCA1's first extracellular domain, and the interaction supports lipid efflux. ABCA1 is a transporter.","interaction_type":"direct binding","direction_and_effect":"ApoA-I binds ABCA1 and drives cholesterol efflux; efflux is lost in mutants with reduced apoA-I cross-linking [PMID:12084722]. ApoA-I binding promotes lipid efflux and inhibits calpain degradation of ABCA1, raising ABCA1 levels [PMID:12511593]. Endogenous apoA-I stabilizes ABCA1 in macrophages [PMID:22271762].","molecular_requirements":"Binding maps to the N-terminal half of ABCA1, with the first extracellular domain as the apoA-I site [PMID:30458687]; critical residues lie in two extracellular loops [PMID:12084722]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ABCA1 in 293 cells with cross-linking [PMID:12084722]; ABCA1-expressing cells with photo-crosslinking [PMID:30458687]; human macrophages [PMID:22271762]. ApoA-I infusion raised ABCA1 in vivo (species not stated) [PMID:12511593].","localisation_and_range":"ApoA-I is flagged secreted; ABCA1 carries transmembrane and receptor flags [flag]. Secreted ligand acting on a membrane protein.","caveats":"The W590S mutant retains full apoA-I cross-linking yet cannot support efflux, so binding is necessary but not sufficient [PMID:12084722]. All four papers were read as abstracts only. ABCA1 is a lipid transporter, not a classical signalling receptor.","key_references":[{"PMID":"12084722","why":"Cross-linking with Tangier mutants"},{"PMID":"30458687","why":"Photo-crosslinking maps apoA-I to the first extracellular domain"},{"PMID":"12511593","why":"Positive feedback: apoA-I stabilizes ABCA1"}],"covers":["LR002134","LR005451"]},"LR002139":{"pair":"APOA2 -> TREM2","headline":"Listed in BioGRID and UniProt from one paper; no curator-verified paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a reconstituted complex for TREM2 and APOA2 [DB:BioGRID]; UniProt states TREM2 acts as a receptor for apolipoproteins including APOA2 and enhances their uptake in microglia [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the database records.","localisation_and_range":"TREM2 is flagged secreted and receptor [flag].","caveats":"Two papers were judged abstract_insufficient. Both records point to PMID 27477018 [DB:BioGRID][DB:UniProt].","key_references":[],"covers":["LR002139","LR005456"]},"LR000069":{"pair":"APOB -> LRP6","headline":"LRP6 binds apoB with low affinity in solid-phase assays and takes up LDL; evidence is partly indirect.","interaction_type":"direct binding","direction_and_effect":"Solid-phase assays showed low-affinity binding of LRP6 for lipid-bound apoB; the R611C mutant bound slightly more tightly [PMID:18948618]. Splenic B cells from LRP6+/- mice had about 30% reduced LDL uptake, and LRP6 colocalized with LDL [PMID:18948618].","molecular_requirements":"Not reported in our evidence beyond LRP6 itself; the mutant showed less efficient apoB dissociation at acidic pH [PMID:18948618].","affinity_potency":[],"species_and_systems":"Mouse splenic B cells and human lymphoblastoid cells [PMID:18948618]. Mouse pair is ortholog-inferred.","localisation_and_range":"LRP6 carries transmembrane and receptor flags [flag]; apoB flagged secreted.","caveats":"Affinity is low, no value is given, and the excerpts note undetectable affinity for apoE. Abstract and excerpts only. BioGRID lists the record from the same paper [DB:BioGRID].","key_references":[{"PMID":"18948618","why":"LRP6 binds apoB and mediates LDL uptake"}],"covers":["LR000069","LR003618"]},"LR005460":{"pair":"APOC3 -> LDLR","headline":"Mouse genetics show APOC3 inhibits triglyceride-rich lipoprotein clearance through LDLR; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"An APOC3-targeting antisense oligonucleotide lowered fasting triglycerides in a manner dependent on LDLR and LRP1; the effect was lost only in mice lacking both [PMID:27400128]. The authors conclude APOC3 inhibits clearance of triglyceride-rich lipoproteins (antagonist-like) through the hepatic LDLR/LRP1 axis [PMID:27400128].","molecular_requirements":"Redundant: either LDLR or LRP1 alone suffices for the effect; both knocked out abolishes it [PMID:27400128].","affinity_potency":[],"species_and_systems":"Mouse, in vivo with knockout lines and injections of lipoproteins [PMID:27400128]. Human pair is ortholog-inferred.","localisation_and_range":"APOC3 flagged secreted; the receptor carries a receptor flag [flag]. Mainly hepatic clearance [PMID:27400128].","caveats":"Indirect genetic evidence; no binding assay in our evidence. Abstract only. Single paper, same for both receptors.","key_references":[{"PMID":"27400128","why":"ASO and receptor knockouts show LDLR/LRP1-dependent effect"}],"covers":["LR002143","LR005460"]},"LR002148":{"pair":"APOE -> LRP4","headline":"Co-IP of apoE and LRP4 in rat brain and transfected cells; abstract only.","interaction_type":"direct binding","direction_and_effect":"ApoE and LRP4 co-immunoprecipitated from LRP4-transfected Cos7 cells and brain homogenate [PMID:17889837]. An antibody to the LRP4 ligand-binding domain suppressed apoE binding to LRP4 in Cos7 cells and reduced neuronal viability [PMID:17889837].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human apoE with rat neurons and brain, Cos7 cells [PMID:17889837]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted [flag]; LRP4 distributed on the neuronal surface [PMID:17889837].","caveats":"Abstract only; no affinity; co-IP does not prove direct binding.","key_references":[{"PMID":"17889837","why":"apoE-LRP4 co-IP and blocking antibody"}],"covers":["LR002148","LR005463"]},"LR003624":{"pair":"APOE -> LRP5","headline":"Single 1998 abstract: LRP5-transduced cells bound more apoE-enriched beta-VLDL; no purified-protein binding.","interaction_type":"direct binding","direction_and_effect":"LDLR-deficient cells transduced with human LRP5 showed increased binding of apoE-enriched beta-VLDL [PMID:9832610]. LRP5 is called an apoE-recognising receptor.","molecular_requirements":"Binding was to apoE-enriched lipoprotein particles, not free apoE; LRP5 has three ligand-binding repeats [PMID:9832610].","affinity_potency":[],"species_and_systems":"Human LRP5 expressed in cells; rabbit tissue also studied [PMID:9832610]. Mouse pair is ortholog-inferred.","localisation_and_range":"LRP5 is a type I membrane protein [PMID:9832610]; ApoE flagged secreted [flag].","caveats":"Abstract only; lipoprotein-level evidence, apoE-specific contribution not isolated.","key_references":[{"PMID":"9832610","why":"LRP5 cloning and beta-VLDL binding"}],"covers":["LR000075","LR003624"]},"LR000078":{"pair":"APOE -> SORL1","headline":"Two abstract-level reports show binding of apoE or apoE-rich lipoproteins to sorLA/LR11; high-affinity claim without a number.","interaction_type":"direct binding","direction_and_effect":"ApoE bound sorLA/LR11 at lumenal domain sites other than the propeptide-inhibitable site [PMID:11294867]. LR11 bound apoE-rich beta-VLDL with high affinity similar to LDLR and VLDLR, and took up and degraded it [PMID:11557679]. BioGRID, IntAct (SPR) and UniProt list the pair [DB:BioGRID] [DB:IntAct] [DB:UniProt].","molecular_requirements":"Furin cleavage activates sorLA [PMID:11294867].","affinity_potency":[],"species_and_systems":"Human receptor in hamster cells [PMID:11557679]; human sorLA [PMID:11294867].","localisation_and_range":"SORL1 flagged transmembrane receptor, apoE secreted [flag]; UniProt notes interaction with secreted SORL1 in cerebrospinal fluid [DB:UniProt].","caveats":"Both papers abstract only; one uses lipoproteins rather than free apoE; no numeric affinity given.","key_references":[{"PMID":"11294867","why":"apoE binding to sorLA lumenal domains"},{"PMID":"11557679","why":"LR11 binds apoE-rich beta-VLDL"}],"covers":["LR000078","LR003627"]},"LR002157":{"pair":"APP -> CNTN4","headline":"APP binds CNTN4 directly, via the CNTN4 second fibronectin repeat and the APP copper-binding domain, with a crystal structure; well supported.","interaction_type":"direct binding","direction_and_effect":"APP and APLP1 interact with CNTN3-5, and APLP2 also binds CNTN4 and CNTN5 [PMID:34958801]. A CNTN4-APP complex is described as guiding visual-system circuit assembly, citing earlier work [PMID:34958801]. Binding assays showed APP binds CNTN3 about equal to CNTN4, above CNTN5 [PMID:31318883]. Curator effect label (agonist) is not tested directly in these papers.","molecular_requirements":"Interface is CNTN FN2 plus the amyloid copper-binding domain; a chicken CNTN4-APP structure was solved at 2.05 \u00c5 [PMID:34958801]. CNTN4 is a GPI-anchored protein that acts through co-receptor complexes [PMID:34958801].","affinity_potency":[{"value":"K = 0.40 \u03bcM","assay":"biolayer interferometry","system":"zebrafish APPb with CNTN4","cite":"PMID:34958801"}],"species_and_systems":"Recombinant proteins: BLI with mouse and zebrafish proteins, crystallography with chicken CNTN4-APP; human APP(E1) aggregated so was not used [PMID:34958801]. Binding assays used proteins cloned from mouse cDNA [PMID:31318883]. Human pair is ortholog-inferred.","localisation_and_range":"Contactins are GPI-anchored with no intracellular region [PMID:34958801]; CNTN4 is flagged secreted and receptor, APP secreted and transmembrane [flag]. These interactions occur between cell-surface-anchored proteins in a co-receptor complex [PMID:34958801].","caveats":"No human-protein affinity is given in our evidence. The authors note their BLI values are weaker than earlier 17-35 nM values from dimeric Fc/AP fusions [PMID:34958801]. Primary 2022 paper read as abstract plus excerpts. IntAct lists a pull-down [DB:IntAct].","key_references":[{"PMID":"34958801","why":"BLI and structures of CNTN-amyloid pairs"},{"PMID":"31318883","why":"Alanine-scanning of the APP-CNTN binding interface"}],"covers":["LR002157","LR005472"]},"LR002166":{"pair":"APP -> RPSA","headline":"One paper links Abeta, an APP fragment, to the laminin receptor RPSA with FRET, pull-down and ELISA.","interaction_type":"direct binding","direction_and_effect":"RPSA (LRP/LR) interacts with Abeta on HEK293 cells; antibody blockade lowered Abeta42-induced apoptosis and shRNA knockdown hampered Abeta42 internalisation, so RPSA acts as an uptake receptor [PMID:24990253].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293 cells; pull-down used shed Abeta from conditioned medium (about 37.6 pg/ml) [PMID:24990253].","localisation_and_range":"Cell-surface interaction on non-permeabilised cells [PMID:24990253].","caveats":"The ligand is the Abeta fragment, not full-length APP. Single paper; curator evidence sentence is a fragment ('form a biologically relevant interaction'). Pull-down enrichment was modest (34% over lysate controls, p = 0.039611287) [PMID:24990253].","key_references":[{"PMID":"24990253","why":"FRET, pull-down and internalisation data for LRP/LR-Abeta"}],"covers":["LR002166"]},"LR003633":{"pair":"AREG -> EGFR","headline":"AREG binds EGFR, though more weakly than EGF; supported by two papers and several databases.","interaction_type":"direct binding","direction_and_effect":"Amphiregulin binds the EGF receptor but not as well as EGF does [PMID:2466334]. In EGFR-devoid NR6 fibroblasts, C-terminal truncation of EGFR did not affect AR binding but impaired AR mitogenic signalling [PMID:10085134]. Annotated stimulatory.","molecular_requirements":"EGFR C-terminal autophosphorylation region is needed for full AR signalling, not for binding [PMID:10085134].","affinity_potency":[],"species_and_systems":"Human amphiregulin and receptor in cell systems; NR6 fibroblasts expressing human EGFR [PMID:10085134]. Mouse pair is ortholog-inferred.","localisation_and_range":"AREG is flagged secreted and non-transmembrane [flag].","caveats":"Both papers abstract only. Binding strength is described qualitatively; no affinity reported. GtoPdb lists binding with no affinity [DB:GtoPdb].","key_references":[{"PMID":"2466334","why":"Amphiregulin binds EGF receptor, weaker than EGF"},{"PMID":"10085134","why":"AR binding unaffected by EGFR truncation"}],"covers":["LR000084","LR003633"]},"LR000087":{"pair":"ARTN -> RET","headline":"ARTN activates RET, mainly through the GFRA3 co-receptor; functional evidence in two papers, no direct ARTN-RET binding shown.","interaction_type":"functional only","direction_and_effect":"ARTN is an agonist. It signals through RET with the co-receptor GFRalpha3 and ARTN-induced neurite outgrowth was abolished by anti-RET antibody [PMID:30853893]. In the original report ARTN activates GFRalpha3-RET and also GFRalpha1-RET [PMID:9883723].","molecular_requirements":"RET is the common signalling chain and needs a GFRalpha co-receptor (GFRalpha3 preferred) [PMID:9883723]. NCAM is also required for ARTN's neuritogenic effect in the 2019 study [PMID:30853893]. Electron microscopy structure and IntAct record of a RET chain with ARTN exist [DB:PDB 6Q2S] [DB:IntAct]; UniProt says ARTN acts via GFRA3 to activate RET [DB:UniProt].","affinity_potency":[],"species_and_systems":"2019 study: human recorded for both partners, with cerebellar granule neurons and PC12 cells (RET phosphorylation about 600% over control) [PMID:30853893]. 1998 study: recorded as mouse, neurons in culture, abstract only [PMID:9883723].","localisation_and_range":"ARTN is flagged secreted; RET is flagged as receptor [flag]. Paracrine signalling is implied, not tested.","caveats":"No direct ARTN-RET binding is shown in the papers; RET activation depends on a GFRalpha co-receptor. Mouse pair is ortholog-inferred. 9883723 was read as abstract only.","key_references":[{"PMID":"9883723","why":"Identified ARTN as ligand of GFRalpha3-RET"},{"PMID":"30853893","why":"RET phosphorylation and RET-dependent neurite outgrowth"}],"covers":["LR000087","LR003636"]},"LR000096":{"pair":"AVP -> AVPR2","headline":"Well supported direct binding and full agonism of vasopressin at the V2 receptor, with nanomolar affinity in human recombinant systems and structures in PDB.","interaction_type":"direct binding","direction_and_effect":"AVP acts as a full agonist; GtoPdb lists Type=Agonist, Action=Full agonist [DB:GtoPdb]. AVP binding to human V2 was displaced by the antagonist OPC-41061 [PMID:9864265]. In CHO cells AVP occupancy of V2 receptors decreased cell proliferation, in contrast to V1 and V3 [PMID:9322919].","molecular_requirements":"Single-chain GPCR; no co-receptor reported in our evidence. PDB entries 7BB6, 7BB7, 7DW9, 7KH0 and 7R0C exist [DB:PDB] and BioGRID lists a reconstituted complex [DB:BioGRID]; details of subunits are not reported in our evidence.","affinity_potency":[{"value":"Ki 4.2 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"Ki 0.78 nM","assay":"[3H]AVP binding competition","system":"HeLa cells expressing human V2","cite":"PMID:9864265"},{"value":"Kd 2.14 nM","assay":"[3H]AVP saturation binding","system":"COS-1 cells expressing human V2","cite":"PMID:9459574"},{"value":"Kd 1.21 nM","assay":"[3H]AVP saturation binding","system":"CHO cells expressing hV2","cite":"PMID:9884074"}],"species_and_systems":"Human receptor in transfected CHO, COS-1 and HeLa cells. Rat and bovine tissues appear only as comparators in other papers [PMID:12446593][PMID:11012895]. No mouse experiment is in the dossier.","localisation_and_range":"AVP is flagged secreted and V2 as transmembrane [flag]; range is paracrine or endocrine.","caveats":"Nearly all papers were read as abstracts only. Several rows use V2 as a selectivity comparator [PMID:15084136][PMID:16158071]. The only full-text row [PMID:9322919] was browser-read and its quote is unverified. 4 papers were abstract_insufficient and 1 review_only.","key_references":[{"PMID":"9864265","why":"AVP Ki 0.78 nM at human V2 vs antagonist OPC-41061"},{"PMID":"9884074","why":"Kd of AVP at hV1A, hV1B, hV2 in CHO cells"},{"PMID":"9264324","why":"Agonist EC50 at human V2 and V1b, with binding comparison"}],"covers":["LR000096","LR003645"]},"LR009312":{"pair":"B2M -> HLA-F","headline":"B2M is the light chain refolded with HLA-F heavy chain into a stable complex; this is an association, not a signalling ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"Recombinant HLA-F heavy chain was refolded with beta2-microglobulin into a stable complex [PMID:11169396]. The paper's receptor result is that HLA-F tetramers bind ILT2 and ILT4 and that surface plasmon resonance showed a direct HLA-F-ILT2/ILT4 interaction; this is not a B2M-receptor result [PMID:11169396].","molecular_requirements":"HLA-F heavy chain with B2M is needed to form the complex used; HLA-F was undetected at the cell surface in this study [PMID:11169396]. IntAct lists SPR and molecular sieving for the HLA-F-B2M pair [DB:IntAct P30511-P61769].","affinity_potency":[],"species_and_systems":"Human recombinant proteins, B cell lines and HUT-78 T cells [PMID:11169396].","localisation_and_range":"HLA-F was undetected at the cell surface, so range is cell-internal or contact only if surface-exposed; HLA-F is flagged transmembrane and B2M secreted [flag].","caveats":"Single paper read as abstract only. The curators record this as an obligate heavy/light chain association rather than a signalling pair [PMID:11169396]. Structures 5IUE and 5KNM contain both chains [DB:PDB 5IUE].","key_references":[{"PMID":"11169396","why":"HLA-F refolded with B2M; tetramer binding to ILT2/ILT4"}],"covers":["LR009312"]},"LR012039":{"pair":"BAMBI -> ACVR2B:BMPR1A","headline":"BAMBI to ACVR2B:BMPR1A has no verified paper; support is limited to one BioGRID record that names a different receptor chain pair.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR2B and BMPR1A; the BioGRID record concerns BMPR1B only, which is not a member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012039"]},"LR012390":{"pair":"BAMBI -> FZD8:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD8:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012390"]},"LR002175":{"pair":"BGN -> CD44","headline":"Biglycan signals through CD44 with TLR4 in macrophages; CD44 is a co-receptor, with no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Biglycan triggers autophagy in macrophages; macrophages lacking TLR2/TLR4, CD14 or CD44 show that the pro-autophagy signal required TLR4 interaction with CD44 [PMID:30712922]. The authors call CD44 a novel signalling co-receptor for biglycan [PMID:30712922]. In vivo, the biglycan-CD44 interaction increased M1 autophagy and renal M2 macrophage numbers and reduced tubular damage after ischemia/reperfusion injury [PMID:30712922].","molecular_requirements":"TLR4 plus CD44 are needed for the autophagy signal; CD44 acts with TLR4, not alone [PMID:30712922].","affinity_potency":[],"species_and_systems":"Murine macrophages and mice, including knockouts; soluble biglycan also promoted autophagy in human peripheral blood macrophages [PMID:30712922]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Soluble biglycan (secreted flag) acting on macrophages; CD44 has transmembrane and secreted flags [flag].","caveats":"Abstract-only; genetic loss-of-function, no direct binding or affinity. CD44 acts as co-receptor with TLR4, so scoring biglycan -> CD44 alone may overstate.","key_references":[{"PMID":"30712922","why":"CD44/TLR4 axis required for biglycan-induced autophagy"}],"covers":["LR002175","LR005489"]},"LR005046":{"pair":"BGN -> FGFR3","headline":"Cell-free experiments show biglycan binds FGFR3c; one abstract-only paper, and signalling effect is only proposed.","interaction_type":"direct binding","direction_and_effect":"Experiments in a cell-free system confirmed that BGN binds FGFR3c and FGF1 [PMID:25260943]. The authors postulate that BGN, secreted by peritubular cells, modulates FGFR3c signalling [PMID:25260943]; the direction (activating or inhibitory) was not tested in our evidence.","molecular_requirements":"The FGFR3c mesenchymal splice isoform is studied; BGN has a sequence homologous to the FGFR3c-binding site on FGF1 [PMID:25260943].","affinity_potency":[],"species_and_systems":"Human testis (expression) and a cell-free binding system; abstract-only [PMID:25260943].","localisation_and_range":"BGN has a secreted flag [flag]; proposed paracrine action from peritubular cells to adjacent spermatogonia [PMID:25260943].","caveats":"Abstract-only; no affinity values; BGN binds FGF1 too, so it may act through FGF1 rather than as a direct agonist. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"25260943","why":"BGN binds FGFR3c in a cell-free system"}],"covers":["LR001660","LR005046"]},"LR003651":{"pair":"BGN -> TLR2","headline":"Biglycan is an endogenous TLR2 agonist in macrophages, shown genetically, with a microscale thermophoresis record in IntAct.","interaction_type":"functional only","direction_and_effect":"Biglycan acts in macrophages as an endogenous ligand of TLR4 and TLR2, activating p38, ERK and NF-kappaB and stimulating TNF-alpha and MIP-2 [PMID:16025156]. Effects were reduced in TLR4-mutant, TLR2-/- and MyD88-/- macrophages and abolished in TLR2-/-/TLR4-mutant cells [PMID:16025156]. Biglycan-null mice had a survival benefit in LPS- or zymosan-induced sepsis [PMID:16025156]. IntAct lists a microscale thermophoresis record P21810-O60603 citing PMID 24480070 [DB:IntAct].","molecular_requirements":"TLR2 and TLR4 each contribute, with complete loss only in the double mutant; MyD88 is needed [PMID:16025156].","affinity_potency":[],"species_and_systems":"Mouse macrophages and mice (genetic models); human and mouse pairs listed [PMID:16025156]. Abstract-only read.","localisation_and_range":"Biglycan released from the matrix or from macrophages acts as a soluble signal [PMID:16025156]; secreted flag [flag].","caveats":"Abstract-only; evidence is functional, with no affinity values in our evidence. The two TLRs are not separated except by the genetic series; the IntAct record gives no values here.","key_references":[{"PMID":"16025156","why":"biglycan signals through TLR4 and TLR2 in macrophages"}],"covers":["LR000102","LR003651"]},"LR007107":{"pair":"BMP10 -> ACVRL1:BMPR2","headline":"Conflicting: BMPR2 binding to BMP10 has structural database support, but the one judged paper found ALK1 (ACVRL1) did not confer BMP10 signalling.","interaction_type":"conflicting","direction_and_effect":"GtoPdb lists BMP10 as an agonist at both ACVRL1 and BMPR2 [DB:GtoPdb]. A receptor screen in COS7 cells found only ALK3 or ALK6 conferred BMP10 signalling, so ALK1 was tested negative; the paper's own answer for BMP10 is ALK3/ALK6 with BMPRII or ActRIIA [PMID:16049014].","molecular_requirements":"The BMPR2 half is backed by PDB 7PPA and 7PPB, X-ray structures of the BMPR2 extracellular domain with BMP10 [DB:PDB 7PPA] [DB:PDB 7PPB], and a BioGRID reconstituted complex [DB:BioGRID]. The ACVRL1 half is backed only by database assertion; UniProt cites the negative paper's PMID [DB:UniProt].","affinity_potency":[],"species_and_systems":"Screen used COS7 and MC3T3 cell lines, read from the abstract only [PMID:16049014]; PDB entries are recombinant structures.","localisation_and_range":"BMP10 is annotated as secreted and the receptor complex as transmembrane [flag].","caveats":"The only judged paper is a verified negative for the ALK1 chain; the pairing as a type I/type II complex is not shown experimentally in our evidence.","key_references":[{"PMID":"16049014","why":"Negative for ALK1 signalling with BMP10"}],"covers":["LR007107"]},"LR007116":{"pair":"BMP4 -> ACVR2A:BMPR1A","headline":"BMP4 requires both ACVR2A and BMPR1A for osteoinductive signalling in primary hMSC (siRNA, abstract only); database support is consistent.","interaction_type":"functional only","direction_and_effect":"In primary human mesenchymal stem cells, knockdown showed osteoinductive BMP activities are elicited through type I receptors ACVR1A and BMPR1A and type II receptors ACVR2A and BMPR2; BMP-2/4 used predominantly BMPR1A [PMID:18436533]. Effect is agonist. GtoPdb lists BMP4 as agonist at both ACVR2A and BMPR1A [DB:GtoPdb]; UniProt describes BMP4 initiating signalling via BMPR1A and a type II receptor (BMPR2 named) [DB:UniProt].","molecular_requirements":"Complex of one type II (ACVR2A) and one type I (BMPR1A) chain. The paper does not test this particular heterodimeric pairing; it shows each chain's contribution separately, and BMPR2 was also required [PMID:18436533]. A least-expressed-subunit score is therefore only a proxy.","affinity_potency":[],"species_and_systems":"Primary human bone marrow-derived mesenchymal stem cells; siRNA knockdown [PMID:18436533].","localisation_and_range":"BMP4 is flagged secreted; receptors transmembrane [flag].","caveats":"Abstract only. Functional knockdown, not binding. In that paper ACVR2A mattered less for BMP-2/4 than BMPR2 [PMID:18436533]. Two further rows were review_only.","key_references":[{"PMID":"18436533","why":"siRNA screen of BMP-2/4 receptor use in primary hMSC"}],"covers":["LR007116"]},"LR001662":{"pair":"BMP4 -> RGMB","headline":"BMP4 binds RGMB (DRAGON) directly in two papers, with the tightest SPR affinity of the RGMs, Kd 2.6 nM; acts as a BMP co-receptor.","interaction_type":"direct binding","direction_and_effect":"RGMB (DRAGON) enhances BMP signalling; the abstract states it binds BMP2 and BMP4 directly but not BMP7 or other TGF-beta ligands, and the enhancing action is reduced by Noggin, indicating ligand dependence [PMID:15671031]. Curators label the effect agonist [PMID:15671031][PMID:23029472].","molecular_requirements":"DRAGON also associates directly with type I (ALK2, ALK3, ALK6) and type II (ActRII, ActRIIB) BMP receptors; its signalling is reduced by dominant negative Smad1 and ALK3 or ALK6 [PMID:15671031]. The BMP4 binding partner is RGMB itself.","affinity_potency":[{"value":"Kd 2.6 nM","assay":"SPR","system":"RGMB vs BMP4, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human. The 2005 paper used Xenopus embryos for function [PMID:15671031]; the 2012 paper used SPR with recombinant proteins [PMID:23029472]. BioGRID holds a reconstituted-complex record from the 2005 paper [DB:BioGRID]. Mouse pair is projected from human.","localisation_and_range":"DRAGON is described as GPI-anchored [PMID:15671031], i.e. membrane-tethered (juxtacrine); the entity flag marks RGMB as not secreted [flag].","caveats":"Both papers were read as abstracts by the curators (2012 paper also with full-text excerpts). Binding is ligand-selective: BMP7 was not bound in the 2005 paper [PMID:15671031].","key_references":[{"PMID":"15671031","why":"first report of DRAGON/RGMB as BMP co-receptor; direct BMP2/BMP4 binding"},{"PMID":"23029472","why":"SPR affinity of RGMB for BMP4"}],"covers":["LR001662","LR005048"]},"LR007125":{"pair":"BMP5 -> ACVR2A:BMPR1A","headline":"BMP5 to ACVR2A:BMPR1A rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with type I receptor BMPR1A and type II receptor BMPR2, not ACVR2A; UniProt also says BMPR1A phosphorylates SMAD1/5/8 [PMID:29321139] [DB:UniProt][PMID:11580864].","molecular_requirements":"Chains in the complex: ACVR2A and BMPR1A; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 3 review_only. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007125"]},"LR007134":{"pair":"BMP6 -> ACVR2A:BMPR1A","headline":"BMP6 to ACVR2A:BMPR1A rests on database records only; no verified paper row.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP6 as agonist at ACVR2A and BMPR1A [DB:GtoPdb]. UniProt says BMP6 may promote HAMP expression via its receptor BMPR1A/ALK3 [DB:UniProt][PMID:30097509]. BioGRID has ACVR2A-BMP6 records [DB:BioGRID][PMID:10504300][PMID:18070108].","molecular_requirements":"Complex of ACVR2A and BMPR1A; whether both are needed is not reported in our evidence. Records are per chain, not for the assembled complex.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence beyond the human annotation.","localisation_and_range":"BMP6 is flagged secreted and both chains transmembrane [flag].","caveats":"Three screened papers were review_only. UniProt's BMPR1A statement is hedged ('potentially'). BioGRID's BMP6-BMPR1B record is not for this pair.","key_references":[],"covers":["LR007134"]},"LR002184":{"pair":"BMP6 -> ACVRL1","headline":"Curated paper found BMP6 does not bind endogenous ALK-1; only a database agonist record supports the pair.","interaction_type":"conflicting","direction_and_effect":"GtoPdb lists BMP6 as an agonist at ACVRL1 [DB:GtoPdb]. The one verified paper concluded ALK-1 is not a physiological BMP-6 receptor [PMID:10504300].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The paper used COS-7 overexpression and endogenous cells (HUVEC); human versus other origin of reagents is not stated in the dossier. Pair is listed for human and mouse, both projected from other evidence [flag].","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Negative result: endogenous ALK-1-expressing HUVEC cells did not bind BMP-6; weak binding seen only in COS-7 overexpression was judged an overexpression artifact [PMID:10504300]. The paper's abstract reports binding of BMP-6 to ALK-2, BMPR-IA and BMPR-IB, not ALK-1. Six other papers were abstract-insufficient. Treat as unlikely to be a bona fide receptor for CCC scoring.","key_references":[{"PMID":"10504300","why":"Verified negative: ALK-1 not a physiological BMP-6 receptor"}],"covers":["LR002184","LR005498"]},"LR007143":{"pair":"BMP7 -> ACVR2A:BMPR1A","headline":"Complex-level row with no curator-verified papers; rests on database records for the individual chains.","interaction_type":"database-asserted only","direction_and_effect":"No paper in our evidence confirms the combined ACVR2A:BMPR1A receptor. GtoPdb lists BMP7 as agonist for ACVR2A and for BMPR1A separately [DB:GtoPdb]. UniProt states BMP7 initiates canonical BMP signalling by associating with type I receptor ACVR1 and type II receptor ACVR2A [DB:UniProt].","molecular_requirements":"Both chains would be required by the complex definition; no paper tests the pairing. Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Three papers were judged review_only and none was confirmed. BioGRID records show BMP7 with ACVR2A (affinity capture-Western, co-crystal structure) and BMPR1B, but none for BMPR1A [DB:BioGRID]. UniProt names ACVR1, not BMPR1A, as the type I partner [DB:UniProt].","key_references":[],"covers":["LR007143"]},"LR007152":{"pair":"BMP8A -> ACVR2A:BMPR1A","headline":"BMP8A -> ACVR2A:BMPR1A is database-asserted only here; no paper was verified for this complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8A as an agonist at ACVR2A and at BMPR1A [DB:GtoPdb]; UniProt says BMP8A associates with type I receptor BMPR1A and type II receptor BMPR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"Three papers were review-only; the dossier holds no verified primary paper. The complex is assembled from separate chain records.","key_references":[],"covers":["LR007152"]},"LR008250":{"pair":"BMP8B -> BMPR1A:BMPR2","headline":"BMP8B -> BMPR1A:BMPR2 is asserted only by GtoPdb agonist records for each chain; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-BMPR1A and BMP8B-BMPR2 each as Type=Agonist, Action=Agonist [DB:GtoPdb].","molecular_requirements":"Receptor modelled as a type I (BMPR1A) plus type II (BMPR2) complex [flag]. GtoPdb records the chains separately, so joint requirement is not shown in our evidence [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human entities).","localisation_and_range":"Complex flagged as receptor and transmembrane [flag]; range not reported in our evidence.","caveats":"No curator-verified paper; several candidate papers were judged abstract-insufficient, review-only or about a different entity, so none supports the pair. The GtoPdb record is a database assertion, not an experiment.","key_references":[],"covers":["LR008250"]},"LR005505":{"pair":"BSG -> GP6","headline":"BSG (EMMPRIN) binds platelet GPVI directly, with a Kd of 88 nM by SPR and functional rolling assays, from one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"EMMPRIN-Fc supports rolling (not firm adhesion) of ADP-stimulated human platelets; blocking antibodies against EMMPRIN or GPVI reduce it, and GPVI-transfected CHO cells roll on EMMPRIN-Fc [PMID:19350111]. The curator labels GPVI the receptor and the effect agonist.","molecular_requirements":"GPVI alone in transfected CHO cells was sufficient for enhanced rolling on EMMPRIN-Fc; other co-receptors are not reported in our evidence [PMID:19350111].","affinity_potency":[{"value":"Kd 88 nM","assay":"ELISA and surface plasmon resonance, EMMPRIN binding to GPVI","system":"recombinant human proteins","cite":"PMID:19350111"}],"species_and_systems":"Human platelets, CHO transfectants and recombinant Fc fusions; ortholog-inferred mouse version [PMID:19350111].","localisation_and_range":"BSG is flagged transmembrane and not secreted [flag]; contact-mediated (rolling) interaction on platelets and cells [PMID:19350111].","caveats":"Abstract only; one paper. The reciprocal experiment (EMMPRIN-transfected cells on GPVI-Fc) is also reported [PMID:19350111].","key_references":[{"PMID":"19350111","why":"Rolling assays plus ELISA/SPR giving Kd 88 nM for EMMPRIN-GPVI."}],"covers":["LR002191","LR005505"]},"LR001671":{"pair":"BSG -> SELE","headline":"Basigin is a glycan-dependent E-selectin ligand on neutrophils in mouse renal ischemia/reperfusion; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Bsg-deficient mice showed suppressed neutrophil infiltration and less renal damage; Bsg-/- neutrophils had reduced E-selectin binding and reduced E-selectin-dependent adherence to HUVEC [PMID:19443639]. Curator effect: agonist.","molecular_requirements":"Binding depends on N-linked glycans: Bsg isolated from HL-60 cells bound E-selectin and tunicamycin abolished this binding; neutrophil Bsg carries N-linked polylactosamine chains [PMID:19443639].","affinity_potency":[],"species_and_systems":"Mouse in vivo model and neutrophils, plus HL-60 and HUVEC in vitro cells; mouse experiments for the paper, human cell lines for binding [PMID:19443639].","localisation_and_range":"BSG is flagged transmembrane; SELE is flagged transmembrane and not secreted [flag]; leukocyte-endothelial contact (juxtacrine).","caveats":"Abstract only; no affinity reported; effect on receptor is adhesion, not classical signalling [PMID:19443639].","key_references":[{"PMID":"19443639","why":"Bsg-deficient mice and neutrophil binding assays; glycan-dependent E-selectin binding."}],"covers":["LR001671","LR005051"]},"LR010842":{"pair":"BTC -> EGFR:ERBB2","headline":"Our only verified paper shows BTC binding EGFR and HER4, not the EGFR:ERBB2 complex; the pair is thinly supported.","interaction_type":"database-asserted only","direction_and_effect":"BTC-toxin fusions bind and induce tyrosine phosphorylation of EGFR and HER4; BTC-TX48 mainly phosphorylates HER4 [PMID:9528863]. No evidence for the EGFR:ERBB2 heterodimer as a unit is shown in the paper excerpts.","molecular_requirements":"Heterodimer requirement is not reported in our evidence. PDB 8U4K has chains of BTC (P35070) and ERBB2 (P04626) [DB:PDB 8U4K]; GtoPdb and IntAct records concern EGFR [DB:GtoPdb] [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human cells and recombinant toxin fusions [PMID:9528863].","localisation_and_range":"BTC is flagged secreted and transmembrane [flag].","caveats":"Abstract-level reading; a second paper was abstract-insufficient. Database records mostly concern EGFR alone, not the complex.","key_references":[{"PMID":"9528863","why":"BTC binding of EGFR and HER4 (not the ERBB2 heterodimer)."}],"covers":["LR010842"]},"LR005514":{"pair":"C1qa -> Met","headline":"Candidate C1q receptor from an unbiased pull-down screen in human neural stem cells; mouse pair is projected from human evidence.","interaction_type":"functional only","direction_and_effect":"C1q was cross-linked to membrane proteins and c-MET was among five transmembrane candidates identified by pull-down and mass spectrometry; the proximity-ligation assay was reported to validate the C1q-c-MET interaction and the curator labels it agonist [PMID:32894219].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were in human neural stem cells (hNSC); the mouse pair is ortholog-inferred, not tested in mouse [PMID:32894219].","localisation_and_range":"C1q is annotated secreted [flag]. Cell-surface receptor role is a candidate assignment.","caveats":"Candidate-level evidence; functional validation in the paper was for CD44 only, not for c-MET. Paper read as abstract and excerpts. ","key_references":[{"PMID":"32894219","why":"screen identifying five candidate C1q receptors in hNSC"}],"covers":["LR005514"]},"LR005523":{"pair":"C1QC -> CD44","headline":"CD44 mediates C1q signalling and chemotaxis in human neural stem cells; functional plus proximity-ligation support from one paper.","interaction_type":"functional only","direction_and_effect":"CRISPR-Cas9 CD44 knockout was used to test that CD44 mediates C1q-induced signalling (p-ERK) and chemotaxis in hNSC; the abstract reports CD44 mediates these effects in vitro and hNSC migration and repair in vivo after spinal cord injury [PMID:32894219]. Stimulatory.","molecular_requirements":"The ligand studied was assembled C1q (C1QA:C1QB:C1QC), not the single C1QC chain; chain-alone activity is not shown [PMID:32894219]. Co-receptor or subunit requirements on the CD44 side are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neural stem cells in vitro (CD44 identified among five candidate C1q receptors by crosslinking and mass spectrometry, then proximity ligation assay indicating close contact <30 nm); in vivo spinal cord injury model, host species not stated in the excerpts [PMID:32894219].","localisation_and_range":"C1q is secreted (ligand flag); CD44 is flagged as transmembrane and also secreted [flag]. Acts on cell-surface CD44 of the responding cell [PMID:32894219].","caveats":"Curated from the abstract plus excerpts. Proximity ligation shows nearness, not a measured affinity; no Kd reported. Mouse interaction is ortholog-inferred only.","key_references":[{"PMID":"32894219","why":"CD44 identified as C1q receptor on hNSC; knockout abolishes C1q-induced signalling/chemotaxis"}],"covers":["LR002210","LR005523"]},"LR005532":{"pair":"C1QTNF3 -> ADIPOR1","headline":"CTRP3 relaxes vessels, but the ADIPOR1 dependence was shown for CTRP9, not CTRP3; indirect, family-level support.","interaction_type":"functional only","direction_and_effect":"CTRPs 3, 5 and 9 caused concentration-dependent vasorelaxation; CTRP3 and CTRP5 were comparable to adiponectin [PMID:21836066]. ADIPOR1 knockdown blocked CTRP9-induced AMPK/Akt/eNOS phosphorylation and NO production, ADIPOR2 knockdown did not; this was not reported for CTRP3 in our evidence [PMID:21836066].","molecular_requirements":"Not reported in our evidence for CTRP3.","affinity_potency":[],"species_and_systems":"Aortic vascular rings (murine CTRPs) and human umbilical vein endothelial cells (HUVECs) [PMID:21836066]. Curator labels human/human, but the abstract states murine CTRPs were assayed.","localisation_and_range":"Secreted ligand [flag]; range not reported.","caveats":"No direct binding of CTRP3 to ADIPOR1 shown. The ADIPOR1 mechanism is for CTRP9 only. Abstract-level curation with excerpts. Mouse interaction ortholog-inferred.","key_references":[{"PMID":"21836066","why":"CTRP3/5/9 vasorelaxation; ADIPOR1 knockdown mechanism for CTRP9"}],"covers":["LR002219","LR005532"]},"LR003705":{"pair":"C3 -> C5AR2","headline":"C3a binds C5L2 (C5AR2) at moderate affinity in one abstract-only paper; signalling role unclear.","interaction_type":"direct binding","direction_and_effect":"C5L2 has moderate affinity for C3a, and cross-competition suggests C3a binds a site distinct from C5a [PMID:11773063]. C4a displaced C3a. Unlike CD88 and C3aR, C5L2 did not support degranulation or calcium increase, though ligation potentiated IgE-receptor degranulation [PMID:11773063].","molecular_requirements":"Single receptor chain; no co-receptor reported. Binding site distinct from C5a's [PMID:11773063].","affinity_potency":[],"species_and_systems":"Human C5L2 transfected into RBL-2H3 cells [PMID:11773063]; mouse pair is ortholog-inferred.","localisation_and_range":"C3a flagged secreted and C5AR2 transmembrane [flag].","caveats":"One paper, abstract only; no numeric affinity in our evidence. UniProt text describes C5AR2 as receptor for dearginated C3a [DB:UniProt]. C3a is a cleavage fragment of C3.","key_references":[{"PMID":"11773063","why":"C5L2 binds C3a at moderate affinity"}],"covers":["LR000156","LR003705"]},"LR000159":{"pair":"C3 -> ITGAX","headline":"iC3b fragment of C3 binds ITGAX (CD11c, p150,95); supported by binding and cell-based papers.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose isolated p150,95 from human membranes [PMID:4062888]. Cells with human p150,95 alpha subunit and a chicken beta subunit bound IgM-iC3b erythrocytes [PMID:7512600]. Dendritic cell phagocytosis of Francisella depended on C3 opsonins and CR3/CR4 [PMID:16857732].","molecular_requirements":"p150,95 is the alphaX:beta2 heterodimer sharing the beta subunit with CR3 [PMID:4062888]. Cells needed a heterologous (chicken) beta subunit for activation of binding [PMID:7512600]. Ligand recognition maps to the I domain [PMID:7512600].","affinity_potency":[],"species_and_systems":"Human materials: membranes, transfectants and dendritic cells [PMID:4062888][PMID:7512600][PMID:16857732]. Mouse pair is ortholog-inferred. BioGRID and IntAct list reconstituted-complex and SPR records [DB:BioGRID][DB:IntAct].","localisation_and_range":"Membrane integrin; contact-dependent (annotation [flag]).","caveats":"Abstract only for all papers. Ligand is iC3b, not intact C3. Phagocytosis paper implicates both CR3 and CR4 so it cannot isolate ITGAX [PMID:16857732].","key_references":[{"PMID":"4062888","why":"iC3b affinity isolation of p150,95"},{"PMID":"7512600","why":"CD11c/CD18 as iC3b receptor"},{"PMID":"16857732","why":"CR4 role in complement-dependent phagocytosis"}],"covers":["LR000159","LR003708"]},"LR000168":{"pair":"C5 -> C5AR1","headline":"C5a binds and activates C5AR1; supported by several functional papers and databases, though one cited paper concerns C5AR2.","interaction_type":"direct binding","direction_and_effect":"C5a acts as an agonist: the C-terminus drives all agonist activity at human C5a receptors [PMID:15661745], human recombinant C5a induces MPO secretion and umbilical artery contraction [PMID:10602324], and the receptor was cloned and bound C5a with high affinity [PMID:1847994]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The receptor N-terminal residues 21-30 bind C5a [PMID:9553099]; Arg175, Arg206, Asp282 and Glu199 contact the C-terminal Arg and carboxylate of C5a [PMID:15661745]. The active ligand is the C5a fragment of C5.","affinity_potency":[{"value":"pEC50 8.0-9.0","assay":"GtoPdb agonist record","system":"not stated in dossier","cite":"PMID:9881961"}],"species_and_systems":"Human ligand and receptor throughout; transfected COS-7 cells, human PMNs and umbilical artery [PMID:1847994] [PMID:10602324].","localisation_and_range":"C5 (C5a) flagged secreted; C5AR1 flagged transmembrane [flag]; C5a acts on cell-surface receptors.","caveats":"Several papers are abstract-only; the structure-activity work used mostly synthetic peptide mimics [PMID:15661745]. PMID 11773063 concerns C5L2 (C5AR2), not C5AR1. Competing receptor C5AR2 also binds C5a.","key_references":[{"PMID":"9553099","why":"N-terminal receptor domain binds C5a (NMR)"},{"PMID":"15661745","why":"Mapping of C5a-binding residues"},{"PMID":"1847994","why":"Cloning and high-affinity binding of human C5aR"}],"covers":["LR000168"]},"LR005055":{"pair":"CADM1 -> CADM3","headline":"CADM1 and CADM3 (Necl-1) bind heterophilically in adhesion and SPR assays; two papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with Necl-2 (CADM1), nectin-1 and nectin-3, but not Necl-5 or nectin-2 [PMID:15741237]. SPRi also showed CADM1 interacting with CADM3 [PMID:30131958]. Reactome lists a Necl-1:Necl-2 trans heterodimer [DB:Reactome].","molecular_requirements":"Both are single transmembrane chains; no co-receptor requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell aggregation assays (15741237) and cell-free SPRi with human recombinant proteins (30131958).","localisation_and_range":"Both flagged transmembrane [flag]; trans-interaction between adjacent cells (juxtacrine). CADM3 is neural-tissue specific at non-junctional contact sites [PMID:15741237].","caveats":"15741237 is abstract only; no affinity values for CADM3 in our excerpts. The interaction is symmetric, so direction is arbitrary.","key_references":[{"PMID":"15741237","why":"Heterophilic Necl-1/Necl-2 adhesion with negative controls"},{"PMID":"30131958","why":"SPRi interaction of CADM1 with CADM3"}],"covers":["LR001679","LR005055"]},"LR001680":{"pair":"CADM1 -> CRTAM","headline":"Well-supported direct CADM1-CRTAM binding with nM affinity and an immune-cell functional effect.","interaction_type":"direct binding","direction_and_effect":"NK cells and CD8+ T cells recognise CADM1 (Necl-2) through CRTAM, which is expressed only on activated cells; the interaction promotes NK cytotoxicity and CD8+ T-cell IFN-gamma secretion in vitro and NK-cell-mediated rejection of CADM1-expressing tumours in vivo [PMID:15811952]. UniProt gives the same functional summary [DB:UniProt]. CADM1 acts as the epithelial/tumour ligand, CRTAM as the receptor on cytotoxic lymphocytes.","molecular_requirements":"Whole ectodomains bound in SPRi. The paper states the IgV loops are primarily involved while IgC loops facilitate binding [PMID:30131958]. UniProt notes the interaction competes with CRTAM and CADM1 homodimerisation [DB:UniProt]. No extra subunit reported.","affinity_potency":[{"value":"Kd 3.3 nM","assay":"SPRi, CADM1-Fc with CRTAM-Fc, ectodomains","system":"Fc fusions from 293-F cells","cite":"PMID:30131958"}],"species_and_systems":"SPRi used human-labelled recombinant ectodomains [PMID:30131958]; the NK/CD8 T-cell and tumour work is labelled human in the dossier but species is not stated in the abstract read [PMID:15811952]. Structure of a complex is deposited [DB:PDB 4H5S]; IntAct lists cosedimentation and solid-phase assays [DB:IntAct].","localisation_and_range":"Both partners are flagged membrane-bound [flag]; the paper describes the interaction between epithelial cells expressing CADM1 and CD8+ T/NK cells expressing CRTAM, i.e. contact-dependent [PMID:30131958].","caveats":"The earlier functional paper was read as an abstract only [PMID:15811952]. The paper reports an earlier E. coli IgV-IgV Kd of 12.5 uM, far weaker than 3.3 nM, and attributes it to the IgC loops [PMID:30131958]. Dissociation is very slow versus other CADM partners [PMID:30131958].","key_references":[{"PMID":"15811952","why":"CRTAM recognises CADM1; NK/CD8 T-cell function and tumour rejection"},{"PMID":"30131958","why":"SPRi Kd 3.3 nM, slow off-rate"}],"covers":["LR001680","LR005056"]},"LR002229":{"pair":"CADM2 -> CADM2","headline":"Homophilic CADM2 binding detected by SPRi in one paper; no affinity reported for it in our evidence.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM2 with all CADM family proteins [PMID:30131958]. This is self-binding, so direction is not meaningful.","molecular_requirements":"CADM2 ectodomain-Fc; homodimer, no other subunit reported [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human-labelled recombinant Fc ectodomains [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged non-secreted [flag]; homophilic trans adhesion is consistent with Reactome Necl transhomodimerisation entries [DB:Reactome].","caveats":"One paper. The curated sentence (CADM1-Fc binding CADM2) describes a different pairing than CADM2-CADM2, so support is via the paper's general statement. Affinity for CADM2-CADM2 is not reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family, homophilic CADM2 binding"}],"covers":["LR002229","LR005539"]},"LR005541":{"pair":"CADM2 -> CADM4","headline":"Direct CADM2-CADM4 binding stated by SPRi in one paper; no affinity or species label recorded.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM2, CADM3 and CADM4 with all CADM family proteins [PMID:30131958].","molecular_requirements":"Ectodomain-Fc proteins; no other subunit reported [PMID:30131958].","affinity_potency":[],"species_and_systems":"Recombinant Fc ectodomains; the curator left species unrecorded, though the paper used an anti-human IgG-Fc antibody for Western blotting [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag].","caveats":"One paper; no Kd for this pairing in our evidence. Support is a blanket statement, not a pair-specific result.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family"}],"covers":["LR002231","LR005541"]},"LR002238":{"pair":"CALCA -> CRCP","headline":"No evidence that CALCA binds CRCP; the only link is a gene name containing 'CGRP'. Both papers judged pair-absent.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. The paper studied RCP (CRCP) and found a direct interaction with an intracellular domain of CLR, not with CGRP [PMID:22315449].","molecular_requirements":"Not reported in our evidence. CRCP is described only as a CGRP receptor component affecting CLR signalling [PMID:22315449].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the mouse pair is the recorded species, human is ortholog-inferred.","localisation_and_range":"CALCA flagged secreted [flag]; CRCP is flagged receptor only [flag].","caveats":"Curators verified the pair as absent. The only database item is the HGNC name 'CGRP receptor component', which contains the ligand name [DB:HGNC]. This is likely a name-based pairing, not binding.","key_references":[{"PMID":"22315449","why":"RCP-CLR intracellular interaction, no CGRP-RCP binding"}],"covers":["LR002238","LR005548"]},"LR007161":{"pair":"CALCB -> CALCRL:RAMP1","headline":"beta-CGRP to the CALCRL:RAMP1 complex is supported by database records only; no confirmed paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists beta-CGRP as full agonist at CALCRL and RAMP1 [DB:GtoPdb]. Reactome states the CGRP receptor can bind calcitonin gene-related peptides [DB:Reactome R-HSA-420127]. UniProt says CALCB/CGRP2 induces vasodilation mediated by the CALCRL-RAMP1 complex [DB:UniProt].","molecular_requirements":"Both CALCRL and RAMP1 form the receptor complex [DB:UniProt].","affinity_potency":[{"value":"pKi 9.9 to 11.0","assay":"GtoPdb record for CALCB-RAMP1","system":"database record","cite":"DB:GtoPdb"},{"value":"pKi 7.3 to 7.7","assay":"GtoPdb record for CALCB-CALCRL","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human complex entity; no species or system given beyond database records.","localisation_and_range":"Ligand flagged secreted and complex flagged receptor and transmembrane [flag].","caveats":"No papers were confirmed; judged rows were abstract_insufficient or review_only. Support is from databases only.","key_references":[],"covers":["LR007161"]},"LR005550":{"pair":"CALCB -> RAMP3","headline":"Not supported: the one paper checked found no CALCB-RAMP3 pairing; only GtoPdb agonist records assert it.","interaction_type":"database-asserted only","direction_and_effect":"A curator judged pair_absent for the one paper: knockdown of RAMP3 inhibited ADM-induced cAMP, and absence of both RAMP2 and RAMP3 further increased CALCB-induced cAMP synthesis, not the pattern expected for an agonist relationship [PMID:26423127]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 7.0 to 7.5","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat mesenteric artery smooth muscle cells [PMID:26423127].","localisation_and_range":"Ligand flagged secreted, RAMP3 transmembrane [flag].","caveats":"Verified negative from an abstract-only read. Database support only; remaining judged rows were different_entity or abstract_insufficient.","key_references":[{"PMID":"26423127","why":"RAMP3 linked to ADM, not CALCB, signalling"}],"covers":["LR002240","LR005550"]},"LR000177":{"pair":"CALR -> LRP1","headline":"Calreticulin as an agonist ligand for LRP1 (CD91) is supported by several abstract-level papers, mostly functional.","interaction_type":"functional only","direction_and_effect":"Calreticulin is described as binding and activating LRP on the engulfing phagocyte as an eat-me signal [PMID:16239148]. CD91 signals for calreticulin, including NF-kappaB activation, and calreticulin immunization primed Th17 responses in a CD91-dependent manner in a TGF-beta setting [PMID:22045000]. LRP mediated thrombospondin-calreticulin focal adhesion disassembly [PMID:12821648].","molecular_requirements":"LRP is called a calreticulin coreceptor because calreticulin is not transmembrane; LRP-deficient fibroblasts did not respond, and the isolated proteins LRP and CRT interact [PMID:12821648]. Calreticulin-CD91 colocalised on macrophage surface and anti-CD91 blocked uptake [PMID:11560994].","affinity_potency":[],"species_and_systems":"Curator fields record human for both partners; abstracts do not name species except macrophages and thymocytes in [PMID:22234309] (peritoneal and bone marrow-derived macrophages, likely rodent, not stated). Cell assays, not in vivo.","localisation_and_range":"CALR is flagged secreted and LRP1 a receptor [flag]; papers describe cell-surface calreticulin on target cells and phagocytes [PMID:16239148].","caveats":"All five shown papers were read as abstracts, with excerpts for [PMID:11560994]. PMID 22234309 uses the pairing as background and its own finding is glucocorticoid upregulation of LRP1. Calreticulin is not transmembrane, so other partners may be needed. A BioGRID Affinity Capture-Western record also exists [DB:BioGRID]. One further paper was abstract_insufficient and one pending.","key_references":[{"PMID":"16239148","why":"Calreticulin binds and activates LRP on phagocytes"},{"PMID":"12821648","why":"LRP as calreticulin coreceptor; isolated proteins interact"},{"PMID":"22045000","why":"CD91 signalling for calreticulin and Th17 priming"}],"covers":["LR000177","LR003722"]},"LR003723":{"pair":"CALR -> SCARF1","headline":"Calreticulin is endocytosed via SREC-I in an abstract-read paper; supported by one study.","interaction_type":"direct binding","direction_and_effect":"SREC-I (SCARF1) mediates endocytosis of calreticulin and gp96; ectopic SREC-I in CHO cells conferred recognition and uptake, competed by fucoidin and acetylated LDL, and SREC-I overexpression in macrophages increased chaperone endocytosis [PMID:15371419].","molecular_requirements":"Not all scavenger receptors that bind acetylated LDL bind calreticulin or gp96, so specificity goes beyond generic scavenging [PMID:15371419]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"CHO cells with ectopic SREC-I, and macrophages including SRA-knockout macrophages; the curator records human for both partners but the abstract does not state species [PMID:15371419].","localisation_and_range":"CALR is flagged secreted [flag]; the paper describes endocytic uptake of extracellular chaperone.","caveats":"Only the abstract was read. The function is endocytic clearance and antigen cross-presentation, so this is an uptake receptor and not clearly a signalling one. A second confirmed paper exists but was not shown. Direct binding is inferred from uptake competition, as no affinity is given.","key_references":[{"PMID":"15371419","why":"SREC-I mediates calreticulin endocytosis"}],"covers":["LR000178","LR003723"]},"LR002247":{"pair":"CBLN2 -> NRXN1","headline":"CBLN2 acts with NRXN1 SS4+ in mouse prefrontal cortex and hippocampus; evidence is genetic.","interaction_type":"functional only","direction_and_effect":"Nrxn1SS4+ and Nrxn3SS4+ act by binding secreted Cbln2, which activates postsynaptic GluD1 receptors; in prefrontal cortex Nrxn1SS4+-Cbln2 signalling selectively controlled NMDA-receptors without changing spine or synapse numbers [PMID:36205393].","molecular_requirements":"The SS4+ splice variant of Nrxn1 is used; Cbln2 then signals to GluD1 [PMID:36205393].","affinity_potency":[],"species_and_systems":"Mouse constitutive Cbln2 knockouts at CA1 to subiculum synapses and in prefrontal cortex; curators recorded human [PMID:36205393].","localisation_and_range":"CBLN2 is flagged secreted and NRXN1 transmembrane [flag].","caveats":"Abstract read only. The abstract states binding but the shown assays are physiological. GluD1 is the downstream receptor in this paper. A second confirmed paper was not shown.","key_references":[{"PMID":"36205393","why":"Nrxn1SS4+-Cbln2-GluD1 signalling regulates NMDA receptors"}],"covers":["LR002247","LR005557"]},"LR000186":{"pair":"CCL11 -> CCR5","headline":"CCL11 binds and activates CCR5 in human cells; supported by two abstract-read papers, with weak binding affinity.","interaction_type":"direct binding","direction_and_effect":"Eotaxin is reported as a CCR5 agonist (and a CCR2 antagonist) [PMID:11264152]. It triggers CCR5 at 100 nM and induces CCR5 internalisation in monocytes and transfected cells [PMID:11264152]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 21.7 nmol/L","assay":"[125I]-MIP-1beta competition binding (five values reported; the curator assigned 21.7 to this ligand)","system":"CCR5-expressing stable cell line","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor, transfected cells and monocytes [PMID:11264152][PMID:10477718]. The mouse pair is projected by orthology.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Both papers read as abstracts only. The affinity row comes from a sentence listing five IC50 values; the curator's note ties 21.7 to this ligand but the sentence itself does not name it.","key_references":[{"PMID":"11264152","why":"Eotaxin is a CCR5 agonist; internalises CCR5"},{"PMID":"10477718","why":"CCR5 competition binding panel of CC chemokines"}],"covers":["LR000186","LR003731"]},"LR003732":{"pair":"CCL11 -> CXCR3","headline":"CCL11 binds CXCR3 with high affinity but does not activate it; reported as a silent binder or antagonist, not an agonist.","interaction_type":"conflicting","direction_and_effect":"CCL11 does not activate CXCR3 and can block IP10-mediated activation in CXCR3-transfected cells [PMID:9660793]. A second paper reports CCL11 binds with high affinity but is neither agonist nor antagonist, and proposes a decoy role [PMID:12884299]. GtoPdb lists an antagonist [DB:GtoPdb].","molecular_requirements":"Chimeras localise the CCL11/CXCL11 shared binding site to the CXCR3 extracellular loops [PMID:12884299].","affinity_potency":[{"value":"pKi 7.2","assay":"competition binding against IP10","system":"CXCR3-transfected cells","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and receptor, recombinant cells [PMID:9660793][PMID:12884299]. The mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"The two papers disagree on whether CCL11 is a weak antagonist or functionally silent. The pair is not an activating pair despite the Stimulatory/Inhibitory flag in the record; both papers are abstract-only.","key_references":[{"PMID":"12884299","why":"High-affinity but functionally silent CCL11 binding to CXCR3"},{"PMID":"9660793","why":"Eotaxin blocks IP10 activation of CXCR3"}],"covers":["LR000187","LR003732"]},"LR002256":{"pair":"CCL14 -> ACKR1","headline":"CCL14 binds the Duffy antigen (ACKR1) with a Ki of 91.8 nM on human erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Binding only; signalling is not reported in our evidence [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 91.8 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes, native receptor [PMID:15358176].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Single paper, competition against CXCL8. Ki is just under the 100 nM cutoff for strong binding used by the authors.","key_references":[{"PMID":"15358176","why":"Duffy antigen chemokine binding profile"}],"covers":["LR002256"]},"LR000195":{"pair":"CCL14 -> CCR1","headline":"Human CCL14 binds and activates CCR1 in recombinant systems; binding is weaker than for MIP-1alpha and activity needs the processed form.","interaction_type":"direct binding","direction_and_effect":"Agonist: CCL14 (HCC-1) specifically activated CCR1 among a receptor panel and induced chemotaxis of monocytes, THP-1 and CCR1-transfected cells [PMID:9687537]. Full agonist in [35S]-GTPgammaS exchange in a second study [PMID:12381680]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Full-length HCC-1 is described as a nonfunctional precursor; the N-terminally truncated HCC-1[9-74] is the potent CCR1/CCR3/CCR5 agonist [PMID:11085751]. No co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"IC50 93 nM","assay":"competition with MIP-1alpha for binding (MIP-1alpha IC50 1.3 nM)","system":"CCR1-transfected cells","cite":"PMID:9687537"},{"value":"pKi 7.4","assay":"displacement of 125I-MIP-1alpha","system":"membranes of Ba/F3-hCCR1 cells","cite":"PMID:12381680"}],"species_and_systems":"All experiments human ligand and human receptor, in transfected cell lines and monocytes; read as abstracts only [PMID:9687537][PMID:12381680][PMID:11085751].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"CCR1 is promiscuous, so binding is not specific to CCL14. Affinity is about 70-fold lower than MIP-1alpha [PMID:9687537]. Which form (full-length vs [9-74]) was tested in the first two papers is not reported in our evidence.","key_references":[{"PMID":"9687537","why":"Identifies CCR1 as a functional HCC-1 receptor; binding and chemotaxis"},{"PMID":"12381680","why":"Binding and GTPgammaS panel at CCR1"},{"PMID":"11085751","why":"Processed HCC-1[9-74] is the active agonist"}],"covers":["LR000195"]},"LR003741":{"pair":"CCL20 -> CXCR3","headline":"Single weak competition-binding observation (Ki 140 nM); no functional evidence for CCL20 at CXCR3 in our dossier.","interaction_type":"direct binding","direction_and_effect":"In a competition-binding table, MIP-3alpha (CCL20) competed with 125I-IP10 on recombinant CXCR3 with 140 +/- 20 (nM Ki) [PMID:9660793]. The curator labelled it a full agonist, as does GtoPdb [DB:GtoPdb], but the paper's agonist data in our excerpt concern IP10, MIG and eotaxin, not CCL20.","molecular_requirements":"Not reported in our evidence beyond CXCR3 expressed in CHO cells.","affinity_potency":[{"value":"Ki 140 nM (140 +/- 20)","assay":"competition binding vs 125I-IP10","system":"CHO cells expressing human CXCR3","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and human receptor in recombinant CHO cells [PMID:9660793]. The mouse pair is projected from human.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Rests on one paper, quoted from a table row read via browser (unverified quote). It is a weak competitor compared with IP10 and MIG (Ki 0.14 and 4.9 nM) [PMID:9660793]. Whether CCL20 activates CXCR3 is not shown in our evidence. Other papers judged were different-entity or abstract-insufficient.","key_references":[{"PMID":"9660793","why":"only paper; Ki 140 nM for CCL20 competition on CXCR3"}],"covers":["LR000214","LR003741"]},"LR007170":{"pair":"CCL22 -> DPP4","headline":"Supported only by a BioGRID biochemical-activity record; no confirmed paper shows ligand-receptor signalling.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated in the BioGRID record; no experiments are shown in our evidence.","localisation_and_range":"Ligand flagged secreted, DPP4 flagged transmembrane receptor [flag].","caveats":"The only support is one BioGRID record typed 'Biochemical Activity' citing [PMID:9933589] [DB:BioGRID]. Judged papers were review-only (1) or abstract-insufficient (3), so none was confirmed.","key_references":[],"covers":["LR007170"]},"LR000249":{"pair":"CCL3 -> CCR5","headline":"CCL3 binds and activates human CCR5 across several independent papers, with GtoPdb full-agonist and PDB structures.","interaction_type":"direct binding","direction_and_effect":"CCL3 binds CCR5 with high affinity and CCR5 cells generate inositol phosphates in response [PMID:8663314]. GtoPdb lists full agonist [DB:GtoPdb]. CCL3 via CCR5 activates Gi proteins and JAK2 independently [PMID:15251452].","molecular_requirements":"CCR5 alone in recombinant cells is sufficient. For binding of CCL3 and RANTES the N-terminus acidic residues and ECL2 residues are required [PMID:11700073]. Structures with both chains are in PDB [DB:PDB 7F1Q][DB:PDB 7F1T].","affinity_potency":[{"value":"pKi 8.0 to 8.9","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human proteins in recombinant cell lines [PMID:8663314][PMID:15251452][PMID:10477718].","localisation_and_range":"CCL3 is flagged as secreted and CCR5 as transmembrane [flag].","caveats":"All papers were read as abstracts only; affinity numbers for CCL3 itself appear only as the GtoPdb range, and MIP-1alpha is often one of several ligands tested. No mouse data in our evidence.","key_references":[{"PMID":"8663314","why":"Cloning of CCR5 with high-affinity binding of MIP-1 alpha"},{"PMID":"11700073","why":"CCR5 residues required for MIP-1 alpha binding"},{"PMID":"15251452","why":"CCL3 signalling via CCR5 to Gi and JAK2"}],"covers":["LR000249"]},"LR000258":{"pair":"CCL5 -> CCR4","headline":"CCL5 (RANTES) binds CCR4 in competition assays (IC50 9.3 nM, human); functional CCR4 evidence is shared with CCR1.","interaction_type":"direct binding","direction_and_effect":"[125I]RANTES binding to human and murine CC CKR-4 was measured by equilibrium competition [PMID:8573157]. In mast cells CCL5 was the only agonist of seven that induced chemotaxis [PMID:12270118]. Reactome states CCR3, 4 and 5 bind CCL5 [DB:Reactome R-HSA-373061].","molecular_requirements":"Not reported in our evidence. Anti-CCR4 alone only partly blocked mast-cell migration; both CCR1 and CCR4 had to be blocked for complete inhibition [PMID:12270118].","affinity_potency":[{"value":"IC50 9.3 +/- 3.0 nM","assay":"competition for [125I]RANTES binding","system":"human CCR4, transfected HL-60 cells","cite":"PMID:8573157"},{"value":"IC50 5.7 +/- 2.6 nM","assay":"competition for [125I]RANTES binding","system":"murine CCR4, transfected HL-60 cells","cite":"PMID:8573157"}],"species_and_systems":"Human and mouse CCR4 in HL-60 cells [PMID:8573157]; human cord blood mast cells [PMID:12270118]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"Both papers were abstract-only reads. The mast-cell data cannot separate CCR4 from CCR1. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"8573157","why":"RANTES binding IC50 to human and murine CCR4"},{"PMID":"12270118","why":"RANTES chemotaxis of mast cells via CCR1 and CCR4"}],"covers":["LR000258","LR003768"]},"LR002265":{"pair":"CCL5 -> CCRL2","headline":"Functional evidence only: CCL5 triggered actin polymerization and MAPK in CRAM-transfected cells, but no calcium or migration; direct binding not shown.","interaction_type":"functional only","direction_and_effect":"CCL5 induced higher actin polymerization and p44/42 MAPK stimulation in CRAM-A- and CRAM-B-transfected cells than in mock cells [PMID:18397265]. Nalm6 cells, lacking known CCL5 receptors, phosphorylate ERK1/2 on CCL5, but no calcium mobilization or migration was seen [PMID:18397265].","molecular_requirements":"Two splice variants, CRAM-A and CRAM-B, both responded [PMID:18397265]; the receptor does not appear to couple to Gi (ERK1/2 phosphorylation not pertussis toxin sensitive) [PMID:18397265].","affinity_potency":[],"species_and_systems":"Human B-cell lines and transfected cells [PMID:18397265].","localisation_and_range":"CCL5 upregulated CRAM surface expression on pre-B-cell lines [PMID:18397265]; the receptor carries receptor and transmembrane flags [flag].","caveats":"Single paper, read in the browser; the quote is unverified and spot-check is pending. No binding data, no affinity, no database records. This is a non-classical receptor.","key_references":[{"PMID":"18397265","why":"CCL5 effects on CCRL2/CRAM in B cells"}],"covers":["LR002265"]},"LR000267":{"pair":"CCL7 -> CCR10","headline":"One abstract reports MCP-3 binding to the cloned receptor called CCR10 with Kd 1 nM; this is the 1997 receptor, whose identity is not clarified here.","interaction_type":"direct binding","direction_and_effect":"The cloned receptor bound MCP-1 and MCP-3 with highest affinity (KD for MCP-3 1 nM) [PMID:9364936]. Function or signalling was not reported in the abstract.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 1 nM","assay":"MCP-3 binding to cloned receptor","system":"cloned human CCR10","cite":"PMID:9364936"}],"species_and_systems":"Human cloned receptor; expression described as primarily placenta and fetal liver [PMID:9364936]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR10 flagged transmembrane receptor [flag].","caveats":"Abstract only, single paper, no database records. The curated receptor-symbol assignment for this 1997 'CCR10' is not discussed in the dossier.","key_references":[{"PMID":"9364936","why":"Cloning of CCR10; MCP-3 KD 1 nM"}],"covers":["LR000267","LR003777"]},"LR000276":{"pair":"CCL8 -> CCR3","headline":"CCL8 binds CCR3 in vitro (QCM, Kd 1.2 x 10-7 M) and drives CCR3-dependent eosinophil responses; weaker chemoattractant than CCL11 and CCL24.","interaction_type":"direct binding","direction_and_effect":"Purified CCL8 bound CCR3 and induced CCR3 internalization on exposure to 100 nM CCL8; its chemotactic effect on CCR3-expressing cells was weaker than CCL11 and CCL24 [PMID:29281969]. In human eosinophils, >95% of the response to MCP-2 and other chemokines was mediated through CCR3, as shown with a blocking antibody [PMID:9005985]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR3 alone suffices in the tested systems; no co-receptor requirement is reported.","affinity_potency":[{"value":"Kd 1.2 x 10-7 M (120 nM)","assay":"quartz crystal microbalance, purified CCL8 with CCR3","system":"in vitro","cite":"PMID:29281969"}],"species_and_systems":"Recombinant CCL8 made in E. coli, species human [PMID:29281969]; primary human eosinophils and CCR3 transfectants [PMID:9005985]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand acting on a transmembrane receptor [flag].","caveats":"The authors note the CCL8 Kd came from QCM while CCL11 and CCL24 values came from SPR, so the methods are not strictly comparable [PMID:29281969]. The eosinophil paper was read as abstract only and shows CCR3 dependence rather than direct binding [PMID:9005985].","key_references":[{"PMID":"29281969","why":"QCM binding Kd, internalization, weaker chemotaxis than CCL11/CCL24"},{"PMID":"9005985","why":"CCR3 antagonist antibody shows >95% of eosinophil response to MCP-2 is CCR3-mediated"}],"covers":["LR000276","LR003786"]},"LR003921":{"pair":"CCN1 -> ITGB5","headline":"CCN1 binds purified alphavbeta5 and drives fibroblast migration through it; one paper supports this pair.","interaction_type":"direct binding","direction_and_effect":"Fibroblast migration to CYR61 was mediated through integrin alpha(v)beta(5), and CYR61 bound directly to purified alpha(v)beta(5) in vitro [PMID:11287419]. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","molecular_requirements":"beta5 pairs with alphav; the effect did not need the carboxyl-terminal domain of CYR61 [PMID:11287419].","affinity_potency":[],"species_and_systems":"Human skin fibroblasts and purified integrin; CYR61 human. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Single paper, abstract only; the database record cites the same paper, so it is not independent. No affinity is reported.","key_references":[{"PMID":"11287419","why":"Direct alphavbeta5 binding and migration role"}],"covers":["LR000424","LR003921"]},"LR002274":{"pair":"CCN2 -> ITGB1","headline":"CTGF acts through an ITGB1-TrkA receptor complex in glioma stem cells; abstract-level, complex rather than ITGB1 alone.","interaction_type":"functional only","direction_and_effect":"In patient-derived glioma tumour-initiating cells, CTGF binding to ITGB1-TrkA receptor complexes led to NF-kappaB activation (relative luciferase activity 0.53 untreated vs 1.87 with CTGF 200 ng/mL), agonist effect [PMID:21771732]. ITGB1/TrkA inhibitors and CTGF shRNA reduced infiltration in vitro and in xenografts [PMID:21771732].","molecular_requirements":"The reported receptor is an ITGB1-TrkA (NTRK1) complex; the paper used inhibitors rather than showing ITGB1 alone is sufficient [PMID:21771732]. The integrin alpha partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Patient-derived human glioma stem-like cells and orthotopic mouse xenografts [PMID:21771732].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. In the paper, reactive astrocytes secrete CTGF [PMID:21771732].","caveats":"Abstract read only. Curators labelled the assay as direct_binding, but the abstract shows binding to a receptor complex inferred from signalling and inhibitor studies. No affinity reported.","key_references":[{"PMID":"21771732","why":"CTGF signalling via ITGB1-TrkA complex in glioma cells"}],"covers":["LR002274","LR005575"]},"LR000384":{"pair":"CCN2 -> ITGB2","headline":"CCN2 is a ligand for integrin alphaMbeta2 (ITGAM/ITGB2) on monocytes; two abstract-level papers, binding shown via the alphaM subunit.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaMbeta2 mediates monocyte adhesion to CCN2 (CTGF) [PMID:12036876]. A GST-alphaM I domain bound CTGF and the CCN2 H2 peptide (TSVKTYRAKFCGV) [PMID:12036876][PMID:12736251].","molecular_requirements":"The binding evidence involves the alphaM I domain, not the beta2 chain; ITGB2 is the partner chain of the alphaMbeta2 heterodimer that mediated adhesion [PMID:12036876]. Whether beta2 alone binds CCN2 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human THP-1 cells, peripheral blood monocytes, and recombinant GST-alphaMI [PMID:12036876][PMID:12736251].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstracts only. Direct binding is to the alphaM I domain (chain-level evidence for ITGAM), so the ITGB2 pair rests on its being the heterodimer partner. One further judged row was abstract_insufficient [PMID:12036876].","key_references":[{"PMID":"12036876","why":"alphaMbeta2-mediated monocyte adhesion to CTGF"},{"PMID":"12736251","why":"Mapping of the CCN2 H2 site binding alphaM I domain"}],"covers":["LR000384","LR003890"]},"LR005073":{"pair":"CD2 -> CD48","headline":"Direct low-affinity CD2-CD48 binding shown with murine proteins; the human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Force measurements showed head-to-head adhesion between murine CD2 and CD48 extracellular domains [PMID:12356317]. UniProt says CD48 interacts with CD2 [DB:UniProt].","molecular_requirements":"Full-length extracellular domains of both proteins suffice; no other subunit is reported in our evidence [PMID:12356317].","affinity_potency":[],"species_and_systems":"Experiments used mouse proteins (surface force apparatus); the human record is ortholog-inferred [PMID:12356317].","localisation_and_range":"Both flagged membrane receptors [flag]; the bond is low-affinity and needs receptor mobility for avidity [PMID:12356317].","caveats":"Human support is only by ortholog inference from murine data. No affinity value reported here. Abstract-only read.","key_references":[{"PMID":"12356317","why":"Direct force measurement of murine CD2-CD48 adhesion"}],"covers":["LR001705","LR005073"]},"LR001707":{"pair":"CD200 -> CD200R1L","headline":"Thin: evidence concerns CD200R family and CD200R alleles, not CD200R1L specifically; projected by orthology.","interaction_type":"functional only","direction_and_effect":"Recombinant CD200Fc bound COS7 cells transfected with all CD200R isoforms [PMID:15187158]. A second CD200R allele also bound CD200 and the CD200/CD200R interaction was blocked by mAb OX131 [PMID:23691022].","molecular_requirements":"Not reported in our evidence for CD200R1L.","affinity_potency":[],"species_and_systems":"The human pair is ortholog-inferred. Experiments used COS7 transfectants (FACS) [PMID:15187158] and 2B4 Reay cells with SPR using mouse CD200 [PMID:23691022]; curators labelled one as mouse and one as human.","localisation_and_range":"CD200R1L has no secreted or transmembrane flag in our entity record [flag]; localisation not reported in our evidence.","caveats":"Both papers were abstract-level reads and neither names CD200R1L; the link rests on CD200R family and allele statements. Treat as an inference, not a direct test.","key_references":[{"PMID":"15187158","why":"CD200 binds all CD200R family isoforms"},{"PMID":"23691022","why":"CD200R alleles bind CD200"}],"covers":["LR001707"]},"LR002283":{"pair":"CD24 -> SELE","headline":"Direct SPR binding of CD24 to E-selectin with nM affinity, and blocked MCF-7 rolling with anti-CD24; one paper.","interaction_type":"direct binding","direction_and_effect":"CD24 on MCF-7 cells mediates rolling on E-selectin-coated surfaces; rolling was completely blocked by anti-CD24 [PMID:21207944].","molecular_requirements":"Binding is Ca2+-dependent in a microsphere flow assay; actin filaments are involved in rolling [PMID:21207944].","affinity_potency":[{"value":"KD 3.4 +/- 0.7 nM","assay":"surface plasmon resonance (BIAcore)","system":"recombinant CD24 and E-selectin","cite":"PMID:21207944"}],"species_and_systems":"Human MCF-7 breast cancer cells and recombinant proteins [PMID:21207944].","localisation_and_range":"Both partners flagged transmembrane [flag]; cell-surface rolling adhesion.","caveats":"Single paper, abstract-level read with some full-text excerpts; no confirming second primary paper.","key_references":[{"PMID":"21207944","why":"SPR and rolling assay for CD24-E-selectin"}],"covers":["LR002283"]},"LR005082":{"pair":"CD28 -> CD80","headline":"Recombinant soluble CD80 binds CD28-Ig in a direct binding assay; evidence is one abstract-only paper plus databases.","interaction_type":"direct binding","direction_and_effect":"Recombinant s1CD80 bound recombinant CD28-Ig and CD152-Ig, and recombinant sCD80 inhibited the mixed lymphocyte reaction and T-cell proliferation, suggesting a soluble decoy/inhibitory role [PMID:17953528]. UniProt describes CD28 engagement by CD80 or CD86 as stimulating T-cell proliferation and cytokine production [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond the soluble s1CD80 isoform (lacks the transmembrane domain) binding CD28-Ig [PMID:17953528]. Reactome lists CD28 homodimer binding B7-1 homodimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and human T cells [PMID:17953528]; the mouse pair is projected from human evidence.","localisation_and_range":"CD80 is flagged secreted and transmembrane [flag]; the paper shows a naturally occurring soluble form in serum (0 to 1 mg/l) [PMID:17953528]. Membrane form acts by contact [DB:Reactome, plasma membrane complex].","caveats":"Only abstract read; the paper's focus is soluble CD80, so membrane-bound CD80 binding to CD28 is supported mainly by databases (BioGRID, IntAct, Reactome). No affinity reported.","key_references":[{"PMID":"17953528","why":"Recombinant soluble CD80 binds CD28-Ig and inhibits T-cell activation"}],"covers":["LR001715","LR005082"]},"LR001716":{"pair":"CD28 -> CD86","headline":"Human CD86 binds CD28 with avidity similar (within about 2- to 3-fold) to CD80; one abstract-only paper plus databases.","interaction_type":"direct binding","direction_and_effect":"CD86 binds the same receptors (CD28 and CTLA-4) as CD80 and keeps similar overall receptor binding and T-cell costimulatory properties [PMID:7534620]. UniProt: CD28 engagement by CD80 or CD86 increases T-cell proliferation and cytokine production [DB:UniProt].","molecular_requirements":"Not reported in our evidence; Reactome lists CD28 homodimer binding B7-2 monomer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:7534620]; mouse pair projected from human evidence.","localisation_and_range":"Both partners are flagged membrane-bound, non-secreted [flag]; contact-dependent signalling.","caveats":"Abstract only; the paper's main quantitative contrast concerns CTLA-4 (CD80 binds much better than CD86), not CD28. No affinity values for CD28 reported in our evidence. Databases include IntAct SPR and FACS records.","key_references":[{"PMID":"7534620","why":"Compares CD86 and CD80 binding to CD28 and CTLA-4"}],"covers":["LR001716","LR005083"]},"LR000285":{"pair":"CD40LG -> ITGAM","headline":"CD40L binds the integrin ITGAM (Mac-1) in two papers read as abstracts; one is direct binding, one an in vivo transplant hint.","interaction_type":"direct binding","direction_and_effect":"Flow cytometry, radioactive binding assays and immunoprecipitation showed CD40L interacting with Mac-1, giving Mac-1-dependent adhesion, migration and myeloperoxidase release in vitro; CD40/LDLR double-deficient mice had no smaller lesions, and Mac-1 inhibition reduced lesions, suggesting a CD40-independent route [PMID:17372166]. In a murine allograft model CD154 blockade outperformed CD40 blockade, raising the possibility of a second receptor [PMID:32149455].","molecular_requirements":"The binding evidence is for the Mac-1 (alphaM:beta2) heterodimer, so ITGAM alone is not shown to suffice [PMID:17372166].","affinity_potency":[],"species_and_systems":"Curator-recorded species are human for both partners; the abstracts also use mice (atherosclerosis, thioglycolate peritonitis, allograft) [PMID:17372166][PMID:32149455]. Both human and mouse interactions are listed, neither ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; paper localisation details not reported in our evidence.","caveats":"Both papers read as abstracts only. The allograft paper's abstract is truncated, so its ITGAM result is not shown in the dossier text beyond the evidence sentence [PMID:32149455]. Three further papers were judged abstract_insufficient and are not shown.","key_references":[{"PMID":"17372166","why":"Binding assays showing CD40L-Mac-1 interaction"},{"PMID":"32149455","why":"In vivo transplant evidence for a second CD154 receptor"}],"covers":["LR000285","LR003795"]},"LR002292":{"pair":"CD40LG -> ITGB3","headline":"CD40L binding to integrin beta3 (alphaIIbbeta3 and alphavbeta3) is supported by several abstract-level binding papers and UniProt.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble CD40L bound purified alphaIIbbeta3 and activated platelets in a beta3-dependent manner, induced platelet spreading and promoted aggregation; CD40L lacking the KGD motif did not restore thrombosis in CD40L-null mice, and CD40-deficient mice thrombosed normally [PMID:11875495]. Integrin alphavbeta3 bound CD40L in a KGD-independent manner [PMID:31331973]. CD154 binds alphaIIbbeta3 with ~4-fold higher affinity than alpha5beta1 [PMID:22461623]. UniProt lists ITGAV:ITGB3 as a receptor for CD40LG [DB:UniProt].","molecular_requirements":"Evidence is for beta3 heterodimers (alphaIIb:beta3, alphav:beta3). Mutants lacking binding to CD40 or alphaIIbbeta3 map to distinct CD154 residues [PMID:22461623]. Soluble CD40L also activates alphavbeta3 in cell-free conditions [PMID:33571526].","affinity_potency":[],"species_and_systems":"Human and mouse platelets, purified integrin, mouse thrombosis model [PMID:11875495]; human cells in later papers [PMID:31331973][PMID:33571526]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; recombinant soluble CD40L used [PMID:11875495].","caveats":"All shown papers are abstract-only; no numeric affinity for this pair reported. Four more confirmed papers are not shown.","key_references":[{"PMID":"11875495","why":"Binding of soluble CD40L to purified alphaIIbbeta3 and platelets"},{"PMID":"31331973","why":"alphavbeta3 as a CD40L receptor"},{"PMID":"22461623","why":"alphaIIbbeta3 vs alpha5beta1 affinity"}],"covers":["LR002292","LR005591"]},"LR005091":{"pair":"Cd52 -> Siglecg","headline":"Mouse pair is ortholog-inferred; the underlying papers study human Siglec-10, not mouse Siglec-G.","interaction_type":"functional only","direction_and_effect":"Soluble CD52 suppresses T cells via the inhibitory Siglec-10 receptor, and CD52-Fc binding to Siglec-10 requires HMGB1 [PMID:29997173]. In NOD mice, transferring lymphocytes depleted of CD52(hi) cells accelerated diabetes onset [PMID:23685786].","molecular_requirements":"Evidence concerns Siglec-10: sialylated CD52 glycan (alpha-2,3 linkage) and HMGB1 Box B are required [PMID:29997173]. Mouse Siglec-G requirements are not reported in our evidence.","affinity_potency":[{"value":"565 nM","assay":"SPR estimated Kd, CD52-Fc to Siglec-10-Fc (human receptor)","system":"recombinant Fc fusions","cite":"PMID:29997173"}],"species_and_systems":"Binding data are with Siglec-10 (human PBMC and recombinant protein) [PMID:29997173]; the only mouse evidence is NOD mouse CD52(hi) cell depletion, with no Siglec-G readout [PMID:23685786].","localisation_and_range":"Soluble CD52 is released by phospholipase C [PMID:23685786]; annotation flag marks the mouse ligand secreted [flag].","caveats":"No paper in the dossier names mouse Siglec-G; the mapping rests on projection from Siglec-10. Papers are abstract-level for 23685786.","key_references":[{"PMID":"29997173","why":"Mechanism of CD52-Siglec-10 binding (human receptor)"},{"PMID":"23685786","why":"NOD mouse CD52(hi) T cell suppression"}],"covers":["LR005091"]},"LR001725":{"pair":"CD58 -> CD2","headline":"Classic adhesion pair with binding, blocking and structural database evidence.","interaction_type":"direct binding","direction_and_effect":"CD58 is a ligand for CD2; CD2+ cells bind immobilised CD58 [PMID:1377404]. CD2 or CD58 antibodies inhibited IL-12-induced T cell proliferation and IFN-gamma production without affecting IL-12 response itself [PMID:7544396]. Zebrafish Cd58 and Cd2 co-immunoprecipitated and soluble Cd2 competed, and blockade impaired CD4+ T and B cell activation [PMID:29904386].","molecular_requirements":"CD58 and CD59 binding sites on CD2 overlap but are not identical [PMID:1377404]. Complex structure in PDB and BioGRID co-crystal record [DB:PDB 1QA9][DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human cells with purified CD58 [PMID:1377404]; human T cells [PMID:7544396]; zebrafish in vivo model, since no murine Cd58 homolog exists [PMID:29904386].","localisation_and_range":"Both are transmembrane by flags [flag]; adhesion between cells (contact).","caveats":"Three papers are abstract-level. No affinity value reported. Two further rows are pending and one abstract-insufficient (not shown). Reactome, IntAct and UniProt agree [DB:Reactome][DB:IntAct][DB:UniProt].","key_references":[{"PMID":"1377404","why":"Purified CD58 binding to CD2+ cells"},{"PMID":"29904386","why":"Co-IP and competition in zebrafish, in vivo function"},{"PMID":"7544396","why":"Blocking antibodies to CD2 or CD58 in human T cells"}],"covers":["LR001725"]},"LR001734":{"pair":"CD96 -> NECTIN1","headline":"Human nectin-1 binds CD96 directly with low affinity (SPR, ELISA); mouse CD96 also binds nectin-1.","interaction_type":"direct binding","direction_and_effect":"Human CD96 binds the nectin-1 V-domain; this affinity is lower than nectin-1 for nectin-3 or itself, and lower than CD96 for CD155 [PMID:30759143]. Functional effect on NK cells not established in this paper [PMID:30759143]. Mouse CD96 also binds nectin-1 [PMID:17971293].","molecular_requirements":"Binding site is on the V-domain of nectin-1; SPR gave similar KD for ectodomain and V-domain; the CD96 isoform 2 ectodomain was used [PMID:30759143].","affinity_potency":[{"value":"KD 2.4 \u03bcM","assay":"surface plasmon resonance, CD96 ectodomain over nectin-1","system":"recombinant human proteins","cite":"PMID:30759143"}],"species_and_systems":"Human recombinant proteins (ELISA, SPR) [PMID:30759143]; mouse CD96 in a separate paper [PMID:17971293]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound partners; likely contact-dependent.","caveats":"Weak affinity; CD155 may outcompete nectin-1 for CD96 [PMID:30759143]. The mouse paper was read as abstract only [PMID:17971293].","key_references":[{"PMID":"30759143","why":"Human CD96-nectin-1 binding, SPR and V-domain mapping"},{"PMID":"17971293","why":"Mouse CD96 binds nectin-1"}],"covers":["LR001734","LR005099"]},"LR005604":{"pair":"CDH10 -> CDH6","headline":"Type II cadherin heterophilic pair: cadherin-6 analyte bound a cadherin-10 surface strongly in SPR (mouse proteins).","interaction_type":"direct binding","direction_and_effect":"On cadherin-10-coated surfaces, cadherin-6 analyte gave the strongest response, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 share a specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002306","LR005604"]},"LR005613":{"pair":"CDH4 -> CDH4","headline":"R-cadherin homophilic adhesion is supported by one 1991 abstract-level report in chicken cells; weak evidence.","interaction_type":"functional only","direction_and_effect":"Cells expressing R-cadherin adhere to N-cadherin cells but form homotypic clusters in chimeric aggregates, indicating homotypic preference [PMID:1712604].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chicken R-cadherin cDNA cloned from retina; curators record mouse as the experimental species while the abstract concerns chicken, and both human and mouse pairs are ortholog-inferred [PMID:1712604].","localisation_and_range":"Membrane-bound, contact-dependent [flag].","caveats":"The evidence sentence is a whole-abstract summary rather than a homophilic binding result, and the human row was propagated from the mouse row, not re-read. Abstract only.","key_references":[{"PMID":"1712604","why":"R-cadherin cloning and homotypic adhesion"}],"covers":["LR002315","LR005613"]},"LR002319":{"pair":"CDH6 -> CDH9","headline":"Type II cadherin heterophilic pair: cadherin-6 binds cadherin-9 in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On cadherin-6 surfaces cadherin-6 analyte was strongest, followed by binding of cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002319","LR005617"]},"LR002328":{"pair":"CEACAM16 -> TECTB","headline":"Abstract reports CEACAM16 interacts with TECTB; co-IP in transfected cells per the paper's Results.","interaction_type":"direct binding","direction_and_effect":"CEACAM16 is shown to interact with TECTB, suggesting it may stabilise TECTA-TECTB interactions [PMID:25080593]. UniProt lists TECTA and TECTB as CEACAM16 interactors [DB:UniProt].","molecular_requirements":"Also interacts with TECTA; whether TECTB alone suffices is not reported.","affinity_potency":[],"species_and_systems":"Mouse tectorial membrane context in the paper [PMID:25080593]. The human pair is ortholog-inferred and the mouse pair is direct.","localisation_and_range":"Secreted glycoproteins in the tectorial membrane of the inner ear [PMID:25080593].","caveats":"Abstract-level read; the assay is not detailed in this row. Matrix-protein interaction.","key_references":[{"PMID":"25080593","why":"CEACAM16-TECTB interaction in tectorial membrane"}],"covers":["LR002328","LR005622"]},"LR005622":{"pair":"CEACAM16 -> TECTB","headline":"Abstract reports CEACAM16 interacts with TECTB; co-IP in transfected cells per the paper's Results.","interaction_type":"direct binding","direction_and_effect":"CEACAM16 is shown to interact with TECTB, suggesting it may stabilise TECTA-TECTB interactions [PMID:25080593]. UniProt lists TECTA and TECTB as CEACAM16 interactors [DB:UniProt].","molecular_requirements":"Also interacts with TECTA; whether TECTB alone suffices is not reported.","affinity_potency":[],"species_and_systems":"Mouse tectorial membrane context in the paper [PMID:25080593]. The human pair is ortholog-inferred and the mouse pair is direct.","localisation_and_range":"Secreted glycoproteins in the tectorial membrane of the inner ear [PMID:25080593].","caveats":"Abstract-level read; the assay is not detailed in this row. Matrix-protein interaction.","key_references":[{"PMID":"25080593","why":"CEACAM16-TECTB interaction in tectorial membrane"}],"covers":["LR002328","LR005622"]},"LR002337":{"pair":"CEMIP -> LRP1","headline":"CEMIP is one of ten direct LRP1 ligands confirmed in cartilage by one study; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Direct binding of CEMIP to purified LRP1 was confirmed, and LRP1 affinity correlated with endocytosis rate; conditional Lrp1 knockout mice show LRP1 regulates these ligands in cartilage [PMID:36028175]. Effect is labelled agonist, but the abstract describes endocytic handling rather than signalling [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, purified LRP1, LRP1-deficient cells and a mouse conditional knockout [PMID:36028175]; mouse pair is ortholog-inferred.","localisation_and_range":"CEMIP is flagged secreted [flag]; ligand taken up by cell-surface LRP1 endocytosis [PMID:36028175].","caveats":"Abstract only; no affinity values given; no database records. Part of a systematic ligandome screen with nine companion ligands.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding of CEMIP among ten chondrocyte ligands"}],"covers":["LR002337","LR005626"]},"LR000294":{"pair":"CFH -> ITGAM","headline":"Factor H binds neutrophil Mac-1 (CD11b/CD18); evidence is for the heterodimer, from one 1998 abstract.","interaction_type":"direct binding","direction_and_effect":"Neutrophil adhesion to factor H was blocked by anti-CD11b and anti-CD18 antibodies, and factor H-Sepharose affinity purification with immunoprecipitation identified Mac-1 as a factor H-binding receptor; classed as agonist [PMID:9558116]. Surface-bound factor H increased neutrophil hydrogen-peroxide generation 2-5-fold [PMID:9558116].","molecular_requirements":"The evidence concerns the Mac-1 heterodimer (CD11b/CD18); the CD11b chain alone is not shown to suffice [PMID:9558116]. Adhesion needed divalent metal ions [PMID:9558116].","affinity_potency":[],"species_and_systems":"Human neutrophils and purified human factor H [PMID:9558116]. Adhesion was neutrophil-specific, not seen with eosinophils.","localisation_and_range":"Secreted factor H acts as an adhesion ligand and may tether tissue through glycosaminoglycans [PMID:9558116].","caveats":"Abstract only; no affinity; the same paper supports both the ITGAM and ITGB2 rows. No database records.","key_references":[{"PMID":"9558116","why":"Factor H as a Mac-1 adhesion ligand on human neutrophils"}],"covers":["LR000294"]},"LR001743":{"pair":"CFP -> NCR1","headline":"Properdin (CFP) binds the NK receptor NKp46 and NKp46 was needed for CFP benefit in mouse Neisseria infection.","interaction_type":"direct binding","direction_and_effect":"Serum-purified human CFP bound human NKp46-Fc but not control NKp30-Fc; classed as agonist [PMID:28480349]. CFP treatment benefit in mouse Neisseria meningitidis infection depended on NKp46 and group-1 NKp46+ ILCs [PMID:28480349].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant and serum proteins for binding; mouse in vivo infection model [PMID:28480349]. The mouse pair is listed separately.","localisation_and_range":"CFP is a soluble plasma glycoprotein (secreted flag [flag]) acting on NK and ILC membrane NKp46 [PMID:28480349].","caveats":"Full text read; no affinity in excerpts. IntAct lists a fluorescence-activated cell sorting record [DB:IntAct]. One further confirmed row not shown.","key_references":[{"PMID":"28480349","why":"CFP identified as an NKp46 ligand with in vivo validation"}],"covers":["LR001743","LR005103"]},"LR003804":{"pair":"CGA -> LHCGR","headline":"The CGA alpha chain contacts LHCGR; LH and hCG bind with high affinity, but receptor specificity comes from the beta chain.","interaction_type":"direct binding","direction_and_effect":"Cross-linking showed hCG alpha bound the LH/CG receptor exodomain [PMID:10342833]. LH and hCG are full agonists; hCG and LH displaced radiolabeled hCG with ED50 4.3 and 4.8 ng/ml and induced cAMP [PMID:1922095] [PMID:12727981]. Exon 10 deletion impaired LH but not hCG action [PMID:12727981].","molecular_requirements":"Ligands are heterodimers of CGA with LHB (LH) or a CGB product (hCG); recombinant FSH, with the same CGA, was not effective, so the beta chain determines specificity [PMID:1922095].","affinity_potency":[{"value":"Kd 1.2x10^-10 M","assay":"radioligand binding, 125I-hCG","system":"transfected human 293 cells expressing human LH receptor","cite":"PMID:1922095"},{"value":"ED50 4.3 ng/ml (hCG), 4.8 ng/ml (LH)","assay":"displacement of 125I-hCG","system":"transfected human 293 cells","cite":"PMID:1922095"},{"value":"pKd 9.899999618530273 to 11.800000190734863","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:1922095"}],"species_and_systems":"Human proteins in cell lines [PMID:1922095] [PMID:12727981]. Equine, rat and ovine LH/CG failed to displace hCG on the human receptor [PMID:1922095]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted hormone acting on transmembrane receptor [flag].","caveats":"Abstract-only papers. CGA alone is not the specific ligand. Structures: [DB:PDB 7FIG] [DB:PDB 7FIH] [DB:PDB 7FII]; [DB:BioGRID] [DB:GtoPdb]. Two further confirmed rows not shown.","key_references":[{"PMID":"1922095","why":"Kd and displacement data for human LH/hCG on human LHR"},{"PMID":"10342833","why":"hCG alpha cross-links to the LHR exodomain"},{"PMID":"12727981","why":"Binding vs activation dissociated by exon 10 deletion"}],"covers":["LR000297","LR003804"]},"LR010734":{"pair":"CHAD -> ITGA2:ITGB1","headline":"Chondroadherin binds the integrin alpha2beta1 heterodimer on cells; one 1997 paper, bovine system.","interaction_type":"direct binding","direction_and_effect":"Chondroadherin-mediated adhesion of chondrocytes was partially inhibited by an anti-beta1 antibody and was cation dependent; alpha2beta1 was identified by immunoprecipitation after affinity purification [PMID:9281592].","molecular_requirements":"Complex of ITGA2 and ITGB1 [flag]; adhesion needed Mg2+ or Mn2+ but not Ca2+. Adhesion decreased by 2/3 with 100 \u03bcg/ml anti-beta1 antibody [PMID:9281592].","affinity_potency":[],"species_and_systems":"Bovine articular chondrocytes in adhesion assays and affinity purification (as labelled for this row) [PMID:9281592].","localisation_and_range":"Matrix protein chondroadherin flagged secreted [flag]; the integrin is cell-surface.","caveats":"Evidence is from a single 1997 paper read as abstract (full-text excerpts available). Antibody inhibition was partial; no affinity reported.","key_references":[{"PMID":"9281592","why":"Cation-dependent adhesion, anti-beta1 blocking, affinity purification"}],"covers":["LR010734"]},"LR002346":{"pair":"CKLF -> CCR4","headline":"CKLF1 acts as a functional, non-canonical CCR4 agonist in one human transfected-cell study; no direct binding measurement reported.","interaction_type":"functional only","direction_and_effect":"CKLF1 induced chemotaxis and calcium flux in CCR4-transfected cells, with cross-desensitisation of TARC/CCL17 responses, consistent with agonism at CCR4 [PMID:16137713]. Desensitisation was asymmetric: CKLF1 fully desensitised a later TARC/CCL17 response, but TARC/CCL17 only partly desensitised CKLF1 [PMID:16137713]. Pertussis toxin abolished chemotaxis, indicating Gi/o coupling [PMID:16137713].","molecular_requirements":"CCR4 alone in transfected cells was sufficient; no co-receptor requirement is reported in our evidence. CCR6-transfected cells did not respond to CKLF1 [PMID:16137713].","affinity_potency":[],"species_and_systems":"Human CKLF1 and human CCR4 in transfected HEK293 cells; the mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"CKLF is flagged secreted and CCR4 a transmembrane receptor [flag]; secreted ligand acting on a membrane receptor.","caveats":"Single primary paper; functional readouts only, no binding affinity. UniProt also lists CKLF as binding CCR4, citing the same paper [DB:UniProt]. Mouse evidence is not independent.","key_references":[{"PMID":"16137713","why":"Chemotaxis, calcium flux and desensitisation showing CKLF1 is a CCR4 agonist"}],"covers":["LR002346","LR005629"]},"LR005631":{"pair":"CLEC1B -> PDPN","headline":"CLEC-2 (CLEC1B) and podoplanin bind directly, with crystal structure and flow cytometry support; the biological direction is podoplanin to CLEC-2.","interaction_type":"direct binding","direction_and_effect":"Podoplanin is the physiological ligand activating platelet CLEC-2, so the stored direction CLEC1B -> PDPN is reversed [PMID:17616532]. Podoplanin induced platelet aggregation, and recombinant CLEC-2 inhibited aggregation induced by podoplanin-expressing tumour cells or lymphatic endothelial cells [PMID:17616532]. UniProt says PDPN binding triggers CLEC1B activation in platelets [DB:UniProt].","molecular_requirements":"Binding depends on sialic acid on podoplanin O-glycans [PMID:17616532]. Crystal structures show both podoplanin and rhodocytin bind the noncanonical side face of CLEC-2 [PMID:25458834] [DB:PDB 3WSR].","affinity_potency":[],"species_and_systems":"Human proteins; platelets and flow cytometry [PMID:17616532]. Mouse pair is ortholog-inferred.","localisation_and_range":"PDPN is membrane-bound (juxtacrine, e.g. on tumour or lymphatic endothelial cells) per the paper [PMID:17616532]; CLEC1B is annotated secreted in the entity flags, which conflicts with its platelet-receptor role [flag].","caveats":"Both papers abstract only. No affinity in our evidence.","key_references":[{"PMID":"17616532","why":"Podoplanin-CLEC-2 association; platelet aggregation"},{"PMID":"25458834","why":"Crystal structures of CLEC-2 with podoplanin"}],"covers":["LR002349","LR005631"]},"LR005109":{"pair":"CLEC4G -> LAG3","headline":"LSECtin (CLEC4G) reported to interact with LAG-3 in melanoma; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"LSECtin interacted with LAG-3, and LAG-3 blockade restored IFN\u03b3 secretion reduced by melanoma LSECtin expression, so the effect is inhibitory on T cells [PMID:24769443].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Paper used B16 melanoma cells and mice; the dossier records ligand and receptor species as human. The mouse pair is listed as a separate interaction; the human pair is ortholog-inferred. Abstract only [PMID:24769443].","localisation_and_range":"CLEC4G is not flagged secreted [flag]; presented on melanoma cell surface [PMID:24769443], so contact-dependent.","caveats":"Only the word 'interacted' is available; the assay type, affinity and whether binding is direct are not shown in the abstract, though labelled direct_binding. Single paper.","key_references":[{"PMID":"24769443","why":"LSECtin interacts with LAG-3; LAG-3 blockade restores IFN\u03b3"}],"covers":["LR001751","LR005109"]},"LR002355":{"pair":"CLSTN3 -> NRXN2","headline":"Calsyntenin-3 binds \u03b2-neurexins as a synaptic adhesion pair; isoform-specific evidence for NRXN2 is not shown (abstract only).","interaction_type":"direct binding","direction_and_effect":"Clstn3 is a postsynaptic adhesion molecule that induces presynaptic differentiation via presynaptic neurexins; \u03b2-Nrxns directly interact via their LNS domain with Clstn3 and Clstn3 cadherin domains [PMID:32434929].","molecular_requirements":"Splice site 4 (SS4) insert-positive \u03b2-Nrxn variants, but not insert-negative variants, reversed the impaired Clstn3 synaptogenic activity; Clstn3 selectively formed complexes with SS4-positive Nrxns in vivo [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; hippocampal neurons and Clstn3 conditional knockout mice (mouse pair is the non-inferred one) [PMID:32434929]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners transmembrane/adhesion proteins (not flagged secreted [flag]); trans-synaptic, contact-dependent [PMID:32434929].","caveats":"Abstract only. The evidence sentence names \u03b2-Nrxns collectively, not NRXN2 specifically; the paper title mentions both \u03b1- and \u03b2-neurexins but gene-level assignment is not shown. Earlier debate on whether Nrxns bind Clstn3 directly is noted [PMID:32434929].","key_references":[{"PMID":"32434929","why":"\u03b2-neurexin LNS domain binds Clstn3; SS4-dependent synaptogenic activity"}],"covers":["LR002355","LR005635"]},"LR005640":{"pair":"CLU -> TREM2","headline":"Clusterin/apoJ is a TREM2 ligand from a protein microarray screen with uptake assays; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CLU/APOJ was identified as a TREM2 ligand; wild-type TREM2 overexpression enhanced CLU uptake in heterologous cells; Trem2 knockout microglia showed reduced CLU internalization [PMID:27477018].","molecular_requirements":"Binding was abolished or reduced by disease-associated TREM2 mutations [PMID:27477018]. TYROBP/DAP12 role is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"Protein microarray, heterologous cells, Trem2-knockout microglia and human macrophages [PMID:27477018].","localisation_and_range":"Clusterin is flagged secreted [flag]; TREM2 is flagged both secreted and receptor [flag].","caveats":"Abstract only; no affinity given. UniProt and BioGRID cite the same paper [DB:UniProt Q9NZC2][DB:BioGRID 2593475]. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"27477018","why":"TREM2 binds apolipoproteins including CLU; mutations reduce binding and uptake"}],"covers":["LR002360","LR005640"]},"LR003813":{"pair":"CNTF -> IL6ST","headline":"CNTF signals through a CNTFR/gp130/LIFR complex; gp130 is a shared signalling chain, so support is for the complex rather than direct CNTF-gp130 binding.","interaction_type":"functional only","direction_and_effect":"CNTF acts as an agonist; GtoPdb lists it as Agonist [DB:GtoPdb]. Signalling through the complex was shown in human receptor reconstitution and cell assays [PMID:10966616][PMID:16051226].","molecular_requirements":"CNTF signals through a receptor complex of CNTFR with gp130 (IL6ST) and LIFR [PMID:10966616][PMID:16051226]. gp130 is shared among CNTF, LIF and OSM signalling [PMID:16051226]. CNTFR is the non-signalling alpha chain [PMID:10966616]. UniProt states ligand binding to CNTFR induces dimerization of IL6ST/gp130 and LIFR [DB:UniProt]. A PDB structure holds chains of CNTFR and LIFR proteins, not gp130 [DB:PDB 8D74].","affinity_potency":[],"species_and_systems":"Human proteins in reconstituted receptor complex and cell signalling [PMID:10966616][PMID:16051226]. The mouse pair is inferred from human evidence.","localisation_and_range":"CNTF is flagged secreted and IL6ST a transmembrane receptor [flag].","caveats":"No direct CNTF-gp130 binding is shown; gp130 acts as a signalling chain within a complex and is shared across cytokines. Both confirmed papers were read as abstracts only. A user scoring this pair should require CNTFR and LIFR too.","key_references":[{"PMID":"16051226","why":"CNTF signalling needs LIFR N-terminal domain within gp130/LIFR complex"},{"PMID":"10966616","why":"Describes CNTFR with gp130 and LIFR complex"}],"covers":["LR000307","LR003813"]},"LR002364":{"pair":"CNTN1 -> NFASC","headline":"Direct contactin-1 / neurofascin-155 adhesion complex supported by crystal structures and a cell-aggregation assay.","interaction_type":"direct binding","direction_and_effect":"Contactin-1 and neurofascin-155 interact across cells to form paranodal myelin-axon junctions [PMID:36329006]. Cells expressing human CNTN1/CASPR1 aggregated with Nfasc155-expressing cells, and patient Nfasc155 variants (p.P705T, p.P939Ter) abolished this interaction [PMID:31501903].","molecular_requirements":"The Nfasc155 isoform is the glial partner; Nfasc186 and Nfasc140 are axonal isoforms [PMID:31501903]. In the aggregation assay CNTN1 was co-expressed with CASPR1 [PMID:31501903]. Reactome lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome]. Complexed structures reveal competing and complementary interfaces, glycosylation and splice-variant effects [PMID:36329006].","affinity_potency":[],"species_and_systems":"Crystal structures [PMID:36329006]; transfected N2A cell aggregation with human proteins [PMID:31501903].","localisation_and_range":"Both are cell-surface proteins forming a trans adhesion junction (paper text) [PMID:36329006]; this is contact-dependent, not diffusible.","caveats":"Structure paper read as abstract only. The cell assay used CNTN1 together with CASPR1, so CNTN1-alone contribution is not separated. Mouse pair is inferred from human evidence.","key_references":[{"PMID":"36329006","why":"Crystal structures of contactin-1 / neurofascin-155 complex"},{"PMID":"31501903","why":"Aggregation assay; patient variants abolish binding"}],"covers":["LR002364","LR005644"]},"LR001752":{"pair":"CNTN1 -> NOTCH1","headline":"F3/contactin reported as a functional Notch ligand in oligodendrocyte cells; abstract-only evidence plus database records.","interaction_type":"functional only","direction_and_effect":"F3/contactin acts as a functional ligand of Notch, signalling in OLN-93 oligodendrocyte cells and precursors [PMID:14567914].","molecular_requirements":"Not reported beyond the abstract. BioGRID lists affinity capture-Western and Reactome a CNTN1:NOTCH1:DTX complex [DB:BioGRID][DB:Reactome].","affinity_potency":[],"species_and_systems":"OLN-93 oligodendrocyte cell line; ligand and receptor species not specified in the curation row [PMID:14567914]. Human pair is ortholog-inferred.","localisation_and_range":"CNTN1 is flagged transmembrane [flag]; the paper calls F3 GPI-linked [PMID:14567914].","caveats":"Abstract-only read; the paper does not distinguish NOTCH1 from other Notch paralogs in our evidence; species not specified.","key_references":[{"PMID":"14567914","why":"F3/contactin as functional Notch ligand"}],"covers":["LR001752","LR005110"]},"LR010671":{"pair":"CNTN2 -> CNTN2:CNTNAP2","headline":"In vivo knockout evidence that TAG-1 is needed for axonal Caspr2 at juxtaparanodes; the complex target is a curated composite.","interaction_type":"functional only","direction_and_effect":"Without TAG-1, axonal Caspr2 did not accumulate at juxtaparanodes and enrichment of shaker-type K+ channels was lost [PMID:12975355].","molecular_requirements":"The receptor entity is the CNTN2:CNTNAP2 complex; the paper shows TAG-1 association with Caspr2 is required for juxtaparanodal organisation [PMID:12975355]. BioGRID lists affinity capture-Western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"TAG-1 knockout mice, myelinated axons [PMID:12975355].","localisation_and_range":"Juxtaparanodes of myelinated axons; CNTN2 flagged secreted [flag].","caveats":"Loss-of-function phenotype in an abstract-only read; does not show direct binding to the complex.","key_references":[{"PMID":"12975355","why":"TAG-1 knockout disrupts Caspr2 localisation"}],"covers":["LR010671"]},"LR002373":{"pair":"CNTNAP1 -> NFASC","headline":"The neurofascin NF155 extracellular domain binds the CASPR-contactin complex on cells and from brain lysate; the CASPR chain alone is not isolated.","interaction_type":"direct binding","direction_and_effect":"NF155 extracellular domain binds specifically to cells expressing the paranodin/Caspr-contactin complex and to that complex from brain lysates in vitro; NF155 antibodies and the extracellular domain inhibit myelination in cocultures [PMID:11839274].","molecular_requirements":"The binding is to the Caspr-contactin cis complex, so contactin is part of the receptor unit; whether Caspr alone suffices is not reported in our evidence [PMID:11839274]. Reactome lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome R-HSA-373682].","affinity_potency":[],"species_and_systems":"Transfected cells, brain lysate and myelinating cocultures; species not reported in our evidence [PMID:11839274].","localisation_and_range":"Both partners are annotated non-secreted [flag]; the paper frames this as a trans axon-glia interaction at paranodal junctions [PMID:11839274].","caveats":"Abstract-only read; the pair is stored with CNTNAP1 as ligand, but the paper tested NF155 as the glial protein binding the Caspr-contactin complex [PMID:11839274].","key_references":[{"PMID":"11839274","why":"NF155 binds the paranodin/Caspr-contactin complex"}],"covers":["LR002373","LR005653"]},"LR003822":{"pair":"COL14A1 -> CD44","headline":"A chondroitin/dermatan sulfate CD44 form was identified as a cell-surface receptor for collagen XIV by affinity chromatography and immunoprecipitation.","interaction_type":"direct binding","direction_and_effect":"Cell adhesion to collagen XIV was inhibited by heparin or decorin and by chondroitinase ABC or heparinase III pretreatment; affinity chromatography on collagen XIV-Sepharose yielded a chondroitin/dermatan sulfate proteoglycan identified as a CD44 family member by immunoprecipitation [PMID:8986622]. Effect labelled agonist.","molecular_requirements":"The receptor is a glycosaminoglycan-modified CD44 form of 97-105 kDa after chondroitinase ABC digestion; no detectable integrins in the eluates [PMID:8986622].","affinity_potency":[],"species_and_systems":"Human placental collagen XIV and fibroblast and other cell surface proteins; curator species human [PMID:8986622].","localisation_and_range":"COL14A1 is annotated secreted, CD44 secreted and transmembrane [flag].","caveats":"Abstract-only; the evidence is chromatographic, and the abstract does not report affinity. The BioGRID record is co-purification [DB:BioGRID][PMID:8986622].","key_references":[{"PMID":"8986622","why":"CD44 proteoglycan as cell receptor for collagen XIV"}],"covers":["LR000316","LR003822"]},"LR002382":{"pair":"COL18A1 -> ITGAV","headline":"Mixed: one abstract-read paper reports endostatin interacting with alphaV integrins; another reports alpha5beta1 only.","interaction_type":"conflicting","direction_and_effect":"Recombinant human endostatin interacts with alpha5 and alphaV integrins on human endothelial cells; soluble endostatin inhibits integrin-dependent migration [PMID:11158588].","molecular_requirements":"Which alphaV beta partner is not resolved; the entity is annotated as integrin alphaVbeta3 [flag]. Ligand is endostatin, the collagen XVIII fragment, not intact COL18A1 [PMID:11158588].","affinity_potency":[],"species_and_systems":"Human endothelial cells, human endostatin; abstract only [PMID:11158588].","localisation_and_range":"Ligand is a secreted fragment; receptor is membrane-bound.","caveats":"Conflicting: a second paper states human endostatin activity is mediated by alpha5beta1 and that alphaVbeta3 is used by tumstatin, and it was judged pair_absent [PMID:12682293]. The positive paper is an abstract-only read. No affinity.","key_references":[{"PMID":"11158588","why":"Endostatin interacts with alpha5 and alphaV integrins"},{"PMID":"12682293","why":"Negative: alphaVbeta3 attributed to tumstatin, endostatin to alpha5beta1"}],"covers":["LR002382","LR005661"]},"LR003831":{"pair":"COL1A1 -> ITGA1","headline":"Integrin alpha1 I domain binds type I collagen with sub-micromolar affinity in one full-text SPR study.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha1 I domain bound fibrillar collagen types I, II and III with similar affinities by surface plasmon resonance [PMID:16043429]. Effect on signalling: not reported in our evidence.","molecular_requirements":"Only the isolated alpha1 I domain was tested; the beta1 partner was not part of the assay [PMID:16043429]. Type I collagen was the assembled heterotrimer, not COL1A1 alone.","affinity_potency":[{"value":"KD1 ~0.15-0.32 uM","assay":"surface plasmon resonance (BIAcore), alpha1I binding to fibrillar collagens, high-affinity class","system":"recombinant integrin alpha1 I domain, purified fibrillar collagen","cite":"PMID:16043429"},{"value":"KD2 ~5.5-7.3 uM","assay":"surface plasmon resonance, lower-affinity class","system":"recombinant integrin alpha1 I domain, purified fibrillar collagen","cite":"PMID:16043429"}],"species_and_systems":"Human recombinant proteins [PMID:16043429].","localisation_and_range":"Receptor is a membrane integrin; collagen is matrix.","caveats":"Isolated I domain, not the full receptor. The paper's focus is a binding site in collagen III.","key_references":[{"PMID":"16043429","why":"SPR binding of integrin I-domains to collagens I-III"}],"covers":["LR000325","LR003831"]},"LR003840":{"pair":"COL1A2 -> ITGB1","headline":"Integrin alpha11beta1 binds collagen type I-Sepharose in one abstract-read paper; evidence is for the heterodimer and the collagen heterotrimer, not the single chains.","interaction_type":"direct binding","direction_and_effect":"The alpha(11)beta(1) integrin heterodimer bound collagen type I-Sepharose, and muscle cells localised alpha11beta1 into focal contacts on collagen I [PMID:10464311]. Direction is collagen to integrin; the dossier carries a 'Stimulatory' modulatory label [flag].","molecular_requirements":"The binder is the alpha11beta1 heterodimer and the ligand is the collagen I heterotrimer (2x COL1A1 + COL1A2), per the curator note; this resource records them by chain. ITGB1 alone, and COL1A2 alone, are not shown to be sufficient [PMID:10464311].","affinity_potency":[],"species_and_systems":"Human fetal muscle cells and cDNA cloning per the abstract; the binding result's species is not stated in our evidence. Both the human and mouse pair are ortholog-inferred (not directly tested) [PMID:10464311].","localisation_and_range":"ITGB1 is flagged not secreted [flag]; collagen is a secreted matrix ligand, so contact-dependent signalling (inferred from flags).","caveats":"Abstract read only. The paper's main subject is cloning of the alpha11 chain. Three further papers were abstract-insufficient and one is pending; only one confirmed paper is visible. Mouse rows are projected from human.","key_references":[{"PMID":"10464311","why":"alpha11beta1 binds collagen I-Sepharose"}],"covers":["LR000334","LR003840"]},"LR000339":{"pair":"COL2A1 -> ITGB1","headline":"Collagen II signals through ITGB1 in several studies, including a 2019 full-text paper; chain-only evidence with alpha partners varying.","interaction_type":"direct binding","direction_and_effect":"On interacting with COL2A1, ITGB1 competed with BMP receptors for SMAD1, inhibiting SMAD1 activation and nuclear import; COL2A1 also activated ITGB1-induced ERK1/2 phosphorylation, and blocking ITGB1 reversed COL2A1 effects [PMID:30854241]. Curator label: antagonist (of chondrocyte hypertrophy).","molecular_requirements":"ITGB1 is described as the major receptor for COL2A1; alpha partners are not specified there [PMID:30854241]. Other papers implicate alpha2beta1 [PMID:7688313; PMID:7520045] and alpha10beta1 [PMID:9685391].","affinity_potency":[],"species_and_systems":"Human cell lines SW1353 and Hs819.T, human articular chondrocytes, and a Col2a1 p.Gly1170Ser mouse model [PMID:30854241]; bovine chondrocytes [PMID:7688313].","localisation_and_range":"ITGB1 is flagged not secreted [flag]; collagen is a matrix ligand, so contact-dependent.","caveats":"Seven confirmed papers, one pending; shown ones are mostly abstract-read. The 2019 paper used blocking antibody and phosphorylation readouts, not binding measurements. ITGB1 is a shared chain, so signals could reflect any beta1 integrin.","key_references":[{"PMID":"30854241","why":"COL2A1 signals via ITGB1 to suppress BMP-SMAD1"},{"PMID":"9685391","why":"Alpha10beta1 purified on collagen II"},{"PMID":"7688313","why":"Chondrocyte adhesion blocked by anti-beta 1"}],"covers":["LR000339","LR003845"]},"LR002391":{"pair":"COL3A1 -> ADGRG1","headline":"Collagen III was identified as the ligand of GPR56 (ADGRG1) with matching mouse knockout phenotypes; also supported by UniProt.","interaction_type":"direct binding","direction_and_effect":"COL3A1 was identified as the GPR56 ligand by an in vitro biotinylation/proteomics approach; Col3a1-null mice show cortical overmigration similar to Gpr56-null mice, and collagen III inhibited neural migration in vitro via GPR56 [PMID:21768377]. GPR56 couples to Galpha(12/13) and activates RhoA on ligand binding. Curator label: antagonist (migration inhibition).","molecular_requirements":"Not reported in our evidence beyond GPR56 coupling to Galpha(12/13).","affinity_potency":[],"species_and_systems":"Mouse knockouts and in vitro assays; curators record human ligand and receptor [PMID:21768377]. Pair projected to human and mouse.","localisation_and_range":"COL3A1 flagged secreted; ADGRG1 flagged both secreted and transmembrane [flag]; matrix contact inferred.","caveats":"Abstract read only. UniProt states interaction with COL3A1 and role in cortical development [DB:UniProt]. One review-only and one pending paper not shown.","key_references":[{"PMID":"21768377","why":"Col3a1 identified as GPR56 ligand"}],"covers":["LR002391","LR005670"]},"LR000348":{"pair":"COL4A3 -> CD47","headline":"COL4A3 peptide affinity-purified CD47 from tumour cells; abstract only, peptide-based.","interaction_type":"direct binding","direction_and_effect":"CD47/IAP was isolated from melanoma and prostate cells by affinity purification with the alpha3(IV)179-208 peptide [PMID:10493512]; the peptide inhibits tumour cell proliferation via increased cAMP per the abstract [PMID:10493512].","molecular_requirements":"CD47 was found alongside the beta3 integrin subunit and the alpha(v)beta3 complex [PMID:10493512]; whether CD47 acts alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human tumour cells; a peptide, not full-length COL4A3 [PMID:10493512].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; peptide bait only; Mr 52,000 band identified as CD47. No affinity reported. Human pair labelled orthology-inferred in the dossier.","key_references":[{"PMID":"10493512","why":"CD47 and alpha(v)beta3 as receptors for alpha3(IV) chain"}],"covers":["LR000348","LR003854"]},"LR002418":{"pair":"COL5A1 -> DDR1","headline":"Type V collagen induces DDR1 phosphorylation in a full-text paper; chain not resolved.","interaction_type":"direct binding","direction_and_effect":"Commercial human type V collagen induced DDR1 phosphorylation comparable to the A204-derived ligand [PMID:9659900].","molecular_requirements":"Commercial type V collagen is mostly the COL5A1/COL5A2 heterotrimer and the paper does not resolve single chains [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor; mouse pair is projected [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Chain-level binding not shown; no affinity reported.","key_references":[{"PMID":"9659900","why":"Type V collagen activates DDR1"}],"covers":["LR002418","LR005697"]},"LR005703":{"pair":"COL8A1 -> ITGB1","headline":"COL8A1 is reported to interact directly with ITGB1 on colorectal cancer cells, activating PI3K-AKT; abstract-level evidence plus computational support.","interaction_type":"direct binding","direction_and_effect":"COL8A1 secreted from THBS2+ CAFs is reported to directly interact with ITGB1 on resistant malignant cells, activating PI3K-AKT signaling and promoting EMT and oxaliplatin resistance; ITGB1 knockdown or an AKT inhibitor mitigated these effects [PMID:39732719].","molecular_requirements":"ITGB1 only; alpha partner not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human colorectal cancer; mouse pair is ortholog-inferred. Abstract plus full-text excerpts [PMID:39732719].","localisation_and_range":"Ligand flagged secreted [flag]; CAF-derived, acting on neighbouring tumor cells [PMID:39732719].","caveats":"Excerpts show CellChat inference, spatial colocalisation and molecular docking for COL8A1-ITGB1 [PMID:39732719]; direct biochemical binding data are not shown in the excerpts.","key_references":[{"PMID":"39732719","why":"COL8A1-ITGB1 interaction drives oxaliplatin resistance in CRC"}],"covers":["LR002424","LR005703"]},"LR002427":{"pair":"COL8A2 -> SLC4A11","headline":"SLC4A11 extracellular loop 3 was reported to interact with COL8A2 by mass spectrometry; matrix-adhesion context.","interaction_type":"direct binding","direction_and_effect":"A GST fusion protein of SLC4A11-EL3 interacts with COL8A2, identified by mass spectrometry; the abstract states a direct interaction [PMID:31691803]. An anti-EL3 antibody suppressed cell adhesion, identifying EL3 as the Descemet's membrane binding site [PMID:31691803].","molecular_requirements":"EL3 of SLC4A11 is required for binding [PMID:31691803].","affinity_potency":[],"species_and_systems":"SLC4A11-transfected HEK293 cells and primary human corneal endothelial cells; mouse pair is ortholog-inferred [PMID:31691803].","localisation_and_range":"Ligand flagged secreted [flag]; COL8A2 is a principal Descemet's membrane protein, so matrix adhesion [PMID:31691803].","caveats":"Abstract only for this pair; identification is by mass spectrometry, no affinity reported. Receptor is a solute transporter whose signaling-receptor role is not established in our evidence.","key_references":[{"PMID":"31691803","why":"SLC4A11-EL3 interacts with COL8A2 and mediates cell adhesion"}],"covers":["LR002427","LR005706"]},"LR005712":{"pair":"COMP -> ITGAV","headline":"COMP cell attachment is partly blocked by anti-alphaVbeta3 antibody; functional, with the integrin acting as the alphaVbeta3 heterodimer.","interaction_type":"functional only","direction_and_effect":"A function-blocking anti-alphaVbeta3 antibody reduced cell attachment to COMP by 35%, one of two independent attachment mechanisms alongside CD47, with COMP acting as agonist/adhesive ligand [PMID:20033473].","molecular_requirements":"The receptor is the alphaVbeta3 heterodimer (entity named integrin alphaVbeta3 [flag]); ITGAV alone is not shown to suffice [PMID:20033473].","affinity_potency":[],"species_and_systems":"Ligament cells and chondrocytes on recombinant COMP; ligament cell species not stated in the excerpts [PMID:20033473].","localisation_and_range":"Extracellular matrix ligand acting on a cell-surface receptor [PMID:20033473].","caveats":"Antibody blocking only, no binding measurement; the authors cite other work for COMP-alphaVbeta3 interaction and report an RGD-dependent route. Reactome lists the binding reaction [DB:Reactome R-HSA-2426259]. One paper, abstract-level curation.","key_references":[{"PMID":"20033473","why":"Anti-alphaVbeta3 antibody reduces cell attachment to COMP"}],"covers":["LR002433","LR005712"]},"LR005118":{"pair":"COMP -> ITGB3","headline":"Anti-alphaVbeta3 antibody reduces cell attachment to COMP; functional evidence only, beta3 as part of the alphaVbeta3 heterodimer.","interaction_type":"functional only","direction_and_effect":"A function-blocking anti-alphaVbeta3 antibody reduced cell attachment to COMP, alongside anti-CD47; this is agonist-type adhesion [PMID:20033473].","molecular_requirements":"Evidence concerns the alphaVbeta3 heterodimer, not ITGB3 alone [PMID:20033473].","affinity_potency":[],"species_and_systems":"Ligament cells attached equally to purified human COMP and recombinant mouse COMP ('almost identical'); ligament cell species not stated in excerpts [PMID:20033473].","localisation_and_range":"Extracellular matrix ligand acting on a cell-surface receptor [PMID:20033473].","caveats":"Antibody blocking only; no binding assay. Chain-level entry for a heterodimer. A further review_only paper was judged. Reactome lists the reaction [DB:Reactome R-HSA-2426259].","key_references":[{"PMID":"20033473","why":"Anti-alphaVbeta3 antibody reduces COMP attachment; human and mouse COMP compared"}],"covers":["LR001760","LR005118"]},"LR000366":{"pair":"CORT -> MRGPRX2","headline":"Cortistatin is a Gq-coupled agonist of MRGPRX2, supported by two papers plus GtoPdb, UniProt and PDB structures.","interaction_type":"direct binding","direction_and_effect":"Cortistatin is a high-potency agonist at MrgX2; in MrgX2-expressing cells it raises intracellular Ca2+ with no effect on cAMP, indicating Gq coupling [PMID:12915402]. GtoPdb lists a full agonist [DB:GtoPdb]. A SAR study found a motif shared by cortistatin and PAMP [PMID:16111673].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pEC50 6.900000095367432 to 7.599999904632568","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:12915402"}],"species_and_systems":"Human ligand and receptor in cells expressing MrgX2 [PMID:12915402]. PDB lists complex structures 7S8L, 7S8M, 7VDL, 7VV4 [DB:PDB 7S8L].","localisation_and_range":"CORT secreted by flag [flag]; UniProt describes it as acting on mast cells [DB:UniProt].","caveats":"Papers read as abstracts. UniProt notes MRGPRX2 also binds many other ligands [DB:UniProt].","key_references":[{"PMID":"12915402","why":"Deorphanisation: cortistatin as MrgX2 agonist"},{"PMID":"16111673","why":"Shared structural motif of PAMP and cortistatin"}],"covers":["LR000366"]},"LR004821":{"pair":"CRIPTO -> ACVR1C","headline":"Cripto reported to interact with ALK7 (ACVR1C) as a Nodal co-receptor; one abstract-level paper plus Reactome complexes.","interaction_type":"direct binding","direction_and_effect":"Cripto can independently interact with ALK7, and its expression greatly enhances ALK7 and ActRIIB responses to Nodal ligands [PMID:11485994]. Cripto acts as co-receptor, not as a signalling ligand [PMID:11485994].","molecular_requirements":"Reactome lists an ACVR1C:ACVR2B:EGF-CFC complex [DB:Reactome]. ALK7 responses to Nodal are enhanced by Cripto expression [PMID:11485994].","affinity_potency":[],"species_and_systems":"The paper used vertebrate developmental models (mouse tagged) [PMID:11485994]. The human pair is inferred from other species.","localisation_and_range":"CRIPTO is flagged secreted [flag]. Cripto is described as a co-receptor/co-factor for Nodal [PMID:11485994].","caveats":"Single paper, read as abstract only. No affinity. Not tested here in isolation from Nodal.","key_references":[{"PMID":"11485994","why":"Cripto interacts with ALK7 and enhances Nodal response"}],"covers":["LR001426","LR004821"]},"LR001428":{"pair":"CRIPTO -> ACVR2B","headline":"Cripto-ActRIIB evidence conflicts: ternary complex with activin reported, but isolated CFC domain does not bind ActRIIB.","interaction_type":"conflicting","direction_and_effect":"Cripto formed a complex with activin and ActRII/IIB by co-immunoprecipitation [PMID:12682303]; the same paper reports Cripto blocks activin signalling. The synthetic Cripto CFC domain explicitly did not recognise ActRIIB [PMID:19035567].","molecular_requirements":"Cripto-ActRIIB association depends on activin being present in the complex [PMID:12682303]. Reactome lists ACVR1C:ACVR2B:EGF-CFC complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species of the co-IP is unspecified in the curated row [PMID:12682303]; the CFC domain was human and synthetic [PMID:19035567]. Human and mouse pairs are both projected.","localisation_and_range":"CRIPTO is flagged secreted [flag].","caveats":"Both papers read as abstracts only. The negative result concerns only the isolated CFC domain, not full-length Cripto. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"12682303","why":"Complex of Cripto, activin and ActRII/IIB"},{"PMID":"19035567","why":"CFC domain does not bind ActRIIB"}],"covers":["LR001428","LR004823"]},"LR002436":{"pair":"CRIPTO -> CDON","headline":"Cripto (TDGF1) binds the CDON ectodomain in pull-downs; one full-text paper, mouse genetics with HEK293T binding assays.","interaction_type":"direct binding","direction_and_effect":"CDON-Fc interacted efficiently with TDGF1-AP, similar to its interaction with SHH-N-AP [PMID:32876567]. Interaction was reported alongside genetic interaction of Cdon with Tdgf1 in ethanol-induced holoprosencephaly [PMID:32876567].","molecular_requirements":"CDON-Fc did not bind the negative control CD164-AP and interacted only weakly with AP-tagged ALK4, ActRIIA and ActRIIB [PMID:32876567]. Co-receptor role in Nodal signalling is proposed in this paper.","affinity_potency":[],"species_and_systems":"Ectodomain pull-downs in HEK293T cells; the study is a mouse model [PMID:32876567]. Human pair is as listed; the mouse pair is inferred.","localisation_and_range":"CRIPTO is flagged secreted [flag]; the CDON ectodomain was used as a secreted fusion in vitro [PMID:32876567].","caveats":"Single paper. Ectodomain pull-down does not show signalling direction; CDON is a co-receptor rather than a classic receptor. No affinity reported.","key_references":[{"PMID":"32876567","why":"Pull-downs show CDON and LRP2 bind TDGF1"}],"covers":["LR002436","LR005715"]},"LR001761":{"pair":"CRLF1 -> CNTFR","headline":"CRLF1 forms a heterodimer with CLCF1 that engages CNTFR; CRLF1 alone is not shown to bind.","interaction_type":"direct binding","direction_and_effect":"CLF (CRLF1) associates with CLC (CLCF1) to form a heteromeric ligand for the CNTF receptor complex [PMID:10966616]. The CRLF1/CLCF1 dimer binds CNTFR [PMID:23355913]. GtoPdb lists an agonist record [DB:GtoPdb]. In hepatic stellate cells ectopic CRLF1 retarded myofibroblast activation [PMID:23355913], so effect there is antagonistic.","molecular_requirements":"CRLF1 requires CLCF1 for CNTFR binding; the receptor complex is CNTFR plus gp130 and LIFR [PMID:10966616, PMID:23355913]. UniProt says CRLF1 engages CNTFR through CLCF1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse system [PMID:10966616]; human hepatic stellate cells [PMID:23355913]. The mouse pair is inferred.","localisation_and_range":"CRLF1 is flagged secreted [flag].","caveats":"Both papers read as abstracts only. CRLF1 does not bind CNTFR alone per the curator note [PMID:23355913]. Pairwise CRLF1-CNTFR binding is not shown separately from the composite ligand.","key_references":[{"PMID":"10966616","why":"CLF-CLC composite ligand for CNTF receptor complex"},{"PMID":"23355913","why":"CRLF1/CLCF1 dimer binds CNTFR; role in fibrosis"}],"covers":["LR001761","LR005119"]},"LR005721":{"pair":"CRP -> FCGR2B","headline":"CRP binds Fc\u03b3RIIb by SPR and drives Fc\u03b3RIIB-dependent endothelial effects in mice; functional and binding support.","interaction_type":"direct binding","direction_and_effect":"SPR showed CRP binding to Fc\u03b3RIIb [PMID:33790888]. In mice, elevated CRP caused insulin resistance in mice with endothelial Fc\u03b3RIIB but not in mice lacking it; in culture CRP suppressed endothelial insulin transcytosis via Fc\u03b3RIIB activation [PMID:27207525]. This is an activating effect on the receptor.","molecular_requirements":"Single chain Fc\u03b3RIIB; downstream eNOS antagonism reported [PMID:27207525].","affinity_potency":[],"species_and_systems":"SPR with human recombinant proteins [PMID:33790888]; mouse genetics (CRP transgenic, endothelial Fc\u03b3RIIB-deficient) for function [PMID:27207525]; species of cultured cells not reported in our evidence.","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"The mouse study is functional and does not itself show binding [PMID:27207525].","key_references":[{"PMID":"33790888","why":"SPR binding to Fc\u03b3RIIb"},{"PMID":"27207525","why":"endothelial Fc\u03b3RIIB required for CRP-induced insulin resistance"}],"covers":["LR002444","LR005721"]},"LR002445":{"pair":"CRP -> FCGR3A","headline":"CRP binds Fc\u03b3RIIIa directly with low affinity in one SPR study; no other support.","interaction_type":"direct binding","direction_and_effect":"CRP bound immobilised Fc\u03b3RIIIa in SPR sensorgrams [PMID:33790888]. Fc\u03b3RIII blocking reduced phagocytosis in monocytes and activated neutrophils, a readout confounded by IgG binding [PMID:33790888].","molecular_requirements":"Single chain; Fc\u03b3RIIIa V/F158 variants bound similarly [PMID:33790888].","affinity_potency":[],"species_and_systems":"Human recombinant receptors and human cells [PMID:33790888].","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only).","caveats":"Single paper, no database support. Affinity is not reported in our evidence for this receptor.","key_references":[{"PMID":"33790888","why":"SPR array showing CRP binding to Fc\u03b3RIIIa"}],"covers":["LR002445"]},"LR000375":{"pair":"CSF1 -> CSF1R","headline":"CSF1 binds and activates CSF1R; supported by binding and functional papers plus structures, though the papers were read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"CSF1 specifically bound murine CSF-1 receptor (c-fms) and, with the growth factor present, the receptor was phosphorylated on tyrosine in membrane preparations [PMID:2408759]. Curators label the effect agonist/stimulatory [PMID:8355686]. Co-addition of M-CSF and IL-34 gave a distinct activation pattern with higher tyrosine phosphorylation at low concentrations [PMID:26095744].","molecular_requirements":"The three N-terminal Ig-like domains of CSF1R form the high-affinity binding region; domains 1-2 alone did not interact with M-CSF, domain 3 was needed, and domains 4-5 did not bind and may inhibit [PMID:8355686]. A single receptor chain is involved; no co-receptor is reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding mapping used murine c-fms segments expressed in Sf9 cells [PMID:8355686]; binding and phosphorylation used mouse macrophage preparations [PMID:2408759]; the IL-34/M-CSF study used cells expressing the receptor [PMID:26095744]. Curators record the mouse pair and a human pair projected from it by orthology (human pair flagged ortholog-inferred).","localisation_and_range":"Annotation flags mark CSF1 as both secreted and transmembrane, and CSF1R as a transmembrane receptor [flag]; range (soluble versus membrane-bound ligand) is not reported in our evidence.","caveats":"All three shown papers were read as abstracts only. The 2015 paper reports a possible M-CSF/IL-34 heteromer, so some activation patterns may reflect the combination rather than CSF1 alone [PMID:26095744]. Databases (BioGRID, IntAct, PDB 4WRL/4WRM, Reactome, UniProt) also record the complex, but several records involve CSF1 together with IL-34 [DB:PDB 4WRL] [DB:Reactome]. GtoPdb lists no type or action [DB:GtoPdb].","key_references":[{"PMID":"2408759","why":"Murine CSF-1 binding and ligand-induced receptor phosphorylation"},{"PMID":"8355686","why":"Maps the high-affinity CSF1 binding region to Ig-like domains 1-3"},{"PMID":"26095744","why":"M-CSF plus IL-34 alters receptor phosphorylation"}],"covers":["LR000375","LR003881"]},"LR011229":{"pair":"CSH2 -> PRLR","headline":"Support for CSH2 acting on PRLR rests on database records only; one paper is pending.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CSH2-PRLR as agonist [DB:GtoPdb]. UniProt states it does not interact with GHR but only activates PRLR through zinc-induced dimerization [DB:UniProt].","molecular_requirements":"Zinc-induced dimerisation is the reported route to PRLR activation [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence; receptor annotated transmembrane [flag].","caveats":"No verified paper; the one judged row is pending. Support is database-only.","key_references":[],"covers":["LR011229"]},"LR002454":{"pair":"CX3CL1 -> ITGA4","headline":"Direct binding of CX3CL1 chemokine domain to integrin alpha4beta1 reported in one paper; the integrin acts as a co-receptor alongside CX3CR1.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(4)beta(1), and membrane-bound fractalkine also bound it, suggesting biological relevance [PMID:23125415]. The study frames integrins as co-receptors: an integrin-binding-defective mutant is defective in ternary complex formation and acts as an antagonist of CX3CR1 [PMID:23125415]. UniProt states ITGA4:ITGB1 binds fractalkine and may act as its coreceptor in CX3CR1-dependent signalling [DB:UniProt].","molecular_requirements":"The integrin heterodimer is alpha4 with beta1 (alpha4beta1); the paper does not test the alpha4 chain alone [PMID:23125415]. Signalling by CX3CL1 involves CX3CR1 plus integrin in a ternary complex [PMID:23125415]. Full-text passages note that EDTA did not fully suppress FKN-CD binding to alpha4beta1 [PMID:23125415].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; recombinant FKN-CD and integrins plus cell experiments. Mouse pair is ortholog-inferred. IntAct has a co-immunoprecipitation record [DB:IntAct].","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; membrane-bound fractalkine also bound the integrins [PMID:23125415].","caveats":"Only one primary paper, read as abstract (full text excerpts available). The affinity of 3.0 x 10(-10) M is reported for alphavbeta3, not for alpha4beta1; no alpha4beta1 affinity in our evidence. Authors state their finding contradicts earlier studies, and the paper's own full text discusses why earlier work may have missed binding [PMID:23125415]. Receptor is the alpha chain of a heterodimer.","key_references":[{"PMID":"23125415","why":"Only paper showing direct FKN-CD binding to alpha4beta1"}],"covers":["LR002454","LR005730"]},"LR005730":{"pair":"CX3CL1 -> ITGA4","headline":"Direct binding of CX3CL1 chemokine domain to integrin alpha4beta1 reported in one paper; the integrin acts as a co-receptor alongside CX3CR1.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(4)beta(1), and membrane-bound fractalkine also bound it, suggesting biological relevance [PMID:23125415]. The study frames integrins as co-receptors: an integrin-binding-defective mutant is defective in ternary complex formation and acts as an antagonist of CX3CR1 [PMID:23125415]. UniProt states ITGA4:ITGB1 binds fractalkine and may act as its coreceptor in CX3CR1-dependent signalling [DB:UniProt].","molecular_requirements":"The integrin heterodimer is alpha4 with beta1 (alpha4beta1); the paper does not test the alpha4 chain alone [PMID:23125415]. Signalling by CX3CL1 involves CX3CR1 plus integrin in a ternary complex [PMID:23125415]. Full-text passages note that EDTA did not fully suppress FKN-CD binding to alpha4beta1 [PMID:23125415].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; recombinant FKN-CD and integrins plus cell experiments. Mouse pair is ortholog-inferred. IntAct has a co-immunoprecipitation record [DB:IntAct].","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; membrane-bound fractalkine also bound the integrins [PMID:23125415].","caveats":"Only one primary paper, read as abstract (full text excerpts available). The affinity of 3.0 x 10(-10) M is reported for alphavbeta3, not for alpha4beta1; no alpha4beta1 affinity in our evidence. Authors state their finding contradicts earlier studies, and the paper's own full text discusses why earlier work may have missed binding [PMID:23125415]. Receptor is the alpha chain of a heterodimer.","key_references":[{"PMID":"23125415","why":"Only paper showing direct FKN-CD binding to alpha4beta1"}],"covers":["LR002454","LR005730"]},"LR000393":{"pair":"CXCL10 -> CXCR3","headline":"CXCL10 is a well-established agonist of CXCR3, with binding, potency and in vivo support in human and mouse.","interaction_type":"direct binding","direction_and_effect":"CXCL10 binds CXCR3 and acts as an agonist [PMID:9064356][PMID:9660793]; potency order was CXCL11 >> CXCL10 > CXCL9 [PMID:15761110]. In mouse cells, CXCL10-induced migration depended on CXCR3 through ERK activation [PMID:28724396]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR3 alone mediated migration; for osteoclastogenic cytokines CXCR3 and TLR4 were both needed [PMID:28724396]. CXCL10 heparin/GAG binding was separable from CXCR3 binding [PMID:12571234].","affinity_potency":[{"value":"Ki 0.14 nM","assay":"binding of IP10 to heterologously expressed CXCR3","system":"human CXCR3","cite":"PMID:9660793"},{"value":"KD 1.35 nM","assay":"ligand binding to murine CXCR3","system":"murine CXCR3 in L1.2 pre-B cells","cite":"PMID:10556837"}],"species_and_systems":"Human receptor and ligand in transfected cells [PMID:9660793]; murine CXCR3 transfectants [PMID:10556837]; mouse murine IP-10 on CHO-expressed CXCR3 [PMID:12571234]; primary mouse cells and arthritis model [PMID:28724396].","localisation_and_range":"CXCL10 is flagged secreted and CXCR3 transmembrane [flag].","caveats":"Mostly abstract-level reads. CXCL10 also antagonises CCR3 [PMID:12884299].","key_references":[{"PMID":"9660793","why":"Pharmacology of CXCR3 with IP10 and MIG"},{"PMID":"9064356","why":"Cloning of the IP10/Mig receptor"},{"PMID":"28724396","why":"CXCR3-dependent CXCL10 signalling in mouse arthritis"}],"covers":["LR000393","LR003899"]},"LR003903":{"pair":"CXCL12 -> ACKR3","headline":"CXCL12 is a high-affinity ligand of ACKR3 (CXCR7), an atypical arrestin-recruiting scavenger receptor; well supported by papers and databases.","interaction_type":"direct binding","direction_and_effect":"CXCL12 binds RDC1/CXCR7 specifically and saturably with apparent KD approximately 0.4 nM, and promoted internalisation and chemotactic signals in CXCR4-negative cells [PMID:16107333]. Later work found CXCR7 activation does not cause Ca2+ mobilization or cell migration [PMID:16940167], and that CXCR7 recruits beta-arrestin and acts as a scavenger of CXCL12 by internalisation and degradation [PMID:20956518][PMID:20161793]. GtoPdb lists an agonist [DB:GtoPdb]; PDB structures exist [DB:PDB 7SK3].","molecular_requirements":"Single receptor chain in these papers. ACKR3 also binds CXCL11 [PMID:20161793]. CXCR4 is a separate CXCL12 receptor that need not be present [PMID:16107333].","affinity_potency":[{"value":"KD approximately 0.4 nM","assay":"binding","system":"RDC1/CXCR7 in T lymphocytes","cite":"PMID:16107333"},{"value":"EC50 30 nM","assay":"beta-arrestin recruitment","system":"CXCR7 cells","cite":"PMID:20956518"},{"value":"pEC50 7.52-7.9","assay":"GtoPdb affinity record","system":"human, per database","cite":"PMID:20956518"}],"species_and_systems":"Human ligand and receptor in cells; scavenging also shown in adult mouse heart valves and human umbilical vein endothelium [PMID:20161793].","localisation_and_range":"CXCL12 flagged secreted, ACKR3 transmembrane [flag]; paracrine.","caveats":"All four shown papers were read as abstracts. Papers disagree on signalling: chemotactic signalling in [PMID:16107333] versus none in [PMID:16940167]; CXCR7 function is described as controversial [PMID:20161793]. Little CXCR7 down-regulation by CXCL12 was seen in primary cells [PMID:20161793].","key_references":[{"PMID":"16107333","why":"Original binding KD for CXCL12 at RDC1/CXCR7"},{"PMID":"20161793","why":"Scavenger function of CXCR7 for CXCL12"},{"PMID":"20956518","why":"CXCL12 beta-arrestin recruitment EC50 at CXCR7"}],"covers":["LR000398","LR003903"]},"LR002463":{"pair":"CXCL12 -> GPR17","headline":"One abstract-only 2016 paper reports SDF-1 activating GPR17 in vitro with cangrelor blockade, supported by in silico modelling.","interaction_type":"functional only","direction_and_effect":"SDF-1 activated GPR17 in a reference GPCR pharmacological assay and a primary oligodendrocyte precursor maturation model; the orthosteric antagonist cangrelor blocked the activation concentration-dependently [PMID:26971834]. Effect is agonist.","molecular_requirements":"Not reported in our evidence; GPR17 acts as a single chain. In silico modelling was used to study the recognition mechanism [PMID:26971834].","affinity_potency":[],"species_and_systems":"Species labelled human for both partners by the curator; the abstract does not name the species. Primary oligodendrocyte precursors were used [PMID:26971834]. The mouse pair is projected.","localisation_and_range":"CXCL12 is flagged secreted [flag].","caveats":"Abstract only; no binding measurement or affinity reported. A single paper, with no independent replication in our evidence.","key_references":[{"PMID":"26971834","why":"Only paper: SDF-1 activates GPR17, blocked by cangrelor"}],"covers":["LR002463","LR005737"]},"LR001770":{"pair":"CXCL12 -> ITGAV","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alphavbeta3 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alphavbeta3 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGAV alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001770","LR005127"]},"LR005127":{"pair":"CXCL12 -> ITGAV","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alphavbeta3 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alphavbeta3 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGAV alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001770","LR005127"]},"LR003912":{"pair":"CXCL2 -> CXCR2","headline":"Well supported agonist interaction: high-affinity binding and potent signalling in human receptor transfectants, plus a GtoPdb record and structures.","interaction_type":"direct binding","direction_and_effect":"Agonist: GRObeta/CXCL2-class ELR+ chemokines are potent agonists at IL8RB (CXCR2) by calcium flux, competing for high-affinity binding [PMID:8702798]. CXCL2-induced ASMC migration depended on p38 MAPK and CXCR2 [PMID:23904157]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement reported in our evidence. PDB entries 8XVU and 8XXH contain a CXCL2 chain and a CXCR2 chain [DB:PDB 8XVU].","affinity_potency":[{"value":"Kd 5.7 nM","assay":"binding of recombinant murine MIP-2 to human type B IL-8 receptor","system":"recombinant","cite":"PMID:9260277"},{"value":"EC50 4 nM","assay":"calcium flux, GRObeta at IL8RB","system":"HEK293 transfectants","cite":"PMID:8702798"},{"value":"pIC50 7.0 to 9.1","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in HEK293 cells and human primary ASMCs [PMID:8702798][PMID:23904157]; murine MIP-2 on human receptor and on murine receptor (Kd 6.8 nM) [PMID:9260277].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"Mostly abstract-only reads. PMID:8550564 names GROalpha, not CXCL2, so it supports CXCL2 only by analogy within the selectivity group. Ligand identity in the EC50 listing (GRObeta) is an alias-based assignment.","key_references":[{"PMID":"8702798","why":"Potency and competition binding at IL8RB"},{"PMID":"9260277","why":"Kd for MIP-2 at human and murine receptors"},{"PMID":"23904157","why":"CXCL2 migration via CXCR2 in ASMCs"}],"covers":["LR000410","LR003912"]},"LR000924":{"pair":"CXCL8 -> SDC1","headline":"CXCL8 forms a complex with heparan sulfate and syndecan-1 on endothelium; a presentation scaffold, supported by one paper.","interaction_type":"direct binding","direction_and_effect":"IL-8 was detected in a trimolecular complex with heparan sulfate and syndecan-1 in endothelial culture supernatants [PMID:12902511]. This is retention of the chemokine on a shed proteoglycan, not reported signalling through syndecan-1.","molecular_requirements":"Heparan sulfate is part of the complex [PMID:12902511]; whether the syndecan-1 protein core binds IL-8 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cell culture [PMID:12902511]. The pair is marked ortholog-inferred to this species entry, but the experiment was human.","localisation_and_range":"Syndecan-1 is flagged secreted and transmembrane [flag]; the paper describes a shed complex, which fits the paper's constitutive shedding observation [PMID:12902511].","caveats":"Single abstract-only paper; a BioGRID reconstituted-complex record cites it [DB:BioGRID]. The curator notes syndecan-1 acts as a gradient-presenting scaffold, not a signal-transducing receptor (CXCR1/CXCR2 are the signalling receptors). Users scoring CCC signalling should treat this as non-signalling.","key_references":[{"PMID":"12902511","why":"IL-8/heparan sulfate/syndecan-1 complex shed from endothelium"}],"covers":["LR000924"]},"LR002472":{"pair":"CXCL9 -> ACKR1","headline":"CXCL9 binds the Duffy antigen (ACKR1) weakly on human erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CXCL9 displaced 125I-CXCL8 from human erythrocytes with Ki 162.0 nM, in the paper's weak-binding class (Ki 100 nM-1 microM) [PMID:15358176]. Direction/signalling is not reported; ACKR1 is an atypical receptor and effect on signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 162.0 nM","assay":"125I-CXCL8 competition displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes with human chemokine [PMID:15358176]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Only one paper; affinity is markedly weaker than the strong binders in that study. The stored evidence sentence is a fragment and does not itself name CXCL9; the Ki comes from the curator's assay detail.","key_references":[{"PMID":"15358176","why":"Duffy antigen chemokine binding panel, Ki 162.0 nM"}],"covers":["LR002472","LR005746"]},"LR010824":{"pair":"DCN -> TGFB1","headline":"No curator-verified paper; support is database records of decorin-TGFB1 complexes only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; BioGRID records are reconstituted complexes [DB:BioGRID 297017].","localisation_and_range":"Both flagged secreted; TGFB1 is a ligand, not a receptor, per flags [flag]. Likely ligand-ligand binding rather than receptor signalling.","caveats":"Rests on BioGRID alone [DB:BioGRID 280658] [DB:BioGRID 305820]. Six papers judged as different entity; others review-only or abstract-insufficient.","key_references":[],"covers":["LR010824"]},"LR002481":{"pair":"DEFB103A -> CXCR4","headline":"hBD-3 is reported to antagonise CXCR4 and block SDF-1alpha binding; structure-activity data in one paper.","interaction_type":"functional only","direction_and_effect":"Antagonist: prior work cited in the abstract reports hBD-3 antagonising CXCR4 and promoting internalisation without activation [PMID:23659571]; this paper maps structural features of hBD-3 for inhibiting SDF-1alpha-CXCR4 interaction.","molecular_requirements":"Activity falls with replacement of all six cysteines, acidic replacement of terminal cationic residues, loss of N-terminal residues 1-10, or neutral replacement of Lys8/Lys32/Arg36 [PMID:23659571].","affinity_potency":[],"species_and_systems":"Human hBD-3 mutants tested on SDF-1alpha/CXCR4 binding and signalling; no cell type is named in our evidence.","localisation_and_range":"DEFB103A flagged secreted; CXCR4 transmembrane receptor [flag].","caveats":"Abstract only; direct hBD-3 binding to CXCR4 is not shown in our evidence, only inhibition of SDF-1alpha-CXCR4 interaction.","key_references":[{"PMID":"23659571","why":"Structure-activity mapping of hBD-3 CXCR4 antagonism"}],"covers":["LR002481"]},"LR000429":{"pair":"DEFB103B -> CCR2","headline":"Fc-fused human beta-defensin 3 binds CCR2 and drives chemotaxis (full text), but only one paper supports this pair.","interaction_type":"direct binding","direction_and_effect":"hBD3:Ig bound CCR2-transfected HEK293 cells by flow cytometry and induced dose-dependent CCR2-specific chemotaxis of HEK293 cells, human monocytes and mouse peritoneal cells; labelled agonist by the curators [PMID:20483750]. CCL2/MCP-1 preincubation abolished hBD-induced migration, and hBD3:Ig inhibited MCP-1 migration; CCR2-deficient mouse cells did not migrate [PMID:20483750]. Reactome lists a bound complex citing the same paper [DB:Reactome].","molecular_requirements":"Not reported in our evidence; the ligand is a fusion protein in the key study, with no subunit or co-receptor requirement tested. Binding to CXCR4 was not seen [PMID:20483750].","affinity_potency":[],"species_and_systems":"Human beta-defensin 2 and 3 Fc fusion proteins (hBD2:Ig, hBD3:Ig) and their mouse orthologs bound human CCR2 in HEK293 cells and acted on human monocytes and CCR2-deficient versus wild-type mouse peritoneal exudate cells [PMID:20483750]. Mouse orthologs bound human or mouse CCR2 [PMID:20483750].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Single paper; the ligand is an Ig-Fc fusion and the paper cites a personal communication as its origin hypothesis. The Reactome record is a copy of the same paper [DB:Reactome]. Peak chemotaxis was at 10 to 100 ng/ml for the fusion proteins; no Kd reported.","key_references":[{"PMID":"20483750","why":"Binding and chemotaxis via CCR2, with CCR2-null mouse cells"}],"covers":["LR000429"]},"LR000438":{"pair":"DHH -> PTCH1","headline":"Direct binding reported for the PTCH/PTCH2 pair with all hedgehogs (abstract only); UniProt also asserts DHH-PTCH binding.","interaction_type":"direct binding","direction_and_effect":"Biochemical analysis shows PTCH and PTCH2 both bind all hedgehog family members with similar affinity and can form a complex with SMO [PMID:9811851]. UniProt states DHH acts by binding PTCH1 or PTCH2, relieving smoothened inhibition [DB:UniProt].","molecular_requirements":"PTCH forms a complex with SMO [PMID:9811851]; UniProt records two PTCH1 molecules engaging one hedgehog (SHH, IHH and DHH) molecule [DB:UniProt].","affinity_potency":[],"species_and_systems":"The paper isolated the human PTCH2 gene and analysed human PTCH and PTCH2 biochemically; the experimental system for the DHH-specific binding is not detailed in the abstract [PMID:9811851]. Human pair is ortholog-inferred, mouse is not.","localisation_and_range":"DHH flagged secreted and transmembrane; PTCH1 flagged receptor [flag].","caveats":"The abstract does not separate DHH from other hedgehogs; no affinity value is given. Two further rows were abstract-insufficient. Paralog issue: PTCH2 is also reported as the likely DHH receptor in vivo [PMID:9811851].","key_references":[{"PMID":"9811851","why":"PTCH and PTCH2 bind all hedgehog proteins with similar affinity"}],"covers":["LR000438","LR003930"]},"LR003930":{"pair":"DHH -> PTCH1","headline":"Direct binding reported for the PTCH/PTCH2 pair with all hedgehogs (abstract only); UniProt also asserts DHH-PTCH binding.","interaction_type":"direct binding","direction_and_effect":"Biochemical analysis shows PTCH and PTCH2 both bind all hedgehog family members with similar affinity and can form a complex with SMO [PMID:9811851]. UniProt states DHH acts by binding PTCH1 or PTCH2, relieving smoothened inhibition [DB:UniProt].","molecular_requirements":"PTCH forms a complex with SMO [PMID:9811851]; UniProt records two PTCH1 molecules engaging one hedgehog (SHH, IHH and DHH) molecule [DB:UniProt].","affinity_potency":[],"species_and_systems":"The paper isolated the human PTCH2 gene and analysed human PTCH and PTCH2 biochemically; the experimental system for the DHH-specific binding is not detailed in the abstract [PMID:9811851]. Human pair is ortholog-inferred, mouse is not.","localisation_and_range":"DHH flagged secreted and transmembrane; PTCH1 flagged receptor [flag].","caveats":"The abstract does not separate DHH from other hedgehogs; no affinity value is given. Two further rows were abstract-insufficient. Paralog issue: PTCH2 is also reported as the likely DHH receptor in vivo [PMID:9811851].","key_references":[{"PMID":"9811851","why":"PTCH and PTCH2 bind all hedgehog proteins with similar affinity"}],"covers":["LR000438","LR003930"]},"LR008106":{"pair":"DKK2 -> KREMEN1:LRP6","headline":"No verified paper; database records only, and the single judged row was a different entity.","interaction_type":"database-asserted only","direction_and_effect":"IntAct holds coimmunoprecipitation and bio-layer interferometry records and UniProt notes interaction involving DKK2 [DB:IntAct] [DB:UniProt].","molecular_requirements":"Which chains are required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"DKK2 flagged secreted; KREMEN1:LRP6 flagged transmembrane [flag].","caveats":"One judged row was different_entity; the IntAct BLI record (O75581-Q9UBU2) and the UniProt text do not by themselves establish a ternary complex.","key_references":[],"covers":["LR008106"]},"LR002490":{"pair":"DKK3 -> KREMEN2","headline":"DKK3 interacts with Krm2 in one 2010 paper using biochemical and functional assays; single-paper support.","interaction_type":"direct binding","direction_and_effect":"Dkk3 interacts with Krm1 and Krm2, contrary to earlier studies; Krm2 abolished Dkk3-mediated potentiation of Wnt signalling [PMID:20370576]. Curator direction is agonist for the Dkk3 pro-Wnt effect.","molecular_requirements":"Dkk3 did not interact with, or alter expression of, LRP6, so LRP6 is not needed for this binding; blocking glycosylation did not change the Dkk3-Krm interaction [PMID:20370576].","affinity_potency":[],"species_and_systems":"Human proteins per the curator record; the mouse pair is listed and the human pair is ortholog-inferred [PMID:20370576]. Specific cell system not recorded.","localisation_and_range":"Membrane-bound Kremen receptor; DKK3 flagged secreted [flag]. Range not otherwise reported.","caveats":"One paper only, no database record. Affinity not reported in our evidence. Earlier studies reported no such interaction, per this paper [PMID:20370576].","key_references":[{"PMID":"20370576","why":"Dkk3 interacts with Krm1 and Krm2, not LRP6"}],"covers":["LR002490","LR005758"]},"LR005136":{"pair":"DKK4 -> KREMEN2","headline":"Krm2 co-operates with Dkk4 to inhibit Wnt signalling in one cell assay; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Krm2 co-operates with Dkk4 to inhibit Wnt signalling in human 293 fibroblasts [PMID:12527209]. Direct Dkk4-Krm2 binding is not shown in our evidence.","molecular_requirements":"Interaction of Krm2 with Dkks is mediated by the second cysteine-rich domain [PMID:12527209]; LRP6 context noted in the same assay.","affinity_potency":[],"species_and_systems":"Human 293 fibroblasts; Xenopus embryos for Dkk2 [PMID:12527209]. Human pair; mouse pair ortholog-inferred.","localisation_and_range":"Not reported in our evidence; Kremen2 flagged as a receptor [flag].","caveats":"Read as abstract only. The abstract reports Krm2 binding Dkk1 and Dkk2 with high affinity, not Dkk4. Single paper, no database record.","key_references":[{"PMID":"12527209","why":"Krm2 co-operates with Dkk4, not Dkk3, in Wnt inhibition"}],"covers":["LR001780","LR005136"]},"LR000447":{"pair":"DLK2 -> NOTCH1","headline":"DLK2 interacts with the same NOTCH1 region as DLK1 and inhibits NOTCH signalling; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"DLK2 interacts with itself, with DLK1 and with the same NOTCH1 receptor region as DLK1, inhibiting basal NOTCH signalling in preadipocytes and mouse embryo fibroblasts; DLK1 and DLK2 decrease activity even when triggered by canonical ligands, and each reverses the other's effect [PMID:21419176].","molecular_requirements":"DLK1 co-presence modulates the effect: DLK2-induced decrease is reversed by DLK1 overexpression and vice versa [PMID:21419176].","affinity_potency":[],"species_and_systems":"Preadipocytes and mouse embryo fibroblasts; human pair ortholog-inferred, mouse pair direct [PMID:21419176].","localisation_and_range":"DLK2 flagged not secreted [flag]; contact-type action is not stated in our evidence.","caveats":"Abstract only; single paper; no database record; no affinity reported.","key_references":[{"PMID":"21419176","why":"DLK2 binds NOTCH1 region and inhibits NOTCH"}],"covers":["LR000447","LR003939"]},"LR005145":{"pair":"DSC2 -> DSG3","headline":"DSC2 -> DSG3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358].","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001789","LR005145"]},"LR005154":{"pair":"DSPP -> ITGB6","headline":"DSP domain of DSPP binds integrin beta6 in a protein-library screen with functional blockade; one paper.","interaction_type":"direct binding","direction_and_effect":"DSP (a DSPP-derived fragment) was identified as a ligand of integrin beta6 by bait screening; the 36-residue DSP aa183-219 fragment binds and activates ERK1/2 and P38, blocked by anti-integrin beta6 antibody and siRNA [PMID:27430624].","molecular_requirements":"The processed DSP domain, not full-length DSPP, acts, in an RGD-independent manner [PMID:27430624]. Partner alpha chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse dental mesenchymal cells (mDPC6T) per the full-text excerpts; the human pair is ortholog-inferred and the mouse pair is the direct one.","localisation_and_range":"DSPP is flagged as secreted [flag]; DSPP is processed to DSP, DGP and DPP [PMID:27430624].","caveats":"Binding rests on a library screen; no affinity reported in our evidence. Evidence from a single paper.","key_references":[{"PMID":"27430624","why":"DSP aa183-219 binds integrin beta6 and signals"}],"covers":["LR001798","LR005154"]},"LR000456":{"pair":"EBI3 -> IL6ST","headline":"EBI3 alone binds IL-6 and drives gp130 trans-signalling in one paper; as an IL-27 subunit, it also engages IL6ST.","interaction_type":"conflicting","direction_and_effect":"EBI3 activated STAT3 and proliferation in IL-6-dependent B9 cells, via IL-6 trans-signalling, less efficiently than soluble IL-6Ralpha; co-IP and SPR indicated EBI3 binds IL-6 [PMID:28280243]. Binding to gp130 itself is not shown.","molecular_requirements":"The IL-27 route needs the p28 partner; UniProt describes the IL27/EBI3 heterodimer signalling via IL27RA and IL6ST [DB:UniProt]. PDB structures contain EBI3 and IL6ST chains [DB:PDB 7U7N].","affinity_potency":[],"species_and_systems":"Human proteins; B9 mouse plasmacytoma line and Ba/F3 transfectants; abstract only.","localisation_and_range":"EBI3 is flagged as secreted; IL6ST is flagged as transmembrane [flag].","caveats":"The confirmed paper shows EBI3 binding IL-6, not IL6ST; the direct EBI3-IL6ST link is indirect. Abstract only.","key_references":[{"PMID":"28280243","why":"EBI3 binds IL-6 and drives gp130 trans-signalling"}],"covers":["LR000456","LR003947"]},"LR002508":{"pair":"EDIL3 -> ITGB2","headline":"Del-1 antagonises LFA-1 (ITGB2 with ITGAL), and may bind Mac-1; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Del-1 acts as an LFA-1 antagonist; human Del-1 inhibited LFA-1-dependent transendothelial migration of human neutrophils, and Del-1-Fc was ineffective in Itgal-/- mice [PMID:22447028]. Recombinant EDIL3 inhibited osteoclastogenesis of mouse MDSCs via binding to Mac-1 but not LFA-1 [PMID:31110935].","molecular_requirements":"ITGB2 is shared by LFA-1 and Mac-1; the two papers implicate different alpha partners and give opposing LFA-1 results.","affinity_potency":[],"species_and_systems":"Human neutrophils, mouse periodontitis [PMID:22447028]; mouse MDSCs [PMID:31110935].","localisation_and_range":"Not reported in our evidence.","caveats":"The papers conflict on LFA-1: PMID:31110935 reports binding to Mac-1 but not LFA-1. No binding affinity reported. PMID:31110935 abstract only.","key_references":[{"PMID":"22447028","why":"Del-1 antagonises LFA-1 in neutrophils and periodontitis"},{"PMID":"31110935","why":"EDIL3 binds Mac-1 in MDSC osteoclastogenesis"}],"covers":["LR002508","LR005776"]},"LR000465":{"pair":"EDN3 -> EDNRB","headline":"ET-3 is a well-supported agonist of ETB with binding, functional and in vivo evidence.","interaction_type":"direct binding","direction_and_effect":"ET-3 is an agonist: equal potency with ET-1 in displacing 125I-ET-1 and in Ca2+ responses [PMID:1713452]; ET-3 competed with ETB selectivity over ETA in heart tissue [PMID:8904635]; ET-3 contracts gallbladder mainly via ETB [PMID:11982704]; a mouse Edn3 knockout and lethal-spotting mutation indicate the interaction is essential for neural-crest lineages [PMID:8001160]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"Domain mapping: replacing the second and third extracellular regions of ETB with ETA's raised ET-3 Ki, and a Lys-161 substitution reduced ET-3 affinity 5.6-fold [PMID:8086489]. In vivo, ET-3 must be proteolytically activated from big-EDN3 [PMID:8001160].","affinity_potency":[{"value":"Ki 5 x 10(-11) M","assay":"125I-ET-1 displacement, wild-type ETB (rose to 10(-8) M with ETA domains)","system":"CHO cells, human ETB","cite":"PMID:8086489"},{"value":"pKd 9.8 to 11.5","assay":"GtoPdb range, full agonist","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human cloned receptor in COS and CHO cells [PMID:1713452][PMID:8086489]; human and rat heart [PMID:8904635]; human and opossum gallbladder [PMID:11982704]; mouse genetics [PMID:8001160]. Both species pairs are listed. BioGRID reconstituted complex [DB:BioGRID]; PDB 6IGK [DB:PDB 6IGK].","localisation_and_range":"ET-3 annotated secreted, ETB transmembrane [flag].","caveats":"All shown papers were read as abstracts only. ETB is non-selective between ET-1 and ET-3, so ET-3 is not unique to it [PMID:1713452]. Species of the heart binding study is unspecified in the record [PMID:8904635].","key_references":[{"PMID":"8086489","why":"ET-3 binding determinants on ETB"},{"PMID":"8001160","why":"EDN3-EDNRB essential in vivo"},{"PMID":"1713452","why":"cloned human ETB, ET-1 and ET-3 equipotent"}],"covers":["LR000465","LR003956"]},"LR000474":{"pair":"EFNA1 -> EPHA8","headline":"Ephrin-A1 binds EphA8 in fibroblasts in one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 Fc chimeras efficiently bound EphA8 expressed in NIH3T3 fibroblasts, confirmed by EphA8 tyrosine phosphorylation on stimulation [PMID:10515610]. Agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Fc-fusion ligand on EphA8-expressing NIH3T3 cells, recorded as human ligand and receptor [PMID:10515610]. Human pair ortholog-inferred, mouse not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"10515610","why":"ephrin-A1 chimera binds and activates EphA8"}],"covers":["LR000474","LR003965"]},"LR000483":{"pair":"EFNA3 -> EPHA1","headline":"Database-only: UniProt says EphA1 binds EFNA3 with low affinity; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: EPHA1 binds EFNA3 and EFNA4 with low affinity and EFNA1 with high affinity, EFNA1 likely being the cognate ligand [DB:UniProt PMID:17634955]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is not ortholog-inferred, mouse is.","localisation_and_range":"EFNA3 annotated transmembrane, EPHA1 transmembrane [flag].","caveats":"Low-affinity binding is a database statement only; no paper in our dossier tests it.","key_references":[],"covers":["LR000483","LR003974"]},"LR000492":{"pair":"EFNA4 -> EPHA2","headline":"Ephrin-A4 binds EphA2 in several assays, and EFNA4 overexpression activates EPHA2 in liver cancer cells.","interaction_type":"direct binding","direction_and_effect":"An ephrin-A4 immunoglobulin chimera bound EphA2 on human tonsil dendritic-phenotype cells [PMID:10607706]. Ephrin-A4 Fc binds most EphA receptors with high apparent affinity (apparent KD in Fig. 1; values not given in our evidence) [PMID:22568954]. EFNA4 overexpression activated EPHA2 phosphorylation at Ser897 in HCC cells [PMID:34484860].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human tonsil cells [PMID:10607706]; ELISA, species unspecified [PMID:22568954]; human hepatocellular carcinoma cells [PMID:34484860]. Mouse pair is ortholog-inferred.","localisation_and_range":"EFNA4 is flagged both secreted and transmembrane [flag]; a secreted ephrin-A4 form from activated B cells is described [PMID:10607706].","caveats":"The HCC result is overexpression with phosphorylation readout, not binding [PMID:34484860]. The 22568954 result was a browser read with an unverifiable quote. BioGRID lists affinity capture records [DB:BioGRID].","key_references":[{"PMID":"10607706","why":"Ephrin-A4 chimera binds EphA2"},{"PMID":"22568954","why":"ELISA of ephrin-A4 Fc across EphA receptors"},{"PMID":"34484860","why":"EFNA4 activates EPHA2 phosphorylation in HCC"}],"covers":["LR000492","LR003983"]},"LR009042":{"pair":"EFNA5 -> EPHB1","headline":"Binding of LERK-7 (EFNA5) to soluble elk was shown by transfection in one 1997 abstract; BioGRID lists the same study.","interaction_type":"direct binding","direction_and_effect":"Transfected CV1/EBNA cells expressing LERK-7 bound soluble forms of hek and elk, and soluble LERK-7 induced phosphorylation of eck in a human adenocarcinoma line [PMID:9245480]. Which of these old names corresponds to EPHB1 is a curator mapping, not stated in the abstract.","molecular_requirements":"not reported in our evidence. LERK-7 is GPI-anchored [PMID:9245480].","affinity_potency":[],"species_and_systems":"Human LERK-7 cloned from a fetal brain library; cell-based binding with soluble receptor forms in CV1/EBNA cells [PMID:9245480].","localisation_and_range":"LERK-7 is anchored to the membrane by GPI linkage [PMID:9245480]; the entity flags list it as non-secreted and transmembrane [flag], so contact-dependent.","caveats":"Single paper, abstract only. BioGRID records a reconstituted complex from the same paper [DB:BioGRID]. Entry is typed Receptor-Receptor, which looks inconsistent with a ligand.","key_references":[{"PMID":"9245480","why":"LERK-7 binds soluble elk/hek and induces eck phosphorylation"}],"covers":["LR009042"]},"LR000519":{"pair":"EFNB2 -> EPHB2","headline":"Strongly supported direct binding with a 2.7 A co-crystal structure and functional repulsion data.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of the EphB2-ephrin-B2 complex at 2.7 A resolution [PMID:11780069]. EphB2 is cleaved by MMPs on ephrin-B2 interaction, which enables repulsive signalling [PMID:18713744]. Annotated stimulatory.","molecular_requirements":"Each Eph binds one ephrin through a dimer interface; two dimers form a tetramer promoting higher-order clustering [PMID:11780069]. MMP-2/MMP-9 cleavage of the EphB2 ectodomain is needed for repulsion in HEK293 cells [PMID:18713744].","affinity_potency":[],"species_and_systems":"Species curator-annotated human [PMID:11780069]; HEK293 cells and hippocampal neurons for cleavage [PMID:18713744]. ELISA also supports binding [PMID:22568954]. BioGRID: reconstituted complex [DB:BioGRID].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No numeric affinity in our evidence. Abstract-level reading. Growth-cone data in the cleavage paper used ephrin-B1.","key_references":[{"PMID":"11780069","why":"Crystal structure of EphB2/ephrin-B2 complex"},{"PMID":"18713744","why":"Ephrin-B2-induced MMP cleavage of EphB2 for repulsion"}],"covers":["LR000519","LR004010"]},"LR000528":{"pair":"EFNB3 -> EPHB3","headline":"Direct binding with a Kd of approximately 1 nM, described as selective.","interaction_type":"direct binding","direction_and_effect":"Ephrin-B3 had a high-affinity interaction with EphB3 among five receptors tested for transmembrane-ligand binding [PMID:9484836]. ELISA shows ephrin-B3 Fc binds EphB receptors most weakly [PMID:22568954]. Annotated stimulatory.","molecular_requirements":"Ephrin-B3 cytoplasmic domain is close to ephrin-B2's [PMID:9484836].","affinity_potency":[{"value":"Kd approximately 1 nM","assay":"binding studies, dissociation constant","system":"murine ephrin-B3 characterisation","cite":"PMID:9484836"}],"species_and_systems":"Murine ephrin-B3 [PMID:9484836]; ELISA species unspecified. BioGRID: reconstituted complex [DB:BioGRID]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Abstract level. Ephrin-B3 binds heparan sulfate proteoglycans per the ELISA paper, which was browser-read and unverified [PMID:22568954].","key_references":[{"PMID":"9484836","why":"Ephrin-B3 identified; ~1 nM EphB3 binding"},{"PMID":"22568954","why":"ELISA across EphB receptors"}],"covers":["LR000528","LR004019"]},"LR002526":{"pair":"EGFL7 -> ITGB3","headline":"Same evidence as the ITGAV row: T cells adhere to EGFL7 via alphavbeta3 integrin; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Human and mouse activated T cells adhere to EGFL7 through integrin alphavbeta3 [PMID:29483510]. EGFL7 knockout worsens EAE and recombinant EGFL7 improves it [PMID:29483510].","molecular_requirements":"ITGB3 acts as part of the alphaVbeta3 heterodimer; ITGAV is also needed [PMID:29483510].","affinity_potency":[],"species_and_systems":"Human and mouse T cells and EAE mice [PMID:29483510].","localisation_and_range":"EGFL7 is secreted by annotation [flag]; described as ECM-bound [PMID:29483510].","caveats":"One paper, abstract only; no direct binding or affinity data in our evidence.","key_references":[{"PMID":"29483510","why":"T cell adhesion to EGFL7 via alphavbeta3"}],"covers":["LR002526","LR005794"]},"LR005811":{"pair":"EPHA2 -> EFNA4","headline":"EPHA2-EFNA4 has BioGRID and IntAct association records only; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EFNA4-EPHA2 by affinity capture-MS and -Western [DB:BioGRID]; IntAct lists an anti-tag coimmunoprecipitation association [DB:IntAct]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EFNA4 is flagged secreted, EPHA2 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Four review-only rows. Association assays only, no affinity data.","key_references":[],"covers":["LR002543","LR005811"]},"LR002544":{"pair":"EPHA2 -> EFNA5","headline":"EPHA2-EFNA5 is supported by a crystal structure and IntAct assays, but no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the complete EphA2 ectodomain with the ephrin A5 receptor-binding domain is recorded [DB:PDB 2X11]; IntAct lists light scattering and pull-down [DB:IntAct]. UniProt states EPHA2 engaged by EFNA5 may regulate lens fiber cell shape and interactions [DB:UniProt].","molecular_requirements":"Receptor-binding domain of ephrin-A5 and the EphA2 ectodomain were used in the structure [DB:PDB 2X11].","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; four review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002544","LR005812"]},"LR002553":{"pair":"EPHA4 -> EFNA4","headline":"EPHA4-EFNA4 has ELISA, co-IP and BioGRID records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"IntAct lists direct interaction by ELISA and an anti-tag coimmunoprecipitation association [DB:IntAct]; BioGRID lists affinity capture-MS [DB:BioGRID]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EFNA4 is flagged secreted, EPHA4 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity data.","key_references":[],"covers":["LR002553","LR005821"]},"LR002562":{"pair":"EPHA6 -> EFNA1","headline":"Database-only claim: UniProt lists EPHA6 among the receptors bound by EFNA1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA1 entry) states it binds the receptor tyrosine kinases EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EFNA1 carries a secreted flag and a transmembrane flag [flag]; EPHA6 carries a receptor flag only. Range is therefore unclear from our evidence.","caveats":"No curator-verified paper; support is database records only. The only record is a UniProt subunit sentence; no binding assay or affinity in our evidence.","key_references":[],"covers":["LR002562","LR005830"]},"LR002571":{"pair":"EPHA7 -> EFNA5","headline":"Binding by ELISA and mouse in vivo apoptosis data support EphA7/ephrin-A5 interaction; both papers confirmed from abstracts or a browser read.","interaction_type":"direct binding","direction_and_effect":"In mouse embryos, ephrin-A5-Fc expression correlated with apoptosis of EphA7-expressing cells, and ephrin-A5 null mutation gave the converse phenotype; the curator labels this agonist-like signalling [PMID:22976838]. Ephrin-A5 Fc bound with high apparent affinity to most EphA receptors in ELISA, but the quoted sentence does not single out EphA7 [PMID:22568954].","molecular_requirements":"The apoptosis phenotype was reported with cell-cell contact between EphA-expressing and ephrin-A-expressing cells [PMID:22976838]. Other subunit requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse embryos in vivo [PMID:22976838]. ELISA with Fc fusion proteins, species unspecified [PMID:22568954].","localisation_and_range":"Membrane-anchored; the abstract proposes signalling via cell-cell contact [PMID:22976838]. Annotation flags mark EPHA7 as secreted and transmembrane and EFNA5 as transmembrane [flag].","caveats":"Abstract-only reading of [PMID:22976838]; [PMID:22568954] quote was browser-read and is marked unverifiable pending spot-check. The EphA7 sentence in the mouse paper reflects a mixed Eph/ephrin-A context, including ephrin-A2 double-deficient embryos. Apparent KD values are in a figure not in our evidence. BioGRID [DB:BioGRID 280893] and IntAct comigration [DB:IntAct Q15375-P52803] records also exist.","key_references":[{"PMID":"22976838","why":"Mouse in vivo gain- and loss-of-function: ephrin-A5 induces apoptosis of EphA7-expressing cells."},{"PMID":"22568954","why":"ELISA binding of ephrin-A5 Fc to EphA receptors."}],"covers":["LR002571","LR005839"]},"LR002580":{"pair":"EPHB1 -> EFNB3","headline":"UniProt-only claim that EFNB3 is a cognate ligand for EPHB1; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EPHB1 entry) states cognate/functional ephrin ligands include EFNB1, EFNB2 and EFNB3 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only one UniProt sentence; no assay or affinity in our evidence.","key_references":[],"covers":["LR002580","LR005848"]},"LR000537":{"pair":"EREG -> EGFR","headline":"EREG binds EGFR directly by cross-linking and is an agonist; supported by structures and databases.","interaction_type":"direct binding","direction_and_effect":"[125I]epiregulin directly bound EGFR in human breast carcinoma lines, and epiregulin stimulated tyrosine phosphorylation of ErbB receptors, with EGFR and/or ErbB-4 mediating the main signal [PMID:9419975]. Annotated as stimulatory [flag]. UniProt lists epiregulin among EGFR ligands [DB:UniProt].","molecular_requirements":"Binding was seen to EGFR alone as a cross-linked species; no co-receptor requirement is reported in our evidence. Epiregulin did not bind ErbB-2 or ErbB-3 directly [PMID:9419975].","affinity_potency":[],"species_and_systems":"Experiments used human ligand and receptor in four human breast carcinoma lines [PMID:9419975]. The mouse pair is projected from human evidence (ortholog-inferred) [flag]. Structures PDB 5WB7, 7LEN, 7LFR, 7LFS and 8HGP contain both chains [DB:PDB 5WB7].","localisation_and_range":"EREG is flagged both secreted and transmembrane, EGFR transmembrane [flag]; paracrine or juxtacrine action is not distinguished in our evidence.","caveats":"Primary evidence is one 1997 paper read as abstract. No affinity reported. GtoPdb record lists binding without affinity values [DB:GtoPdb].","key_references":[{"PMID":"9419975","why":"Cross-linking shows epiregulin binds EGFR directly"}],"covers":["LR000537","LR004028"]},"LR004029":{"pair":"EREG -> ERBB4","headline":"Epiregulin binds ErbB-4 directly by cross-linking in human cells; one abstract-level paper plus databases.","interaction_type":"direct binding","direction_and_effect":"[125I]epiregulin directly bound ErbB-4 (and EGFR) in human breast carcinoma lines; the main intracellular signal was mediated by ErbB-4 and/or EGFR [PMID:9419975]. Annotated stimulatory [flag].","molecular_requirements":"No co-receptor requirement reported in our evidence; ErbB-4 binding occurred in lines with different ErbB subsets [PMID:9419975].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, four human breast carcinoma lines [PMID:9419975]. The mouse pair is ortholog-inferred [flag].","localisation_and_range":"EREG flagged secreted and transmembrane; ErbB-4 transmembrane [flag].","caveats":"Abstract-only. No affinity. GtoPdb record has no action or affinity values [DB:GtoPdb].","key_references":[{"PMID":"9419975","why":"Cross-linking shows direct epiregulin binding to ErbB-4"}],"covers":["LR000538","LR004029"]},"LR010617":{"pair":"F10 -> F3","headline":"No paper evidence for F10 to F3 as ligand-receptor; PDB and Reactome record a TF:FVIIa:FX complex.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes TF:FVII plus FX giving TF:FVII:FXa [DB:Reactome]; PDB 9P0X shows a tissue factor/FVIIa structure with a Fab [DB:PDB 9P0X].","molecular_requirements":"Records involve tissue factor with factor VII as a complex; a direct F10-F3 contact is not shown.","affinity_potency":[],"species_and_systems":"Human records [DB:PDB 9P0X].","localisation_and_range":"F10 flagged secreted, not transmembrane [flag].","caveats":"No curator-verified paper; the one judged row was different_entity. Database records are about a substrate in a TF:FVIIa enzyme complex, not a receptor binding.","key_references":[],"covers":["LR010617"]},"LR002607":{"pair":"F11R -> ITGB2","headline":"JAM-A binds LFA-1; ITGB2 row inherits evidence for the ITGAL:ITGB2 heterodimer.","interaction_type":"direct binding","direction_and_effect":"JAM-1 is a ligand of LFA-1 [PMID:11812992]; recombinant JAM-A binds the immobilised locked-open alphaL I domain directly [PMID:15528364].","molecular_requirements":"The binding site is on alphaL, not ITGB2 [PMID:15528364]. Beta chain contribution not shown in our evidence; the curator notes subunit rows inherit heterodimer evidence.","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:15528364][PMID:11812992]; mouse pair ortholog-inferred [flag]. Reactome records the complex [DB:Reactome].","localisation_and_range":"JAM-A needs redistribution from tight junctions [PMID:11812992].","caveats":"Chain-only caveat: ITGB2 alone is not shown to bind JAM-A. Abstract-level reads.","key_references":[{"PMID":"15528364","why":"Binding site is on alphaL I domain"},{"PMID":"11812992","why":"JAM-1 as LFA-1 ligand"}],"covers":["LR002607","LR005874"]},"LR001806":{"pair":"F11R -> JAM2","headline":"Jam1a-Jam2a interaction is needed for Notch signalling in zebrafish HSC specification; functional, no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Jam1a-Jam2a interactions facilitate transduction of Notch signals from the somite to HSC precursors; Notch reactivation rescued HSCs in jam1a- or jam2a-deficient embryos [PMID:25119047]. Curators classed it as agonist-like [PMID:25119047].","molecular_requirements":"jam1a (f11r) in HSC precursors and Jam2a in the somite alongside Notch ligands Dlc and Dld [PMID:25119047]. Direct binding not shown.","affinity_potency":[],"species_and_systems":"Experiments were in zebrafish embryos [PMID:25119047]; the pair is recorded as human and mouse, both ortholog-inferred, so the evidence is cross-species.","localisation_and_range":"JAMs are transmembrane; juxtacrine contact is described [PMID:25119047; flag].","caveats":"Zebrafish genetics; no binding assay; abstract-level. Dossier lists human species for experiments, which seems inaccurate.","key_references":[{"PMID":"25119047","why":"Zebrafish genetics placing Jam1a-Jam2a upstream of Notch signalling"}],"covers":["LR001806","LR005162"]},"LR000546":{"pair":"F2 -> F2RL2","headline":"Thrombin binds the PAR-3 exodomain peptide in a non-catalytic high-affinity mode; abstract-level, polypeptide only.","interaction_type":"direct binding","direction_and_effect":"Thrombin was found to bind two PAR-3 polypeptides, one without catalysing hydrolysis; PAR-3 inhibited thrombin fibrinogen clotting completely with K(I) of 3 microM [PMID:12732212]. Annotated stimulatory [flag].","molecular_requirements":"PAR-3 at low concentrations binds thrombin in a configuration that blocks the anion-binding exosite but not the catalytic site [PMID:12732212].","affinity_potency":[{"value":"K(I) 3 microM","assay":"inhibition of fibrinogen clotting by PAR-3 polypeptide","system":"solution kinetics","cite":"PMID:12732212"},{"value":"half-saturation 2.5 microM","assay":"enhancement of nitroanilide hydrolysis by PAR-3 polypeptide","system":"solvent lacking Na+","cite":"PMID:12732212"}],"species_and_systems":"Purified thrombin and PAR-3 extracellular domain polypeptide; species not stated in our evidence.","localisation_and_range":"F2 flagged secreted; F2RL2 transmembrane [flag].","caveats":"Cell-free peptide kinetics, abstract-only; receptor activation in cells not shown. Two further rows pending.","key_references":[{"PMID":"12732212","why":"PAR-3 peptide binds thrombin with K(I) 3 microM"}],"covers":["LR000546","LR004037"]},"LR004038":{"pair":"F2 -> F2RL3","headline":"No evidence for thrombin acting on PAR-4 in the verified paper, which reports no effect; a PDB structure exists.","interaction_type":"conflicting","direction_and_effect":"None of the thrombin activities were affected by 50 microM PAR-4 polypeptide, in contrast to PAR-3 [PMID:12732212]. Annotated stimulatory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant polypeptide kinetics; species not stated [PMID:12732212]. PDB 3QDZ is human thrombin with human PAR4 fragment [DB:PDB 3QDZ].","localisation_and_range":"F2 flagged secreted; F2RL3 transmembrane [flag].","caveats":"Both verified rows are pair_absent, the human one propagated from the mouse row without re-reading. The PDB structure and Reactome record favour binding, so evidence conflicts. One row pending.","key_references":[{"PMID":"12732212","why":"Verified negative: PAR-4 polypeptide did not affect thrombin"}],"covers":["LR000547","LR004038"]},"LR005163":{"pair":"FAM3C -> LIFR","headline":"FAM3C (ILEI) is reported to signal through LIFR in breast cancer cells; binding is shown by crosslinking in one paper.","interaction_type":"direct binding","direction_and_effect":"LIFR was identified as the ILEI receptor; ILEI activates STAT3 (and ERK) via LIFR to drive EMT and cancer stem cell formation, and only cells containing LIFR responded to ILEI [PMID:30692635].","molecular_requirements":"A yeast two-hybrid screen found LIFR as a candidate partner; radiolabelled ILEI crosslinked to cell-surface LIFR and co-precipitated with LIFR in HEK293 cells expressing FLAG-LIFR; LIF was the positive control [PMID:30692635]. Roles of gp130 or other co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"NMuMG and E1KD mammary cell lines, HEK293 cells, mouse xenograft/metastasis models; recombinant ILEI [PMID:30692635]. Species of the cell lines is not stated in our evidence.","localisation_and_range":"FAM3C is annotated secreted [flag].","caveats":"Single paper with no affinity data. Y2H and crosslinking are not purified-protein binding. Receptor identification is stated as LIFR mediating signalling, with LIFR knockdown abolishing rescue by ILEI [PMID:30692635].","key_references":[{"PMID":"30692635","why":"Identifies LIFR as ILEI receptor with crosslinking and STAT3 signalling"}],"covers":["LR001807","LR005163"]},"LR000555":{"pair":"FAT4 -> DCHS1","headline":"FAT4 and DCHS1 are a cadherin pair acting across cell boundaries; binding in a synthetic cell system, with mouse and human genetic evidence.","interaction_type":"direct binding","direction_and_effect":"Dchs1 and Fat4 are described as a ligand-receptor pair in mouse development, with similar phenotypes in single and double mutants [PMID:21303848]. Mutations in DCHS1 and FAT4 cause a human recessive syndrome including periventricular neuronal heterotopia [PMID:24056717].","molecular_requirements":"Fat4-Ds1 complexes accumulate at cell boundaries, with slower dynamics than unbound Fat4 and Ds1 [PMID:28826487]. Co-expression in the same cells induced polarization of the complexes [PMID:28826487].","affinity_potency":[],"species_and_systems":"Mammalian cells expressing human Fat4 and Ds1 [PMID:28826487]; mouse knockouts [PMID:21303848]; human patients and mouse neuroepithelium knockdown [PMID:24056717]. PDB 8EGW and 8EGX contain both chains [DB:PDB 8EGW] [DB:PDB 8EGX].","localisation_and_range":"Both are flagged not secreted [flag]; the papers describe complexes at cell boundaries, so signaling is by cell-cell contact [PMID:28826487].","caveats":"All three papers read as abstract only. Genetic papers show shared phenotypes, not direct binding. Roles of ligand versus receptor are annotation; Fat4 is also flagged receptor. Affinity not reported.","key_references":[{"PMID":"28826487","why":"Synthetic system showing Fat4-Ds1 complex formation at cell boundaries."},{"PMID":"21303848","why":"Mouse Dchs1 and Fat4 mutants show shared phenotypes."},{"PMID":"24056717","why":"Human and mouse genetics of DCHS1 and FAT4."}],"covers":["LR000555","LR004046"]},"LR002616":{"pair":"FCER2 -> ITGAM","headline":"CD23 binds CD11b-CD18 (CD11b is the alpha chain) in transfected cells and activates monocytes; single 1995 paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 on liposomes bound COS cells transfected with CD11b-CD18; binding was inhibited by anti-CD11b and anti-CD23 mAbs [PMID:7621072]. Triggering monocytes with recombinant CD23 raised nitrite-oxidative products and IL-1 beta, IL-6 and TNF alpha, reduced by Fab fragments to CD11b and CD23 [PMID:7621072]. Curator labels effect agonist.","molecular_requirements":"The paper tested the CD11b-CD18 heterodimer; CD11a-CD18 did not bind [PMID:7621072]. Whether CD11b alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD23 and human cells (COS transfectants, monocytes) [PMID:7621072].","localisation_and_range":"CD23 is flagged secreted and transmembrane [flag]; ITGAM transmembrane.","caveats":"Single paper, read as abstract only. Not tested with soluble CD23 specifically; no affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binding to CD11b-CD18 and monocyte activation"}],"covers":["LR002616"]},"LR000564":{"pair":"FGA -> ITGA2B","headline":"Fibrinogen binds platelet alphaIIb-beta3; functional and in vivo mouse evidence, BioGRID peptide record; chain-level evidence is indirect.","interaction_type":"direct binding","direction_and_effect":"Mouse platelets with an activated alphaIIbbeta3 (R560beta3) bound fibrinogen continuously, detected by a conformation-specific antibody [PMID:23551977]. Effect direction recorded as agonist [PMID:15031111].","molecular_requirements":"Evidence concerns the alphaIIb-beta3 heterodimer with whole fibrinogen; ITGA2B alone and the FGA chain alone were not separated.","affinity_potency":[],"species_and_systems":"Mouse in vivo platelet model with human beta3 lentivirus [PMID:23551977]; mouse trophoblast with human fibrinogen [PMID:15031111]. Human interaction is ortholog-inferred; BioGRID lists a protein-peptide record [DB:BioGRID].","localisation_and_range":"FGA flagged secreted; ITGA2B flagged receptor [flag].","caveats":"One paper is abstract only. A function-blocking anti-alphaIIb antibody disrupted fibrinogen-dependent outgrowth of mouse trophoblast; its statement that fibrinogen is recognised by alphaVbeta3 and alphaIIbbeta3 is a background citation [PMID:15031111]. Another paper was abstract_insufficient and one review_only (not shown).","key_references":[{"PMID":"23551977","why":"fibrinogen-bound alphaIIbbeta3 in vivo"},{"PMID":"15031111","why":"trophoblast adhesion assays"}],"covers":["LR000564","LR004054"]},"LR004056":{"pair":"FGB -> ITGA2B","headline":"Fibrinogen binding to alphaIIb-beta3 is well supported at the complex level; chain-level attribution to FGB is indirect.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaIIbbeta3 binds fibrinogen via RGD sequences; RGD peptides trigger high-affinity fibrinogen binding and act as partial agonists and competitive antagonists [PMID:2018974]. Murine platelets bound fibrinogen continuously with active alphaIIbbeta3 [PMID:23551977].","molecular_requirements":"alphaIIb-beta3 heterodimer with whole fibrinogen; assays do not separate fibrinogen chains, and FGB alone is not tested.","affinity_potency":[],"species_and_systems":"Human platelet integrin (curator fields) [PMID:2018974]; mouse platelets [PMID:23551977]; human fibrinogen on mouse trophoblast [PMID:15031111]. Human interaction is ortholog-inferred.","localisation_and_range":"FGB flagged secreted; ITGA2B receptor [flag].","caveats":"Two papers abstract only; PMID:15031111 relies on background text. Three further rows were abstract_insufficient. No affinity.","key_references":[{"PMID":"2018974","why":"RGD peptides activate alphaIIbbeta3 fibrinogen binding"},{"PMID":"23551977","why":"fibrinogen-bound alphaIIbbeta3 in vivo"}],"covers":["LR000572","LR004056"]},"LR000573":{"pair":"FGB -> ITGAV","headline":"Functional-only support from one full-text paper on mouse trophoblast; the key statement appears to be background, not a result.","interaction_type":"functional only","direction_and_effect":"Human fibrinogen is stated to be recognized by alphaVbeta3 and alphaIIbbeta3 but not alpha5beta1, with trophoblast outgrowth on fibrinogen independent of alpha5beta1; curated as agonist [PMID:15031111]. The mouse-blastocyst outgrowth assay used the alphaIIb-blocking antibody MWReg30, not an alphaV blocker [PMID:15031111].","molecular_requirements":"Receptor is the alphaVbeta3 integrin heterodimer (ITGAV annotated as integrin alphaVbeta3 [flag]); the ITGAV-only contribution is not separated in our evidence.","affinity_potency":[],"species_and_systems":"Human fibrinogen on mouse blastocyst-derived trophoblast cells with native integrin expression [PMID:15031111]. The human interaction record is ortholog-inferred.","localisation_and_range":"FGB is flagged secreted [flag]; used here as a substrate or soluble ligand [PMID:15031111].","caveats":"The sentence supporting alphaVbeta3 recognition cites earlier work (Hynes, 1992) in the excerpt, so it is background rather than this paper's result [PMID:15031111]. No direct binding or alphaV-specific blockade is reported in our evidence. No database records.","key_references":[{"PMID":"15031111","why":"Mouse trophoblast outgrowth on human fibrinogen; alphaVbeta3 mentioned"}],"covers":["LR000573"]},"LR002625":{"pair":"FGF1 -> ITGAV","headline":"Direct FGF1 binding to integrin alphaVbeta3 with a stated Kd about 1 microm; supports signalling but not initial FGFR1 activation.","interaction_type":"direct binding","direction_and_effect":"FGF1 directly bound soluble and cell-surface integrin alphavbeta3, blocked by mAb 7E3 and cyclic RGDfV; the R50E mutant lost integrin binding and was defective in proliferation, migration and chemotaxis while still inducing FGFR1/FRS2alpha phosphorylation and AKT/ERK activation [PMID:18441324]. UniProt states the binding is essential for FGF1 signaling [DB:UniProt].","molecular_requirements":"The partner is the alphavbeta3 heterodimer (ITGAV:ITGB3); beta3 CYDMKTTC loop implicated; FGF1's integrin site overlaps its heparin site but differs from its FGFR site [PMID:18441324]. UniProt describes a ternary complex with FGFR1 and ITGAV:ITGB3 [DB:UniProt].","affinity_potency":[{"value":"KD about 1 microm","assay":"direct binding to soluble and cell-surface alphavbeta3","system":"human FGF1, human integrin","cite":"PMID:18441324"}],"species_and_systems":"Human FGF1 and human integrin alphavbeta3 [PMID:18441324]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 is flagged secreted [flag]; interaction occurs with cell-surface integrin [PMID:18441324].","caveats":"Abstract only. Only weak binding to several beta1 integrins tested [PMID:18441324]. ITGAV alone is not separated from the alphaVbeta3 heterodimer. Single primary paper.","key_references":[{"PMID":"18441324","why":"FGF1 binds alphavbeta3, Kd about 1 microm; R50E mutant"}],"covers":["LR002625","LR005891"]},"LR004065":{"pair":"FGF17 -> FGFR2","headline":"FGF17 activates FGFR2c in BaF3 cells and transforms 3T3 cells; functional evidence, with a BioGRID record.","interaction_type":"functional only","direction_and_effect":"Mouse FGF17 transformed 3T3 fibroblasts, indicating activation of the c form of FGFR1 or FGFR2 [PMID:10381577]. FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the FGFR4 two-Ig form [PMID:16597617]. Agonist.","molecular_requirements":"c splice forms [PMID:16597617]; FGFR2 is not separated from FGFR1 in the transformation assay [PMID:10381577].","affinity_potency":[],"species_and_systems":"BaF3 panel [PMID:16597617]; mouse FGF17 on mouse 3T3 cells [PMID:10381577]. A BioGRID protein-peptide record exists [DB:BioGRID].","localisation_and_range":"FGF17 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617]. Transformation result abstract-only; one paper abstract-insufficient.","key_references":[{"PMID":"10381577","why":"FGF17 transforms 3T3 via FGFR1c/2c"},{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000581","LR004065"]},"LR000582":{"pair":"FGF17 -> FGFR3","headline":"FGF17 activates FGFR3c in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-like domain form of FGFR4 [PMID:16597617]. Agonist.","molecular_requirements":"c isoform of FGFR3 [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF17 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified [PMID:16597617]. Two other judged rows were review-only and one abstract-insufficient.","key_references":[{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000582","LR004066"]},"LR000591":{"pair":"FGF19 -> FGFR4","headline":"Well supported direct binding: FGF19 is a high-affinity, heparin-dependent FGFR4 ligand, with KLB enhancing the physiological complex.","interaction_type":"direct binding","direction_and_effect":"FGF19 binds FGFR4 as an agonist (pKd 9.0) and was the first FGF reported to bind FGFR4 exclusively [PMID:10525310]. 125I-FGF19 bound and activated FGFR4 in cells expressing FGFR4/KLB [PMID:22442730]. BaF3 assays also showed FGF19 activity toward FGFR4 [PMID:16597617]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"Binding is heparin dependent [PMID:10525310]. Reactome describes the complex FGFR4:HS:KLB:FGF19 [DB:Reactome]; with KLB, FGF19 acts on FGFR4 and FGFR1 comparably [PMID:22442730].","affinity_potency":[{"value":"pKd 9.0","assay":"binding of FGF-19 to FGFR4","system":"human ligand and receptor","cite":"PMID:10525310"}],"species_and_systems":"Human ligand and receptor in binding studies [PMID:10525310][PMID:22442730]; FGF19 crystal structure solved at 1.3 A resolution [PMID:14730967]. BioGRID reconstituted complex, IntAct solid-phase assay [DB:BioGRID][DB:IntAct].","localisation_and_range":"FGF19 annotated secreted, FGFR4 annotated transmembrane [flag].","caveats":"The FGF19-FGFR4 complex in the structure paper is a computational model; only FGF19 alone was crystallised [PMID:14730967]. Exclusivity for FGFR4 conflicts with later reports of activity toward FGFR1c, 2c and 3c [PMID:16597617] and FGFR1-KLB binding [PMID:22442730]. Several papers were read as abstract only.","key_references":[{"PMID":"10525310","why":"FGF-19 high-affinity, heparin-dependent FGFR4 ligand"},{"PMID":"22442730","why":"FGF19 binds and activates FGFR4/KLB cells; compared with FGFR1"},{"PMID":"14730967","why":"FGF19 crystal structure and FGFR4 complex model"}],"covers":["LR000591"]},"LR004092":{"pair":"FGF2 -> FGFR1","headline":"Strongly supported canonical FGF2-FGFR1 interaction, including a 3 A ternary crystal structure with heparin.","interaction_type":"direct binding","direction_and_effect":"FGF2 binds FGFR1 well [PMID:10950949]; a 3 A crystal structure of a dimeric 2:2:2 FGF:FGFR:heparin complex shows heparin contacting both ligand and receptor [PMID:11030354]. Perlecan heparan sulfate formed ternary complexes with FGF2 and FGFR1c [PMID:24509440]. Dossier modulatory effect: stimulatory [flag].","molecular_requirements":"Heparin or heparan sulfate is part of the signalling complex: it augments FGF-FGFR binding and promotes FGFR dimerisation; the 6-O-sulfate of heparin is pivotal [PMID:11030354]. Ternary complexes were sensitive to Hep III digestion [PMID:24509440].","affinity_potency":[],"species_and_systems":"Human proteins in all three papers [PMID:11030354][PMID:10950949][PMID:24509440]. Structures PDB 1CVS and 1FQ9; BioGRID, IntAct and UniProt records [DB:PDB 1CVS][DB:PDB 1FQ9][DB:BioGRID][DB:IntAct][DB:UniProt].","localisation_and_range":"FGF2 is annotated secreted and FGFR1 transmembrane [flag]; HS in the matrix (perlecan) acts as an adaptor.","caveats":"Two of three papers were read as abstract only. No Kd given in our evidence. Three further papers were abstract_insufficient.","key_references":[{"PMID":"11030354","why":"3 A FGF:FGFR:heparin ternary structure"},{"PMID":"24509440","why":"Perlecan HS forms FGF2-FGFR1c ternary complexes"},{"PMID":"10950949","why":"FGF2 binds FGFR1 well"}],"covers":["LR000608","LR004092"]},"LR000609":{"pair":"FGF2 -> FGFR2","headline":"FGF2 binds FGFR2 well and activates c splice forms, from two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"FGF-2 binds well to FGFR1, FGFR2 and FGFR4 but poorly to KGFR (FGFR2-IIIb) [PMID:10950949]. In BaF3 mitogenic assays FGF2 preferentially activates c splice forms [PMID:8663044]. Dossier modulatory effect: stimulatory [flag].","molecular_requirements":"Splice form matters: the IIIb form (KGFR) binds FGF2 poorly [PMID:10950949], and c forms are preferred [PMID:8663044]. Heparin dependence is not reported for this pair in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the binding study [PMID:10950949]; BaF3 species not stated [PMID:8663044]. BioGRID, IntAct, PDB 1EV2, 1II4, 1IIL and Reactome records [DB:BioGRID][DB:IntAct][DB:PDB 1EV2][DB:Reactome].","localisation_and_range":"FGF2 annotated secreted, FGFR2 transmembrane [flag].","caveats":"Both papers abstract only; the first is mainly about FGF-7 and uses FGF-2 as a comparator. No affinity in our evidence.","key_references":[{"PMID":"10950949","why":"FGF-2 binds FGFR2 well, not KGFR"},{"PMID":"8663044","why":"BaF3 activity favouring c splice forms"}],"covers":["LR000609","LR004093"]},"LR000618":{"pair":"FGF2 -> SDC4","headline":"FGF2 binds syndecan-4 (ryudocan) via heparan sulfate chains, with Kd 0.50 nM for purified ryudocan; several supporting papers.","interaction_type":"direct binding","direction_and_effect":"bFGF bound only HS chains of syndecan-1 and -4 ectodomains by BIAcore [PMID:15226297]. Purified human ryudocan bound bFGF, midkine and TFPI via HS chains in a solid-phase assay [PMID:8621465]. Cotransfected syndecan-4 with FGFR1 increased specific 125I-bFGF binding two- to three-fold in K562 cells [PMID:8609172]. BioGRID lists a co-purification record [DB:BioGRID].","molecular_requirements":"HS chains mediate binding; heparitinase abolished it, chondroitin ABC lyase did not [PMID:8621465]. Syndecan-4 supports FGF2-FGFR1 complex formation in K562 cells [PMID:8609172].","affinity_potency":[{"value":"0.50 nM","assay":"apparent dissociation constant, solid-phase binding of bFGF to purified ryudocan","system":"human ryudocan from EAhy926 cells","cite":"PMID:8621465"}],"species_and_systems":"Murine mammary syndecan ectodomains [PMID:15226297]; human EAhy926 ryudocan [PMID:8621465]; human K562 cells [PMID:8609172].","localisation_and_range":"SDC4 is flagged as a receptor and FGF2 secreted [flag]; ryudocan is a cell-surface proteoglycan [PMID:8621465].","caveats":"HS-chain binding is not specific to syndecan-4; the Kd comes from an abstract-only paper. One further paper was abstract_insufficient and one pending.","key_references":[{"PMID":"8621465","why":"Ryudocan binds bFGF with Kd 0.50 nM via HS"},{"PMID":"15226297","why":"BIAcore: bFGF binds HS chains of SDC4"},{"PMID":"8609172","why":"Syndecan-4 increases FGF2 binding to FGFR1"}],"covers":["LR000618","LR004102"]},"LR001815":{"pair":"FGF20 -> FGFR1","headline":"FGF20 activating FGFR1 is supported only indirectly: a family-wide mitogenic screen and mouse heart genetics.","interaction_type":"functional only","direction_and_effect":"In the BaF3 mitogenic screen, FGF9, 16 and 20 activated FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. In mouse heart, endocardial/epicardial FGF signals, with Fgf9, Fgf16 and Fgf20 expressed, were received by FGFR1 and FGFR2 acting redundantly [PMID:15621532].","molecular_requirements":"FGFR1 and FGFR2 act redundantly in cardiomyoblasts [PMID:15621532]. Heparan sulfate or other co-factors are not reported in our evidence for FGF20.","affinity_potency":[],"species_and_systems":"BaF3 cell lines, species unspecified [PMID:16597617]; knockout mice and embryonic mouse heart organ culture [PMID:15621532].","localisation_and_range":"FGF20 is flagged secreted and FGFR1 transmembrane [flag]; paracrine signalling in heart is described [PMID:15621532].","caveats":"No FGF20-FGFR1 binding data. The screen quote does not name FGFR1 specifically, and the mouse pairing is inferred from joint Fgf9/16/20 knockout and redundant Fgfr1/Fgfr2 requirement, not isolated FGF20 data. The first paper's quote was browser-read and flagged unverifiable. Review, pending and abstract_insufficient rows are not shown.","key_references":[{"PMID":"16597617","why":"Mitogenic receptor-specificity screen of FGF9/16/20"},{"PMID":"15621532","why":"Mouse heart FGF signals via FGFR1/FGFR2"}],"covers":["LR001815","LR005170"]},"LR005172":{"pair":"FGF20 -> FGFR3","headline":"FGF20 is reported in a mitogenic screen to act on FGFR3b-expressing cells; single indirect source.","interaction_type":"functional only","direction_and_effect":"FGF9, 16 and 20 consistently showed activity toward FGFR3b-expressing cells in the BaF3 mitogenic assay [PMID:16597617].","molecular_requirements":"Only the b splice form of FGFR3 is named in the quote; other isoforms are not reported in our evidence [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cells engineered to express FGFRs; species unspecified [PMID:16597617]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF20 flagged secreted, FGFR3 transmembrane [flag].","caveats":"One paper, a subfamily-level statement not specific to FGF20; no binding data. A review row is not shown. The excerpt was browser-read and flagged unverifiable.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenic screen of the FGF family"}],"covers":["LR001817","LR005172"]},"LR004083":{"pair":"FGF20 -> FGFR4","headline":"FGF20 is reported in a mitogenic screen to activate FGFR4 with high activity; single indirect source.","interaction_type":"functional only","direction_and_effect":"FGF9, 16 and 20 activated FGFRc isoforms and FGFR4 with high activity in the BaF3 mitogenic assay [PMID:16597617].","molecular_requirements":"Not reported in our evidence beyond FGFR4 being activated; heparan sulfate need is not stated.","affinity_potency":[],"species_and_systems":"BaF3 FGFR-expressing cell lines; species unspecified [PMID:16597617]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF20 flagged secreted; FGFR4 flagged secreted and transmembrane [flag].","caveats":"One paper, a subfamily-level statement; no direct binding or FGF20-specific data. Quote was browser-read and flagged unverifiable. Review and abstract_insufficient rows are not shown.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenic screen of the FGF family"}],"covers":["LR000599","LR004083"]},"LR002634":{"pair":"FGF21 -> FGFR1","headline":"FGF21 binds FGFR1 with KLB present, with stronger affinity than FGFR4; direct binding evidence, KLB-dependent.","interaction_type":"direct binding","direction_and_effect":"FGF21 binds FGFR1 with much higher affinity than FGFR4 in the presence of KLB [PMID:22442730]. GtoPdb lists the pair as agonist [DB:GtoPdb]. A BaF3 mitogenic assay also reports FGF21 activity toward FGFR1c [PMID:16597617].","molecular_requirements":"KLB is described as an indispensable mediator of FGF19/FGF21 binding to FGFRs [PMID:22442730]. FGF21 competed with labeled FGF19 on FGFR1-KLB cells and on KLB alone, with over 90% efficiency at 1 ug/ml [PMID:22442730]. Activity toward FGFR1c but not FGFR1b is reported [PMID:16597617].","affinity_potency":[{"value":"half-maximum competition about 150 ng/ml","assay":"competition of unlabeled FGF21 against 125I-FGF19 binding","system":"cells co-expressing FGFR1 and KLB","cite":"PMID:22442730"}],"species_and_systems":"The 2012 study used recombinant protein in cultured cells (T-Rex 293 expressing FGFR1-KLB) and mice for signaling [PMID:22442730]; the species of reagents in the 2006 BaF3 study is unspecified [PMID:16597617].","localisation_and_range":"FGF21 is flagged secreted and not transmembrane [flag]; the receptor is flagged transmembrane [flag]. Endocrine range is not stated in our evidence beyond the flags.","caveats":"FGF21 could not be radio-iodinated without losing activity, so binding was measured indirectly by competition with FGF19 [PMID:22442730]. The 2012 paper was curated from the abstract plus excerpts; the 2006 paper was read only as an abstract in the dossier and its quote is unverified. Mouse pair is projected from human.","key_references":[{"PMID":"22442730","why":"Quantitative binding of FGF21 to FGFR1-KLB vs FGFR4-KLB"},{"PMID":"16597617","why":"BaF3 mitogenic activity of FGF21 on FGFR1c"}],"covers":["LR002634","LR005900"]},"LR005901":{"pair":"FGF21 -> FGFR3","headline":"Functional (mitogenic) activity of FGF21 on FGFR3c reported in one screen; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"FGF21 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 but not FGFR1b, 2b or 3b in BaF3 cells [PMID:16597617]; stimulatory.","molecular_requirements":"Only c splice forms were active; cofactors not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"BaF3 lines expressing individual FGFRs; species unspecified [PMID:16597617].","localisation_and_range":"FGF21 secreted [flag]; FGFR3 transmembrane [flag].","caveats":"Single functional paper; quote browser-read and unverified [PMID:16597617]. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR002635","LR005901"]},"LR000627":{"pair":"FGF5 -> FGFR2","headline":"FGF5 binds and activates FGFR2: nanomolar KD with recombinant human proteins and Co-IP in nasopharyngeal carcinoma cells.","interaction_type":"direct binding","direction_and_effect":"Recombinant human FGF-5 bound and induced autophosphorylation of FGFR2 [PMID:8386828]. In NPC cells, CAF-secreted FGF5 bound FGFR2 (Co-IP) and activated Keap1/Nrf2/HO-1 signalling, inhibiting cisplatin-induced ferroptosis [PMID:38637504]. FGF5 bound FGFR2 more tightly than other FGFRs in NPC tissues [PMID:38637504].","molecular_requirements":"Heparin was present in the recombinant activity assays [PMID:8386828]. Other requirements are not reported in our evidence.","affinity_potency":[{"value":"KD between 0.5 and 1.5 x 10(-9) M","assay":"competition binding","system":"recombinant human FGF-5 with human FGFR-2","cite":"PMID:8386828"}],"species_and_systems":"Human NPC cell lines (HK1, C666-1), patient tissues and a nude-mouse xenograft with recombinant FGF5 [PMID:38637504]; human recombinant proteins [PMID:8386828]; BaF3 with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGF5 is a secreted factor (CAF-derived) [PMID:38637504] and flagged secreted [flag]; FGFR2 is a membrane receptor.","caveats":"The authors note it is uninvestigated whether FGF5/FGFR2 activates Keap1/Nrf2/HO-1 directly [PMID:38637504]. The KD range is shared with FGFR1 and from an abstract-only read.","key_references":[{"PMID":"38637504","why":"Co-IP and functional FGF5/FGFR2 axis in NPC"},{"PMID":"8386828","why":"KD and autophosphorylation of FGFR2"},{"PMID":"8663044","why":"BaF3 specificity survey"}],"covers":["LR000627","LR004111"]},"LR004119":{"pair":"FGF7 -> FGFR2","headline":"Well supported: FGF7 activates the b isoform of FGFR2, with BaF3 mitogenesis and database binding records.","interaction_type":"functional only","direction_and_effect":"FGF7 and FGF10 activate only the b isoform of FGFR2 [PMID:12591959]; FGFs 7, 10 and 22 strongly activated FGFR2b in BaF3 cells [PMID:16597617]. The pair is annotated stimulatory.","molecular_requirements":"Splice isoform FGFR2b (exon IIIb) is the responsive form [PMID:12591959]. Heparan sulfate is described as a modulating cofactor in the survey abstract [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cell lines, species unspecified [PMID:16597617]. The structure paper (abstract only) restates FGF7 activity but solved FGF10-FGFR2b, not FGF7 [PMID:12591959]. Database records: BioGRID reconstituted complex, IntAct cross-linking/saturation binding [DB:BioGRID][DB:IntAct].","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"The FGF7 statement in PMID:12591959 is background rather than this paper's own result. BaF3 quote is browser-read and pending spot-check.","key_references":[{"PMID":"16597617","why":"FGF7 strongly activates FGFR2b in BaF3"},{"PMID":"12591959","why":"States FGF7 and FGF10 activate only FGFR2b"}],"covers":["LR000635","LR004119"]},"LR000636":{"pair":"FGF7 -> NRP1","headline":"FGF7 binds immobilised NRP1 strongly in a biosensor; heparin-dependent and functional relevance not shown.","interaction_type":"direct binding","direction_and_effect":"Strong binding to Npn-1 was observed with the four FGFs tested, including FGF-7 [PMID:15695515]. No FGF7 functional effect is reported in our evidence.","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site [PMID:15695515].","affinity_potency":[],"species_and_systems":"Optical biosensor with low-density immobilised Npn-1; human proteins [PMID:15695515]. Both interactions are ortholog-inferred.","localisation_and_range":"NRP1 is flagged as a transmembrane receptor with a secreted form [flag]; FGF7 localisation is not reported in our evidence.","caveats":"FGF-2 and FGF-4, not FGF-7, were additionally confirmed in a solution pull-down [PMID:15695515]. Binding is likely electrostatic rather than a specific interface; no kinetics for FGF7.","key_references":[{"PMID":"15695515","why":"Biosensor binding of FGF-7 to Npn-1"}],"covers":["LR000636","LR004120"]},"LR004128":{"pair":"FGF9 -> FGFR4","headline":"FGF9 activates FGFR4 in mitogenic assays; support is functional only and mouse and human are projected.","interaction_type":"functional only","direction_and_effect":"FGFs of the FGF9 subfamily activated FGFRc isoforms and FGFR4 with high activity in BaF3 mitogenesis assays [PMID:16597617]. A second BaF3 study covers FGF9 specificity across receptor splice variants [PMID:8663044].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BaF3 experiments is unspecified [PMID:16597617][PMID:8663044]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"FGF9 is flagged secreted and FGFR4 transmembrane [flag].","caveats":"No direct binding data and no database records. Both papers are functional mitogenic readouts; the FGFR4 statement comes from the sentence on the FGF9 subfamily [PMID:16597617]. The sentence cited from PMID:8663044 does not mention FGFR4 explicitly.","key_references":[{"PMID":"16597617","why":"FGF9-subfamily FGFs activate FGFR4"},{"PMID":"8663044","why":"BaF3 receptor specificity of FGFs"}],"covers":["LR000644","LR004128"]},"LR000645":{"pair":"FGG -> ITGA2B","headline":"Fibrinogen gamma chain binds integrin alphaIIbbeta3 via its C-terminal gammaC peptide; strong structural support.","interaction_type":"direct binding","direction_and_effect":"The fibrinogen gamma C-terminal peptide binds alphaIIbbeta3 on platelets; the integrin MIDAS Mg2+ binds the gammaC Asp side chain [PMID:18710925]. RGD peptides bind and activate the receptor, giving high-affinity fibrinogen binding [PMID:2018974]. Fibrinogen was recognised by alphaIIbbeta3 in trophoblast outgrowth [PMID:15031111].","molecular_requirements":"The functional receptor is the alphaIIb/beta3 heterodimer, not alphaIIb alone. The KQAGDV motif binds in the groove between the subunits [PMID:26631735]. Fibrinogen is FGA:FGB:FGG and the assay does not separate the chains [PMID:2018974].","affinity_potency":[],"species_and_systems":"Human crystal structures and platelets [PMID:18710925][PMID:2018974]; human fibrinogen on mouse trophoblast cells [PMID:15031111]. Both human and mouse pairs listed, not inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"PDB structures 2VDO-2VDR include a fibrinogen chain and ITGA2B [DB:PDB 2VDO]; BioGRID has a protein-peptide record [DB:BioGRID]. Several papers were read as abstracts only. Use the complex when scoring.","key_references":[{"PMID":"18710925","why":"Crystal structure of alphaIIbbeta3 with gammaC peptide"},{"PMID":"26631735","why":"KQAGDV of the gamma chain binds the integrin; beta3 binding suffices to open headpiece"},{"PMID":"2018974","why":"RGD binding activates fibrinogen binding to alphaIIbbeta3"}],"covers":["LR000645","LR004129"]},"LR001824":{"pair":"FGG -> TLR4","headline":"Fibrinogen is reported as an endogenous TLR4 ligand activating monocytes; functional with database support.","interaction_type":"functional only","direction_and_effect":"Fibrinogen activated monocytes from pre-eclamptic patients as an endogenous TLR4 ligand [PMID:24661950]. Reactome describes cleaved fibrinogen products binding TLR4:LY96 [DB:Reactome R-HSA-8870678].","molecular_requirements":"Reactome lists the TLR4:LY96 complex [DB:Reactome R-HSA-8870678]; requirement for MD-2 is not shown by the paper in our evidence.","affinity_potency":[],"species_and_systems":"Human monocytes from patients [PMID:24661950]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"Abstract-only read; whole fibrinogen, not FGG chain, and cleaved products in Reactome. Direct binding is not shown in our evidence; IntAct records ELISA [DB:IntAct].","key_references":[{"PMID":"24661950","why":"Fibrinogen as TLR4 ligand on monocytes"}],"covers":["LR001824","LR005179"]},"LR002643":{"pair":"FLRT1 -> ADGRL3","headline":"Ecto-LPHN3-Fc bound FLRT1 strongly; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Ecto-LPHN3-Fc bound strongly to FLRT1 and FLRT2 as well as FLRT3 [PMID:22405201]. Effect of binding on signalling not reported for FLRT1 in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Receptor-ligand binding and pull-downs; species recorded as human [PMID:22405201]. Human pair is ortholog-inferred, mouse is not.","localisation_and_range":"FLRT1 flagged secreted and transmembrane [flag]; FLRT proteins are single-pass transmembrane [PMID:22405201], so contact-mediated.","caveats":"Single confirming paper; mass-spec pull-downs focused on FLRT3. No affinity. No database records.","key_references":[{"PMID":"22405201","why":"LPHN3 binds FLRT1/2/3"}],"covers":["LR002643","LR005909"]},"LR005910":{"pair":"FLRT1 -> UNC5B","headline":"FLRT1 binds UNC5B, weakly in one paper and near saturation in a binding screen.","interaction_type":"conflicting","direction_and_effect":"All FLRT1-3 and Unc5A-D combinations bound at or near saturation in a high-throughput binding screen with ELISA titration [PMID:26633812]. Another paper found FLRT1 showed only relatively weak binding to Unc5B [PMID:21673655].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified ectodomains, CHO.K1 aggregation and mouse retina [PMID:26633812]; species of the other paper not stated. Human pair ortholog-inferred.","localisation_and_range":"FLRT1 flagged secreted and transmembrane [flag]; contact-mediated.","caveats":"Binding strength disagrees between papers [PMID:21673655][PMID:26633812]. One was a browser-read quote pending spot-check [PMID:21673655]. No affinity values.","key_references":[{"PMID":"26633812","why":"FLRT x Unc5 binding screen"},{"PMID":"21673655","why":"FLRT1 weak on Unc5B; FLRT2-Unc5D specificity"}],"covers":["LR002644","LR005910"]},"LR002652":{"pair":"FLRT2 -> UNC5A","headline":"FLRT2 binds UNC5A directly in a full-text extracellular binding screen; one paper, no affinity reported.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. FLRT2 stripes repelled 18% of neurons, whereas Unc5A stripes gave no attractive or repulsive response (n=257/257, 100% permissive) with reduced outgrowth and viability [PMID:26633812]. UniProt states the UNC5A extracellular domain interacts with the FLRT2 extracellular domain [DB:UniProt, PMID:25374360].","molecular_requirements":"Purified ectodomains were used for the ELISA titrations and full-length proteins for the cell aggregation assay; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding screen used purified ectodomains and CHO.K1 cells; neurite assays used mouse retinal neurons. The record covers a human and a mouse pair; the paper's species labels in the curated row are human for both partners [PMID:26633812].","localisation_and_range":"Both partners carry transmembrane flags and the cell aggregation assay indicates interaction between opposing cell surfaces (contact-mediated) [PMID:26633812]; FLRT2 is also flagged secreted [flag].","caveats":"Direct binding is supported by one paper plus a UniProt statement; no functional effect specific to FLRT2-UNC5A is reported. Unc5A stripes did not repel neurons [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Full-text screen showing all FLRT x Unc5 pairs bind near saturation."}],"covers":["LR002652","LR005918"]},"LR007206":{"pair":"FLRT3 -> ADGRL2","headline":"Only family-level support for FLRT3 binding latrophilin-2; no ADGRL2-specific experiment in our dossier.","interaction_type":"functional only","direction_and_effect":"Curator-confirmed papers describe FLRT-latrophilin interaction generally: the Lphn3 N-terminal region binds FLRT [PMID:25728924], and Lphn1-3 interact with FLRT1-3 [PMID:27091502]. Neurons were repelled by Lphn3 stripes while HeLa cells adhered [PMID:25728924]; these are Lphn3 results.","molecular_requirements":"Not reported in our evidence for ADGRL2.","affinity_potency":[],"species_and_systems":"Mouse Lphn3 crystal structures, SPR and cultured cells [PMID:25728924]; purified ectodomains, crystallography [PMID:27091502]. No ADGRL2 experiment reported.","localisation_and_range":"FLRT3 annotated secreted and transmembrane, ADGRL2 transmembrane [flag].","caveats":"Both papers concern Lphn3; ADGRL2 is covered only by family-level statements. Three further papers were review-only and two abstract-insufficient. No affinity, no database records.","key_references":[{"PMID":"25728924","why":"Lphn3 structure and FLRT binding surface (family-level for this pair)"},{"PMID":"27091502","why":"Family statement that Lphn1-3 interact with FLRT1-3"}],"covers":["LR007206"]},"LR002661":{"pair":"FLRT3 -> UNC5D","headline":"Binding is supported by a screen but a 2011 study found Unc5D specific for FLRT2, so evidence conflicts.","interaction_type":"conflicting","direction_and_effect":"All twelve FLRT x Unc5 pairs, including FLRT3 and Unc5D, bound near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. The 2011 abstract reports that Unc5D binds specifically to FLRT2 and calls FLRT3 the partner of Unc5B, so the curators judged the FLRT3-Unc5D pair absent from it [PMID:21673655].","molecular_requirements":"FLRT3, ADGRL3 and UNC5D are listed in complexes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Screen: purified ectodomains, CHO.K1 aggregation [PMID:26633812]; 2011: abstract only, neocortex [PMID:21673655].","localisation_and_range":"FLRT3 annotated secreted and transmembrane, UNC5D transmembrane [flag].","caveats":"Specificity statements in the abstract argue against FLRT3-Unc5D, though it does not test the pair explicitly [PMID:21673655]. Human pair is ortholog-inferred. No affinity.","key_references":[{"PMID":"26633812","why":"Screen shows FLRT3-Unc5D binding"},{"PMID":"21673655","why":"Reports Unc5D specificity for FLRT2"}],"covers":["LR002661","LR005927"]},"LR004137":{"pair":"Flt3l -> Flt3","headline":"Mouse Flt3l-Flt3 binding and receptor activation are supported by three abstract-level papers; no affinity reported.","interaction_type":"direct binding","direction_and_effect":"Cloned ligand conferred binding to a soluble flt3/flk-2 receptor and stimulated proliferation of receptor-transfected cells [PMID:7505204]. FL induced AKT activation and FoxO3 phosphorylation in FDC-P1 cells expressing murine FLT3, blocked by LY294002 [PMID:15147956]. A mutational screen with a FLT3R-Fc probe described FLT3L as binding and activating its receptor [PMID:9651358]. Agonist.","molecular_requirements":"Soluble ligand was active [PMID:7505204]; a mutation predicted to disrupt the FLT3L dimerization interface altered the ligand's Stokes radius [PMID:9651358]. Subunit requirements for the receptor are not reported.","affinity_potency":[],"species_and_systems":"Murine receptor and cells in [PMID:7505204] and [PMID:15147956]; the structure-function screen used human FLT3L and a receptor-Fc fusion [PMID:9651358].","localisation_and_range":"The cloned ligand is a type I transmembrane protein and a soluble form is also active [PMID:7505204]; the entity is flagged secreted [flag].","caveats":"All three papers were read as abstracts only. No affinity values in our evidence.","key_references":[{"PMID":"7505204","why":"expression cloning of the ligand with binding to soluble flt3/flk-2"},{"PMID":"9651358","why":"ligand residues for receptor binding and affinity"},{"PMID":"15147956","why":"downstream AKT/FoxO3 signalling in FLT3-expressing cells"}],"covers":["LR004137"]},"LR000654":{"pair":"FN1 -> CD44","headline":"Direct binding of CD44 to the C-terminal heparin-binding domain of fibronectin is shown by one 1992 paper plus BioGRID records.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified CD44 bound fibronectin, mediated through the chondroitin sulfate-containing form of CD44; the binding site on fibronectin is its COOH-terminal heparin-binding domain [PMID:1730778]. Binding was inhibited by chondroitin sulfate and by the syndecan ectodomain [PMID:1730778].","molecular_requirements":"Binding required the chondroitin sulfate-modified CD44 form [PMID:1730778].","affinity_potency":[],"species_and_systems":"Human proteins per curator fields; mouse pair is orthology-inferred [PMID:1730778]. BioGRID lists affinity capture-Western and reconstituted-complex records [DB:BioGRID].","localisation_and_range":"FN1 flagged secreted, CD44 flagged both secreted and transmembrane [flag]; matrix-to-cell contact.","caveats":"Only one confirmed paper; no affinity reported. The cell source for the CD44 isolation is not stated in our evidence.","key_references":[{"PMID":"1730778","why":"CD44 binds the COOH-terminal heparin-binding domain of fibronectin"}],"covers":["LR000654","LR004138"]},"LR007017":{"pair":"FN1 -> ITGA11:ITGB1","headline":"No curated paper supports fibronectin binding to ITGA11:ITGB1; evidence is generic fibronectin-integrin database records.","interaction_type":"database-asserted only","direction_and_effect":"Database records show fibronectin with ITGB1 (BioGRID reconstituted complex, affinity capture-Western) and IntAct SPR/FACS records [DB:BioGRID] [DB:IntAct]. The structural and pathway records are for the alpha5beta1 complex with fibronectin [DB:PDB 7NWL] [DB:Reactome]. Direction and effect are not reported for this pair.","molecular_requirements":"ITGA11:ITGB1 is a complex; the cited records concern ITGB1 or alpha5beta1, not this alpha chain, so alpha-chain specificity is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; BioGRID and IntAct experiment species not stated in our evidence.","localisation_and_range":"FN1 flagged secreted; the integrin complex is flagged transmembrane or receptor [flag].","caveats":"No confirmed paper. Support is inferred from ITGB1/alpha5beta1 records.","key_references":[],"covers":["LR007017"]},"LR004146":{"pair":"FN1 -> ITGA9","headline":"The EIIIA segment of fibronectin is reported as a ligand of integrin alpha9beta1; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The EIIIA segment of fibronectin is a ligand for integrins alpha9beta1 and alpha4beta1 [PMID:11839764].","molecular_requirements":"Binding is through the alternatively spliced EIIIA segment, so only EIIIA-containing FN1 isoforms apply [PMID:11839764]. The receptor is the alpha9beta1 heterodimer.","affinity_potency":[],"species_and_systems":"Experimental species not specified in the dossier [PMID:11839764].","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"One paper, abstract-only, with the same paper entered twice for the subunit and complex pairs. No database records. No affinity reported in our evidence.","key_references":[{"PMID":"11839764","why":"First identification of integrins binding the EIIIA segment"}],"covers":["LR000662","LR004146"]},"LR000663":{"pair":"FN1 -> ITGAV","headline":"Fibronectin binds alphaV-containing integrins, backed by force spectroscopy, reconstitution and structures.","interaction_type":"direct binding","direction_and_effect":"FN1 is an agonist ligand; alphaV-class integrins and alpha5beta1 solely recognise the FN RGD motif, and alphaV-class integrins retain FN-RGE binding [PMID:33141174]. In a neuroblastoma extract, liposomes with all three polypeptides bound vitronectin, fibronectin and type I collagen [PMID:1693626].","molecular_requirements":"AlphaV pairs with a beta chain; a novel beta1-like subunit with alphaV mediated fibronectin/collagen binding, while alphaVbeta3 gave vitronectin binding [PMID:1693626]. Databases cover ITGB3-FN1 and PDB structures with a P05106 chain [DB:PDB 4MMX].","affinity_potency":[],"species_and_systems":"Human cells [PMID:1693626, PMID:33141174]. PMID:15031111 used human FN on mouse trophoblast.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Abstract-only for two papers. PMID:15031111 concerns alphaIIbbeta3, not alphaV (curation flag). Two other judged rows were assigned to a different entity.","key_references":[{"PMID":"33141174","why":"alphaV-class integrins bind the FN RGD motif"},{"PMID":"1693626","why":"Reconstituted liposomes bind fibronectin"}],"covers":["LR000663","LR004147"]},"LR007026":{"pair":"FN1 -> ITGAV:ITGB3","headline":"Supported by database records only: structures, BioGRID and IntAct; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence; class is annotated Adhesion-Adhesion [flag].","molecular_requirements":"PDB 4MMX is an X-ray structure of the AlphaVBeta3 ectodomain bound to the tenth domain of fibronectin [DB:PDB 4MMX]. Reactome entries concern alphaIIbbeta3 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond record types.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"No papers confirmed; two review-only papers were judged. Records include BioGRID ITGB3-FN1 reconstituted complex [DB:BioGRID] and IntAct solid-phase and FACS [DB:IntAct].","key_references":[],"covers":["LR007026"]},"LR004155":{"pair":"FN1 -> TSHR","headline":"Fibronectin anchors TSHR and modulates its responsiveness; not a signalling ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"Fibronectin/ECM interaction concentrated TSHR at lamellipodia; ECM attachment increased TSH-stimulated adenylate cyclase but not PLC, and constitutive activity appeared only in attached cells [PMID:11981027]. Fibronectin does not itself activate TSHR in this evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured human thyroid cells and transfected cells [PMID:11981027]; mouse is inferred.","localisation_and_range":"TSHR flagged transmembrane receptor [flag]; fibronectin matrix-bound.","caveats":"Abstract only; no direct binding assay or affinity. The homologous LH receptor, which does not interact with ECM, served as a negative control [PMID:11981027]. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"11981027","why":"TSHR-ECM/fibronectin interaction modulates signalling"}],"covers":["LR000671","LR004155"]},"LR005181":{"pair":"FNDC5 -> ITGAV","headline":"Irisin (FNDC5) binds alphaV-class integrins; binding plus functional and mouse knockout evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Irisin binds alphaV-class integrins; chemical inhibition of alphaV integrins blocked irisin signalling in osteocytes and fat cells, and irisin increased osteocyte survival and sclerostin production [PMID:30550785]. Agonist-type effect.","molecular_requirements":"Interaction mapped to alphaV/beta5 integrin, so the receptor is the integrin heterodimer [PMID:30550785].","affinity_potency":[],"species_and_systems":"Recombinant irisin in cultured cells and mice; FNDC5-null mice were protected from ovariectomy-induced bone loss [PMID:30550785].","localisation_and_range":"FNDC5 flagged secreted [flag]; irisin is described as a muscle-secreted hormone (endocrine) [PMID:30550785].","caveats":"Single paper, abstract-level curation plus excerpts; no affinity values reported in our evidence. No database record.","key_references":[{"PMID":"30550785","why":"Irisin binds alphaV integrins"}],"covers":["LR001826","LR005181"]},"LR000672":{"pair":"FSHB -> FSHR","headline":"Established FSH-FSHR hormone-receptor pair supported by structures and databases; no curator-verified papers in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists FSHB-FSHR as an agonist interaction [DB:GtoPdb]. UniProt says FSHB binds FSHR to activate downstream signalling [DB:UniProt].","molecular_requirements":"FSH is a CGA:FSHB heterodimer binding FSHR [DB:UniProt]; crystal structures of FSH with the receptor are PDB 1XWD and 4AY9 [DB:PDB 1XWD].","affinity_potency":[],"species_and_systems":"Structures are of the human complex [DB:PDB 1XWD]; mouse row is inferred.","localisation_and_range":"FSHB flagged secreted; FSHR flagged transmembrane receptor [flag].","caveats":"Papers judged were abstract_insufficient or unresolvable, so no verified paper; GtoPdb affinity units are not given. Co-subunit CGA is needed per UniProt.","key_references":[],"covers":["LR000672","LR004156"]},"LR008520":{"pair":"FST -> INHBA","headline":"Follistatin binds activin A (INHBA) per structures and databases; curated papers were all judged off-target.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records follistatin binding activin [DB:Reactome R-HSA-2473184]; UniProt says INHBA interacts with FST [DB:UniProt]. Follistatin is an inhibitor (flag) [flag].","molecular_requirements":"Co-crystal structures PDB 2B0U and 2P6A [DB:PDB 2B0U, DB:PDB 2P6A]; BioGRID reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human structures and in vitro reconstitution [DB:BioGRID].","localisation_and_range":"Receptor-side flagged secreted [flag].","caveats":"No verified paper: five judged a different entity and one review-only. Affinity not reported in our evidence.","key_references":[],"covers":["LR008520"]},"LR007215":{"pair":"GALP -> GALR2:GPR151","headline":"No primary evidence for a GALR2:GPR151 complex; support is for GALR2 alone from GtoPdb.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence for the complex. GtoPdb lists GALP as an agonist at GALR2 alone [DB:GtoPdb].","molecular_requirements":"Whether GPR151 is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments for this complex are in our evidence; the papers judged were review-only or had insufficient abstracts.","localisation_and_range":"GALP is flagged as secreted; the receptor entry is flagged as a transmembrane receptor [flag].","caveats":"Support rests on GALR2 records, not on GPR151 participation [DB:GtoPdb]. Treat as the single-receptor pair. A UniProt record (O88854) says it is a receptor for galanin, GALP and spexin-1 [DB:UniProt].","key_references":[],"covers":["LR007215"]},"LR002670":{"pair":"GAS1 -> PTPRA","headline":"GAS1 binds PTPRA directly by SPR (KD ~1 uM) and stains PTPRA-expressing cells; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"GAS1 bound PTPRA exclusively among tested RPTPs and tetramerised GAS1 bound K562 cells overexpressing PTPRA, which the authors interpret as GAS1 acting as a soluble ligand for cell-surface PTPRA [PMID:36178190]. Activating or inhibitory effect is not reported in our evidence.","molecular_requirements":"Full-length PTPRA was used in cells and the ectodomain for SPR; no PTPRU or PTPRJ binding was seen by SPR [PMID:36178190]. Co-receptor needs are not reported in our evidence.","affinity_potency":[{"value":"KD of ~1 uM","assay":"surface plasmon resonance","system":"human GAS1 analyte binding PTPRA ectodomain","cite":"PMID:36178190"}],"species_and_systems":"Human proteins: CRISPRa screen, SPR and cell-surface staining of K562 cells [PMID:36178190]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS1 is flagged as non-secreted and as a receptor [flag], although the paper calls it a soluble ligand [PMID:36178190].","caveats":"Single paper from a high-throughput deorphanisation screen; affinity is low (micromolar). The curator evidence sentence is a figure legend describing the cell staining assay.","key_references":[{"PMID":"36178190","why":"CRISPRa screen, SPR and cell staining identifying GAS1-PTPRA"}],"covers":["LR002670","LR005935"]},"LR004164":{"pair":"GAS6 -> MERTK","headline":"Direct agonist interaction supported by binding with a Kd and by Mer phosphorylation; moderate affinity.","interaction_type":"direct binding","direction_and_effect":"GAS6 is an agonist of MERTK: Gas6 induced rapid phosphorylation of Mer in several cell types, followed by transient p42 MAP kinase activation [PMID:9160883], and stimulated Mer phosphorylation in CHO cells [PMID:8939948].","molecular_requirements":"Gas6 bound soluble Mer-Fc in co-precipitation, and protein S did not [PMID:8939948]. Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926]. Partner chains beyond Mer are not reported in our evidence.","affinity_potency":[{"value":"Kd 29 nM","assay":"BIAcore kinetic analysis, rat Gas6 to Mer-Fc","system":"soluble receptor-Fc fusion","cite":"PMID:8939948"}],"species_and_systems":"Curators record human ligand and receptor; the Kd used rat Gas6 and Mer-Fc, with phosphorylation in CHO cells [PMID:8939948]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS6 is flagged secreted and MERTK transmembrane [flag]. Reactome records MERTK binding Gas6 or Protein S [DB:Reactome].","caveats":"Abstract-only reading for all papers. The 29 nM Kd is the weakest of the three TAM receptors in the same study (0.4 and 2.7 nM for Axl and Sky) [PMID:8939948]. One paper is still pending.","key_references":[{"PMID":"8939948","why":"Kd of rat Gas6 for Mer-Fc"},{"PMID":"9160883","why":"Gas6 induces Mer phosphorylation and MAP kinase activation"},{"PMID":"25074926","why":"TAM reporter-line activation by GAS6"}],"covers":["LR000680","LR004164"]},"LR000681":{"pair":"GAS6 -> TYRO3","headline":"Direct agonist interaction supported by binding and reporter studies; affinity in the low nM range.","interaction_type":"direct binding","direction_and_effect":"GAS6 is a ligand for TYRO3 (also called Sky/Rse) [PMID:7867073] and stimulated Sky phosphorylation in CHO cells [PMID:8939948]. Reporter-cell activation depends on context [PMID:25074926].","molecular_requirements":"Gas6 bound soluble Sky-Fc [PMID:8939948]; Gla domain and EGF-like repeats were not required for binding to Rse, and the G-domain region activated Rse phosphorylation [PMID:8621659]. Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926].","affinity_potency":[{"value":"Kd 2.7 nM","assay":"BIAcore kinetic analysis, rat Gas6 to Sky-Fc","system":"soluble receptor-Fc fusion","cite":"PMID:8939948"}],"species_and_systems":"Curators record human ligand and receptor; the Kd used rat Gas6 [PMID:8939948]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS6 is flagged secreted and TYRO3 transmembrane [flag].","caveats":"All papers were read as abstracts only; two more were review-only. Protein S is also a TYRO3 ligand [PMID:7867073], so TYRO3 is not specific to GAS6.","key_references":[{"PMID":"8939948","why":"Kd of Gas6 for Sky-Fc"},{"PMID":"7867073","why":"Identifies Gas6 and protein S as Tyro 3/Axl ligands"},{"PMID":"8621659","why":"G-domain region binds and activates Rse"}],"covers":["LR000681","LR004165"]},"LR007224":{"pair":"GDF11 -> ACVR1B:ACVR2B","headline":"GDF11 interacts with ALK4 and signals through it in mouse reporter assays; the complex also has IntAct and PDB records.","interaction_type":"direct binding","direction_and_effect":"GDF11 can interact with type I receptors ALK4, ALK5 and ALK7 but predominantly uses ALK4 and ALK5 to activate a Smad3-dependent reporter [PMID:16845371].","molecular_requirements":"ALK4 (ACVR1B) is evidenced directly; the ACVR2B chain is not tested in this paper's abstract. IntAct records a GDF11 interaction with Q13705 by surface plasmon resonance [DB:IntAct], and PDB 7MRZ has chains of both [DB:PDB 7MRZ].","affinity_potency":[],"species_and_systems":"Mouse reporter assays and Alk5 mutant embryos [PMID:16845371].","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"The paper read is abstract-only; 'interact' is not quantified and no affinity is reported. The IntAct and PDB records are given without chain identity beyond accession.","key_references":[{"PMID":"16845371","why":"GDF11 interacts with ALK4/5/7 and signals via ALK4 and ALK5"}],"covers":["LR007224"]},"LR004173":{"pair":"GDF11 -> ACVR2B","headline":"GDF11 binds ActRIIB (ACVR2B) in mouse work and has IntAct SPR and PDB records.","interaction_type":"direct binding","direction_and_effect":"Gdf11 binds both ActRIIA and ActRIIB and induces Smad2 phosphorylation [PMID:12414726]. An Alk5 heterozygous mutation potentiated Gdf11-null-like phenotypes in an Acvr2b-null background, a genetic interaction [PMID:16845371].","molecular_requirements":"ActRIIA and ActRIIB cooperate and can compensate; type I partner includes ALK5 and ALK4 [PMID:12414726][PMID:16845371].","affinity_potency":[],"species_and_systems":"Mouse genetics and biochemistry [PMID:12414726][PMID:16845371]; IntAct records surface plasmon resonance for O95390-Q13705 [DB:IntAct]; PDB 7MRZ [DB:PDB 7MRZ].","localisation_and_range":"GDF11 flagged secreted [flag].","caveats":"Both papers abstract-only; one row is still pending and one abstract-insufficient. No affinity value in our evidence. Human pair is ortholog-inferred.","key_references":[{"PMID":"12414726","why":"Gdf11 binds ActRIIA and ActRIIB"},{"PMID":"16845371","why":"Genetic interaction of Acvr2b with Alk5 in GDF11 signalling"}],"covers":["LR000689","LR004173"]},"LR000690":{"pair":"GDF2 -> ACVR1","headline":"BMP-9 (GDF2) binds ALK2 weakly alone, strongly with BMPR-II or ActR-II, and signals through ALK2 in myoblasts and ovarian cells.","interaction_type":"direct binding","direction_and_effect":"In transfected COS cells BMP-9 bound weakly to ALK2, and binding was greatly facilitated by co-expressed BMPR-II or ActR-II [PMID:17311849]. In ovarian cells BMP9 signalled predominantly via ALK2/Smad1/Smad4 rather than ALK1 [PMID:19996292]. UniProt: interacts with ACVR1 [DB:UniProt]; GtoPdb agonist [DB:GtoPdb].","molecular_requirements":"Type II partner (BMPR-II or ActR-II) increases ALK2 binding; ALK2, ActRIIA and BMPRII were required in ovarian cells [PMID:17311849][PMID:19996292].","affinity_potency":[],"species_and_systems":"Transfected COS cells and myoblasts [PMID:17311849]; ovarian surface epithelial and cancer lines [PMID:19996292]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP9 can act in an autocrine fashion in ovarian cancer lines [PMID:19996292].","caveats":"Both papers are abstract-level for this pair; ALK1 is the high-affinity receptor in endothelial cells [PMID:17311849], so ALK2 is a weaker, context-dependent receptor. No numeric affinity.","key_references":[{"PMID":"17311849","why":"BMP-9 binding to ALK2 enhanced by type II receptors"},{"PMID":"19996292","why":"BMP9 signals through ALK2 in ovarian cells"}],"covers":["LR000690","LR004174"]},"LR007233":{"pair":"GDF5 -> ACVR2B:BMPR1B","headline":"GDF-5 binds ActR-IIB in COS-1 cells and signals through BMPR-IB with it; the complex is inferred from separate observations.","interaction_type":"direct binding","direction_and_effect":"GDF-5 bound ActR-IIB in COS-1 transfectants [PMID:8702914]. UniProt says GDF5 binds BMPR1B with high affinity [DB:UniProt]. Stimulatory in the interaction record.","molecular_requirements":"The curated paper shows type II binding; signalling through BMPR-IB in the presence of the type II receptor is in the curators' assay description [PMID:8702914].","affinity_potency":[],"species_and_systems":"COS-1 transfectants; curators label human [PMID:8702914].","localisation_and_range":"The receptor complex is flagged transmembrane [flag].","caveats":"Abstract only. The evidence sentence concerns the type II subunit only. Four other rows were review-only.","key_references":[{"PMID":"8702914","why":"GDF-5 type II receptor binding and BMPR-IB signalling"}],"covers":["LR007233"]},"LR004182":{"pair":"GDF5 -> BMPR1A","headline":"GDF5 binds BMPR1A, but more weakly than BMPR1B; supported by binding and functional papers.","interaction_type":"direct binding","direction_and_effect":"CDMP-1 (GDF5) bound BMPR-IB and BMPR-II and weakly BMPR-IA [PMID:9525338]. GDF5 activity on osteoblast differentiation is reported through Smad1/5/8 [PMID:11282024]. UniProt describes BMPR1A as lower affinity than BMPR1B [DB:UniProt]. Stimulatory in the interaction record.","molecular_requirements":"Binding was tested with immobilised BMPR1A and BMPR1B ectodomains by Biacore; mutant N445T GDF5 did not differ significantly from wild-type [PMID:19956691]. Type II partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant ligand and ectodomains; C2C12 mouse myoblast cells; curators label human [PMID:19956691][PMID:11282024].","localisation_and_range":"The receptor is flagged transmembrane [flag].","caveats":"Binding is weak and Kd values for BMPR1A are not in our excerpts. [PMID:11282024] does not test BMPR1A directly. Two of five confirmed rows and one different_entity row are not shown.","key_references":[{"PMID":"19956691","why":"Biacore of GDF5 with BMPR1A and BMPR1B ectodomains"},{"PMID":"9525338","why":"CDMP-1 receptor binding, weak for BMPR-IA"}],"covers":["LR000698","LR004182"]},"LR007242":{"pair":"GDF7 -> ACVR2B:BMPR1A","headline":"GDF7 -> ACVR2B:BMPR1A: functional evidence only, from one abstract-only paper; chains not shown together.","interaction_type":"functional only","direction_and_effect":"ALK3 overexpression conferred GDF7 signalling in COS7 cells [PMID:16049014]. ACVR2B itself is not named in the cited sentence. GtoPdb lists agonist records for the individual chains [DB:GtoPdb].","molecular_requirements":"Complex of ACVR2B and BMPR1A (ALK3). Evidence comes from separate manipulations (receptor overexpression or shRNA of one chain), not from a test of the assembled pair [PMID:16049014]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 transfectants and MC3T3 cells with shRNA and Smad1/5/8 reporters; curator species fields are blank or human, abstract-only [PMID:16049014].","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Single abstract-only paper. No binding or affinity data for the assembled complex in our evidence. Direct binding of GDF7 to the individual chains is documented in other rows, not this one.","key_references":[{"PMID":"16049014","why":"Receptor overexpression and shRNA define the type I and type II requirements for GDF7."}],"covers":["LR007242"]},"LR004191":{"pair":"GDF7 -> BMPR2","headline":"GDF7 binds BMPR2 directly (KD 52.1 nM for rhBMP12) with functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound BMPR2 with similar affinity to rhBMP13 (GDF6) [PMID:21702718]. BMPRII shRNA suppressed GDF7 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type II receptors act with a type I partner: ALK3 or ALK6 overexpression conferred GDF7 signalling [PMID:16049014].","affinity_potency":[{"value":"KD 52.1 nM","assay":"surface plasmon resonance, KD (kin), rhBMP12 (GDF7) vs BMPR2 ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. BMPR2 binding was more than 10-fold weaker than type I binding [PMID:21702718]. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR000707","LR004191"]},"LR009141":{"pair":"GDF9 -> BMPR1B","headline":"Weak functional evidence only: a soluble BMPR1B ectodomain partly blocks GDF9; no binding shown.","interaction_type":"functional only","direction_and_effect":"The BMPR-IB ectodomain was partially effective in blocking GDF-9 action on granulosa cells [PMID:12135884]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; BMPRII was the most effective blocker [PMID:12135884].","affinity_potency":[],"species_and_systems":"Soluble receptor-Fc blockade of GDF-9 bioactivity (granulosa cell proliferation, FSH-stimulated progesterone); rat cells per the curators' note for the related BMPR2 pair [PMID:12135884].","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Only partial blockade, read from the abstract; no direct BMPR1B binding was tested [PMID:12135884].","key_references":[{"PMID":"12135884","why":"BMPR-IB ectodomain partially blocks GDF-9"}],"covers":["LR009141"]},"LR000708":{"pair":"GDF9 -> BMPR2","headline":"Direct binding supported: the BMPRII ectodomain co-precipitates GDF-9 and is the most effective blocker; type I partner needed.","interaction_type":"direct binding","direction_and_effect":"GDF-9 acts as an agonist: the BMPRII ectodomain was most effective in blocking GDF-9 stimulation of granulosa cell proliferation and suppression of FSH-stimulated progesterone, and BMPRII antisense oligomers prevented GDF-9-induced thymidine incorporation [PMID:12135884]. BioGRID and GtoPdb agree [DB:BioGRID][DB:GtoPdb].","molecular_requirements":"Signalling requires an unidentified type I partner in addition to BMPRII, per the curator note [PMID:12135884].","affinity_potency":[],"species_and_systems":"Human GDF-9 with rat granulosa cells and neonatal ovary; the human and mouse pair rows are ortholog-inferred, not tested directly [PMID:12135884].","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Only one paper, read as abstract; binding was by ectodomain co-precipitation, not full-length receptor [PMID:12135884].","key_references":[{"PMID":"12135884","why":"BMPRII ectodomain coprecipitates GDF-9; antisense blocks signalling"}],"covers":["LR000708","LR004192"]},"LR000717":{"pair":"GHRL -> GHSR","headline":"Ghrelin is the established agonist of GHSR, supported by binding, functional and database evidence in several papers.","interaction_type":"direct binding","direction_and_effect":"Ghrelin was purified from rat stomach as an endogenous ligand of GHS-R, and the acylated peptide releases GH [PMID:10604470]. It acts as an agonist and stimulates signalling beyond the receptor basal activity [PMID:12907757]. LEAP2 is an endogenous antagonist that inhibits GHSR activation by ghrelin [PMID:29233536]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Octanoylation at Ser3 is essential for activity [PMID:10604470]; desoctanoylated ghrelin did not compete for binding [PMID:11314756]. Glu3.33 is an obligatory anchor residue for ghrelin agonists [PMID:21402696]. A dimer model proposes ghrelin activates one protomer [PMID:15905359].","affinity_potency":[{"value":"4.6-5.4 x 10(-7) mol/l","assay":"competition for 125I-Tyr-Ala-hexarelin binding (ghrelin and cortistatin similar)","system":"human pituitary membranes","cite":"PMID:11227737"}],"species_and_systems":"Human tissue membranes and transfected COS-7/HEK293 cells [PMID:11314756][PMID:12907757]; rat stomach purification [PMID:10604470]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted, receptor transmembrane [flag]; ghrelin is a stomach-derived circulating hormone in the abstract [PMID:29233536].","caveats":"All papers abstract only. The receptor shows strong ligand-independent signalling, so ghrelin adds modestly to the baseline [PMID:12907757]. Co-applied synthetic agonists can modulate ghrelin signalling [PMID:15905359]. PMID 21402696 concerns a synthetic agonist, with ghrelin only as background.","key_references":[{"PMID":"10604470","why":"Purification of ghrelin as the GHS-R ligand"},{"PMID":"11314756","why":"125I-ghrelin binding to human membranes; octanoylation required"},{"PMID":"29233536","why":"LEAP2 antagonism of ghrelin at GHSR"}],"covers":["LR000717","LR004200"]},"LR010554":{"pair":"GLS2:SLC1A1 -> GRIN1:GRIN2B","headline":"Protein-association records only; no paper confirms GLS2:SLC1A1 -> GRIN1:GRIN2B as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010554"]},"LR009006":{"pair":"GNAI2 -> ADORA1","headline":"GNAI2-ADORA1 is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-Western ADORA1-GNAI2 [DB:BioGRID][PMID:11369591]; PDB structures with chains of both partners [DB:PDB 6D9H]; UniProt names ADORA1 among interacting GPCRs [DB:UniProt][PMID:12359238]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009006"]},"LR008421":{"pair":"GNAI2 -> MTNR1A","headline":"Database-asserted only: BioGRID and IntAct list co-purification of GNAI2 and MTNR1A; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence; records are only association assays [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists Affinity Capture-Western [PMID:10598579] and Affinity Capture-MS [PMID:17215244]; IntAct lists tandem affinity purification [PMID:26514267][PMID:17215244]. Cell systems and species of the assays are not reported in our evidence; the pair is annotated human.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Association assays do not show direct binding, direction or function. Curated judgements were 'different_entity' (2) and 'unresolvable' (1).","key_references":[],"covers":["LR008421"]},"LR009015":{"pair":"GNAI2 -> TBXA2R","headline":"Database-asserted only: one BioGRID FRET record; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a FRET assay [PMID:15782186]; cell system and species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. One curated judgement: 'different_entity'. A single FRET record does not show function or direction.","key_references":[],"covers":["LR009015"]},"LR008502":{"pair":"GNAS -> PTGIR","headline":"Database-asserted only: four BioGRID records of varied assay types; the one curated paper was retracted.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists Co-crystal Structure [PMID:16460020], Affinity Capture-Western [PMID:11895442], Reconstituted Complex [PMID:16114876] and FRET [PMID:16352729]; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. The single curated paper was judged 'retracted'.","key_references":[],"covers":["LR008502"]},"LR002706":{"pair":"GPR15LG -> CXCR4","headline":"GPR15LG binds CXCR4 at the orthosteric site, but acts as a modulator or biased antagonist, not a plain agonist.","interaction_type":"conflicting","direction_and_effect":"The abstract says GPR15LG binds the orthosteric site of CXCR4 and enhances CXCL12-mediated signalling synergistically, boosting migration of CD4+ T cells and cancer cells [PMID:40394646]. The full text adds that GPR15LG did not activate CXCR4 in primary CD4+ T cells (no Akt/Erk activation), and acts as a biased antagonist of beta-arrestin-2 recruitment and internalisation [PMID:40394646].","molecular_requirements":"Binding needs the CXCR4 N-terminus: deleting residues 2-29 strongly reduced binding, and D181A reduced it [PMID:40394646].","affinity_potency":[{"value":"IC50 829 \u00b1 139 nM","assay":"competition with labelled CXCL12","system":"CXCR4 cells","cite":"PMID:40394646"},{"value":"IC50 1.3 \u00b1 0.1 \u00b5M","assay":"competition with anti-CXCR4 antibody 12G5","system":"SupT1 cells","cite":"PMID:40394646"}],"species_and_systems":"Human proteins; SupT1 cells, primary human CD4+ T cells, HIV-1 infection assays and molecular dynamics modelling [PMID:40394646].","localisation_and_range":"GPR15LG is flagged as secreted [flag].","caveats":"Single paper. Effect direction is context dependent and depends on the readout. Binding rests on competition assays and simulation, not direct affinity measurement. A second pair (GPR15LG with ACKR3) was modelled but not supported by competition [PMID:40394646].","key_references":[{"PMID":"40394646","why":"Binding, competition IC50 values and functional modulation of CXCR4"}],"covers":["LR002706","LR005971"]},"LR010752":{"pair":"GREM1 -> BMP2","headline":"Only a UniProt subunit statement supports this pair; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that GREM1 interacts with BMP2 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the human pair is listed.","localisation_and_range":"Both partners are flagged as secreted [flag]; BMP2 is flagged non-transmembrane [flag], so this is a secreted ligand-ligand pair.","caveats":"No papers were verified: the one judged row was classed as a different entity. Rests on a single database record.","key_references":[],"covers":["LR010752"]},"LR000726":{"pair":"GREM1 -> KDR","headline":"Gremlin binds and activates VEGFR2 (KDR) in several systems; monomeric gremlin acts as an antagonist.","interaction_type":"direct binding","direction_and_effect":"Gremlin binds VEGFR2 independently of BMP and activates it like VEGF-A, driving angiogenesis in vitro and in vivo [PMID:20660291]. Agonist effects were also reported in kidney cells, with NF-kB-linked inflammation [PMID:25810250], and in retinal pigment epithelial cells via Akt-mTORC2 [PMID:27894090]. In contrast, monomeric gremlin engages VEGFR2 non-productively and antagonises angiogenesis driven by dimeric gremlin or VEGF-A165 [PMID:27174917].","molecular_requirements":"Oligomeric state matters: the dimer activates, while the C141A mutant and wild-type monomers do not, and wild-type dimer induced VEGFR2 complex formation and internalisation while C141A did not [PMID:27174917]. Gremlin binding to VEGFR2 was fully competed by VEGF-A165 [PMID:27174917].","affinity_potency":[],"species_and_systems":"Human proteins in endothelial cells, murine kidney and renal cells, ARPE-19 cells, chick CAM and mouse Matrigel plug assays [PMID:20660291] [PMID:25810250] [PMID:27174917] [PMID:27894090].","localisation_and_range":"GREM1 is flagged as secreted [flag]; gremlin also binds heparan sulphate proteoglycans on cells [PMID:27174917].","caveats":"Effect depends on gremlin oligomeric form. A surface plasmon resonance comparison is mentioned only as prior work, with no numeric value in our evidence [PMID:27174917]. Most papers read as abstract only. IntAct has a cross-linking record [DB:IntAct]. Four of eight confirmed rows are shown.","key_references":[{"PMID":"20660291","why":"Original report of gremlin binding and activating VEGFR2"},{"PMID":"27174917","why":"Monomer versus dimer: antagonist versus agonist"},{"PMID":"25810250","why":"Gremlin-VEGFR2 signalling in kidney inflammation"}],"covers":["LR000726","LR004208"]},"LR001833":{"pair":"GRN -> TNFRSF1A","headline":"Progranulin is reported to bind TNFR1 directly and antagonise TNF-alpha, from one mouse-focused paper.","interaction_type":"direct binding","direction_and_effect":"PGRN bound directly to TNF receptors and disturbed the TNF\u03b1-TNFR interaction; the authors call PGRN an antagonist of TNF\u03b1 signalling [PMID:21393509].","molecular_requirements":"The abstract says 'TNFRs' in plural; it does not separate TNFR1 from TNFR2. Atsttrin, an engineered protein of three PGRN fragments, showed selective TNFR binding [PMID:21393509].","affinity_potency":[],"species_and_systems":"The study is largely mouse in vivo (PGRN-deficient mice, collagen-induced arthritis) [PMID:21393509]. The human pair is ortholog-inferred. IntAct lists two-hybrid and pull-down records [DB:IntAct].","localisation_and_range":"GRN is flagged secreted; TNFRSF1A is flagged as a transmembrane receptor [flag].","caveats":"Only an abstract was read; receptor-specific (TNFR1) binding is inferred from a plural statement. Orthogonal TNFR1 evidence is database-only.","key_references":[{"PMID":"21393509","why":"PGRN binds TNFRs and blocks TNF\u03b1"}],"covers":["LR001833","LR005188"]},"LR004209":{"pair":"GRP -> BRS3","headline":"Evidence argues against GRP binding BRS3 in human or mouse; BRS3 is reported as an orphan.","interaction_type":"conflicting","direction_and_effect":"A 2019 study concludes that placental mammalian BRS3 lost binding affinity for NMB/GRP and signals constitutively, ligand-independently [PMID:30840614]. The 2001 paper says BRS-3 has high affinity for no known natural bombesin peptides [PMID:11112777].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human BRS-3 binding to synthetic bombesin analogues (22 peptides tested against hBRS-3, hGRPR and hNMBR) [PMID:11112777]; evolutionary and functional analysis across 17 vertebrate BRS3, including human and mouse [PMID:30840614].","localisation_and_range":"GRP is flagged secreted [flag].","caveats":"Both curated papers argue against the pair; one was confirmed only on comparative binding. In the 2019 paper, only nonplacental vertebrate BRS3 retains GRP/NMB binding [PMID:30840614]. Both read as abstract (the first with excerpts).","key_references":[{"PMID":"30840614","why":"BRS3 is an orphan in placental mammals"},{"PMID":"11112777","why":"BRS-3 has no high-affinity natural bombesin ligand"}],"covers":["LR000727","LR004209"]},"LR006810":{"pair":"GUCA1A -> GUCY2F","headline":"Supported only by a GtoPdb activator annotation; no judged papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GUCA1A as an activator of GUCY2F [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmation; other candidate papers were abstract_insufficient or different_entity. Affinity not given in GtoPdb.","key_references":[],"covers":["LR006810"]},"LR005190":{"pair":"HAVCR1 -> CD300LB","headline":"TIM1 (HAVCR1) binds LMIR5/CD300b in mouse cell-based assays; one paper, human pair projected from mouse.","interaction_type":"direct binding","direction_and_effect":"LMIR5-Fc stained TIM1-expressing Ba/F3 cells, and coimmunoprecipitation showed physical interaction of LMIR5 with TIM1 [PMID:20566714]. The authors call TIM1 an endogenous ligand for the DAP12-coupled activating receptor LMIR5; TIM1 or TIM4 stimulation induced LMIR5-mediated mast cell activation [PMID:20566714].","molecular_requirements":"The Ig-like domain of LMIR5 bound TIM1 near the phosphatidylserine-binding site; among LMIR family members only LMIR5 bound TIM1, and LMIR5 also bound TIM4 [PMID:20566714]. Coreceptor or subunit requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used mouse proteins and cells (Ba/F3, mast cells, mice, dorsal air pouch, kidney ischemia/reperfusion) [PMID:20566714]. The human pair is ortholog-inferred, so no human experiment is in our evidence.","localisation_and_range":"HAVCR1 is flagged as a membrane receptor, not secreted [flag]; contact-dependent signalling is implied but TIM1-Fc was also used as a soluble probe [PMID:20566714].","caveats":"Single paper; judged from abstract by the curators, with full-text excerpts available. Affinity not reported in our evidence. TIM1-Fc also stained parental Ba/F3 cells, suggesting other TIM1 ligands exist [PMID:20566714].","key_references":[{"PMID":"20566714","why":"Expression cloning, Fc-binding, coIP and in vivo LMIR5 deficiency"}],"covers":["LR001835","LR005190"]},"LR000735":{"pair":"HBEGF -> CD9","headline":"CD9 physically associates with membrane HB-EGF and boosts its diphtheria toxin binding; a co-receptor-like partner.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation and cross-linking suggest tight association of CD9 with membrane HB-EGF, and CD9 increased cell-surface DT-binding sites 15-fold [PMID:8194524]. Reactome has DT:HBEGF:CD9 complexes [DB:Reactome R-HSA-5334770].","molecular_requirements":"Human and monkey CD9 up-regulated DT binding but mouse CD9 did not; residues between Ala156 and Asp183, notably Gly158, Val159 and Thr175, were required [PMID:11735113].","affinity_potency":[],"species_and_systems":"Mouse L cell transfectants with monkey CD9 [PMID:8194524]; human/monkey/mouse CD9 chimeras [PMID:11735113]. Mouse pair is ortholog-inferred, and mouse CD9 lacked up-regulation activity here [PMID:11735113].","localisation_and_range":"Membrane-bound proHB-EGF with CD9 in the same membrane (juxtacrine) [flag].","caveats":"Readouts are diphtheria toxin binding, not HB-EGF signalling. Abstracts only; two further judged papers were insufficient.","key_references":[{"PMID":"8194524","why":"CD9 associates with HB-EGF/DTR, co-IP and cross-linking"},{"PMID":"11735113","why":"CD9 residues needed for up-regulation"}],"covers":["LR000735","LR004217"]},"LR004218":{"pair":"HBEGF -> EGFR","headline":"HB-EGF binds and activates EGFR with strong support from binding and functional papers plus several database records.","interaction_type":"direct binding","direction_and_effect":"Synthetic HB-EGF EGF-like domain (44-86) showed high binding affinity to EGFR on A431 cells, like human EGF [PMID:12725245]. HB-EGF induced tyrosine phosphorylation of ErbB2 and ErbB4 and, to a lesser degree, EGFR in mouse cardiac myocytes [PMID:12621152]. Binding to HER1 was shown alongside HER4 [PMID:9135143].","molecular_requirements":"Truncating C-terminal Leu86 caused a drastic reduction in binding [PMID:12725245]. EGFR homodimer requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human A431 cells with synthetic peptide [PMID:12725245]; NIH 3T3 overexpressing HER1 [PMID:9135143]; mouse in vivo [PMID:12621152]. Mouse pair ortholog-inferred.","localisation_and_range":"HB-EGF is flagged secreted and transmembrane, so soluble or juxtacrine [flag].","caveats":"All papers abstract only. In vivo paper shows EGFR phosphorylation weaker than ErbB2/ErbB4 [PMID:12621152]. Databases: BioGRID, IntAct, Reactome, GtoPdb (pKi unit listed, no value) [DB:GtoPdb].","key_references":[{"PMID":"12725245","why":"Binding affinity of HB-EGF EGF domain to EGFR"},{"PMID":"9135143","why":"HB-EGF binds HER1 and HER4"},{"PMID":"12621152","why":"In vivo ErbB phosphorylation by HB-EGF"}],"covers":["LR000736","LR004218"]},"LR003714":{"pair":"Hc -> C5ar2","headline":"C5a binds the orphan receptor C5L2 (C5ar2) with high affinity in human cells; single paper, mouse pair inferred.","interaction_type":"direct binding","direction_and_effect":"C5L2/gpr77 bound C5a with high affinity and had 10-fold higher affinity for C5adR(74) than CD88; moderate affinity for C3a [PMID:11773063]. C5L2 transfectants did not degranulate, mobilise calcium or internalise on ligand binding, so no classical signalling was seen [PMID:11773063].","molecular_requirements":"Single receptor, no coreceptor reported in our evidence. C3a appeared to bind a distinct site from C5a [PMID:11773063].","affinity_potency":[],"species_and_systems":"Human C5a and human C5L2 transfectants; the mouse pair is ortholog-inferred [PMID:11773063].","localisation_and_range":"Hc is flagged secreted [flag].","caveats":"One abstract-level paper; numeric affinities not reported in our evidence. Role as non-signalling binder is as described by the authors.","key_references":[{"PMID":"11773063","why":"C5L2 binds C5a and C5adR(74) with high affinity"}],"covers":["LR003714"]},"LR000744":{"pair":"HGF -> MET","headline":"Canonical HGF-MET pair with direct binding, a crystal structure and receptor-activation data; very well supported.","interaction_type":"direct binding","direction_and_effect":"HGF acts as an agonist: it binds MET and induces tyrosine phosphorylation of the Met beta subunit [PMID:1655405][PMID:1846706]. UniProt describes HGF as an activating ligand that promotes MET dimerization [DB:UniProt]. A shed soluble Met fragment can bind HGF and act as a decoy that blocks HGF/c-Met signalling [PMID:22689693].","molecular_requirements":"Only the proteolytically mature HGF beta-chain, not the single-chain precursor, binds Met in the crystal structure with the Sema/PSI domains [PMID:15167892]. Mature HGF is an alpha/beta heterodimer: a high-affinity site in HGF-alpha binds Met IPT domains 3 and 4, and a low-affinity site in HGF-beta binds the Sema domain [PMID:18495663]. Pro-HGF binds but does not activate Met [PMID:18495663].","affinity_potency":[],"species_and_systems":"Experiments used human proteins and human cells; the dossier covers both the human and mouse pair, and no mouse-specific experiments are reported in our evidence [PMID:1655405][PMID:15167892]. Structures are listed in PDB, for example [DB:PDB 1SHY].","localisation_and_range":"HGF is annotated as secreted and MET as a transmembrane receptor [flag], so signalling is paracrine or autocrine.","caveats":"No affinity values for HGF-MET are given in our evidence. Several papers were read as abstracts only. Soluble Met may dampen HGF signalling [PMID:22689693].","key_references":[{"PMID":"1846706","why":"HGF cross-linked to c-met; c-met is the cell-surface HGF receptor"},{"PMID":"15167892","why":"Crystal structure of HGF beta-chain with Met Sema/PSI"},{"PMID":"18495663","why":"High-affinity HGF-alpha site on Met IPT 3/4"}],"covers":["LR000744","LR004225"]},"LR002715":{"pair":"HJV -> HFE","headline":"HJV and HFE bind each other in transfected cells and form a membrane complex with TfR2; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"HFE and TfR2 bind HJV in a non-competitive manner, and HFE, TfR2 and HJV form a multi-protein membrane complex [PMID:22728873]. HJV competes with TfR1 for HFE binding, implicating this in iron sensing [PMID:22728873]. Effect on signalling is not reported in our evidence.","molecular_requirements":"TfR2 is part of the complex; TfR2-ECD residues 120-139 are critical for both HFE and HJV binding [PMID:22728873].","affinity_potency":[],"species_and_systems":"Human proteins in transfected HuH7 cells, using glycerol-gradient sedimentation and co-immunoprecipitation [PMID:22728873]. Mouse pair is ortholog-inferred.","localisation_and_range":"HJV is annotated as secreted and HFE as a transmembrane receptor [flag].","caveats":"One paper, read as an abstract. Co-immunoprecipitation in a complex could reflect indirect contact. HJV and HFE are not a conventional ligand-receptor pair; the receptor role of HFE is annotation only.","key_references":[{"PMID":"22728873","why":"HFE and TfR2 bind HJV in a membrane complex"}],"covers":["LR002715","LR005979"]},"LR000753":{"pair":"HLA-B -> LILRB1","headline":"Direct, human-human binding of HLA-B class I to inhibitory LILRB1, shown by SPR and Fc-fusion assays; micromolar affinity.","interaction_type":"direct binding","direction_and_effect":"HLA-B class I molecules are ligands of LILRB1 (ILT2/LIR-1), an inhibitory receptor; ILT2 binding to MHC class I transfectants delivers a negative signal that inhibits NK and T cell killing [PMID:9382880]. LIR-1-Fc binding to cells was blocked by a pan-HLA-A,-B,-C antibody [PMID:9285411].","molecular_requirements":"LILRB1 bound only folded, beta2-microglobulin-associated class I and not free heavy chain [PMID:21270408]. The soluble D1D2 domains of ILT2 were sufficient for binding in SPR [PMID:12853576].","affinity_potency":[{"value":"Kd \u2248 8.8 \u03bcM","assay":"surface plasmon resonance, soluble ILT2 D1D2 over immobilised HLA-B35","system":"recombinant human proteins","cite":"PMID:12853576"}],"species_and_systems":"All experiments were human: recombinant proteins, class I transfectants and NK cells [PMID:12853576][PMID:9382880][PMID:9285411][PMID:21270408].","localisation_and_range":"Both partners are annotated as transmembrane (HLA-B not secreted) [flag], so signalling is by cell-cell contact.","caveats":"Four confirmed papers, all read as abstracts or excerpts; binding is allele-dependent across more than 90 HLA class I alleles [PMID:21270408], and the Kd is for HLA-B35 only. UniProt describes broad HLA-A/B/C/G/F recognition, so HLA-B is not unique [DB:UniProt].","key_references":[{"PMID":"12853576","why":"SPR Kd for ILT2 D1D2 with HLA-B35"},{"PMID":"21270408","why":"LILRB1 binds folded class I only, many HLA alleles"},{"PMID":"9382880","why":"ILT2 binds MHC class I and inhibits NK/T killing"}],"covers":["LR000753"]},"LR002724":{"pair":"HLA-C -> KIR2DS1","headline":"HLA-C group 2 complexes bind activating KIR2DS1 directly in a 97-HLA screen; older functional data agree.","interaction_type":"direct binding","direction_and_effect":"KIR2DS1 is an activating NK receptor; KIR2DS1 binding was narrowly restricted to HLA-C group 2 complexes [PMID:28546555]. NK clones expressing p50/EB6 receptors were induced to lyse Cw4+ target cells [PMID:7650491].","molecular_requirements":"Binding was exclusive to HLA-C2 complexes tested, and KIR2DS1 and KIR2DL1 share C2 specificity, but KIR2DL1 also bound some HLA-C1 and two HLA-B complexes [PMID:28546555].","affinity_potency":[],"species_and_systems":"Human recombinant KIR-Fc and HLA proteins [PMID:28546555]; human NK clones [PMID:7650491].","localisation_and_range":"HLA-C annotated transmembrane [flag]; contact-dependent.","caveats":"Abstract-level or excerpt reading for the 2017 paper; PMID:7650491 is functional and uses older receptor names. No affinity values. One further paper was abstract-insufficient.","key_references":[{"PMID":"28546555","why":"KIR2DS1 binds HLA-C2 complexes in a 97-HLA screen"},{"PMID":"7650491","why":"p50/EB6 NK clones lyse Cw4+ targets"}],"covers":["LR002724"]},"LR007251":{"pair":"HLA-E -> KLRC1:KLRD1","headline":"Strongly supported binding of HLA-E to the inhibitory CD94/NKG2A heterodimer by tetramer, affinity and structure data.","interaction_type":"direct binding","direction_and_effect":"HLA-E tetramer bound CD94/NKG2A transfectants and NK cells; surface HLA-E protected targets from CD94/NKG2A+ NK clones [PMID:9486650]. NKG2A/CD94 is inhibitory and bound HLA-E with high affinity [PMID:15728498].","molecular_requirements":"Needs the KLRC1 (NKG2A) plus KLRD1 (CD94) heterodimer [PMID:15728498]. HLA-E presents leader peptides; peptide identity changed affinity, HLA-E allele did not [PMID:15728498]. BioGRID lists KLRD1-HLA-E as a reconstituted complex [DB:BioGRID 283051]; IntAct has SPR [DB:IntAct Q13241-P13747]; structures [DB:PDB 3CDG].","affinity_potency":[],"species_and_systems":"Human; transfectants, NK clones and purified proteins [PMID:9486650][PMID:15728498].","localisation_and_range":"HLA-E flagged secreted and transmembrane; receptor transmembrane [flag]; Reactome describes the complex at the plasma membrane [DB:Reactome R-HSA-198914].","caveats":"No numeric affinity in our evidence. Both papers abstract only; five other papers were review-only.","key_references":[{"PMID":"9486650","why":"Identification of HLA-E as ligand for CD94/NKG2A"},{"PMID":"15728498","why":"Quantitative affinity of NKG2A/CD94 for HLA-E"}],"covers":["LR007251"]},"LR000762":{"pair":"HLA-E -> KLRD1","headline":"HLA-E, presenting class I leader peptides, is bound by CD94/NKG2A; well supported by crystal structures and binding assays.","interaction_type":"direct binding","direction_and_effect":"CD94/NKG2A is the inhibitory receptor and HLA-E the ligand; HLA-E tetramer bound CD94/NKG2A, B and C transfectants, and surface HLA-E protected targets from lysis by CD94/NKG2A+ NK clones [PMID:9486650]. Binding of soluble CD94/NKG2A to HLA-E was shown directly [PMID:9886400]. The reported effect direction is antagonist (inhibitory) [PMID:9486650].","molecular_requirements":"Recognition needs peptide-loaded HLA-E (class I leader peptides) and the CD94-NKG2 heterodimer [PMID:9886400]. In the crystal structure the CD94 subunit dominated the interaction with HLA-E and NKG2A was more peripheral [PMID:18332182]; the KLRD1 (CD94) chain therefore carries most of the contact, but the partner is NKG2A (KLRC1) in the evidence.","affinity_potency":[{"value":"approximately 6-fold higher affinity of NKG2A/CD94 than NKG2C/CD94 (relative, no absolute value)","assay":"structure-based comparison","system":"purified proteins","cite":"PMID:18448674"}],"species_and_systems":"Human proteins in direct-binding and crystal-structure work [PMID:18083576, PMID:18332182, PMID:9486650, PMID:9886400]. Mouse Qa-1/CD94-NKG2A experiments support the same axis [PMID:14734748, PMID:9815261].","localisation_and_range":"HLA-E is flagged both secreted and transmembrane [flag]; the experiments describe it as a cell-surface ligand on target cells, so contact-dependent [PMID:9486650].","caveats":"Peptide dependent; CD94/NKG2A did not interact with classical HLA class I molecules [PMID:9886400]. All papers were read as abstracts only. The mouse papers use Qa-1, not HLA-E. Rows are stored with KLRD1 in the ligand slot.","key_references":[{"PMID":"9486650","why":"HLA-E tetramer binds CD94/NKG2A/B/C transfectants; protects from NK lysis"},{"PMID":"9886400","why":"soluble CD94/NKG2A binds HLA-E, peptide dependent"},{"PMID":"18332182","why":"crystal structure of CD94-NKG2A bound to HLA-E"}],"covers":["LR000762"]},"LR001842":{"pair":"HLA-F -> LILRB2","headline":"HLA-F binds LILRB2 (ILT4) by surface plasmon resonance; single older abstract plus database records.","interaction_type":"direct binding","direction_and_effect":"Transfection of ILT4 conferred HLA-F tetramer binding and surface plasmon resonance showed a direct HLA-F-ILT4 interaction [PMID:11169396]. Signalling effect not reported in our evidence.","molecular_requirements":"HLA-F refolded with beta2-microglobulin was used [PMID:11169396].","affinity_potency":[],"species_and_systems":"Human recombinant protein and transfected cells [PMID:11169396].","localisation_and_range":"HLA-F flagged transmembrane [flag]; undetected at cell surface in this study [PMID:11169396].","caveats":"Abstract only; no affinity values; same paper covers ILT2 and ILT4 together. IntAct and UniProt records add support [DB:IntAct, DB:UniProt].","key_references":[{"PMID":"11169396","why":"SPR and tetramer binding of HLA-F to ILT2/ILT4"}],"covers":["LR001842"]},"LR002733":{"pair":"HMGB1 -> AGER","headline":"Direct binding of amphoterin (HMGB1) to RAGE shown with purified proteins in a 1995 abstract-read paper; database records add support.","interaction_type":"direct binding","direction_and_effect":"Rat amphoterin bound purified sRAGE in a saturable, dose-dependent way, blocked by anti-RAGE IgG or sRAGE. RAGE blockade also prevented binding to embryonic rat neurons and inhibited neurite formation on amphoterin-coated substrates [PMID:7592757]. Activating or inhibitory effect beyond this is not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond soluble RAGE ectodomain binding [PMID:7592757].","affinity_potency":[],"species_and_systems":"Rat amphoterin (brain-purified or recombinant), rat neurons and bovine-lung-derived fractions [PMID:7592757]. The human and mouse pairs are ortholog-inferred, not directly tested.","localisation_and_range":"HMGB1 is flagged secreted [flag]; paracrine action on cells is implied by the neuron binding assay [PMID:7592757].","caveats":"Single curated paper, abstract only, and rat/bovine material. Databases list BioGRID affinity capture, IntAct SPR and PDB 8I9M [DB:BioGRID][DB:IntAct][DB:PDB 8I9M].","key_references":[{"PMID":"7592757","why":"Amphoterin binds RAGE; blocked by anti-RAGE and sRAGE"}],"covers":["LR002733","LR005981"]},"LR002742":{"pair":"HMGB1 -> SCARA5","headline":"SCARA5 recognises HMGB1 and clears it, shown only in fish models; human and mouse pairs are ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"SCARA5 is identified as an HMGB1 recognition receptor that negatively regulates HMGB1-mediated inflammation. Tetraodon SCARA5 associates with TnHMGB1 and mediates its endocytosis into lysosomes; overexpression suppresses CpG-ODN responses and ablation intensifies them [PMID:27647835].","molecular_requirements":"Association occurs through the A and B boxes, depends on the cysteine redox state, and is inhibited by the T box [PMID:27647835].","affinity_potency":[],"species_and_systems":"Pufferfish (Tetraodon nigroviridis) and zebrafish (Danio rerio) proteins and models; no human or mouse experiments in our evidence [PMID:27647835].","localisation_and_range":"HMGB1 is flagged secreted [flag]; SCARA5 mediates endocytosis [PMID:27647835].","caveats":"All evidence is from fish orthologs, read from the abstract only; transfer to human or mouse is inference.","key_references":[{"PMID":"27647835","why":"SCARA5 as an HMGB1 receptor in pufferfish and zebrafish"}],"covers":["LR002742","LR005990"]},"LR004227":{"pair":"HMGB1 -> SDC1","headline":"Amphoterin (HMGB1) binds syndecan in a 1992 solid-phase assay via heparan sulfate chains; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Syndecan bound amphoterin in a saturable way; binding was inhibited by heparan sulfate and heparin and partly by anti-amphoterin antibodies [PMID:1369684]. Amphoterin is proposed as a putative pericellular ligand. Signalling effect is not reported in our evidence.","molecular_requirements":"Heparan sulfate chains of syndecan are involved, since chondroitin sulfate was less effective at inhibiting [PMID:1369684].","affinity_potency":[],"species_and_systems":"Solid-phase assay; mouse mammary epithelial cells bound amphoterin directly [PMID:1369684]. Both species pairs are ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; both proteins localised to lateral surfaces of adhered epithelial cells, which suggests pericellular, contact-range action [PMID:1369684].","caveats":"Single old abstract-only paper. Binding rests on a glycosaminoglycan chain, so core-protein specificity is unclear.","key_references":[{"PMID":"1369684","why":"Syndecan binds amphoterin via heparan sulfate"}],"covers":["LR000768","LR004227"]},"LR000771":{"pair":"HRG -> FCGR1A","headline":"Histidine-rich glycoprotein blocks IgG binding to FcgammaRI on THP1 cells; one abstract-level paper, binding not directly measured.","interaction_type":"functional only","direction_and_effect":"HRG competitively blocks monomeric IgG binding to FcgammaRI on THP1 monocytic cells, with concentration- and Zn2+-dependent modulation of IgG and immune-complex binding [PMID:10421785]. The curator records no activating effect, so HRG acts as an inhibitor of IgG binding rather than a classical agonist.","molecular_requirements":"Zn2+ dependence is reported [PMID:10421785]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human THP1 cells and human proteins [PMID:10421785]. ","localisation_and_range":"HRG is flagged as secreted [flag]; plasma protein acting on monocytes [PMID:10421785].","caveats":"Abstract-only reading; no affinity reported, and interaction is inferred from competition with IgG.","key_references":[{"PMID":"10421785","why":"HRG blocks monomeric IgG binding to FcgammaRI on THP1 cells"}],"covers":["LR000771"]},"LR002751":{"pair":"HSPA1A -> LRP1","headline":"HSP70 binds CD91 on cells (2001) and docks to CD91 in silico (2025); binding is cell-level or computational.","interaction_type":"direct binding","direction_and_effect":"FITC-labelled hsp70 binds RAW264.7 and related cell lines via CD91, competed by alpha2-macroglobulin and anti-CD91 [PMID:11290339]. Docking suggests strong, stable binding of full-length HSPA1A to CD91 [PMID:40813535].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cell lines [PMID:11290339]; in silico docking, no experimental species for the docking paper [PMID:40813535]. The human pair is ortholog-inferred.","localisation_and_range":"HSPA1A is flagged as secreted [flag].","caveats":"The 2001 evidence sentence concerns gp96; the hsp70 result comes from the curator's detail. The 2025 evidence is computational and abstract only. One further row was abstract_insufficient.","key_references":[{"PMID":"11290339","why":"hsp70 binds cells via CD91, competed by alpha2-macroglobulin"},{"PMID":"40813535","why":"In silico docking of HSPA1A to CD91"}],"covers":["LR002751","LR005999"]},"LR008232":{"pair":"HSPG2 -> ITGA2:ITGB1","headline":"Perlecan C-terminal fragment endorepellin engages the alpha2beta1 integrin complex in human endothelial cells, with anti-angiogenic signalling; functional, fragment-only.","interaction_type":"functional only","direction_and_effect":"Endorepellin engages alpha2beta1, raising cAMP, activating PKA and FAK and disassembling stress fibres and focal adhesions; curators label it antagonist, as it blocks endothelial migration and angiogenesis [PMID:15240572]. Reactome records the binding and an HSPG2(3687-4391):Integrin alpha2beta1 complex [DB:Reactome R-HSA-4088220] [DB:Reactome R-HSA-4088236].","molecular_requirements":"Requires the alpha2beta1 heterodimer as the receptor; only the C-terminal fragment (HSPG2 3687-4391) is implicated, not full-length perlecan [DB:Reactome R-HSA-4088236] [PMID:15240572].","affinity_potency":[],"species_and_systems":"Human endothelial cells in vitro [PMID:15240572].","localisation_and_range":"Soluble perlecan fragment acting on the endothelial cell surface (paracrine); perlecan is flagged secreted [flag] [PMID:15240572].","caveats":"Fragment, not full-length perlecan. Direct binding measurement is not reported in our evidence; the paper is read at abstract plus excerpts and the evidence sentence is functional.","key_references":[{"PMID":"15240572","why":"Endorepellin-alpha2beta1 signalling and anti-angiogenic effect"}],"covers":["LR008232"]},"LR004236":{"pair":"HSPG2 -> ITGB1","headline":"Recombinant perlecan domain V promotes cell adhesion blocked by anti-integrin beta1 antibodies (abstract only); functional, not direct binding.","interaction_type":"functional only","direction_and_effect":"Recombinant perlecan fragment V, but not fragment Vc, promoted adhesion of several cell lines, and this was blocked by antibodies against the integrin beta1 chain [PMID:9431988]. Reactome lists endorepellin binding alpha2beta1 integrin, which includes ITGB1 [DB:Reactome R-HSA-4088236].","molecular_requirements":"Domain V (three LG and four EG modules) is the active region; beta1 is paired with an alpha chain, but the alpha partner in this paper is not reported in our evidence [PMID:9431988].","affinity_potency":[],"species_and_systems":"Human recombinant domain V produced in embryonic kidney cells; cell-line identities are not reported in our evidence [PMID:9431988]. Mouse pair is ortholog-inferred.","localisation_and_range":"Perlecan is flagged secreted [flag]; the paper concerns a matrix cell-adhesion site, so it is contact or matrix-mediated [PMID:9431988].","caveats":"Abstract only. Antibody blockade of adhesion does not show direct binding, and the abstract notes this domain may be only one of several adhesive sites. Two other papers were abstract_insufficient.","key_references":[{"PMID":"9431988","why":"Perlecan domain V adhesion blocked by anti-beta1 integrin antibodies"}],"covers":["LR000778","LR004236"]},"LR011085":{"pair":"IBSP -> ITGAV:ITGB5","headline":"One 2026 abstract reports secreted IBSP binding ITGAV on pancreatic tumour cells; ITGB5 is not named.","interaction_type":"functional only","direction_and_effect":"Fibroblast-secreted IBSP binds ITGAV on tumour cells, activating PI3K/AKT and promoting resistance to gemcitabine-induced apoptosis [PMID:42435946]. Database entries concern ITGAV:ITGB3, not ITGB5 [DB:UniProt].","molecular_requirements":"Only ITGAV is named in the abstract; the ITGB5 partner is not shown [PMID:42435946].","affinity_potency":[],"species_and_systems":"Pancreatic cancer cells and fibroblasts; species not reported in our evidence [PMID:42435946].","localisation_and_range":"IBSP is secreted into the extracellular milieu and detectable in peripheral blood [PMID:42435946].","caveats":"Abstract only. Two other papers were abstract_insufficient. Reactome and UniProt records describe alphaVbeta3, not alphaVbeta5.","key_references":[{"PMID":"42435946","why":"Fibroblast IBSP binds ITGAV, activating PI3K/AKT"}],"covers":["LR011085"]},"LR004245":{"pair":"ICAM1 -> ITGB2","headline":"ICAM-1 binds beta2 integrins (LFA-1, CD11c/CD18) with direct-binding support, but ITGB2 alone is a shared chain, not a specific partner.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 acts as an agonist/adhesion ligand: direct binding to sLFA-1 [PMID:9780171], to CD11c/CD18 [PMID:16252253] and an LFA-1 alpha-chain binding region [PMID:7642561]; ICAM-1/CD18 engagement was needed for macrophage-mediated myeloma drug resistance in vitro and in a SCID mouse model [PMID:22996336].","molecular_requirements":"ITGB2 pairs with different alpha chains: the binding data are for LFA-1 (alphaL) and alphaX heterodimers, and the ICAM-1 D1D2 fragment sufficed for LFA-1 binding [PMID:9780171]. In the myeloma study, antibodies to CD11a, CD11b or CD11c did not affect the protective effect, so the alpha partner there is unresolved [PMID:22996336].","affinity_potency":[{"value":"Kd 500 nM","assay":"surface plasmon resonance, monomeric sLFA-1 binding to ICAM-1 D1D2-IgG chimera; k(diss) 0.1 s(-1)","system":"soluble human LFA-1","cite":"PMID:9780171"}],"species_and_systems":"Human proteins and cells; the myeloma study also used a human myeloma-SCID mouse model [PMID:22996336]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound adhesion on cell contact (the myeloma effect was cell-contact based [PMID:22996336]); ICAM1 also carries a secreted flag [flag].","caveats":"Most papers were read as abstracts. Seven confirmed and eight abstract_insufficient rows; only a subset is shown. BioGRID and UniProt support ICAM1-ITGB2 and LFA-1/Mac-1 receptor roles [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"9780171","why":"Kd 500 nM for sLFA-1 binding ICAM-1 D1D2"},{"PMID":"16252253","why":"SPR for ICAM-1 with CD11c/CD18"},{"PMID":"22996336","why":"Functional ICAM-1/CD18 role in myeloma drug resistance, in vitro and in vivo"}],"covers":["LR000787","LR004245"]},"LR007044":{"pair":"ICAM4 -> ITGAL:ITGB2","headline":"Complex-level pair supported only by UniProt statements; the one judged paper was abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that ITGAL/ITGB2 is a receptor for ICAM1, ICAM2, ICAM3 and ICAM4 [DB:UniProt], and that ITGAX:ITGB2 is a receptor of erythrocyte ICAM4 mediating erythrophagocytosis [DB:UniProt].","molecular_requirements":"The receptor is the ITGAL:ITGB2 heterodimer; both subunits carry receptor flags [flag]. Which subunits are required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence beyond the human entity record.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag]; range unclear.","caveats":"No curator-verified paper; evidence is database annotation only. Affinity and direction not reported in our evidence.","key_references":[],"covers":["LR007044"]},"LR002760":{"pair":"ICAM4 -> ITGAX","headline":"CD11c/CD18 (alphaXbeta2) is a macrophage receptor for red-cell ICAM-4; a single human study with binding-site mapping.","interaction_type":"direct binding","direction_and_effect":"ICAM-4 functions as a ligand for CD11c/CD18; curated as agonist. Anti-ICAM-4 and anti-integrin antibodies inhibit erythrophagocytosis, implicating the pair in senescent red-cell clearance [PMID:16985175]. UniProt agrees [DB:UniProt].","molecular_requirements":"The receptor is the CD11c/CD18 heterodimer. Both Ig domains of ICAM-4 contain binding sites; important residues cluster in two regions of domain 1 with an extension into domain 2, and two ICAM-4-derived peptides modulate binding [PMID:16985175].","affinity_potency":[],"species_and_systems":"Human proteins; CD11c/CD18 expressed on splenic and bone-marrow macrophages [PMID:16985175]. Mouse pair is ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion. Red-cell expression of ICAM-4 is stated in the abstract [PMID:16985175].","caveats":"One paper, abstract only. Affinity not reported in our evidence.","key_references":[{"PMID":"16985175","why":"ICAM-4 as ligand for CD11c/CD18; binding-site mapping"}],"covers":["LR002760","LR006006"]},"LR004254":{"pair":"ICAM4 -> ITGB1","headline":"Single abstract-only study shows beta1-integrin (alpha4beta1, alphaVbeta1) mediated adhesion to ICAM-4-Fc; no direct binding assay.","interaction_type":"functional only","direction_and_effect":"Cell adhesion to ICAM-4-Fc was inhibited by LDV peptide and antibodies, identifying alpha4beta1, and alphaV integrins (notably alphaVbeta1) on alpha4beta1-negative cells [PMID:11435317]. UniProt lists ITGA5:ITGB1 among ICAM4 partners in vitro [DB:UniProt].","molecular_requirements":"beta1 acts with alpha4 or alphaV; the dossier gives no beta1-alone evidence. Neither the LETS nor LDV motif in ICAM-4 domain 1 was critical [PMID:11435317].","affinity_potency":[],"species_and_systems":"Human cell lines with an ICAM-4-Fc construct [PMID:11435317]; mouse pair ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only; antibody and peptide inhibition rather than binding. Affinity not reported.","key_references":[{"PMID":"11435317","why":"alpha4beta1 and alphaV integrins bind ICAM-4-Fc"}],"covers":["LR000800","LR004254"]},"LR004263":{"pair":"IFNA13 -> IFNAR1","headline":"Chain-level binding of human alpha-IFNs to IFNAR1, applied to IFNA13 by class statements; thin.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists IFNA13 as an agonist of IFNAR1 [DB:GtoPdb]; the interaction is stimulatory in the record.","molecular_requirements":"Alpha-IFNs bind isolated IFNAR1 chain; competitive 1:1 binding to ifnar1-EC and ifnar2-EC for all IFNs tested [PMID:17174979].","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"binding to isolated receptor chain","system":"alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human recombinant/purified subunits [PMID:21856167] [PMID:17174979].","localisation_and_range":"Not reported in our evidence (no annotation flags for IFNA13).","caveats":"Both papers are abstract only and do not name IFNA13. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"21856167","why":"Class-wide affinities"},{"PMID":"17174979","why":"Receptor subunit affinities for several IFNs"}],"covers":["LR008443","LR004263"]},"LR000807":{"pair":"IFNA14 -> IFNAR1","headline":"Chain-level micromolar binding of alpha-IFNs to IFNAR1, applied to IFNA14 by a class statement.","interaction_type":"direct binding","direction_and_effect":"IFNA14 is a stimulatory agonist at IFNAR1 [PMID:21856167] [DB:GtoPdb].","molecular_requirements":"Chain-only evidence on isolated IFNAR1 [PMID:21856167].","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"binding to isolated receptor chain","system":"12 human alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human isolated chains.","localisation_and_range":"IFNA14 flagged secreted [flag].","caveats":"Abstract only; IFNA14 not named in the abstract.","key_references":[{"PMID":"21856167","why":"Chain affinities of alpha-IFN subtypes"}],"covers":["LR000807"]},"LR011715":{"pair":"IFNA17 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA17 to a complex listing IFNA2, IFNAR1 and IFNAR2 rests only on GtoPdb; no paper was verified.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA17 as an agonist at IFNAR1 and at IFNAR2 [DB:GtoPdb]. No curator-verified paper supports the pair.","molecular_requirements":"The receptor entry includes IFNA2 as a member alongside IFNAR1 and IFNAR2, which is unexpected for a receptor complex; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experiment in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Judged papers were all abstract_insufficient or about a different entity, so none confirms the pair. Support is from GtoPdb records for the individual chains only; affinity not given (units '-') [DB:GtoPdb].","key_references":[],"covers":["LR011715"]},"LR000816":{"pair":"IFNA21 -> IFNAR2","headline":"IFNA21 binds IFNAR2 on class-wide evidence from one abstract; IFNAR2 is the high-affinity chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR2 at 0.4-5 nM, except IFN-alpha1 at 220 nM [PMID:21856167]. GtoPdb lists IFNA21 as an agonist at IFNAR2 [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tighter-binding chain; IFNAR1 binds at 0.5-5 \u03bcM [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA21. Binding is to the isolated chain.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000816"]},"LR000825":{"pair":"IFNA7 -> IFNAR1","headline":"IFNA7 binds IFNAR1 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA7 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA7 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000825"]},"LR006009":{"pair":"Ifna9 -> Cr2","headline":"Mouse Ifna9 to Cr2 is projected from a human study showing CR2 binds IFN-alpha; no mouse experiment.","interaction_type":"direct binding","direction_and_effect":"Human CR2 bound IFN-alpha by surface plasmon resonance and ELISA, in the same affinity range as its three established ligands [PMID:16785534]. IFN-alpha interacts with CR2 short consensus repeat domains 1 and 2, and anti-CR2 mAb 171 diminished induction of IFN-alpha-responsive genes in human B cells [PMID:16785534].","molecular_requirements":"SCR domains 1 and 2 of CR2, the site used by C3d/iC3b, EBV-gp350 and CD23, are involved [PMID:16785534]. Co-receptor needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used human proteins and human B cells [PMID:16785534]; the mouse pair is ortholog-inferred, with no mouse experiment.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor is flagged a receptor and not secreted [flag].","caveats":"The paper tested 'IFN-alpha' generally, not the Ifna9 subtype; abstract-only reading. Specific affinity values not reported in our evidence.","key_references":[{"PMID":"16785534","why":"SPR and ELISA binding of IFN-alpha to CR2, SCR1-2 mapping"}],"covers":["LR006009"]},"LR001851":{"pair":"IFNE -> IFNAR1","headline":"IFNE signals through IFNAR1 in mouse, shown functionally; human pair is projected. No database records.","interaction_type":"functional only","direction_and_effect":"IFN-\u03b5 signalled via the Ifnar1 and Ifnar2 receptors to induce IFN-regulated genes, so it acts as a type I IFN agonist [PMID:23449591]. Ifn-\u03b5-deficient mice were more susceptible to HSV-2 and Chlamydia muridarum infection of the female reproductive tract [PMID:23449591].","molecular_requirements":"Both Ifnar1 and Ifnar2 are named as the signalling receptors [PMID:23449591]; whether one chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments; the human pair is ortholog-inferred, the mouse pair is not [PMID:23449591].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The paper reports IFN-\u03b5 constitutively expressed by female reproductive tract epithelium and hormonally regulated [PMID:23449591].","caveats":"Evidence is functional (gene induction), not binding, and abstract-only. No direct binding or affinity data and no database records in our evidence.","key_references":[{"PMID":"23449591","why":"IFN-\u03b5 signals via Ifnar1/Ifnar2; knockout mice more infection-prone"}],"covers":["LR001851","LR005199"]},"LR000834":{"pair":"IFNL2 -> IFNLR1","headline":"IFN-lambda2 (IL-28A) binds IFNLR1 as part of a heterodimeric receptor; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"IL-28 and IL-29 interacted with a heterodimeric class II cytokine receptor of IL-10Rbeta and IL-28Ralpha and showed antiviral activity [PMID:12469119]; GtoPdb lists Agonist [DB:GtoPdb]. Curator notes IFNL2 = IL-28A.","molecular_requirements":"IFNLR1 (IL-28Ralpha) works with IL-10Rbeta [PMID:12469119].","affinity_potency":[],"species_and_systems":"Human, human cells [PMID:12469119].","localisation_and_range":"IFNL2 is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only; the abstract names IL-28 generally, not IL-28A specifically, and does not separate IFNLR1 alone from the heterodimer.","key_references":[{"PMID":"12469119","why":"IL-28/IL-29 receptor discovery"}],"covers":["LR000834"]},"LR004272":{"pair":"IGF1 -> IGF1R","headline":"Well-established IGF1 agonist at IGF1R, supported by structures and databases; our only verified paper is an older chimeric-receptor binding study.","interaction_type":"direct binding","direction_and_effect":"IGF1 is recorded as an agonist of IGF1R [DB:GtoPdb]; the interaction is annotated stimulatory. Chimeric receptor binding studies showed the cysteine-rich domain helps determine IGF-I specificity [PMID:1852007].","molecular_requirements":"Part of the IGF1R cysteine-rich domain determines IGF-I specificity; the insulin receptor N-terminal segment swapped into IGF1R raised insulin affinity but was not critical for high-affinity IGF-I binding [PMID:1852007]. Structures contain chains of both proteins [DB:PDB 4XSS].","affinity_potency":[],"species_and_systems":"Soluble chimeric insulin/IGF-I receptors expressed in mammalian cells (human on both sides) [PMID:1852007]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"IGF1 is flagged secreted and IGF1R transmembrane [flag].","caveats":"The one verified paper was read as an abstract only and addresses receptor specificity rather than measuring IGF1 affinity; no affinity is reported in our evidence. Two further papers are pending.","key_references":[{"PMID":"1852007","why":"Chimeric receptor mapping of IGF-I binding specificity"}],"covers":["LR000840","LR004272"]},"LR000843":{"pair":"IGF2 -> INSR","headline":"Genetic mouse evidence that IGF-II signals partly through the insulin receptor; no direct binding paper in our evidence.","interaction_type":"functional only","direction_and_effect":"Mouse embryos lacking both Igf1r and Insr were as growth-retarded (30% of normal size at birth) as Igf1r/Igf2 double mutants, giving genetic evidence that IGF-II growth promotion is mediated in part by the insulin receptor [PMID:9281335]. Structures of IGF2 with INSR exist [DB:PDB 8U4C].","molecular_requirements":"Not reported in our evidence; IGF1R-null background was needed to reveal the INSR contribution [PMID:9281335].","affinity_potency":[],"species_and_systems":"In vivo knockout mice [PMID:9281335]; the human pair is ortholog-inferred from this mouse work.","localisation_and_range":"IGF2 is flagged secreted and INSR transmembrane [flag].","caveats":"Evidence is indirect genetics, read as abstract only, and does not show binding or isoform. No affinity is reported in our evidence.","key_references":[{"PMID":"9281335","why":"Igf1r/Insr double-null mouse genetics"}],"covers":["LR000843","LR004275"]},"LR006018":{"pair":"IGF2 -> ITGB4","headline":"Integrin alpha6beta4 binds IGF2 in one verified study; ITGB4 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alpha6beta4 heterodimer was tested; ITGB4 alone is not shown [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002772","LR006018"]},"LR011175":{"pair":"IGFBP2 -> IGF1","headline":"Database-supported IGFBP2-IGF1 binding with inhibitory label; no curated paper in the dossier.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory; IGFBP2 binds IGF forming IGF:IGFBP2 [DB:Reactome]. UniProt notes IGFBP2 interacts with IGF1, and works with PTPRB and the IGF1 receptor to regulate IGF1 signalling by stimulating PTEN phosphorylation and AKT1 activation [DB:UniProt].","molecular_requirements":"Co-purification of IGF1 and IGFBP2 recorded [DB:BioGRID]; no subunit requirements reported.","affinity_potency":[],"species_and_systems":"Human only; assay detail beyond co-purification is not reported.","localisation_and_range":"IGF1 is annotated as secreted [flag]; IGFBP2 has no localisation flag.","caveats":"No curator-verified paper (one candidate judged as a different entity). Support is database records only; the inhibitory label and the UniProt signalling-enhancing function are not reconciled in our evidence.","key_references":[],"covers":["LR011175"]},"LR008007":{"pair":"IGHG1:IGLC1 -> FCGR2B","headline":"No paper was judged for this pair; support rests on database records of IgG1 binding FcgammaRIIb.","interaction_type":"database-asserted only","direction_and_effect":"No curated papers are available for this pair. IntAct lists a direct interaction measured by isothermal titration calorimetry and surface plasmon resonance records for P01857 and P31994 [DB:IntAct]. UniProt states IgG1 in immune complexes interacts with FCGR2B [DB:UniProt]. Effect direction is not reported in our evidence.","molecular_requirements":"The dossier covers the IgG1 heavy chain (P01857) in the database records; the light chain IGLC1 is not shown in them [DB:IntAct]. A PDB structure of an IgG1 Fc variant with FcgRIIb exists [DB:PDB 3WJJ].","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence. The structure 3WJJ is an Fc fragment variant (P238D) with the receptor [DB:PDB 3WJJ].","localisation_and_range":"IGHG1 is flagged secreted and FCGR2B a receptor [flag]; range from annotation only.","caveats":"No judged papers; the one judged row was a different entity. The complex ligand IGHG1:IGLC1 is supported only through the heavy chain. The PDB 3WJJ ligand is an engineered Fc variant, not native IgG1.","key_references":[],"covers":["LR008007"]},"LR004281":{"pair":"IHH -> PTCH1","headline":"PTCH1 binds all Hedgehog family members including IHH in a biochemical assay; abstract only.","interaction_type":"direct binding","direction_and_effect":"Biochemical analysis shows PTCH and PTCH2 both bind all hedgehog family members with similar affinity and can form a complex with SMO [PMID:9811851]. In chick cartilage, Ihh regulates Ptc and Gli expression and misexpression blocks hypertrophic differentiation [PMID:8662546]. UniProt describes PTCH1 as a negative regulator of smoothened signalling that is a receptor for SHH, IHH and DHH [DB:UniProt].","molecular_requirements":"PTCH forms a complex with SMO [PMID:9811851]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding assay species not stated in the dossier [PMID:9811851]; chicken Ihh with mouse tissue work [PMID:8662546]. Human pair is ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Both papers are abstract only. The 1996 paper infers Ihh-Ptc engagement from target gene regulation, not binding. No numeric affinity is given.","key_references":[{"PMID":"9811851","why":"PTCH binds all Hedgehog family members"},{"PMID":"8662546","why":"Ihh regulates Ptc in cartilage differentiation"}],"covers":["LR000851","LR004281"]},"LR000852":{"pair":"IHH -> PTCH2","headline":"PTCH2 binds all hedgehog family members with similar affinity in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Biochemical analysis shows PTCH and PTCH2 both bind all hedgehog family members with similar affinity and form a complex with SMO [PMID:9811851]. UniProt describes PTCH2 as a negative regulator of smoothened signalling and a receptor for SHH, IHH and DHH [DB:UniProt]. The authors suggest PTCH2 mediates Desert Hedgehog activity in vivo [PMID:9811851].","molecular_requirements":"PTCH2 can form a complex with SMO [PMID:9811851].","affinity_potency":[],"species_and_systems":"Binding assay species is not reported in our evidence. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Abstract only. IHH is covered by the general statement about all family members. No numeric affinity is given.","key_references":[{"PMID":"9811851","why":"PTCH2 binds all hedgehog family members"}],"covers":["LR000852","LR004282"]},"LR012507":{"pair":"IHH -> SMO","headline":"No papers support this pair; SMO is not a direct IHH receptor in the database text, which says cholesterol activates it.","interaction_type":"database-asserted only","direction_and_effect":"No judged papers. UniProt says SMO is activated by cholesterol in response to hedgehog (DHH, IHH or SHH) morphogens [DB:UniProt]. This describes pathway activation, not direct IHH binding.","molecular_requirements":"PTCH1 or PTCH2 binding is the upstream step in other pairs; SMO requirements here are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Several abstracts were judged insufficient and one was a different entity. The pair rests on a UniProt function line only and may be indirect.","key_references":[],"covers":["LR012507"]},"LR006027":{"pair":"IL12A -> IL6ST","headline":"IL12A-IL6ST rests on one abstract: IL-35, not IL-12, signals through gp130; weak for this pair.","interaction_type":"functional only","direction_and_effect":"IL-35 (containing p35/IL12A) signalled through an IL-12Rbeta2/gp130 heterodimer or homodimers of each chain [PMID:22306691]. Gp130 homodimers sufficed for partial suppression of conventional T cells, not for iTr35 conversion [PMID:22306691].","molecular_requirements":"The full IL-35 receptor (IL-12Rbeta2 plus gp130) is needed for iTr35 conversion; one chain suffices for partial effects [PMID:22306691]. UniProt says p35 signals through IL12RB2/IL6ST heterodimers or homodimers [DB:UniProt].","affinity_potency":[],"species_and_systems":"Abstract-only; dossier tags both species as human, but the experiments' species are not stated in the abstract. Human pair ortholog-inferred, mouse pair not.","localisation_and_range":"IL12A is flagged secreted and IL6ST transmembrane [flag].","caveats":"The partner of p35 in IL-35 is not named in this dossier's abstract. Physical IL12A-IL6ST binding is not shown; evidence is functional. IL-12 itself is not shown to use gp130.","key_references":[{"PMID":"22306691","why":"IL-35 signals via IL-12Rbeta2/gp130 or homodimers"}],"covers":["LR002784","LR006027"]},"LR004290":{"pair":"IL12B -> IL12RB2","headline":"IL12RB2 binds the IL-12 heterodimer, with p35 and p40 both contributing; p40 alone is not shown to bind IL12RB2.","interaction_type":"direct binding","direction_and_effect":"Blocking studies in human cells indicate IL-12 binds IL-12Rbeta2 via heterodimer-specific regions to which p35 and p40 both contribute [PMID:9498755]. IL12RB2-deficient mice lost IL-12-induced function [PMID:11086056]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-12Rbeta1 and IL-12Rbeta2 individually bind IL-12 with low affinity and together with high affinity [PMID:9498755]. Cryo-EM structures 8XRP and 8YI7 contain an IL12B chain and an IL12RB2 chain [DB:PDB 8XRP].","affinity_potency":[],"species_and_systems":"Human COS-7 cells and lymphoblasts [PMID:9498755]; knockout mice [PMID:11086056]. Both human and mouse pairs are present.","localisation_and_range":"IL12B is flagged secreted [flag].","caveats":"Both papers are abstract-only. The binding evidence uses the heterodimer-specific antibody 20C2, so it does not show p40 alone binds IL12RB2. No affinity value is reported. The knockout paper does not test binding.","key_references":[{"PMID":"9498755","why":"IL-12 contacts IL-12Rbeta2 via heterodimer-specific regions"},{"PMID":"11086056","why":"IL12RB2 required for IL-12 function in mice"}],"covers":["LR000860","LR004290"]},"LR000861":{"pair":"IL13 -> IL13RA1","headline":"IL13 binds IL13RA1 directly by structure and biophysical assays in databases; no curator-verified paper yet.","interaction_type":"database-asserted only","direction_and_effect":"IL13 signals through IL13RA1 with IL4R, activating JAK1 and TYK2 and then STAT6 [DB:UniProt]. GtoPdb lists agonist [DB:GtoPdb]. Reactome records IL13 binding IL13RA:TYK2 and phosphorylated complex [DB:Reactome].","molecular_requirements":"IL4R chain is also part of the signalling receptor per UniProt [DB:UniProt]. IL13RA2 is a separate high-affinity decoy [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human records; mouse pair is projected from human by orthology, not tested [DB:UniProt]. Binding assays in IntAct are ITC and SPR [DB:IntAct]; crystal structures [DB:PDB 3BPO] [DB:PDB 5E4E]; BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"IL13 flagged secreted [flag]; receptor flagged as receptor [flag].","caveats":"No judged paper: 3 abstracts were insufficient, 1 review-only, 1 pending. Evidence is database-only; affinity not reported in our evidence.","key_references":[],"covers":["LR000861","LR004291"]},"LR010635":{"pair":"IL16 -> KCNJ15","headline":"Database-asserted only: a UniProt subunit note lists KCNJ15 as an IL16 isoform 1 interactor; no papers support a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt states that isoform 1 interacts with GRIN2D, KCNJ10, KCNJ15 and CACNA1C (By similarity) [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"UniProt annotation 'By similarity' only; no experiment species reported in our evidence [DB:UniProt].","localisation_and_range":"IL16 is annotated as secreted [flag]; no localisation annotation for the partner in our evidence.","caveats":"No curated paper evidence; the interaction was judged a different entity in our curation. The UniProt statement is inferred by similarity, not shown directly for this pair.","key_references":[],"covers":["LR010635"]},"LR000870":{"pair":"IL17A -> IL17RC","headline":"IL-17A binds IL-17RC in SPR with affinity comparable to IL-17F, as part of an IL-17RA/IL-17RC receptor; one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17A, IL-17F and the heterodimer bound IL-17RC with comparable affinities; IL-17A activity was inhibited by soluble IL-17RA rather than IL-17RC [PMID:18684971]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"IL-17RC functions as a receptor for IL17A and IL17F homodimers within a heterodimer with IL17RA, but UniProt also notes it may bind IL17A with high affinity without IL17RA [DB:UniProt]. PDB 7UWN and 7ZAN contain IL17RC and IL17RA chains [DB:PDB 7UWN].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and human bronchial epithelial cells [PMID:18684971]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17A annotated as secreted [flag]; IL-17RC annotated as a receptor [flag].","caveats":"Single paper, read as abstract only; no affinity values reported in the abstract [PMID:18684971].","key_references":[{"PMID":"18684971","why":"SPR binding of IL-17A, F and A/F to IL-17RC; receptor complex"}],"covers":["LR000870","LR004300"]},"LR011733":{"pair":"IL1A -> IL1B:IL1R2:IL1RAP","headline":"Database-asserted only: no verified paper; the receptor complex is odd because it lists IL1B as a receptor member.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1A-IL1RAP as agonist [DB:GtoPdb]; Reactome lists the IL1R2 complex with IL1 and IL1R2 binding IL1 [DB:Reactome]; UniProt calls IL1R2 a non-signaling receptor for IL1A, IL1B and IL1RN [DB:UniProt].","molecular_requirements":"IL1R2 is described as a non-signaling receptor [DB:UniProt]; IL1RAP role in this complex is not tested in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our evidence; species not reported beyond the human entity record.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"No curator-verified paper in our evidence; support rests on database records only. Two papers are still pending curation. Affinity not reported.","key_references":[],"covers":["LR011733"]},"LR004308":{"pair":"IL1A -> IL1R1","headline":"IL-1alpha binds the same type I receptor as IL-1beta; old competition-binding evidence in murine and human cells.","interaction_type":"direct binding","direction_and_effect":"IL-1 alpha uses the receptor shared with IL-1 beta on both murine and human cells [PMID:2946959]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"UniProt says IL1A binds IL1R1 together with IL1RAP to form the high affinity receptor complex [DB:UniProt]; this paper does not address IL1RAP.","affinity_potency":[],"species_and_systems":"Murine T cells/fibroblasts and human cells, from the abstract [PMID:2946959].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Abstract only; no affinity or assay detail reported in our evidence. One more paper is pending.","key_references":[{"PMID":"2946959","why":"IL-1 alpha and IL-1 beta share one receptor on murine and human cells"}],"covers":["LR000878","LR004308"]},"LR007305":{"pair":"IL1B -> IL1R2:IL1RAP","headline":"Database-asserted only: no verified paper, but structures and UniProt describe IL1RAP binding ligand-bound IL1R2.","interaction_type":"database-asserted only","direction_and_effect":"UniProt calls IL1R2 a non-signaling receptor for IL1A, IL1B and IL1RN, and says IL1RAP associates with secreted ligand-bound IL1R2 [DB:UniProt]; GtoPdb lists IL1B-IL1RAP as agonist [DB:GtoPdb].","molecular_requirements":"Both chains are described by UniProt, which says IL1RAP increases the affinity of secreted IL1R2 for IL1B [DB:UniProt]. PDB 3O4O has IL1B and IL1R2 chains [DB:PDB 3O4O]; IntAct lists binding records for IL1RAP-IL1B [DB:IntAct].","affinity_potency":[],"species_and_systems":"No experiments from curated papers in our evidence.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"No curator-verified paper in our evidence; support rests on database records only. Two papers were judged review-only and not used.","key_references":[],"covers":["LR007305"]},"LR006036":{"pair":"IL1F10 -> IL1RAPL1","headline":"IL-38 binds IL1RAPL1 (full-length and truncated), with processing-dependent opposite effects on IL-6; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Both full-length and truncated IL-38 bound IL1RAPL1; the precursor increased macrophage IL-6, whereas truncated IL-38 reduced IL-6 by attenuating JNK/AP1 signalling downstream of IL1RAPL1 [PMID:26892022]. Curators label it antagonist, which applies to the truncated form only.","molecular_requirements":"The N-terminally processed (truncated) form is the anti-inflammatory one [PMID:26892022]. Reactome lists complexes for both forms [DB:Reactome]. Co-receptor needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human apoptotic cells and primary human macrophages [PMID:26892022]; the mouse pair is inferred.","localisation_and_range":"IL1F10 is flagged secreted and IL1RAPL1 transmembrane [flag]; the paper describes release from apoptotic cells [PMID:26892022].","caveats":"Abstract only. The effect depends on which IL-38 form is present, so a single agonist/antagonist label is misleading. Another paper judged for this pair is still pending.","key_references":[{"PMID":"26892022","why":"IL-38 forms bind IL1RAPL1 with opposite IL-6 effects"}],"covers":["LR002793","LR006036"]},"LR001860":{"pair":"IL1RAPL1 -> PTPRD","headline":"IL1RAPL1 extracellular domains interact with PTPdelta to induce excitatory presynapse formation; structure in PDB.","interaction_type":"direct binding","direction_and_effect":"The IgG-like extracellular domains of IL1RAPL1 induce excitatory pre-synapse formation by interacting with PTPdelta, and the complex recruits RhoGAP2 to drive dendritic spine formation [PMID:21926414].","molecular_requirements":"Extracellular Ig-like domains are needed; IL1RAPL1 TIR domains interact with RhoGAP2 intracellularly [PMID:21926414]. A PDB structure has chains of both proteins [DB:PDB 5WY8]. BioGRID has affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Species of the experiments is not stated in the dossier; neuron culture assays [PMID:21926414]. Both human and mouse pairs are projected from other evidence.","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic action.","caveats":"Abstract read only for the binding statement; the full-text excerpts shown cover figures on spines, not the binding. No affinity reported.","key_references":[{"PMID":"21926414","why":"IL1RAPL1 ectodomain interacts with PTPdelta for presynapse formation"}],"covers":["LR001860","LR005206"]},"LR004317":{"pair":"IL20 -> IL20RA","headline":"IL-20 signals through IL20RA with IL20RB, but IL20RA alone does not bind IL-20 in the one binding study.","interaction_type":"direct binding","direction_and_effect":"IL-20 induces STAT3 phosphorylation through the type I complex IL-20Ralpha/IL-20Rbeta and the type II complex IL-22R/IL-20Rbeta [PMID:11564763] [PMID:12351624]. GtoPdb lists Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"IL20RA is part of a ternary 1:1:1 complex with IL-20 and the second receptor; sIL-20R1 does not bind IL-19 or IL-20 on its own, and the ligand first binds receptor II [PMID:14580208]. Type II signalling uses IL22RA1 instead of IL20RA [PMID:11564763].","affinity_potency":[],"species_and_systems":"Recombinant human soluble ectodomains from Drosophila S2 cells with size-exclusion chromatography [PMID:14580208]; transfected cell lines for signalling [PMID:12351624]. Mouse pair projected.","localisation_and_range":"IL-20 flagged secreted [flag].","caveats":"Binding evidence is for the heterodimer, not IL20RA alone; individual-chain evidence is inherited from complex-level data. All papers abstract only.","key_references":[{"PMID":"14580208","why":"sIL-20R1 does not bind IL-20 alone; ternary complex forms"},{"PMID":"11564763","why":"IL-20 signals through two receptor complexes"},{"PMID":"12351624","why":"Receptor redundancy among IL-19, IL-20, IL-24"}],"covers":["LR000887","LR004317"]},"LR007314":{"pair":"IL21 -> IL21R:IL2RG","headline":"IL-21 acts through the IL21R:IL2RG complex; binding needs IL-21R but signalling needs gamma(c). One abstract-level paper.","interaction_type":"functional only","direction_and_effect":"IL-21 binds IL-21R on gamma(c)-deficient cells without signalling; EDgamma-16 cells reconstituted with gamma(c) activate JAK1, JAK3, STAT1 and STAT3 [PMID:11418623]. GtoPdb lists agonist records for both chains [DB:GtoPdb].","molecular_requirements":"Both chains are required for a functional receptor: IL-21R for binding, gamma(c) for signal transduction [PMID:11418623]. Cross-linking shows direct binding of IL-21 to gamma(c) [PMID:11418623].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; ED40515(-) and gamma(c)-transfected EDgamma-16 cells [PMID:11418623].","localisation_and_range":"Ligand is flagged secreted and the complex transmembrane [flag].","caveats":"Abstract-only evidence from a single paper; a second judged paper was abstract_insufficient. BioGRID lists Affinity Capture-Western for IL2RG-IL21 [DB:BioGRID].","key_references":[{"PMID":"11418623","why":"gamma(c) is an indispensable subunit of the IL-21 receptor complex"}],"covers":["LR007314"]},"LR004326":{"pair":"IL23A -> IL23R","headline":"IL-23 binds IL-23R directly through p19; crystal structure and receptor identification support it, with IL-12Rbeta1 as shared partner.","interaction_type":"direct binding","direction_and_effect":"The crystal structure shows IL-23R binds IL-23 exclusively via its N-terminal immunoglobulin domain [PMID:29287995]. Human IL-23, but not IL-12, has detectable affinity for human IL-23R [PMID:12023369]. Agonist per GtoPdb [DB:GtoPdb].","molecular_requirements":"IL-23 uses only its p19 subunit to contact IL-23R, with an interface of about 900 A2 and 51 residues [PMID:29287995]. IL-23R pairs with IL-12Rbeta1 for IL-23 responsiveness; antibodies to either chain block responses [PMID:12023369].","affinity_potency":[],"species_and_systems":"Human proteins; crystal structure of the IL-23:IL-23R:Nb22E11 complex at 2.8 A [PMID:29287995]; NK line and Ba/F3 transfectants [PMID:12023369].","localisation_and_range":"IL23A is flagged secreted [flag].","caveats":"Abstracts only for both papers. No affinity value is given in our evidence. The ternary complex with IL-12Rbeta1 was unstable and not solved [PMID:29287995].","key_references":[{"PMID":"29287995","why":"crystal structure of IL-23:IL-23R"},{"PMID":"12023369","why":"identification of IL-23R pairing with IL-12Rbeta1"}],"covers":["LR000896","LR004326"]},"LR000906":{"pair":"IL31 -> IL31RA","headline":"IL-31 signals through IL31RA together with OSMR; supported by two abstract-level papers and UniProt.","interaction_type":"functional only","direction_and_effect":"IL-31 signals through a receptor composed of IL-31 receptor A and oncostatin M receptor [PMID:15184896]. UniProt says IL31 binds IL31RA, the signal-transducing subunit of the IL31 receptor complex [DB:UniProt Q8NI17]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"The receptor is an OSMR/IL31RA heterodimer [DB:UniProt Q8NI17]. The signalling paper shows Jak1 binding to GPL (IL31RA) and its activation in heteromeric complexes with OSMRbeta but also in a homomeric complex, and GPL activates STAT3 and STAT5 [PMID:15194700].","affinity_potency":[],"species_and_systems":"Species of the first paper's experiments is unspecified; transgenic mice overexpressing IL-31 developed pruritus, alopecia and skin lesions [PMID:15184896]. The mouse pair is ortholog-inferred. PDB 22PL contains both chains [DB:PDB 22PL].","localisation_and_range":"IL-31 is flagged secreted [flag]; IL31RA is described as a membrane-bound signalling subunit [DB:UniProt Q8NI17].","caveats":"Both papers abstract only; no binding assay or affinity in our evidence. PMID:15194700 hedges the OSMR assignment as 'seems to be'.","key_references":[{"PMID":"15184896","why":"Identifies IL-31 and its IL31RA/OSMR receptor."},{"PMID":"15194700","why":"Signalling of the IL31RA (GPL) receptor chain: STAT3/STAT5, Jak1."}],"covers":["LR000906","LR004335"]},"LR004335":{"pair":"IL31 -> IL31RA","headline":"IL-31 signals through IL31RA together with OSMR; supported by two abstract-level papers and UniProt.","interaction_type":"functional only","direction_and_effect":"IL-31 signals through a receptor composed of IL-31 receptor A and oncostatin M receptor [PMID:15184896]. UniProt says IL31 binds IL31RA, the signal-transducing subunit of the IL31 receptor complex [DB:UniProt Q8NI17]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"The receptor is an OSMR/IL31RA heterodimer [DB:UniProt Q8NI17]. The signalling paper shows Jak1 binding to GPL (IL31RA) and its activation in heteromeric complexes with OSMRbeta but also in a homomeric complex, and GPL activates STAT3 and STAT5 [PMID:15194700].","affinity_potency":[],"species_and_systems":"Species of the first paper's experiments is unspecified; transgenic mice overexpressing IL-31 developed pruritus, alopecia and skin lesions [PMID:15184896]. The mouse pair is ortholog-inferred. PDB 22PL contains both chains [DB:PDB 22PL].","localisation_and_range":"IL-31 is flagged secreted [flag]; IL31RA is described as a membrane-bound signalling subunit [DB:UniProt Q8NI17].","caveats":"Both papers abstract only; no binding assay or affinity in our evidence. PMID:15194700 hedges the OSMR assignment as 'seems to be'.","key_references":[{"PMID":"15184896","why":"Identifies IL-31 and its IL31RA/OSMR receptor."},{"PMID":"15194700","why":"Signalling of the IL31RA (GPL) receptor chain: STAT3/STAT5, Jak1."}],"covers":["LR000906","LR004335"]},"LR005208":{"pair":"IL34 -> PTPRZ1","headline":"IL-34 binds PTPRZ1 (PTP-zeta) in one paper using affinity chromatography and cell lysates; single abstract-level source.","interaction_type":"direct binding","direction_and_effect":"IL-34 bound PTP-zeta in CSF-1R-deficient U251 human glioblastoma lysates and inhibited proliferation, clonogenicity and motility in a PTP-zeta-dependent manner [PMID:23744080]. Reactome and BioGRID (reconstituted complex) agree [DB:Reactome][DB:BioGRID].","molecular_requirements":"Binding depended on PTP-zeta chondroitin sulfate moieties: chondroitinase ABC abrogated binding and CS competed with IL-34 [PMID:23744080].","affinity_potency":[],"species_and_systems":"Affinity chromatography of mouse brain membrane, then human U251 cells [PMID:23744080].","localisation_and_range":"IL-34 flagged secreted; PTPRZ1 flagged transmembrane (also flagged secreted) [flag]; the paper calls it a cell-surface proteoglycan [PMID:23744080].","caveats":"Only one paper, read as abstract. No affinity value. Binding is chondroitin sulfate dependent.","key_references":[{"PMID":"23744080","why":"IL-34 identified as PTP-zeta ligand"}],"covers":["LR001863","LR005208"]},"LR007323":{"pair":"IL36B -> IL1RAP:IL1RL2","headline":"IL-36 acting on the IL1RAP:IL1RL2 complex rests on database records only; no judged papers.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist records for both IL1RAP and IL1RL2 [DB:GtoPdb]; Reactome has a binding reaction IL36:IL1RL2 with IL1RAP [DB:Reactome]. UniProt describes signalling through IL1RL2/IL-36R activating NF-kappa-B and MAPK [DB:UniProt].","molecular_requirements":"Complex of IL1RAP and IL1RL2 (listed members); which subunit binds the ligand is not reported in these records.","affinity_potency":[],"species_and_systems":"Human only; no experimental paper in our evidence.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor complex annotated transmembrane [flag].","caveats":"No papers (three review-only rows). Support is database assertion only.","key_references":[],"covers":["LR007323"]},"LR006045":{"pair":"IL36B -> IL1RL2","headline":"IL36B signalling through IL1RL2 is supported by one functional abstract-only paper plus databases.","interaction_type":"functional only","direction_and_effect":"IL-1F6/F8/F9 activate NF-kappaB IL-1Rrp2 (IL1RL2)-dependently, and anti-IL-1Rrp2 antibodies block it in Jurkat and NCI/ADR-RES cells [PMID:14734551]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Requires the IL-1Rrp2/IL-1RAcP heterodimer per the curator note [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human and mouse cell lines [PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"One paper, abstract only; it names IL-1F6/F8/F9, not IL36B. No binding or affinity data.","key_references":[{"PMID":"14734551","why":"IL-1Rrp2-dependent signalling"}],"covers":["LR002803","LR006045"]},"LR002805":{"pair":"IL36G -> IL1RL2","headline":"IL36G binds the IL-36R extracellular domain with micromolar affinity and activates it; direct binding plus functional support.","interaction_type":"direct binding","direction_and_effect":"Agonists including IL-36gamma bind the IL-36R ectodomain; the antagonist IL-36Ra binds with higher affinity and a slower off rate [PMID:29180446]. IL-1epsilon activated NF-kappaB through IL-1Rrp2 [PMID:11466363][PMID:14734551]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Agonists do not detectably bind IL-1RAcP alone; IL-1RAcP binds IL-36R strongly only with IL-36alpha present, so IL-36R-agonist binary complex recruits IL-1RAcP [PMID:29180446].","affinity_potency":[{"value":"micromolar (agonists vs IL-36R ectodomain)","assay":"surface plasmon resonance / direct binding","system":"recombinant human","cite":"PMID:29180446"}],"species_and_systems":"Human recombinant and human cells [PMID:29180446][PMID:14734551].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"All abstract-only. The ternary-complex experiment used IL-36alpha. The 74 uM figure is a predicted IL-36R/IL-1RAcP affinity, not ligand binding [PMID:29180446].","key_references":[{"PMID":"29180446","why":"Binding analysis of IL-36 agonists and receptors"},{"PMID":"14734551","why":"IL-1Rrp2-dependent NF-kappaB activation"},{"PMID":"11466363","why":"IL-1epsilon signals via IL-1Rrp2"}],"covers":["LR002805","LR006047"]},"LR000915":{"pair":"IL5 -> CSF2RB","headline":"CSF2RB (common beta chain) is the shared signalling subunit of the IL5 receptor; support is indirect via the receptor description and database records.","interaction_type":"functional only","direction_and_effect":"Agonistic ligation of the alpha and common beta subunits triggers proteasomal degradation of the betac cytoplasmic domain, ending signalling [PMID:11748263]. GtoPdb lists IL5 as agonist at CSF2RB [DB:GtoPdb].","molecular_requirements":"IL5 signals through IL5RA plus CSF2RB [DB:UniProt]; a cryo-EM structure of the IL-5 signalling complex exists [DB:PDB 8TLD]. Reactome lists IL5RA:betac:JAK2 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cell system and species not reported for the experiment row; abstract-level only [PMID:11748263].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Only one paper is shown, abstract-only, and it concerns IL-5, IL-3 and GM-CSF receptors together rather than IL5-CSF2RB binding. Betac does not bind IL5 on its own in our evidence; the alpha chain is needed [DB:UniProt]. Affinity not reported.","key_references":[{"PMID":"11748263","why":"Ligand-induced betac degradation in IL-5/IL-3/GM-CSF receptors"}],"covers":["LR000915","LR004343"]},"LR004344":{"pair":"IL5 -> IL5RA","headline":"IL5 binds IL5RA directly with nM to sub-nM affinity; well supported by binding and structure data.","interaction_type":"direct binding","direction_and_effect":"IL5 is an agonist at IL5RA [DB:GtoPdb]. The human alpha chain binds IL-5 with high affinity by itself [PMID:1732409]; hIL5 forms a 1:1 complex with soluble receptor alpha [PMID:7721873].","molecular_requirements":"IL5RA alone suffices for binding in human COS7 cells [PMID:1732409]; signalling uses IL5RA with the common beta chain CSF2RB [DB:UniProt]. Binding determinants lie in FnIII domains 1-3 [PMID:10880230].","affinity_potency":[{"value":"Kd 250-590 pM","assay":"IL-5 binding","system":"COS7 cells transfected with human IL-5 receptor cDNA","cite":"PMID:1732409"},{"value":"Kd 3.1 nM","assay":"titration microcalorimetry","system":"human IL5 with soluble IL5R alpha, Drosophila-expressed","cite":"PMID:7721873"},{"value":"Kd 2.0 nM","assay":"titration microcalorimetry","system":"shIL5R alpha-Fc chimera","cite":"PMID:7721873"}],"species_and_systems":"Human proteins; the mouse alpha chain binds IL-5 with low affinity (Kd approximately 10 nM) [PMID:1732409]; ovine IL-5 activates human but not mouse alpha [PMID:10880230].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Abstracts only. Mouse pair is listed directly, but no mouse-specific binding data are shown beyond the low-affinity statement.","key_references":[{"PMID":"7721873","why":"Calorimetry and structure, Kd 3.1 nM"},{"PMID":"1732409","why":"Cloning and high-affinity binding"},{"PMID":"10880230","why":"Epitope mapping by chimeras"}],"covers":["LR000916","LR004344"]},"LR007332":{"pair":"IL9 -> IL2RG:IL9R","headline":"IL9 acts on the IL2RG:IL9R complex; functional evidence with residue-level requirements in both chains.","interaction_type":"functional only","direction_and_effect":"IL-9 signals through IL-9Ralpha plus gammac, using JAK1 and JAK3 for STAT activation [PMID:9535918]. GtoPdb: agonist for both [DB:GtoPdb].","molecular_requirements":"Both chains are required: IL-9Ralpha Tyr336 and the membrane-proximal segment of gammac [PMID:9535918]. Score as complex by the weaker subunit.","affinity_potency":[],"species_and_systems":"Human; mast cell and T cell lines [PMID:9535918].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"One paper, abstract only; functional, no binding constants. Two other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"9535918","why":"Heteromerization of gammac with IL-9Ralpha, STAT activation"}],"covers":["LR007332"]},"LR011193":{"pair":"INHA -> ACVR1C","headline":"INHA to ACVR1C: GtoPdb assertion only; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA-ACVR1C as agonist [DB:GtoPdb]; modulatory effect stimulatory by annotation only.","molecular_requirements":"A type I receptor alone; a type II receptor is not evidenced here in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Secreted ligand [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Two papers were abstract_insufficient. Type I activin receptors usually need a type II partner, but that is not stated in this dossier.","key_references":[],"covers":["LR011193"]},"LR004353":{"pair":"INHA -> TGFBR3","headline":"Betaglycan binds inhibin and mediates antagonism of activin signalling; two abstract-level direct-binding confirmations.","interaction_type":"direct binding","direction_and_effect":"Betaglycan binds inhibin and can mediate functional antagonism of activin signalling [PMID:10746731]; with betaglycan, inhibin competes with activin for type II activin receptors and prevents activin signalling [PMID:12493742]. Effect is inhibitory (antagonist) per annotation.","molecular_requirements":"Betaglycan is the co-receptor; inhibin then competes at type II receptors [PMID:12493742]. Reactome has an inhibin-A:TGFBR3:ACVR2A complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species and cell system not reported in our evidence; abstracts only. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; betaglycan acts as membrane co-receptor.","caveats":"Both reads are abstract-level. One further paper was abstract_insufficient.","key_references":[{"PMID":"10746731","why":"Betaglycan binds inhibin, antagonizes activin"},{"PMID":"12493742","why":"Inhibin and betaglycan compete with activin at type II receptors"}],"covers":["LR000930","LR004353"]},"LR000933":{"pair":"INHBA -> ACVR2A","headline":"Activin A binds ACVR2A directly, with a crystal structure; five verified papers.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of ACVR2A with activin A; ACVR2A high-affinity growth factors are activin A, activin B and GDF11 [PMID:35643319]. Type II but not type I activin receptor binds activin when expressed alone, and activin induces type I-type II heteromer formation [PMID:9032295]. Agonist; signals through ActRIIA plus ALK4 [PMID:15196700].","molecular_requirements":"ACVR2A binds activin A; a type I receptor is required for signalling [PMID:9032295]. Binding uses a conserved hydrophobic hot spot [PMID:35643319].","affinity_potency":[],"species_and_systems":"Human proteins (structure, K562 cells) [PMID:35643319][PMID:9032295]; mouse reconstitution [PMID:15196700]; mouse pair projected.","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"Verified papers were read as abstract only (35643319 has full-text excerpts). Affinity values are not in our evidence. Three further papers were abstract_insufficient.","key_references":[{"PMID":"35643319","why":"ACVR2A-activin A crystal structure."},{"PMID":"9032295","why":"Type II receptor binds activin; type I needed for signalling."},{"PMID":"15196700","why":"ActRIIA plus ALK4 signalling in reconstitution."}],"covers":["LR000933","LR004356"]},"LR007260":{"pair":"INHBA:INHBB -> ACVR1B:ACVR2A","headline":"Activin A/B ligand complex to ACVR1B:ACVR2A; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists each activin subunit with each receptor chain as agonist interactions [DB:GtoPdb]. Reactome describes activin A, AB and B binding an ACVR2A,B:ACVR1B receptor [DB:Reactome].","molecular_requirements":"BioGRID records ACVR2A with INHBA and INHBB [PMID:9202237] [PMID:10746731]; a structure shows activin A with ACVR2A ligand-binding domain [DB:PDB 7U5P]. UniProt says ACVR2A interacts with activin A [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"No paper-level evidence is held for this pair (only review-only or abstract-insufficient rows), so it rests on database records alone.","key_references":[],"covers":["LR007260"]},"LR004362":{"pair":"INHBB -> ACVR1C","headline":"Activin B signals through ACVR1C (ALK7) in a reconstitution system; one abstract-level paper; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Activin B and activin AB were identified as ALK7 ligands, acting as agonists; ActRIIA with ALK7 is preferred by activin B and activin AB but not activin A [PMID:15196700]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"ActRIIA plus ALK7 combination carries the insulin-secretion response [PMID:15196700]; ALK7 alone as sufficient is not reported.","affinity_potency":[],"species_and_systems":"Experiments used mouse ligand and receptor in receptor reconstitution; the human pair is projected from this [PMID:15196700].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only [PMID:15196700]; no affinity reported. The paper's own notes say the dimer (activin B) is the correct entity.","key_references":[{"PMID":"15196700","why":"Shows activin AB and B are ALK7 ligands"}],"covers":["LR000939","LR004362"]},"LR002814":{"pair":"INHBB -> TGFBR3L","headline":"TGFBR3L is a gonadotrope co-receptor for inhibin B, binding it but not other TGFbeta family ligands; abstract plus excerpts, human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"TGFBR3L binds inhibin B but not other TGFbeta family ligands; knockdown abrogates and overexpression confers inhibin B activity in cells [PMID:34910520].","molecular_requirements":"Acts as a co-receptor; betaglycan is separately required for inhibin A. Double knockout of Tgfbr3l and betaglycan in mice gave infertility [PMID:34910520].","affinity_potency":[],"species_and_systems":"Mouse knockouts and pituitary data; curator species fields are blank. Human TGFBR3L expressed in heterologous cells initially lacked a signal peptide and did not reach the membrane [PMID:34910520].","localisation_and_range":"Abstract calls TGFBR3L a gonadotrope-restricted transmembrane protein [PMID:34910520]; ligand flagged secreted [flag].","caveats":"No affinity reported; human pair is projected from mouse. Ligand is inhibin B, so the INHA partner is implied rather than listed.","key_references":[{"PMID":"34910520","why":"Identifies TGFBR3L as inhibin B co-receptor"}],"covers":["LR002814","LR006054"]},"LR006054":{"pair":"INHBB -> TGFBR3L","headline":"TGFBR3L is a gonadotrope co-receptor for inhibin B, binding it but not other TGFbeta family ligands; abstract plus excerpts, human pair ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"TGFBR3L binds inhibin B but not other TGFbeta family ligands; knockdown abrogates and overexpression confers inhibin B activity in cells [PMID:34910520].","molecular_requirements":"Acts as a co-receptor; betaglycan is separately required for inhibin A. Double knockout of Tgfbr3l and betaglycan in mice gave infertility [PMID:34910520].","affinity_potency":[],"species_and_systems":"Mouse knockouts and pituitary data; curator species fields are blank. Human TGFBR3L expressed in heterologous cells initially lacked a signal peptide and did not reach the membrane [PMID:34910520].","localisation_and_range":"Abstract calls TGFBR3L a gonadotrope-restricted transmembrane protein [PMID:34910520]; ligand flagged secreted [flag].","caveats":"No affinity reported; human pair is projected from mouse. Ligand is inhibin B, so the INHA partner is implied rather than listed.","key_references":[{"PMID":"34910520","why":"Identifies TGFBR3L as inhibin B co-receptor"}],"covers":["LR002814","LR006054"]},"LR000942":{"pair":"INHBC -> ACVR2A","headline":"Activin C reported to bind ACVR2A and antagonise activin A signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Activin-C acts as an activin-A antagonist by binding activin receptor subunits IIA and IIB and modulating canonical Smad signalling [PMID:25180271]. The database-style effect label is Stimulatory, which differs from this antagonist reading.","molecular_requirements":"Type II receptor subunit binding only; a type I partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human granulosa cell line and human gonadal/adrenal cancer tissue [PMID:25180271]. Mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Single paper, read as abstract only; binding method not stated in the abstract. Two confirmed rows are counted but one paper is shown; one other row was review-only and one abstract-insufficient.","key_references":[{"PMID":"25180271","why":"Activin-C binds ActRIIA/IIB and antagonises activin A in human gonadal/adrenal cancer settings"}],"covers":["LR000942","LR004365"]},"LR000951":{"pair":"INS -> LRP2","headline":"Megalin (LRP2) binds and internalises insulin in renal tissue; endocytic clearance receptor, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"An insulin binding site in renal microvillar membranes was found by chemical cross-linking and identified as megalin by immunoprecipitation; megalin internalised insulin into endocytic vesicles [PMID:9773776].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Renal microvillar membranes and proximal tubule cells; species of the experiments is not stated in the abstract [PMID:9773776]. The human pair is projected from other evidence (ortholog inferred).","localisation_and_range":"Megalin is abundant in clathrin-coated pits on the apical surface of proximal tubule cells [PMID:9773776]. Ligand is flagged secreted [flag].","caveats":"Megalin also bound several other low molecular weight polypeptides in ligand blotting, so binding is not specific to insulin. Abstract only; no affinity.","key_references":[{"PMID":"9773776","why":"Cross-linking, immunoprecipitation and internalisation identify megalin as an insulin receptor"}],"covers":["LR000951"]},"LR004371":{"pair":"INSL5 -> RXFP4","headline":"INSL5 is the cognate nanomolar agonist of RXFP4, supported by binding, signalling and structure-function papers.","interaction_type":"direct binding","direction_and_effect":"Human INSL5 displaces 125I-relaxin-3 from the receptor, binds in saturation assays and activates GTPgammaS and cAMP responses [PMID:15525639]. In NCI-H716 cells endogenously expressing RXFP4, INSL5 induced ERK1/2 phosphorylation and inhibited cAMP production [PMID:29535183]. Relaxin-3 also acts on RXFP4 with similar signalling [PMID:27888281]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"RXFP4 residues Glu100, Asp104 and Glu182 and INSL5 B13Arg and B23Arg are important for activation [PMID:25043977]. RXFP4 transmembrane domains 2, 3 and 5 are critical for activation by INSL5 [PMID:18582868].","affinity_potency":[{"value":"Ki 1.5 nM","assay":"125I-relaxin-3 displacement","system":"GPCR142 (RXFP4)","cite":"PMID:15525639"},{"value":"Kd 2.5 nM","assay":"125I-INSL5 saturation binding","system":"GPCR142 (RXFP4)","cite":"PMID:15525639"},{"value":"EC50 1.3 nM and 1.2 nM","assay":"GTPgammaS and cAMP assays","system":"GPCR142 (RXFP4)","cite":"PMID:15525639"},{"value":"4.57 nM","assay":"potency of native hINSL5","system":"human RXFP4","cite":"PMID:26824523"}],"species_and_systems":"Mostly recombinant human receptor in cell lines; human enteroendocrine L-cell line NCI-H716 for native expression [PMID:29535183]. Mouse pair is ortholog-inferred; mouse data are mRNA expression only [PMID:29535183].","localisation_and_range":"Ligand is flagged secreted [flag]. INSL5 is expressed in colonic enteroendocrine L-cells [PMID:29535183].","caveats":"All shown papers are abstract only. Ten confirmed rows exist, eight shown; seven rows are pending. Relaxin-3 is also an agonist, so ligand selectivity is not exclusive.","key_references":[{"PMID":"15525639","why":"Binding and activation of RXFP4 (GPCR142) by INSL5"},{"PMID":"29535183","why":"INSL5 signalling in a human L-cell line"},{"PMID":"25043977","why":"Electrostatic INSL5-RXFP4 residue mapping"}],"covers":["LR000948","LR004371"]},"LR002823":{"pair":"ITGA5 -> ADGRE5","headline":"Integrin alpha5beta1 binds CD97 (ADGRE5) in HUVEC assays; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Soluble CD97 drives integrin-dependent HUVEC migration and invasion, and CD97alpha promotes angiogenesis in vivo [PMID:15576472]. Alpha5beta1 is described as a high-affinity counterreceptor for CD97 [PMID:15576472].","molecular_requirements":"Alpha5beta1 together with chondroitin sulfate proteoglycan synergistically promotes endothelial invasion; alphaVbeta3 also contributes to attachment [PMID:15576472].","affinity_potency":[],"species_and_systems":"Human cells (HUVEC) and an in vivo angiogenesis assay [PMID:15576472]. The mouse pair is projected by orthology.","localisation_and_range":"Soluble CD97 extracellular domain acts as chemoattractant [PMID:15576472]; ADGRE5 is flagged secreted and transmembrane [flag].","caveats":"Abstract only. The ITGA5 entity is a single chain labelled alpha5beta1. No affinity values. The assay_class direct_binding rests on the abstract wording 'strong interactions'.","key_references":[{"PMID":"15576472","why":"CD97 binds alpha5beta1 and drives endothelial invasion"}],"covers":["LR002823","LR006062"]},"LR006063":{"pair":"ITGAX -> AGER","headline":"Mac-1 and, less so, p150,95 (ITGAX) interact with RAGE; abstract-level direct binding plus mouse knockouts.","interaction_type":"direct binding","direction_and_effect":"RAGE-dependent leukocyte adhesion involved a direct interaction with Mac-1 and to a lower extent p150,95, not LFA-1 or beta1-integrins [PMID:14623906]. RAGE-deficient mice had impaired leukocyte recruitment [PMID:14623906].","molecular_requirements":"The evidence for ITGAX is as p150,95 (alphaXbeta2), a weaker partner than Mac-1 [PMID:14623906].","affinity_potency":[],"species_and_systems":"Mouse peritonitis models with human-integrin binding assays on transfected cells [PMID:14623906]; the mouse pair is orthology-projected.","localisation_and_range":"Membrane receptors acting in cell adhesion [PMID:14623906].","caveats":"Abstract read; the p150,95 interaction is secondary to Mac-1. No affinity values.","key_references":[{"PMID":"14623906","why":"RAGE interacts directly with Mac-1 and p150,95"}],"covers":["LR002825","LR006063"]},"LR004380":{"pair":"JAG2 -> NOTCH2","headline":"Jagged2 binds and activates Notch2 in mouse BaF3 cells; limited human evidence.","interaction_type":"direct binding","direction_and_effect":"Jagged2 bound endogenous Notch2 on BaF3 cells, with binding characteristics differing from Delta1 and Jagged1, and induced cleavage, nuclear translocation and reporter activation (agonist) [PMID:10958687]. In human cell assays, MFNG inhibited NOTCH2 activation by JAG1 and JAG2 [PMID:32820046].","molecular_requirements":"Fringe enzymes modulate NOTCH2 activation [PMID:32820046].","affinity_potency":[],"species_and_systems":"Mouse cell system [PMID:10958687]; human cell-based assay [PMID:32820046]. Human pair is ortholog-inferred.","localisation_and_range":"JAG2 flagged as not secreted [flag].","caveats":"Both papers abstract-only. The Fringe paper shows an inhibitory modulation, not a direct measure of JAG2 alone. BioGRID and Reactome records add support [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"10958687","why":"Binding and signalling in BaF3 cells"},{"PMID":"32820046","why":"Fringe modulation in human cells"}],"covers":["LR000957","LR004380"]},"LR002832":{"pair":"JAM2 -> ITGA4","headline":"JAM2 engages integrin alpha4beta1 in T cells in adhesion assays, conditional on JAM3; chain-level record.","interaction_type":"functional only","direction_and_effect":"Neutralizing integrin antibodies defined a JAM2-alpha4beta1 interaction in T cells, attenuated by the alpha4-specific inhibitor TBC 772 [PMID:12070135]. Reactome records the binding [DB:Reactome].","molecular_requirements":"alpha4 pairs with beta1; engagement was enabled only after prior JAM2-JAM3 adhesion and was undetectable where JAM3 was absent [PMID:12070135]. The first Ig-like fold of JAM2 binds both [PMID:12070135].","affinity_potency":[],"species_and_systems":"Human T-cell line adhesion assays [PMID:12070135].","localisation_and_range":"JAM2 flagged as not secreted [flag]; membrane adhesion.","caveats":"Evidence is for the alpha4beta1 heterodimer, not alpha4 alone. Abstract-only; antibody and inhibitor based, no direct binding.","key_references":[{"PMID":"12070135","why":"JAM2-alpha4beta1 in T cells"}],"covers":["LR002832","LR006069"]},"LR006072":{"pair":"JAM3 -> ITGB2","headline":"JAM3 binds beta2-integrin Mac-1 directly in human systems, but evidence is for the Mac-1 heterodimer rather than ITGB2 alone.","interaction_type":"direct binding","direction_and_effect":"JAM-3 is a counterreceptor for Mac-1: JAM-3 directly bound purified Mac-1 in a saturable, dose-dependent way inhibited by anti-Mac-1 or anti-JAM-3 antibody, and purified JAM-3 inhibited neutrophil binding to adherent platelets [PMID:12208882]. JAM-C availability also regulates alphaMbeta2-dependent leukocyte adhesion [PMID:16093349].","molecular_requirements":"Evidence is for the Mac-1 heterodimer (alphaMbeta2); ITGB2 inherits it at complex level. Adhesion was blocked by anti-beta2 antibody; binding was strong for Mac-1, weaker for p150.95 and absent for LFA-1, which shares the beta2 chain, so beta2 alone is not sufficient [PMID:12208882].","affinity_potency":[],"species_and_systems":"Human platelets, U937 and K562 cells, CHO transfectants, purified proteins [PMID:12208882]; species not specified in the second paper [PMID:16093349]. Dossier includes human and mouse entries; experiments shown are human.","localisation_and_range":"JAM-3 is a type I transmembrane glycoprotein [PMID:12208882], so signalling is contact-dependent (juxtacrine); the entity flags also mark JAM3 as secreted [flag], which the papers do not support.","caveats":"Evidence is complex-level; the specificity panel shows LFA-1 (also beta2) does not bind, so ITGB2 is not the determining chain [PMID:12208882]. Second paper read as abstract only [PMID:16093349]. No affinity reported.","key_references":[{"PMID":"12208882","why":"Direct Mac-1 binding with integrin specificity panel"},{"PMID":"16093349","why":"JAM-C and alphaMbeta2-dependent leukocyte adhesion"}],"covers":["LR002835","LR006072"]},"LR000960":{"pair":"KISS1 -> KISS1R","headline":"Kisspeptin is a well-supported agonist of KISS1R (GPR54), with nanomolar binding and many functional papers plus structures.","interaction_type":"direct binding","direction_and_effect":"Kisspeptins (KISS1 products) are full agonists of KISS1R/GPR54, stimulating PIP2 hydrolysis, Ca2+ mobilisation, ERK1/2 and p38 phosphorylation and stress fibre formation [PMID:11457843]; metastin was isolated as the endogenous ligand of the orphan receptor [PMID:11385580]. In mice, kisspeptin stimulates GnRH release through GPR54 [PMID:15665093]. MMP cleavage of metastin decapeptide abolished its ligand activity [PMID:12879005].","molecular_requirements":"Processed peptides act: 54-, 14- and 13-residue peptides with an RF-amide C terminus [PMID:11457843]; the decapeptide is active until cleaved at Gly118-Leu119 [PMID:12879005]. Single receptor chain.","affinity_potency":[{"value":"pKi 8.6-10.4","assay":"GtoPdb curated interaction, full agonist","system":"as recorded in GtoPdb","cite":"PMID:11385580"}],"species_and_systems":"Human kisspeptins on rat and human GPR54 in CHO-K1 cells [PMID:11457843]; hOT7T175-transfected CHO cells [PMID:11385580]; mouse hypothalamus and gpr54-/- mice, sheep [PMID:15665093]. Human and mouse entries are not ortholog-inferred. PDB structures 8XGS and 8ZJD show a Q15726 chain with a Q969F8 chain [DB:PDB 8XGS].","localisation_and_range":"KISS1 products are secreted peptides (secreted flag [flag]), acting on cells expressing KISS1R, paracrine or endocrine; the receptor is a GPCR.","caveats":"Most papers were read as abstracts. Kisspeptin-10 also activates NPFFR1 and NPFFR2, so cross-reactivity exists [PMID:24900254]. One paper was judged on a pending row.","key_references":[{"PMID":"11457843","why":"Kisspeptin isolation, low nanomolar binding to GPR54 and signalling"},{"PMID":"11385580","why":"Metastin as endogenous ligand of hOT7T175"},{"PMID":"15665093","why":"Kisspeptin acts through GPR54 on GnRH release in mice"}],"covers":["LR000960","LR004382"]},"LR012426":{"pair":"KLB -> FGFR3","headline":"Supported only by BioGRID and a UniProt subunit statement; no curated paper confirmation.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond the curated Stimulatory annotation [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID records affinity capture-western [DB:BioGRID]; UniProt states FGFR3 interacts with KLB [DB:UniProt]. Species and system are not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Three papers are still pending and none confirmed, so this rests on database records only.","key_references":[],"covers":["LR012426"]},"LR002841":{"pair":"KLRG1 -> CDH1","headline":"KLRG1 binds E-cadherin and inhibits NK cytotoxicity; direct binding in mouse and human, plus a structure.","interaction_type":"direct binding","direction_and_effect":"KLRG1 is an inhibitory receptor; E-cadherin binding of KLRG1 prevented lysis of E-cadherin-expressing targets by KLRG1+ NK cells [PMID:16461340]. KLRG1 engagement inhibited cadherin-dependent adhesion and influenced dendritic cell cytokine secretion, and induced cadherin tyrosine phosphorylation, so signalling goes both ways [PMID:19855082].","molecular_requirements":"The first two extracellular domains of cadherin are sufficient to initiate KLRG1-dependent signalling [PMID:19855082].","affinity_potency":[],"species_and_systems":"Mouse KLRG1 tetramer expression cloning identified human E-cadherin as a xenogeneic ligand, and mouse E-cadherin as a syngeneic ligand, in BW5147 cells and reporter cells [PMID:16461340]. The human pair is ortholog-inferred and the mouse pair is direct [flag]. Species of the second paper are not reported in the abstract [PMID:19855082]. PDB 3FF7 and Reactome list the complex [DB:PDB 3FF7][DB:Reactome].","localisation_and_range":"Both are membrane proteins [flag]; interaction is by cell contact.","caveats":"No affinity in our evidence. The first paper is read in part from full text, the second as an abstract only. Binding was shown with a mouse probe, so the human-human interaction is inferred.","key_references":[{"PMID":"16461340","why":"Expression cloning of E-cadherin as KLRG1 ligand"},{"PMID":"19855082","why":"Bidirectional KLRG1-cadherin signalling"}],"covers":["LR002841","LR006076"]},"LR010680":{"pair":"KRTAP4-12 -> PLSCR4","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR010680"]},"LR006081":{"pair":"L1CAM -> ITGA9","headline":"Co-IP and colocalisation suggest alpha9beta1 associates with L1 in melanoma cells; alpha9 not directly detected.","interaction_type":"functional only","direction_and_effect":"alpha9beta1 colocalized with L1 and beta1 coprecipitated with L1 in human M21 melanoma cells at cell-cell contact [PMID:10871287].","molecular_requirements":"The alpha9 subunit could not be detected by Western blot, so beta1 coprecipitation is only likely due to alpha9 [PMID:10871287]. The partner is alpha9beta1; ITGB1 required.","affinity_potency":[],"species_and_systems":"Human M21 and M21-L melanoma cells; mouse pair is ortholog-inferred [PMID:10871287].","localisation_and_range":"Colocalised at cell-cell contact sites [PMID:10871287].","caveats":"Authors state they cannot definitively claim alpha9beta1 coprecipitation; association not direct binding evidence.","key_references":[{"PMID":"10871287","why":"Colocalisation and co-IP of alpha9beta1 with L1"}],"covers":["LR002846","LR006081"]},"LR008214":{"pair":"L1CAM -> ITGAV:ITGB1","headline":"One abstract-level paper shows alphavbeta1 binding L1-Ig6 and supporting HUVEC adhesion.","interaction_type":"direct binding","direction_and_effect":"alphavbeta1 interaction with L1-Ig6 supported adhesion of umbilical vein endothelial cells [PMID:9396761].","molecular_requirements":"RGD-dependent; binding observed only with Mn2+ and inhibited by Ca2+ [PMID:9396761]. Needs both chains.","affinity_potency":[],"species_and_systems":"Human L1-Ig6, HUVEC [PMID:9396761].","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Single paper, abstract-level; two other papers judged abstract_insufficient; ranks below alphavbeta3 in the stated hierarchy.","key_references":[{"PMID":"9396761","why":"alphavbeta1 binds L1-Ig6"}],"covers":["LR008214"]},"LR002850":{"pair":"L1CAM -> NRP1","headline":"Specific trans binding of L1 to neuropilin-1 mapped to L1 Ig domain 1; one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"L1 binds NP-1 in trans, not L1 or other Ig CAMs, converting Sema3A-induced repulsion to attraction and activating the NO/cGMP pathway [PMID:12456642]. Soluble L1 acts as a modulator of the Sema3A receptor.","molecular_requirements":"Binding site is a restricted sequence of L1 Ig domain 1; a pathological L1 missense mutation disrupts L1-NP-1 complex formation and Sema3A reversion [PMID:12456642]. Reactome lists L1:NRP1 and a binding reaction [DB:Reactome R-HSA-374580]; BioGRID lists Reconstituted Complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Axon guidance assays with L1 constructs; species not reported in our evidence [PMID:12456642]. Mouse pair is ortholog-inferred.","localisation_and_range":"Trans binding at the membrane; soluble L1 also acts [PMID:12456642]; L1CAM flagged secreted [flag].","caveats":"Abstract only; no affinity values.","key_references":[{"PMID":"12456642","why":"Trans binding of L1 to NP-1 and site mapping"}],"covers":["LR002850","LR006085"]},"LR005217":{"pair":"LAMA2 -> DAG1","headline":"Crystal structure shows laminin alpha2 LG4-LG5 bound to the glycan on alpha-dystroglycan; abstract-only, plus database records.","interaction_type":"direct binding","direction_and_effect":"The structure of laminin-alpha2 LG4-LG5 bound to a LARGE-synthesized oligosaccharide reveals the matrix-binding interaction [PMID:27526028]. UniProt calls DAG1 a receptor for laminin-2 (LAMA2) in Schwann cells (by similarity) [DB:UniProt Q14118]. Labelled Stimulatory [flag].","molecular_requirements":"Binding needs the LARGE-synthesized matrix-binding heteropolysaccharide on alpha-DG [PMID:27526028]; the LG4-LG5 domains of laminin-alpha2 are the contact [PMID:27526028].","affinity_potency":[],"species_and_systems":"Crystal structure with an oligosaccharide, not full-length DAG1 [PMID:27526028]. BioGRID lists a reconstituted complex [DB:BioGRID 306204]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor flagged transmembrane and secreted [flag]; matrix ligand.","caveats":"Abstract only; the structure uses a glycan fragment. UniProt support is by similarity.","key_references":[{"PMID":"27526028","why":"Crystal structure of laminin LG4-LG5 with the DAG1 glycan"}],"covers":["LR001875","LR005217"]},"LR004407":{"pair":"LAMA2 -> ITGB4","headline":"Alpha6beta4 reported as a receptor for laminin 2 in radioligand and adhesion assays; abstract-only, trimer-level.","interaction_type":"direct binding","direction_and_effect":"Cell adhesion and radioligand-binding assays showed alpha6beta4 is a receptor for several laminin isoforms including laminin 2 [PMID:7721947]. Labelled Stimulatory [flag].","molecular_requirements":"The receptor is the alpha6beta4 heterodimer; beta4 mutants lacking either domain did not suppress adhesion to laminins [PMID:7721947].","affinity_potency":[],"species_and_systems":"804G bladder epithelial cells (the curator infers rat), laminin origin unstated [PMID:7721947]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Abstract only; species ambiguous; laminin 2 is a trimer, so LAMA2 alone is not isolated. One review-only row not shown. No affinity reported.","key_references":[{"PMID":"7721947","why":"Alpha6beta4 is a receptor for laminin 2"}],"covers":["LR000987","LR004407"]},"LR006090":{"pair":"LAMA3 -> ITGB1","headline":"Laminin-332 (with LAMA3) binds recombinant integrin alpha3beta1 directly, and keratinocyte adhesion depends on alpha3beta1; assembled-trimer evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-332 bound recombinant alpha3beta1 in solid-phase binding [PMID:16413178]. Keratinocyte adhesion to immunopurified epiligrin was inhibited by an anti-alpha3beta1 antibody, and epiligrin induced alpha3beta1 localisation in focal adhesions, consistent with an adhesion (stimulatory) ligand [PMID:2032285]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Receptor tested is the alpha3beta1 heterodimer, so ITGB1 alone is not shown to suffice. Ligand is the laminin-332/epiligrin trimer, not LAMA3 alone [PMID:16413178][PMID:2032285].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding, laminin-332 vs recombinant alpha3beta1","system":"human recombinant","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins and human foreskin keratinocytes [PMID:16413178][PMID:2032285].","localisation_and_range":"LAMA3 flagged secreted, not transmembrane [flag]; epiligrin is described as a basement-membrane glycoprotein [PMID:2032285].","caveats":"The 2032285 result was read from the abstract only and is antibody-blocking adhesion, not binding. A Reactome record describes alpha2beta1 binding laminin-332, not this receptor [DB:Reactome]. Three papers were abstract-insufficient.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-332"},{"PMID":"2032285","why":"Adhesion to epiligrin blocked by anti-alpha3beta1"}],"covers":["LR002856","LR006090"]},"LR011391":{"pair":"LAMA4 -> ITGA7:ITGB1","headline":"Only LAMA4-ITGB1 co-localisation in mouse brain; alpha7 not examined.","interaction_type":"functional only","direction_and_effect":"LAMA4 and ITGB1 overlapped by immunofluorescence in E14.5 mouse brain, reported as experimental confirmation [PMID:31677479].","molecular_requirements":"Only ITGB1 was tested; ITGA7 is not mentioned [PMID:31677479].","affinity_potency":[],"species_and_systems":"Mouse E14.5 brain [PMID:31677479].","localisation_and_range":"LAMA4 flagged secreted; complex flagged transmembrane [flag].","caveats":"Co-localisation is not binding; alpha7 subunit unsupported. Three papers were abstract-insufficient.","key_references":[{"PMID":"31677479","why":"LAMA4-ITGB1 overlap"}],"covers":["LR011391"]},"LR004416":{"pair":"LAMA5 -> ITGB1","headline":"Laminin alpha5 (as laminin-511/521, -10/11) engages integrin beta1 pairings, shown by binding and antibody blockade; chain-level only.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha3beta1 [PMID:16413178]; laminin-10/11 is a high-affinity alpha3beta1 ligand [PMID:15677332]. Anti-beta1 antibodies blocked adhesion of mouse FDCP-mix cells to alpha5-laminins [PMID:10194432] and of A549 cells to laminin-10/11 [PMID:9624186]. Annotated stimulatory.","molecular_requirements":"ITGB1 acts in alpha/beta heterodimers (alpha3beta1 and alpha6beta1 in these papers); the alpha partner determines specificity and ITGB1 alone was not tested [PMID:16413178][PMID:10194432]. Laminin is the assembled heterotrimer.","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha3beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins and human A549 cells [PMID:16413178][PMID:9624186]; mouse cells [PMID:10194432]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The Kd belongs to the alpha3beta1 heterodimer, not ITGB1 alone. Three of the four confirming papers are abstract-only reads, two being antibody-blocking adhesion assays.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"},{"PMID":"15677332","why":"Laminin-10/11 high-affinity alpha3beta1 ligand"},{"PMID":"9624186","why":"Anti-beta1/alpha3 blocked adhesion to laminin-10/11"}],"covers":["LR000997","LR004416"]},"LR011382":{"pair":"LAMB2 -> ITGA3:ITGB1","headline":"Complex row for laminin beta2 and integrin alpha3beta1; only a PDB record, no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P11047 and a chain of P05556 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA3:ITGB1 heterodimer per the entity record; the PDB chains listed do not include ITGA3 [DB:PDB 7CEC].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB2 is flagged secreted [flag] and ITGA3:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"No papers judged (three abstract_insufficient). Support is one structure record.","key_references":[],"covers":["LR011382"]},"LR004425":{"pair":"LAMB3 -> ITGB1","headline":"LAMB3 (in laminin-332) binds integrin beta1-containing alpha3beta1 at Kd 14 nM; chain-level mapping of an assembled-laminin result.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha3beta1 in solid-phase assays [PMID:16413178]. Annotated effect is Stimulatory [flag]. Reactome records integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"Binder tested is an alpha-beta1 heterodimer (alpha3beta1 for this value); ITGB1 alone was not tested, and the ligand is the whole heterotrimer [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain and with an alpha-beta heterodimer. Three further papers were abstract_insufficient.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-332"}],"covers":["LR001007","LR004425"]},"LR011373":{"pair":"LAMC1 -> ITGA2:ITGB1","headline":"LAMC1 with ITGA2:ITGB1 has only a PDB record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P05556 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Four papers were abstract_insufficient and two different_entity. The PDB entry lists no ITGA2 chain.","key_references":[],"covers":["LR011373"]},"LR004434":{"pair":"LAMC2 -> ITGB1","headline":"Recombinant alpha3beta1 binds laminin-332 (contains LAMC2) with Kd 14 nM; ITGB1 is shared by the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3beta1 bound laminin-332 in solid-phase assays [PMID:16413178]. Recorded effect: stimulatory [flag]. Reactome also lists alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"Binding was by integrin heterodimers and the assembled laminin-332 heterotrimer; beta1 alone and LAMC2 alone were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha3beta1","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted; ITGB1 flagged not secreted [flag].","caveats":"Chain-level assignment inferred from complex-level binding; the Kd belongs to alpha3beta1.","key_references":[{"PMID":"16413178","why":"Recombinant integrin binding to laminin-332"}],"covers":["LR001016","LR004434"]},"LR006108":{"pair":"LCN2 -> SLC22A17","headline":"NGAL binds the SLC22A17 N-terminal domain weakly (about 10 uM) as a fuzzy complex; Reactome lists the full complex.","interaction_type":"direct binding","direction_and_effect":"The disordered N-terminal domain of LCN2-R interacts with NGAL preferentially in its apo state to form a fuzzy complex; the affinity is relatively weak (about 10 uM) so the N terminus alone cannot account for NGAL internalization [PMID:26635366]. Reactome lists SLC22A17:LCN2 complexes with 2,5DHBA and Fe3+ [DB:Reactome R-HSA-5246491].","molecular_requirements":"Other receptor domains are implied beyond the N-terminal domain; the N-terminus may fine-tune or help discriminate apo- from holo-NGAL [PMID:26635366].","affinity_potency":[{"value":"Kd \u224810 \u03bcm","assay":"biophysical measurement (NMR with other methods) of human LCN2-R-NTD with apoNGAL","system":"human proteins","cite":"PMID:26635366"}],"species_and_systems":"Human LCN2-R N-terminal domain and NGAL in vitro; CHO-K1 and murine tubule cells used for topology [PMID:26635366]. Mouse pair is ortholog-projected.","localisation_and_range":"Only the N terminus is extracellular on cell surface staining [PMID:26635366]; LCN2 flagged secreted, SLC22A17 transmembrane [flag].","caveats":"The measured affinity is for the isolated domain only; the dossier lists the 10 uM value as an abstract statement, assay type given loosely. Receptor topology is uncertain between two proposed models [PMID:26635366].","key_references":[{"PMID":"26635366","why":"NMR and biophysical characterisation of NGAL with the SLC22A17 N-terminal domain"}],"covers":["LR002874","LR006108"]},"LR006117":{"pair":"LGALS3 -> ITGB1","headline":"Galectin-3 acts through ITGB1 to drive IL-10 in hepatic NK cells; functional evidence from HBV-transgenic mice, no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Galectin-3 from HBsAg+ hepatocytes induced IL-10 in hepatic conventional NK cells via ITGB1 signalling; anti-CD29 blocked the galectin-3/ITGB1 interaction on NK cells [PMID:38793619].","molecular_requirements":"Beta1 subunit (CD29) only; partner integrin alpha chains not reported in our evidence [PMID:38793619].","affinity_potency":[],"species_and_systems":"HBs-Tg and control B6 mice with cultured NK cells; human TCGA expression only correlative. BioGRID lists Affinity Capture-MS and co-localisation [DB:BioGRID][PMID:38793619].","localisation_and_range":"Galectin-3 secreted from hepatocytes acts on NK cells; ITGB1 flagged as non-secreted receptor [flag][PMID:38793619].","caveats":"No binding assay in this paper; blocking antibody against CD29 is the main test. Human and mouse pairs are ortholog-inferred or not, as annotated; the paper is mouse work.","key_references":[{"PMID":"38793619","why":"Gal-3/ITGB1 signalling drives IL-10 in hepatic cNK cells"}],"covers":["LR002883","LR006117"]},"LR006126":{"pair":"Lgals3bp -> Siglece","headline":"Mouse Siglec-E binds murine LGALS3BP, with lower affinity than the human Siglec-9 interaction; one abstract-level report.","interaction_type":"direct binding","direction_and_effect":"The mouse homolog Siglec-E binds murine LGALS3BP with lower affinity; the same paper reports LGALS3BP inhibiting neutrophil activation in a sialic acid- and Siglec-dependent manner [PMID:25320078].","molecular_requirements":"Sialic acid dependence was shown for human Siglecs; not stated for Siglec-E in our evidence [PMID:25320078].","affinity_potency":[],"species_and_systems":"Mouse pair is ortholog-inferred; the abstract names murine proteins but gives no assay system for this pair [PMID:25320078].","localisation_and_range":"LGALS3BP is a heavily glycosylated secreted molecule [PMID:25320078]; Siglece is non-secreted by flag [flag].","caveats":"Abstract only; one sentence, no affinity values, and the comparison is qualitative.","key_references":[{"PMID":"25320078","why":"States murine Siglec-E binds murine LGALS3BP with lower affinity"}],"covers":["LR006126"]},"LR002904":{"pair":"LGALS9 -> CD180","headline":"Galectin-9 binds CD180 on mouse B-1a cells and restrains TLR responses; evidence is from one paper, abstract-level.","interaction_type":"functional only","direction_and_effect":"Galectin-9 regulates BCR and TLR responses in B-1a cells by regulating the interaction of TLRs with CD180, dampening signaling; Gal9-deficient mice develop autoimmunity [PMID:34369876].","molecular_requirements":"The full text states Gal9 binds TLR4 and CD180 and dampens signal transduction by altering nano-scale co-distribution; CD180 acts as a regulatory molecule [PMID:34369876].","affinity_potency":[],"species_and_systems":"Primary mouse B-1a and B-1b cells (pull-downs with rGal9-coated beads); human pair is ortholog-inferred [PMID:34369876].","localisation_and_range":"Galectin-9 has a secreted flag [flag].","caveats":"Effect was seen in B-1a cells but not B-1b cells. Curated as functional; the pull-down details are cut off in the excerpts shown. No affinity reported.","key_references":[{"PMID":"34369876","why":"Galectin-9 restrains B-1a cell BCR and TLR responses via CD5 and CD180"}],"covers":["LR002904","LR006133"]},"LR006135":{"pair":"LGALS9 -> PTPRC","headline":"Galectin-9 reported to engage CD45 within an inhibitory IgM-BCR complex in B cells; one abstract-only paper, indirect for CD45.","interaction_type":"functional only","direction_and_effect":"Galectin-9 relocalises IgM-BCR together with inhibitory CD45 and CD22, and exogenous galectin-9 nearly completely abolishes BCR signalling; curator labels it antagonist [PMID:30120235]. Excerpts say a pull-down with recombinant galectin-9 followed by mass spectrometry was used to find binders, under a heading 'Galectin-9 binds IgM-BCR and CD45' [PMID:30120235].","molecular_requirements":"Acts alongside IgM-BCR and CD22 in the complex [PMID:30120235].","affinity_potency":[],"species_and_systems":"B cells; excerpts mention mouse strains including Lgals9 knockout, though curator labels human [PMID:30120235]. Human pair is ortholog-inferred.","localisation_and_range":"Galectin-9 flagged secreted and found on the B-cell surface; CD45 flagged transmembrane [flag][PMID:30120235].","caveats":"Same paper as the IgM row; the cited evidence sentence concerns IgM-BCR, not CD45, and the abstract only mentions CD45 as relocalised. No affinity; no database support.","key_references":[{"PMID":"30120235","why":"Galectin-9 relocalises BCR with CD45/CD22, suppressing signalling"}],"covers":["LR002908","LR006135"]},"LR005226":{"pair":"LGI1 -> ADAM22","headline":"LGI1 binds ADAM22 (cell-ELISA, brain IP-MS), with structural and interaction-database support.","interaction_type":"direct binding","direction_and_effect":"LGI1 was identified as an ADAM22-binding protein by immunoprecipitation/mass spectrometry from mouse brain, and quantitative cell-ELISA showed specific binding of LGI1 with ADAM22 [PMID:18974846]. UniProt notes a complex with ADAM22, DLG4/PSD95 and CACNG2/Stargazin [DB:UniProt]. PDB has complexes of the two chains, e.g. [DB:PDB 5Y2Z].","molecular_requirements":"ADAM22 sits in a complex with DLG4/PSD95 and CACNG2/Stargazin [DB:UniProt]; ADAM23 and ADAM11 also bind LGI1 [PMID:18974846].","affinity_potency":[],"species_and_systems":"Mouse proteins in brain and cells (curator labels human) [PMID:18974846]; structural and IntAct evidence are listed as electron microscopy and molecular sieving [DB:IntAct].","localisation_and_range":"LGI1 secreted and binds outside the cell; ADAM22 is a type I transmembrane protein [PMID:18974846].","caveats":"Abstract only for the paper; no affinity. Effect direction not reported in our evidence.","key_references":[{"PMID":"18974846","why":"LGI1 identified as ADAM22 binder; cell-ELISA"}],"covers":["LR001884","LR005226"]},"LR005235":{"pair":"LGI4 -> ADAM23","headline":"LGI4 binds ADAM23 moderately in cell-ELISA, alongside ADAM22 and ADAM11; two confirming papers.","interaction_type":"direct binding","direction_and_effect":"LGI4 significantly binds ADAM23 as well as ADAM22 and ADAM11 [PMID:18974846]. Effect on ADAM23 signalling is not reported in our evidence; the importance of ADAM23 in peripheral nerve myelination is stated as undetermined [PMID:18974846].","molecular_requirements":"No co-receptor requirement reported for ADAM23. Reactome lists an LGI4:ADAM22,11,23 complex at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cell-ELISA with mouse LGI4 and ADAMs [PMID:18974846]; dossier lists human. The human pair is ortholog-inferred.","localisation_and_range":"LGI4 is flagged secreted; ADAM23 carries both is_secreted and is_receptor flags [flag].","caveats":"Moderate interaction, weaker than ADAM22 [PMID:18974846]. The second paper is an unverified browser-read sentence [PMID:20220021]. No affinity value is reported.","key_references":[{"PMID":"18974846","why":"Cell-ELISA showing LGI4 binds ADAM23"},{"PMID":"20220021","why":"Reports Lgi4 binding to Adam23 (browser-read)"}],"covers":["LR001893","LR005235"]},"LR004443":{"pair":"LIF -> LIFR","headline":"LIF binds LIFR, with mutagenesis mapping its binding site; four confirming papers and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"LIF binds LIFR; alanine-scanning of the Ig-like domain maps a LIF binding site at its carboxyl terminus, mainly Phe-328 [PMID:12601009]. LIF signalling is unaffected by deleting the LIFR N-terminal cytokine-binding domain [PMID:16051226]. GtoPdb records an agonist [DB:GtoPdb].","molecular_requirements":"LIFR acts with IL6ST/gp130 [DB:UniProt]. Unlike CNTF, LIF and OSM signalling did not need the LIFR N-terminal cytokine-binding domain [PMID:16051226].","affinity_potency":[],"species_and_systems":"Human cells with human LIFR mutants [PMID:12601009][PMID:16051226]; both mouse and human pairs are listed.","localisation_and_range":"LIF is flagged secreted [flag].","caveats":"Both papers read as abstracts only; no numeric affinity reported. Two more confirmed papers are not shown in the dossier.","key_references":[{"PMID":"12601009","why":"LIF binding site on LIFR mapped to Phe-328"},{"PMID":"16051226","why":"LIF signalling does not need LIFR N-terminal CBD"}],"covers":["LR001026","LR004443"]},"LR006144":{"pair":"LRFN5 -> PTPRS","headline":"LRFN5 (SALM5) binds LAR-RPTPs including PTPRS via Ig domains; one paper, with 8.96 nM Kd measured for LAR.","interaction_type":"direct binding","direction_and_effect":"SALM5 interacts with the Ig domains of LAR-RPTPs (LAR, PTP-delta, PTP-sigma) [PMID:27225731]. PTP-delta and PTP-sigma interacted with SALM5 in cell aggregation assays [PMID:27225731]. Assay detail reports a stimulatory effect on presynaptic differentiation in contacting axons, with the interaction strongly inhibited by splice insert B [PMID:27225731].","molecular_requirements":"The three LAR Ig domains were sufficient for SALM5 binding; the FNIII region did not bind. The interaction was calcium-insensitive [PMID:27225731]. Other SALMs did not interact with LAR in cell aggregation assays [PMID:27225731].","affinity_potency":[{"value":"Kd 8.96 \u00b1 0.92 nM","assay":"Scatchard analysis of LAR-Ecto-Fc binding","system":"SALM5-expressing HEK293T cells; measured for LAR, not PTPRS","cite":"PMID:27225731"}],"species_and_systems":"HEK293T cell aggregation and soluble-binding assays, cocultured hippocampal neurons [PMID:27225731].","localisation_and_range":"Both partners flagged not secreted; transmembrane, so trans-synaptic contact adhesion [flag][PMID:27225731].","caveats":"Affinity was measured for LAR only; PTPRS was shown by cell aggregation only [PMID:27225731]. Record is labelled abstract-only although full-text excerpts exist.","key_references":[{"PMID":"27225731","why":"SALM5 binds LAR-RPTP Ig domains; Kd for LAR 8.96 nM"}],"covers":["LR002919","LR006144"]},"LR002922":{"pair":"LRIG2 -> EGFR","headline":"LRIG2 and its ectodomain co-immunoprecipitate with EGFR and enhance EGFR/Akt signalling in glioblastoma cells; one paper plus two interaction database records.","interaction_type":"direct binding","direction_and_effect":"Full-length LRIG2 and LRIG2 ectodomain physically interact with EGFR and enhance EGFR activation and downstream PI3K/Akt signalling [PMID:25353163]. Curators label the effect agonist [PMID:25353163]. Gefitinib (10 uM) abrogated the Akt activation effect, and the authors suggest LRIG2 stabilises EGFR [PMID:25353163].","molecular_requirements":"The ectodomain alone was sufficient to co-precipitate EGFR, which the authors take to mean the ectodomains mediate recognition [PMID:25353163].","affinity_potency":[],"species_and_systems":"Human glioblastoma cell lines (U87, U251) with overexpressed Flag-tagged LRIG2 [PMID:25353163]. The mouse pair is ortholog-inferred. BioGRID and IntAct list the same co-IP from this paper [DB:BioGRID] [DB:IntAct].","localisation_and_range":"LRIG2 is flagged as non-secreted, but the paper reports that the soluble ectodomain is released from glioblastoma cells [PMID:25353163]. Cell-surface and intracellular colocalisation were seen [PMID:25353163].","caveats":"Evidence is co-IP and colocalisation in overexpressing cells, which does not show direct binding. Both database records cite the same paper, so they are not independent support. Abstract text was truncated; details come from excerpts.","key_references":[{"PMID":"25353163","why":"Co-IP of LRIG2 and its ectodomain with EGFR; enhanced EGFR/Akt activation"}],"covers":["LR002922","LR006147"]},"LR008403":{"pair":"LRPAP1 -> SORL1","headline":"SORL1 was purified by RAP affinity chromatography and LR11 binds and internalises RAP; supported by papers, SPR records and UniProt.","interaction_type":"direct binding","direction_and_effect":"A 250-kDa brain protein (SORL1) was purified by RAP affinity chromatography [PMID:8940146]. Human LR11 overexpressed in hamster cells binds and internalises RAP, and RAP and beta-VLDL compete [PMID:11557679].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human brain extracts [PMID:8940146] and hamster cells expressing human LR11 [PMID:11557679]. IntAct holds SPR records [DB:IntAct], BioGRID reconstituted complexes [DB:BioGRID], and UniProt lists the interaction [DB:UniProt].","localisation_and_range":"LRPAP1 is flagged secreted [flag]. The first abstract describes RAP as an ER/Golgi chaperone [PMID:8940146].","caveats":"RAP is a chaperone/universal LDL receptor-family binder, not a physiological extracellular ligand. 11557679 was read by browser and the quote is marked unverifiable pending spot-check. No affinity in our evidence.","key_references":[{"PMID":"8940146","why":"SORL1 purified by RAP affinity chromatography"},{"PMID":"11557679","why":"LR11 binds and internalises RAP"}],"covers":["LR008403"]},"LR006153":{"pair":"LRRTM1 -> NRXN2","headline":"LRRTM1 is reported to share the S4-lacking neurexin binding code that covers neurexins 1, 2 and 3; support is one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The neurexin binding code of LRRTM2, which binds neurexins 1, 2 and 3 alpha and beta variants lacking an insert at splice site 4, is conserved in LRRTM1 and functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Neurexin variants must lack the splice site 4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"One paper, read as abstract only; species not specified. Both human and mouse pairs are projected from other evidence (ortholog inferred) [PMID:20519524]. No database records.","localisation_and_range":"Both partners are flagged transmembrane [flag]; localisation is not discussed in our evidence for this pair.","caveats":"The paper's text does not specifically name NRXN2 for LRRTM1; the pair is inferred from the general statement that the code is conserved, and the curator note itself says it covers NRXN1-3. Single paper, abstract read, no affinity reported.","key_references":[{"PMID":"20519524","why":"conserved neurexin binding code in LRRTM1"}],"covers":["LR002928","LR006153"]},"LR002931":{"pair":"LRRTM2 -> NRXN2","headline":"LRRTM2 is reported to bind neurexin-2 lacking the S4 insert; support is two abstract-level papers, one only indirect.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds neurexins 1, 2 and 3 alpha and beta variants specifically lacking an insert at splice site 4 [PMID:20519524]. A truncating NRXN2 mutation produced a protein that failed to bind LRRTM2 or NLGN2 in cell binding assays [PMID:21424692].","molecular_requirements":"Neurexin must lack the S4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"Both papers were read as abstract only; the curator lists human for both partners in the 2011 paper [PMID:21424692]. Pair projected to mouse by orthology. No database records.","localisation_and_range":"Both partners flagged transmembrane [flag].","caveats":"The 2010 paper's evidence sentence names neurexin-1beta; NRXN2 is covered only by the general statement. The 2011 abstract says truncating mutations in NRXN1 and NRXN2 fail to bind, but which protein was tested for LRRTM2 binding is not clear from the abstract. No affinity reported.","key_references":[{"PMID":"20519524","why":"LRRTM2 binds neurexins 1, 2, 3 lacking S4"},{"PMID":"21424692","why":"truncated NRXN proteins fail to bind LRRTM2"}],"covers":["LR002931","LR006156"]},"LR006162":{"pair":"LRRTM4 -> GPC5","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner, with GPC5 covered by a class-level result; one paper, mouse glypicans in HEK293T.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC5 says secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. The curator notes the abstract names glypican generically, but the excerpts cover this paralog. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002937","LR006162"]},"LR002940":{"pair":"LRRTM4 -> PTPRS","headline":"PTPRS acts as presynaptic receptor in a glypican-4/LRRTM4 complex; direct LRRTM4-PTPRS binding is not shown.","interaction_type":"functional only","direction_and_effect":"Knockdown of PTPsigma, but not LAR, in cultured neurons significantly reduced the synaptogenic activity of LRRTM4 in heterologous synapse-formation assays, and PTPsigma is called a presynaptic receptor for the GPC-4/LRRTM4 complex [PMID:25624497].","molecular_requirements":"PTPsigma bound only proteolytically cleaved GPC-4 in an HS-dependent way and formed an additional complex with LRRTM4 in rat brains [PMID:25624497]. LRRTM4 engagement therefore appears to run through glypican-4.","affinity_potency":[],"species_and_systems":"Rat brain and cultured neurons [PMID:25624497]; BioGRID lists affinity capture-western [DB:BioGRID]. The nanomolar affinity in the abstract is for GPC-4 with PTPsigma, not LRRTM4.","localisation_and_range":"PTPRS is flagged both secreted and transmembrane [flag]; the paper presents it as a presynaptic receptor acting across the synapse [PMID:25624497].","caveats":"Paper read as abstract only; curator quote is a Discussion sentence marked spot-check pending. No direct LRRTM4-PTPsigma binding is reported; the interaction is glypican-bridged.","key_references":[{"PMID":"25624497","why":"PTPsigma as presynaptic receptor for GPC-4/LRRTM4"}],"covers":["LR002940","LR006165"]},"LR004452":{"pair":"LTA -> LTBR","headline":"LTBR binds LT alpha-beta membrane complexes (shown in mouse); LTA alone as a ligand is not shown in our evidence.","interaction_type":"direct binding","direction_and_effect":"A mouse LTbetaR-Fc chimera bound LT alpha-beta complexes on activated T cells and on insect cells expressing LT alpha and LT beta [PMID:7594541]. Curator labels this agonist; UniProt calls LTBR the receptor for heterotrimeric lymphotoxin containing LTA and LTB [DB:UniProt].","molecular_requirements":"The ligand is the LT alpha/beta heteromer, not LT alpha alone. UniProt says LTA binds LTBR in its heterotrimeric form with LTB, and that the LTA homotrimer binds TNFR1, TNFBR and HVEM [DB:UniProt]. A structure with chains of LTA and LTBR is deposited [DB:PDB 4MXW]; Reactome lists an LTBR:lymphotoxin,TNFSF14 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"The paper used mouse LTbetaR (76% identity to human) with baculovirus-infected insect cells and activated T cells [PMID:7594541]. Curated species labels say human.","localisation_and_range":"LT alpha is flagged secreted and LTBR transmembrane [flag], but the active ligand here is membrane-anchored [PMID:7594541].","caveats":"Abstract read only. The pair as listed credits LTA alone; the evidence supports a requirement for LTB. GtoPdb lists the interaction without type, action or affinity [DB:GtoPdb]. The human pair is projected from mouse evidence.","key_references":[{"PMID":"7594541","why":"Mouse LTbetaR-Fc binds LT alpha-beta complexes"}],"covers":["LR001038","LR004452"]},"LR004461":{"pair":"MADCAM1 -> CD44","headline":"A 1989 binding study showing gp90Hermes, identical to or including CD44, binds MAdCAM; identity of CD44 rests on earlier work.","interaction_type":"direct binding","direction_and_effect":"Lymphocyte gp90Hermes binds in a saturable, reversible fashion to the mucosal vascular addressin (MAd) [PMID:2474557]. The abstract states the Hermes antigen is identical to or includes CD44 [PMID:2474557].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Abstract-only; tissue sections were human; assay was fluorescence energy transfer with purified MAd [PMID:2474557]. Curator species fields are blank.","localisation_and_range":"MAdCAM1 flagged transmembrane (endothelial adhesion molecule) and CD44 flagged both secreted and transmembrane [flag].","caveats":"Abstract-only; CD44 identity with gp90Hermes is cited as earlier work from the authors and others, not shown here. No affinity. Mouse pair is projected.","key_references":[{"PMID":"2474557","why":"gp90Hermes (CD44-related) binds mucosal addressin"}],"covers":["LR001048","LR004461"]},"LR006171":{"pair":"MAG -> RTN4RL2","headline":"MAG binds NgR2 (RTN4RL2) directly with higher affinity than NgR1 in one abstract-only paper; UniProt records the opposite.","interaction_type":"conflicting","direction_and_effect":"NgR2 is a receptor for MAG and mediates MAG inhibitory responses; forced NgR2 expression imparts MAG inhibition to neonatal sensory neurons and soluble NgR2 antagonises MAG [PMID:15673660].","molecular_requirements":"The NgR2 leucine-rich repeat cluster and 'unique' domain are needed for high-affinity MAG binding; binding is sialic acid dependent [PMID:15673660].","affinity_potency":[],"species_and_systems":"Human labelled for both partners; the paper was read as an abstract only and the assay system is not stated in our evidence [PMID:15673660]. Mouse pair is ortholog-inferred.","localisation_and_range":"MAG is flagged secreted; RTN4RL2 is flagged both secreted and receptor [flag]. Range not otherwise reported.","caveats":"Single paper, abstract only, no affinity value in our evidence. UniProt states RTN4RL2 does not interact with MAG, OMG and RTN4 [PMID:12839991][DB:UniProt], conflicting with the paper.","key_references":[{"PMID":"15673660","why":"NgR2 as a selective, sialic acid-dependent MAG receptor"}],"covers":["LR002946","LR006171"]},"LR004470":{"pair":"MDK -> ITGA6","headline":"Midkine binds integrin alpha4beta1 and alpha6beta1 in mouse embryo and cell assays; evidence is for heterodimers, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Midkine binds these integrins; alpha4beta1 and alpha6beta1 are concluded to be functional midkine receptors. Anti-alpha4 antibody inhibited midkine-dependent migration of osteoblastic cells and anti-alpha6 inhibited neurite outgrowth of embryonic neurons; midkine raised paxillin tyrosine phosphorylation [PMID:15466886].","molecular_requirements":"Needs alpha6 with beta1: purified alpha6beta1 bound midkine [PMID:15466886].","affinity_potency":[],"species_and_systems":"Mouse embryo (13-day) extracts and cell assays; curated as human/human, but the experiments used mouse material [PMID:15466886]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine growth factor.","caveats":"Single paper, abstract only. The integrins may cooperate with other midkine receptors (PTPRZ, LRP, ALK) [PMID:15466886]. UniProt records the interaction [DB:UniProt].","key_references":[{"PMID":"15466886","why":"midkine-integrin binding and function"}],"covers":["LR001057","LR004470"]},"LR001059":{"pair":"MDK -> LRP1","headline":"LRP (LRP1) binds midkine with Kd 3.5 nM in mouse embryo membrane proteins; LRP is described as a component of a receptor complex.","interaction_type":"direct binding","direction_and_effect":"LRP was isolated by midkine-affinity chromatography; receptor-associated protein (RAP), which interfered with binding, inhibited MK-dependent survival of embryonic neurons [PMID:10772929].","molecular_requirements":"LRP is a component of the receptor complex for MK; NCAM was also in the fraction [PMID:10772929].","affinity_potency":[{"value":"Kd 3.5 nM","assay":"LRP-MK binding","system":"membrane glycoproteins from day 13 mouse embryos","cite":"PMID:10772929"}],"species_and_systems":"Day-13 mouse embryo material; curated ligand human, receptor mouse [PMID:10772929]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag]; paracrine.","caveats":"Single paper, abstract only; paper uses the name LRP. One review-only row was not used. BioGRID lists affinity capture-MS [DB:BioGRID].","key_references":[{"PMID":"10772929","why":"LRP-midkine Kd and RAP inhibition"}],"covers":["LR001059","LR004472"]},"LR001068":{"pair":"MFGE8 -> ITGAV","headline":"Functional evidence from two mouse studies shows MFGE8 acts through alphav integrins; abstract-level evidence only.","interaction_type":"functional only","direction_and_effect":"Lack of MFG-E8 eliminated alphavbeta5 downstream signalling (MerTK, peak photoreceptor outer segment phagocytosis) in mouse retina [PMID:17620600]. Mfge8 coordinated fatty acid uptake through alphavbeta3- and alphavbeta5-dependent Akt phosphorylation [PMID:24441829].","molecular_requirements":"alphav pairs with beta3 or beta5 in these studies [PMID:17620600, PMID:24441829].","affinity_potency":[],"species_and_systems":"Mouse knockouts, mouse retinal pigment epithelium and Mfge8-deficient mice on diet-induced obesity [PMID:17620600, PMID:24441829]. Human pair is also recorded in the dossier.","localisation_and_range":"Mfge8 is flagged secreted [flag]; the integrin ligand acts on cells in matrix/tissue contexts [PMID:24441829].","caveats":"Evidence is functional (knockout phenotype and signalling) and abstract-level; direct binding to alphav is not shown in these papers.","key_references":[{"PMID":"17620600","why":"Mfge8 loss abolishes alphavbeta5 signalling in RPE"},{"PMID":"24441829","why":"Mfge8 drives fatty acid uptake via alphavbeta3/beta5-Akt"}],"covers":["LR001068","LR004481"]},"LR006180":{"pair":"MIA -> ITGA5","headline":"MIA binds integrin alpha5 (as alpha5beta1) in melanoma cells by far-Western and co-IP and reduces integrin activity; abstract only.","interaction_type":"direct binding","direction_and_effect":"MIA interacts with integrin alpha4beta1 and alpha5beta1, down-regulating integrin activity and MAPK signalling, an antagonist-type effect [PMID:16517605].","molecular_requirements":"The paper identifies alpha4beta1 and alpha5beta1 heterodimers, so both subunits belong to the complex [PMID:16517605]. MIA also binds fibronectin [PMID:16517605].","affinity_potency":[],"species_and_systems":"Human malignant melanoma cells [PMID:16517605]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIA is flagged secreted [flag].","caveats":"Abstract only; no affinity. Evidence is for the integrin heterodimers, not a single chain; the abstract does not say which assay showed which integrin.","key_references":[{"PMID":"16517605","why":"MIA binds alpha4beta1/alpha5beta1 integrins and reduces MAPK signalling"}],"covers":["LR002955","LR006180"]},"LR005244":{"pair":"MIF -> CD74","headline":"MIF binds CD74 directly with a Kd of about 9 nM and activates ERK signalling; this is well supported by two papers.","interaction_type":"direct binding","direction_and_effect":"MIF is an agonist at CD74: CD74 is required for MIF-induced ERK1/2 activation, proliferation and PGE2 production, and soluble CD74 inhibits MIF-mediated ERK activation [PMID:12782713]. In human melanoma cells, autocrine MIF-CD74 activates PI3K/AKT; blocking the interaction reduced AKT phosphorylation and suppressed xenograft tumour growth [PMID:26039541].","molecular_requirements":"The CD74 extracellular domain binds MIF; a membrane-truncated CD74 lacking it did not, and residues 109-149 appear important [PMID:12782713]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 9.0 x 10-9 M (about 9 nM)","assay":"surface plasmon resonance (BIAcore), MIF on chip, soluble CD74 extracellular domain","system":"recombinant proteins","cite":"PMID:12782713"}],"species_and_systems":"Human: COS-7 cells, THP-1 cells and recombinant protein [PMID:12782713]; human melanoma cell lines and a mouse xenograft model [PMID:26039541]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIF is flagged secreted [flag]; secreted MIF binds cell-surface CD74 in an autocrine manner [PMID:26039541].","caveats":"The melanoma paper's blockade used the inhibitor ISO-1 and was read with full text; its binding claim is indirect [PMID:26039541]. BioGRID, Reactome and UniProt records support the interaction [DB:BioGRID] [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"12782713","why":"Expression cloning, binding, SPR Kd of about 9 nM"},{"PMID":"26039541","why":"Autocrine MIF-CD74 drives AKT signalling in melanoma"}],"covers":["LR001904","LR005244"]},"LR001905":{"pair":"MIF -> CXCR2","headline":"MIF directly binds CXCR2 and activates it as a noncognate chemokine-like agonist; one paper plus an IntAct pull-down.","interaction_type":"direct binding","direction_and_effect":"MIF triggers Galphai- and integrin-dependent arrest and chemotaxis, integrin activation and calcium influx through CXCR2; it competes with cognate ligands and directly bound CXCR2. Il8rb (Cxcr2) deficiency abolished MIF-induced leukocyte recruitment [PMID:17435771].","molecular_requirements":"CXCR2 and CD74 formed a receptor complex, and monocyte arrest by MIF in inflamed or atherosclerotic arteries involved both CXCR2 and CD74 [PMID:17435771].","affinity_potency":[],"species_and_systems":"Human ligand and receptor labelled; in vivo work in mice (Mif deficiency, Il8rb deficiency, atherosclerosis-prone mice). Mouse pair is ortholog-inferred [PMID:17435771].","localisation_and_range":"MIF carries a secreted flag [flag]; acts as a soluble ligand [PMID:17435771].","caveats":"Abstract-only reading; no affinity reported. An IntAct pull-down record exists [DB:IntAct].","key_references":[{"PMID":"17435771","why":"MIF is a noncognate ligand of CXCR2 and CXCR4"}],"covers":["LR001905","LR005245"]},"LR001077":{"pair":"MMP9 -> CD44","headline":"CD44 docks MMP-9 at the cell surface; supported by colocalisation, co-IP and functional papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"CD44 provides a cell-surface docking receptor for proteolytically active MMP-9 [PMID:10652271]. CD44 crosslinking raised membrane MMP-9, and CD44 clusters act as an MMP-9 docking site retaining proteolytic activity at the surface [PMID:17912438]. MMP-9 surface localisation on normal keratinocytes was CD44-dependent [PMID:10652271].","molecular_requirements":"Not reported in our evidence beyond CD44 and MMP-9 forming a complex purified by immunoprecipitation [PMID:17912438].","affinity_potency":[],"species_and_systems":"Human MDA-MB-435s breast tumour cells [PMID:17912438]; human experiment species for ligand and receptor in the other paper, with keratinocytes and tumour models [PMID:10652271]. Reactome lists CD44:MMP2, MMP7, MMP9 binding and complex [DB:Reactome]. The human row is ortholog-inferred.","localisation_and_range":"MMP9 is flagged as secreted; CD44 is flagged both secreted and transmembrane [flag]. The papers describe MMP-9 retained on the cell surface.","caveats":"Both papers were read as abstract only. This is docking of a protease, not classical signalling. One further paper is pending and not shown. Human pair is projected from mouse.","key_references":[{"PMID":"17912438","why":"Colocalisation and co-IP of CD44-MMP-9 after crosslinking"},{"PMID":"10652271","why":"CD44 as MMP-9 docking receptor; CD44-dependent surface localisation"}],"covers":["LR001077","LR004489"]},"LR006801":{"pair":"MT-RNR2 -> FPR2","headline":"Humanin is an agonist for FPR2 (FPRL1) with direct binding and nM potency in transfected cells.","interaction_type":"direct binding","direction_and_effect":"Humanin suppressed forskolin-induced cAMP in CHO-hFPRL1 cells, acting as an agonist; N-formylated humanin was more potent [PMID:15465011]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor suffices in transfectants; humanin and formylated humanin interacted directly with hFPRL1 in [125I]-W peptide binding experiments [PMID:15465011].","affinity_potency":[{"value":"pEC50 8.46","assay":"cAMP suppression","system":"CHO-hFPRL1","cite":"PMID:15465011"}],"species_and_systems":"Human proteins in CHO transfectants [PMID:15465011].","localisation_and_range":"Humanin is annotated secreted [flag].","caveats":"Abstract only; one paper. The abstract gives EC50 3.5nM for humanin on FPRL1.","key_references":[{"PMID":"15465011","why":"Humanin as FPRL1/FPRL2 ligand"}],"covers":["LR006801"]},"LR005253":{"pair":"MYL9 -> CD69","headline":"Myl9 reported as a functional CD69 ligand in mouse asthma models and human nasal polyps; abstract-only.","interaction_type":"functional only","direction_and_effect":"Myl9 and Myl12 are new functional ligands for CD69; blockade of the interaction ameliorated allergic airway inflammation [PMID:28783682]. Curator labels it agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse asthma models and human eosinophilic chronic rhinosinusitis nasal polyps; curator fields list human for this row, but the functional work in the abstract is in mouse [PMID:28783682].","localisation_and_range":"Ligand flagged secreted [flag]; platelet-derived Myl9/12 formed intravascular net-like structures with CD69+ cells nearby [PMID:28783682].","caveats":"Abstract only; the abstract does not give binding affinity or a binding assay. Evidence is functional (antibody blockade, in vivo) [PMID:28783682].","key_references":[{"PMID":"28783682","why":"Myl9/12 as CD69 ligands; blockade reduces airway inflammation"}],"covers":["LR001913","LR005253"]},"LR001086":{"pair":"MYOC -> FZD7","headline":"Myocilin-AP fusion bound FZD7 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak. UniProt also records MYOC interacting with FZD7 [DB:UniProt].","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001086","LR004497"]},"LR006207":{"pair":"NCAN -> NRCAM","headline":"Single abstract-only paper reports neurocan association with NrCAM by cell binding and ELISA; no affinity or other support.","interaction_type":"direct binding","direction_and_effect":"Neurocan blocked Sema3F-induced spine elimination and COS-7 cell retraction, which was mediated through NrCAM, Neuropilin-2 and PlexinA3 [PMID:30356641]. Neurocan acts as an inhibitor of NrCAM/Sema3F signalling.","molecular_requirements":"NrCAM is a subunit of the Sema3F receptor complex with Neuropilin-2 and PlexinA3. Neurocan glycosaminoglycan chains were required for inhibition; the C-terminal sushi domain was dispensable [PMID:30356641].","affinity_potency":[],"species_and_systems":"Mouse neocortex, cortical neuron cultures and COS-7 cells; binding by cell binding assay and ELISA [PMID:30356641]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Both entities carry a secreted flag [flag]; neurocan was found at the cell surface of cortical pyramidal neurons and adjacent to dendritic spines [PMID:30356641].","caveats":"Based on one paper read as abstract only; no quantitative binding data. Both species rows are inferred by orthology, not directly tested.","key_references":[{"PMID":"30356641","why":"Cell binding and ELISA association of neurocan with NrCAM"}],"covers":["LR002982","LR006207"]},"LR001914":{"pair":"NCR3LG1 -> NCR3","headline":"B7-H6 binds the NK receptor NKp30 directly by SPR and activates NK cells; well supported by papers and several databases.","interaction_type":"direct binding","direction_and_effect":"B7-H6 on tumour cells engages NKp30 and activates it: NKp30 reporter cells made IL-2 with B7-H6-expressing P815 cells, and NK-92 and primary human NK cells lysed them, blocked by soluble NKp30-Fc [PMID:19528259]. This matches the GtoPdb activator record [DB:GtoPdb].","molecular_requirements":"NKp30 extracellular domain binds the B7-H6 extracellular domain; no binding to other B7 family members or to NKp44, NKp46 and NKG2D [PMID:19528259]. Reactome lists a complex with FCRG3A and CD3Z [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant Fc fusions by SPR, mouse reporter cells expressing an NKp30 chimera, human NK cells [PMID:19528259]. No full mouse B7-H6 gene was found [PMID:19528259].","localisation_and_range":"B7-H6 carries both secreted and transmembrane flags [flag]; the paper describes a tumour cell surface ligand, so signalling is by cell contact [PMID:19528259]. It was not detected in normal human tissues [PMID:19528259].","caveats":"Affinity is not reported in our evidence. The curated paper was read as abstract plus excerpts. Structures and IntAct SPR records support the pair [DB:PDB 3PV6][DB:IntAct].","key_references":[{"PMID":"19528259","why":"Identification of B7-H6 as NKp30 ligand, SPR and NK activation"}],"covers":["LR001914"]},"LR001923":{"pair":"NECTIN3 -> CADM1","headline":"Functional evidence only: antibody blocking suggests heterophilic nectin-3/CADM1 binding between DRG neurons and mast cells.","interaction_type":"functional only","direction_and_effect":"Mast-cell CADM1 mediated attachment to DRG neurites and calcium responses, while nectin-3 was expressed on DRG neurons; a neutralizing anti-nectin-3 antibody inhibited both, suggesting heterophilic CADM1-nectin-3 binding [PMID:22703826]. Reactome lists a Nectin-3:Necl-2 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-culture of mast cells and DRG neurons in vitro; abstract does not state species [PMID:22703826]. The curators recorded human, but the mouse pair is the non-projected one.","localisation_and_range":"Membrane-bound on both partners (flags) [flag]; nectin-3 localised to cell-cell contact regions [PMID:22703826]. Juxtacrine.","caveats":"Single paper, abstract only, no direct binding assay; antibody inhibition does not exclude other partners. CADM1 also binds homophilically [PMID:22703826].","key_references":[{"PMID":"22703826","why":"Anti-nectin-3 blocks mast cell-DRG attachment"}],"covers":["LR001923","LR005262"]},"LR005262":{"pair":"NECTIN3 -> CADM1","headline":"Functional evidence only: antibody blocking suggests heterophilic nectin-3/CADM1 binding between DRG neurons and mast cells.","interaction_type":"functional only","direction_and_effect":"Mast-cell CADM1 mediated attachment to DRG neurites and calcium responses, while nectin-3 was expressed on DRG neurons; a neutralizing anti-nectin-3 antibody inhibited both, suggesting heterophilic CADM1-nectin-3 binding [PMID:22703826]. Reactome lists a Nectin-3:Necl-2 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-culture of mast cells and DRG neurons in vitro; abstract does not state species [PMID:22703826]. The curators recorded human, but the mouse pair is the non-projected one.","localisation_and_range":"Membrane-bound on both partners (flags) [flag]; nectin-3 localised to cell-cell contact regions [PMID:22703826]. Juxtacrine.","caveats":"Single paper, abstract only, no direct binding assay; antibody inhibition does not exclude other partners. CADM1 also binds homophilically [PMID:22703826].","key_references":[{"PMID":"22703826","why":"Anti-nectin-3 blocks mast cell-DRG attachment"}],"covers":["LR001923","LR005262"]},"LR001095":{"pair":"NGF -> SORCS3","headline":"SorCS3 binds NGF in purified-protein assays; one abstract-only paper, supported by IntAct and UniProt.","interaction_type":"direct binding","direction_and_effect":"SorCS3 is described as a new neurotrophin binding Vps10p-domain receptor [PMID:15710408]; effect direction is not reported in our evidence.","molecular_requirements":"The propeptide is not required for processing and does not prevent ligands from binding the SorCS3 precursor form [PMID:15710408].","affinity_potency":[],"species_and_systems":"Binding to purified SorCS3 and cell transfectants; species not specified in the dossier; abstract only [PMID:15710408]. IntAct SPR record [DB:IntAct]. Human pair is listed; mouse pair is ortholog-inferred.","localisation_and_range":"SorCS3 predominates on the plasma membrane with slow internalisation [PMID:15710408]; NGF is annotated secreted [flag].","caveats":"One paper, abstract only; the abstract does not name NGF explicitly and the curator confirmed via protein names. Affinity is not reported in our evidence.","key_references":[{"PMID":"15710408","why":"SorCS3 binds neurotrophin ligands including NGF; propeptide not required"}],"covers":["LR001095","LR004506"]},"LR004506":{"pair":"NGF -> SORCS3","headline":"SorCS3 binds NGF in purified-protein assays; one abstract-only paper, supported by IntAct and UniProt.","interaction_type":"direct binding","direction_and_effect":"SorCS3 is described as a new neurotrophin binding Vps10p-domain receptor [PMID:15710408]; effect direction is not reported in our evidence.","molecular_requirements":"The propeptide is not required for processing and does not prevent ligands from binding the SorCS3 precursor form [PMID:15710408].","affinity_potency":[],"species_and_systems":"Binding to purified SorCS3 and cell transfectants; species not specified in the dossier; abstract only [PMID:15710408]. IntAct SPR record [DB:IntAct]. Human pair is listed; mouse pair is ortholog-inferred.","localisation_and_range":"SorCS3 predominates on the plasma membrane with slow internalisation [PMID:15710408]; NGF is annotated secreted [flag].","caveats":"One paper, abstract only; the abstract does not name NGF explicitly and the curator confirmed via protein names. Affinity is not reported in our evidence.","key_references":[{"PMID":"15710408","why":"SorCS3 binds neurotrophin ligands including NGF; propeptide not required"}],"covers":["LR001095","LR004506"]},"LR004515":{"pair":"NLGN1 -> NRXN3","headline":"Rests on a general neuroligin-neurexin binding paper and a BioGRID record; NRXN3 specifically is not pinned down.","interaction_type":"direct binding","direction_and_effect":"Neuroligin 1 binds a subset of neurexins and binds beta-neurexins as native brain and recombinant proteins [PMID:8576240]. Effect on NRXN3 specifically is not reported in our evidence.","molecular_requirements":"Tight binding only to beta-neurexins lacking an insert at splice site 4 [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat (curator-listed) binding assays [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Abstract says neuroligin binds 'a subset of neurexins', so NRXN3 is not shown individually; the curator notes a paralogue caveat. Abstract only. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin-neurexin binding, splice-dependent"}],"covers":["LR001104","LR004515"]},"LR006216":{"pair":"NLGN2 -> LHFPL4","headline":"Abstract reports LHFPL4/GARLH4 as a major NL2 binding partner at inhibitory synapses; PDB records exist for the pair.","interaction_type":"direct binding","direction_and_effect":"LHFPL4/GARLH4 is identified as a major NL2 binding partner enriched at inhibitory postsynaptic sites; the two regulate each other's protein levels and synaptic clustering in the cerebellum, and Lhfpl4/Garlh4-/- mice have profound impairment of inhibitory synapse formation [PMID:29742426]. A curator label of 'agonist' is not stated in the abstract.","molecular_requirements":"Not reported in our evidence beyond the two-protein association.","affinity_potency":[],"species_and_systems":"Abstract describes knockout mice and cerebellum; curator lists human for both partners. Human pair is ortholog-projected; the mouse pair is not [PMID:29742426].","localisation_and_range":"NLGN2 is a transmembrane protein at inhibitory postsynaptic sites [PMID:29742426]; LHFPL4 has a receptor flag only [flag]. Contact/synaptic setting.","caveats":"Abstract only; the binding method is not stated, and 'binding partner' may include indirect association. PDB lists 13 structures with a chain of Q8NFZ4 and a chain of Q7Z7J7 (e.g. 9FAJ) [DB:PDB 9FAJ]; the dossier does not say which accession is which protein.","key_references":[{"PMID":"29742426","why":"LHFPL4/GARLH4 as NL2 binding partner, knockout phenotype"}],"covers":["LR002992","LR006216"]},"LR004524":{"pair":"NMS -> NMUR1","headline":"Functionally supported agonist pair from one abstract-level deorphanisation paper in rat, plus GtoPdb and UniProt records.","interaction_type":"functional only","direction_and_effect":"NMS is an agonist of the neuromedin U receptor; it was purified from rat brain as an endogenous ligand of FM-4/TGR-1 (NMU receptors) and ICV administration activates SCN neurons and phase-shifts circadian activity in rats [PMID:15635449]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond a receptor chain; a PDB structure with these two chains exists [DB:PDB 7W56].","affinity_potency":[{"value":"pIC50 10.0","assay":"as recorded for the paper's curated affinity field","system":"rat","cite":"PMID:15635449"}],"species_and_systems":"Rat peptide and rat receptor [PMID:15635449]; human and mouse entries are not directly tested in our evidence. UniProt describes NMUR1 as a receptor for NMU and NMS [DB:UniProt].","localisation_and_range":"NMS is flagged secreted and the paper proposes autocrine and/or paracrine action in the SCN [PMID:15635449][flag].","caveats":"Single paper, read as abstract only. The abstract identifies the receptor as FM-4/TGR-1 and does not distinguish NMUR1 from NMUR2, so receptor-subtype specificity is not established by it. The affinity assay is not described in our evidence.","key_references":[{"PMID":"15635449","why":"Identification of NMS as endogenous NMU-receptor ligand with in vivo circadian effect"}],"covers":["LR001113","LR004524"]},"LR011751":{"pair":"NODAL -> ACVR1B:ACVR2B:CRIPTO","headline":"No curator-verified papers; support is database annotation only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states cell-associated CRIPTO acts as a Nodal coreceptor in cis [DB:UniProt]; BioGRID lists NODAL complexes with TDGF1, ACVR2A and ACVR2B [DB:BioGRID].","molecular_requirements":"Row includes CRIPTO, ACVR1B and ACVR2B; subunit-level experimental evidence is not shown.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Nodal flagged secreted [flag]; CRIPTO acts in cis, cell-associated [DB:UniProt].","caveats":"Two papers are pending; nothing experimental is verified.","key_references":[],"covers":["LR011751"]},"LR008430":{"pair":"NOTCH2 -> JAG2","headline":"Jagged2 binds Notch2 and drives its cleavage and reporter activation; functional, human, abstract only.","interaction_type":"functional only","direction_and_effect":"All three DSL proteins bound endogenous Notch2 on BaF3 cells, induced cleavage of Notch2(TM) within 15 min with nuclear translocation, and activated an RBP-Jkappa reporter [PMID:10958687]; agonist.","molecular_requirements":"Jagged2's binding characteristics apparently differed from Delta1 and Jagged1 [PMID:10958687]. Further requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-culture with ligand-expressing cells; the curator records human, though BaF3 cells are named without species in the abstract [PMID:10958687]. Abstract only.","localisation_and_range":"JAG2 flagged transmembrane and non-secreted [flag], consistent with co-culture contact.","caveats":"No affinity. The evidence sentence is background about Notch1. BioGRID records are listed [DB:BioGRID, PMID:10958687].","key_references":[{"PMID":"10958687","why":"DSL proteins induce Notch2 cleavage and signalling"}],"covers":["LR008430"]},"LR004533":{"pair":"NPB -> NPBWR1","headline":"Neuropeptide B is an agonist of NPBWR1 (GPR7), shown by purification and binding in cells.","interaction_type":"direct binding","direction_and_effect":"Neuropeptide B was purified from bovine hypothalamus using cAMP-inhibitory activity on GPR7 cells [PMID:12118011], and four peptides inhibited forskolin-stimulated cAMP accumulation through a pertussis toxin-sensitive mechanism [PMID:12401809]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone is enough; bromination of the N-terminal Trp did not influence binding [PMID:12118011].","affinity_potency":[{"value":"low nanomolar","assay":"binding assay","system":"CHO-K1 cells expressing GPR7","cite":"PMID:12401809"}],"species_and_systems":"Bovine ligand with receptor cells for purification [PMID:12118011]; human receptors in CHO-K1 cells [PMID:12401809]. Both abstract only. Mouse pair ortholog-inferred.","localisation_and_range":"NPB is flagged secreted [flag]; peptide, endocrine or paracrine.","caveats":"Not selective: the peptides also bound GPR8 with similar affinity [PMID:12401809]. One further abstract was insufficient. GtoPdb gives pIC50 without values in our dossier [DB:GtoPdb].","key_references":[{"PMID":"12118011","why":"Purification of the endogenous GPR7 ligand, brominated neuropeptide B"},{"PMID":"12401809","why":"L7 peptides (NPB) bind GPR7 and GPR8 with low nanomolar affinity"}],"covers":["LR001122","LR004533"]},"LR004542":{"pair":"NPPB -> NPR3","headline":"BNP binds the NPR3 clearance receptor, supported by abstract-level binding studies and structures.","interaction_type":"direct binding","direction_and_effect":"Rat BNP-45 interacted preferentially with the C-receptor and bound with lower affinity than rANP to guanylate cyclase-linked receptors and C-receptor [PMID:7901875]. UniProt says BNP binds NPR3 [DB:UniProt].","molecular_requirements":"NPR-C binds hormone as a dimer (1:2 stoichiometry, per curator sentence) [PMID:11533490]; PDB has a BNP-NPR3 structure [DB:PDB 1YK1].","affinity_potency":[],"species_and_systems":"Rat kidney cortex and lung [PMID:7901875]; human, bovine and rat preparations [PMID:1309330]; human NPR-C structure [PMID:11533490]. Mouse pair is projected.","localisation_and_range":"BNP annotated secreted [flag].","caveats":"All papers read as abstracts. Binding-affinity rank order at the C-receptor was ANP greater than CNP greater than BNP in humans and rats [PMID:1309330]. PMID:11533490 abstract describes a CNP complex only. Two further judged papers were unresolvable or insufficient.","key_references":[{"PMID":"7901875","why":"Rat BNP binding and cross-linking to C-receptor"},{"PMID":"1309330","why":"C-receptor affinity rank order"},{"PMID":"11533490","why":"NPR-C structure"}],"covers":["LR001132","LR004542"]},"LR006225":{"pair":"NPY -> GPR83","headline":"Rat-only evidence that NPY binds and activates rat GPR83; the human and mouse pairs are projected from it.","interaction_type":"direct binding","direction_and_effect":"NPY displaced 125I-PYY(3-36) from rat GIR (Gpr83) and activated 35S-GTPgammaS binding, acting as an agonist with a Y2-like profile [PMID:17240481].","molecular_requirements":"Single receptor; no co-receptor reported in our evidence.","affinity_potency":[{"value":"Ki 95 nM","assay":"BIIE0246 displacement of 125I-PYY(3-36) (Y2 antagonist, not NPY itself)","system":"rat GIR-transfected cells","cite":"PMID:17240481"}],"species_and_systems":"Rat ligand and rat receptor in transfected cells [PMID:17240481]. Human and mouse interactions are ortholog-inferred, with no human experiment in our evidence.","localisation_and_range":"NPY is flagged secreted [flag]; GPR83 localisation is not reported in our evidence.","caveats":"One paper, read as abstract only; NPY is described as high-affinity (low nanomolar) but no NPY value is given. The 95 nM is for the antagonist BIIE0246. Human relevance rests on ortholog projection. No database support.","key_references":[{"PMID":"17240481","why":"NPY-family peptides bind and activate rat GIR"}],"covers":["LR003001","LR006225"]},"LR004551":{"pair":"NPY -> NPY2R","headline":"NPY is a high-affinity agonist of NPY2R, supported by three cloning papers, PDB structures and database records.","interaction_type":"direct binding","direction_and_effect":"NPY binds Y2 with high affinity and acts as an agonist: cloned human Y2 cells bind NPY [PMID:7559383], NPY inhibited forskolin-stimulated cAMP and induced calcium mobilization in Y2 CHO cells [PMID:7559383], and human PYY decreased cAMP [PMID:7592910].","molecular_requirements":"Single receptor chain; PDB complexes (7X9B, 7YOO, 8K6N) list one NPY chain and one NPY2R chain [DB:PDB 7X9B].","affinity_potency":[{"value":"pKi 9.27","assay":"125I-PYY displacement by NPY","system":"transiently expressed human Y2","cite":"PMID:7592910"},{"value":"pKd 10.17","assay":"saturation binding of 125I-PYY (not NPY)","system":"human Y2","cite":"PMID:7592910"}],"species_and_systems":"Human receptor in COS-7, CHO, 293 cells [PMID:7559383][PMID:7592910]; human brain library in [PMID:8632753]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY2R transmembrane [flag].","caveats":"All papers read as abstracts only. NPY and PYY have similar affinity, and PP is much weaker [PMID:7592910]. The pKd is for the radioligand 125I-PYY.","key_references":[{"PMID":"7592910","why":"pKi 9.27 for NPY at human Y2"},{"PMID":"7559383","why":"Human Y2 cloning; NPY high-affinity binding and signalling"},{"PMID":"8632753","why":"Independent Y2 cloning from human brain"}],"covers":["LR001142","LR004551"]},"LR001149":{"pair":"NRG2 -> ERBB3","headline":"NRG2 binds ErbB3 and activates it; supported by two 1997 abstract-level papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Agonist: the NRG-2 EGF-like domain binds ErbB3 and ErbB4 and stimulates a different ErbB phosphorylation profile from NRG-1 [PMID:9168115]. Neuregulin-2beta only activated cell lines with ErbB3 and/or ErbB4 [PMID:9168114].","molecular_requirements":"Recombinant NRG2-beta induced phosphorylation of ErbB2, ErbB3 and ErbB4 in cells expressing all three; in defined combinations, activity required ErbB3 and/or ErbB4 [PMID:9168114]. UniProt says ERBB3 extracellular domain binds NRG1 and NRG2, shifting it to an extended dimerisation-competent state [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in cell lines and binding assays; the human and mouse pairs are both ortholog-inferred.","localisation_and_range":"NRG2 is flagged secreted and transmembrane [flag].","caveats":"Both papers are abstract only; no affinity quoted. One further paper is still pending. The ortholog-inferred species rows are projected.","key_references":[{"PMID":"9168115","why":"NRG-2 EGF domain binds ErbB3 and ErbB4"},{"PMID":"9168114","why":"NRG2 activates cells with ErbB3/ErbB4"}],"covers":["LR001149","LR004558"]},"LR006234":{"pair":"NRG3 -> ERBB3","headline":"NRG3 activates ERBB3 only together with ERBB2, from one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"NRG-3 activated erbB3 when co-expressed with erbB2 in cells, an agonist effect [PMID:9772300].","molecular_requirements":"ERBB3 is not shown to respond alone; activation required erbB2 co-expression [PMID:9772300].","affinity_potency":[],"species_and_systems":"Human breast cancer cells and transfected 32D cells [PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag].","caveats":"One paper, abstract only; activation not binding; no affinity. Direct NRG3-ERBB3 binding is not shown.","key_references":[{"PMID":"9772300","why":"erbB2 and erbB3 activated together by NRG-3"}],"covers":["LR003010","LR006234"]},"LR004560":{"pair":"NRG3 -> ERBB4","headline":"NRG3 binds and activates ERBB4; two papers, the primary one showing binding to cells and in vitro.","interaction_type":"direct binding","direction_and_effect":"NRG3 EGF-like domain binds the ErbB4 extracellular domain in vitro, binds ErbB4 on cells and stimulates its tyrosine phosphorylation, an agonist effect [PMID:9275162]. NRG-3 also activated erbB4 when expressed individually [PMID:9772300].","molecular_requirements":"ErbB4 acts as a single chain: activation occurred when expressed individually, unlike erbB2 and erbB3 [PMID:9772300].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; in vitro binding, ErbB4-expressing cells, breast cancer cells and 32D transfectants [PMID:9275162][PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag]; expression restricted to the nervous system [PMID:9275162].","caveats":"Both papers abstract only; no affinity. GtoPdb record lists no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"9275162","why":"NRG3 binds and activates ErbB4"},{"PMID":"9772300","why":"NRG-3 activates erbB4 individually"}],"covers":["LR001151","LR004560"]},"LR010716":{"pair":"NRG4 -> ERBB2:ERBB4","headline":"NRG4 acts through ERBB4; the ERBB2:ERBB4 complex row is supported only through ERBB4.","interaction_type":"functional only","direction_and_effect":"An NRG-4 EGF-like peptide induced growth of interleukin-dependent cells expressing ErbB-4 [PMID:10348342].","molecular_requirements":"Cells expressing the other three ErbB proteins or their combinations did not respond, so ErbB-4 acts without ErbB2 and the ERBB2 member is not supported [PMID:10348342].","affinity_potency":[],"species_and_systems":"Human receptors ectopically expressed in interleukin-dependent cells; synthetic peptide [PMID:10348342].","localisation_and_range":"Pro-NRG-4 is described as a transmembrane protein [PMID:10348342]; flags mark it secreted and transmembrane [flag].","caveats":"Abstract only. Reactome ERBB4 binding records are generic NRG/EGF-like ligand entries [DB:Reactome]. GtoPdb lists NRG4-ERBB4 only [DB:GtoPdb]. No affinity.","key_references":[{"PMID":"10348342","why":"NRG-4 acts selectively through ErbB-4"}],"covers":["LR010716"]},"LR006243":{"pair":"NRXN1 -> LRRTM2","headline":"Well supported: LRRTM2 binds neurexins lacking the SS4 insert by affinity chromatography and cell binding; confirmed again in 2024.","interaction_type":"direct binding","direction_and_effect":"Neurexins were identified as LRRTM2 ligands; binding can produce cell-adhesion junctions and recombinant neurexin-1beta blocks LRRTM2-induced presynaptic differentiation [PMID:20064387]. Nrxn1beta-Fc bound cells expressing AP-LRRTM2 [PMID:39394199].","molecular_requirements":"LRRTM2 binds only neurexins lacking an insert at splice site 4 [PMID:20064387]. A mutation in the LRRTM2 C-terminal cap (EQ) abolished Nrxn1beta-Fc binding, while DT/AA reduced it by 50% [PMID:39394199].","affinity_potency":[],"species_and_systems":"Rat brain affinity chromatography and HEK293 cell binding [PMID:20064387]; 39394199 used human-labelled cell binding with a mouse cKO model. Human pair is ortholog-inferred.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic, contact-dependent.","caveats":"20064387 was read as abstract plus excerpts; no affinity value in our evidence.","key_references":[{"PMID":"20064387","why":"identifies neurexins as LRRTM2 ligands, SS4-dependent"},{"PMID":"39394199","why":"Nrxn1beta-Fc binding to LRRTM2 and its mutational dependence"}],"covers":["LR003019","LR006243"]},"LR006252":{"pair":"NRXN2 -> NLGN2","headline":"Binding of NRXN2 to NLGN2 is used as a readout in cell binding assays; support is abstract-only and indirect.","interaction_type":"direct binding","direction_and_effect":"Truncated NRXN proteins fail to bind LRRTM2 or NLGN2 in cell binding assays, implying wild-type binding [PMID:21424692]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human experiments (curator-assigned species) with cell binding assays and neuron co-culture; abstract only [PMID:21424692]. Mouse pair is listed too.","localisation_and_range":"Both partners flagged transmembrane, non-secreted [flag].","caveats":"The paper is a resequencing study of ASD/SCZ/ID cohorts; NLGN2 binding is a functional readout of mutants, not a binding characterisation. Read as abstract only [PMID:21424692].","key_references":[{"PMID":"21424692","why":"Truncating NRXN mutations lose NLGN2 and LRRTM2 binding"}],"covers":["LR003028","LR006252"]},"LR001158":{"pair":"NTF3 -> NTRK2","headline":"NT-3 binds and activates TrkB as a non-cognate ligand, via Arg-31/His-33; support is abstract-only.","interaction_type":"direct binding","direction_and_effect":"NT-3 can to some extent bind and activate non-cognate TrkA and TrkB; Arg31/His33-to-Ala mutation greatly diminished binding and activation of TrkB [PMID:8621424].","molecular_requirements":"The binding site on TrkA/TrkB is dominated by Arg-31 and His-33, the same residues used for p75LNGFR binding; the cognate TrkC was unaffected [PMID:8621424].","affinity_potency":[],"species_and_systems":"Human experiment species per curator; abstract only [PMID:8621424]. Mouse pair is ortholog-inferred.","localisation_and_range":"NTF3 flagged secreted, NTRK2 transmembrane [flag].","caveats":"The abstract says the physiological relevance of NT-3 binding to TrkA/TrkB is unclear [PMID:8621424]. The verified evidence is mutational loss of binding. No numeric affinity. One review-only row is not shown.","key_references":[{"PMID":"8621424","why":"Arg31/His33 determine NT-3 binding to TrkA/TrkB"}],"covers":["LR001158","LR004567"]},"LR001167":{"pair":"NTN1 -> UNC5C","headline":"Netrin-1 binds UNC5 family fragments by pull-down with human protein; UNC5C is not named individually in the evidence.","interaction_type":"direct binding","direction_and_effect":"Human soluble netrin binds each immunoglobulin repeat of UNC5 in a pull-down assay [PMID:12810718]. UniProt notes netrin-1 binding may dissociate UNC5C from TUBB3 and lead to axon repulsion [DB:UniProt].","molecular_requirements":"UNC5 binds soluble netrin with 1:1 stoichiometry in solution; no evidence of a ternary complex of netrin, DCC and UNC5 [PMID:12810718].","affinity_potency":[],"species_and_systems":"In vitro pull-down with human netrin purified from CHO cells [PMID:12810718]. Reactome lists NTN1:UNC5C complexes [DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5C is transmembrane [flag].","caveats":"Abstract read only, and it refers to the UNC5 family generally rather than UNC5C. Two other rows are abstract_insufficient and one retracted, not shown.","key_references":[{"PMID":"12810718","why":"Netrin pull-down with UNC5 receptor fragments"}],"covers":["LR001167","LR004576"]},"LR006261":{"pair":"NTN3 -> UNC5B","headline":"Murine netrin-3 binds the UNC5 family in one abstract-only paper; UNC5B is not named individually.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds the UNC5 family (UNC5H1, UNC5H2 and UNC5H3) with higher affinity than it binds DCC [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine netrin-3 protein; human pair is ortholog-inferred and the mouse pair too [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and the receptor transmembrane [flag].","caveats":"Abstract only. The evidence sentence names UNC5H1-3, and the mapping to this specific receptor is not stated in the abstract. No numbers are reported.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binds UNC5 family receptors"}],"covers":["LR003037","LR006261"]},"LR003039":{"pair":"NTN4 -> ITGA6","headline":"Netrin-4 binds alpha6beta1 integrin dose-dependently in endothelial cells; one abstract-only paper, no chain-specific data.","interaction_type":"direct binding","direction_and_effect":"Alpha6beta1 integrin binds netrin-4 in a dose-dependent manner; inhibiting alpha6 or beta1 suppresses netrin-4-induced endothelial migration, adhesion, focal adhesion contact and Src-family phosphorylation [PMID:21799154].","molecular_requirements":"The binding is to the alpha6beta1 heterodimer; both the alpha6 and beta1 subunits are needed for the functional effects [PMID:21799154]. Chain-specific binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial and lymphatic endothelial cells; species is not stated in the curation record [PMID:21799154]. Pair is ortholog-inferred for both species.","localisation_and_range":"Netrin-4 is flagged secreted [flag].","caveats":"Abstract only. The ITGA6 pair is a subunit of the complex; CCC tools scoring complexes need both integrin chains.","key_references":[{"PMID":"21799154","why":"Netrin-4 binds and activates endothelial alpha6beta1 integrin"}],"covers":["LR003039","LR006263"]},"LR009411":{"pair":"NTNG2 -> LRRC4C","headline":"Little support: this pair has only a database SPR record and no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a surface plasmon resonance record for the two proteins [DB:IntAct].","localisation_and_range":"Both partners flagged not secreted, receptor transmembrane [flag].","caveats":"The pair is classed Receptor-Receptor and the only judged rows were review_only or different_entity. No papers are shown, so direction and effect are unknown.","key_references":[],"covers":["LR009411"]},"LR001176":{"pair":"NXPH1 -> NRXN1","headline":"Neurexophilin-1 binds the LNS2 domain of neurexin-1 directly, supported by crystal structures and earlier biochemical work.","interaction_type":"direct binding","direction_and_effect":"Neurexophilin was purified in a complex with neurexin I alpha by alpha-latrotoxin affinity chromatography [PMID:8699246], and neurexophilins 1 and 3 bind the second LNS domain of all three alpha-neurexins [PMID:9856994]. Crystal structures of Nxph1 with Nrxn1 LNS2 show an extensive binding interface [PMID:31566781].","molecular_requirements":"Binding needs the LNS2 domain of alpha-neurexin; all LNS2 splice variants bind in the recombinant study [PMID:9856994]. The SS2A insert increases the binding affinity [PMID:31566781]. No co-receptor is reported.","affinity_potency":[],"species_and_systems":"Recombinant proteins and knockout mice (mouse) [PMID:9856994]; rat brain purification [PMID:8699246]; structures with human/mouse constructs per curator tags [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag] binding a presynaptic transmembrane neurexin [flag][PMID:31566781]. Neurexophilin is expressed in a subpopulation of neurons, probably inhibitory interneurons [PMID:8699246].","caveats":"Affinity values are not given in the dossier text. The 1996 and 1998 papers were read as abstracts; the 1996 species is unspecified. Three of six confirmed papers are shown here.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"},{"PMID":"8699246","why":"Original co-purification of neurexophilin with neurexin I alpha"}],"covers":["LR001176","LR004585"]},"LR006270":{"pair":"OMG -> PTPRS","headline":"OMG binds PTPRS by SPR in the micromolar range in one full-text paper; no other evidence.","interaction_type":"direct binding","direction_and_effect":"OMG is the ligand and PTPRS the receptor. SPR showed micromolar-range binding of OMG to all three R2A RPTPs including PTPRS [PMID:36178190]. Functional effect is not reported in our evidence.","molecular_requirements":"PTPRS ectodomain alone; no co-receptor requirement reported in our evidence.","affinity_potency":[{"value":"micromolar range","assay":"SPR, OMG vs RPTP ectodomains","system":"recombinant human proteins","cite":"PMID:36178190"}],"species_and_systems":"Human OMG and PTPRS recombinant ectodomains, SPR [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. PTPRS carries a secreted flag as well as transmembrane and receptor flags [flag], so a shed form is possible but not shown in our evidence.","caveats":"Single paper. The PTPRS interaction came from phylogenetic homology analysis, not the screen [PMID:36178190]. No exact Kd given. No database records.","key_references":[{"PMID":"36178190","why":"SPR validation of OMG binding to R2A RPTPs"}],"covers":["LR003046","LR006270"]},"LR001185":{"pair":"ORM1 -> CCR5","headline":"AGP (ORM1) binds CCR5-dependent sites on human macrophages; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"AGP binds specifically to monocyte-derived macrophages at two sites, and an anti-CCR5 antibody against the second extracellular loop inhibited AGP binding (67%) [PMID:11336643]. AGP also inhibited binding of V3Cs and MIP-1beta to these cells [PMID:11336643]. Agonist or antagonist action on CCR5 is not reported in our evidence.","molecular_requirements":"Glycans (probably mannose residues) are partly involved in binding; heat denaturation only partly inhibited it (43%), suggesting protein-protein interaction as well [PMID:11336643].","affinity_potency":[{"value":"Kd 16 nM","assay":"AGP binding to MDM, high-affinity site","system":"human primary macrophages","cite":"PMID:11336643"},{"value":"Kd 4.9 microM","assay":"AGP binding to MDM, low-affinity site","system":"human primary macrophages","cite":"PMID:11336643"}],"species_and_systems":"Human AGP on human monocyte-derived macrophages, native cell system [PMID:11336643]. Mouse pair is projected from human.","localisation_and_range":"ORM1 is flagged secreted and CCR5 transmembrane [flag]; AGP acts as a soluble ligand on the macrophage surface.","caveats":"Abstract only. The Kd values are for binding to whole macrophages, not purified CCR5; CCR5 involvement rests on antibody inhibition (the abstract is cut off before further results). No database records.","key_references":[{"PMID":"11336643","why":"AGP binding to CCR5-expressing macrophages"}],"covers":["LR001185","LR004594"]},"LR003048":{"pair":"OSTN -> PTPRU","headline":"Osteocrin binds PTPRU by SPR after a CRISPRa screen hit; single full-text paper, no functional effect reported.","interaction_type":"direct binding","direction_and_effect":"OSTN was a hit for PTPRU in a CRISPRa enrichment screen, and SPR showed binding of human PTPRU-ECD (ligand) to human OSTN (analyte) fitted with a 1:1 model [PMID:36178190]. Agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"Only the PTPRU extracellular domain was tested; no co-receptor or subunit requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in SPR with recombinant ectodomain; the screen used cultured cells [PMID:36178190]. Mouse pair is ortholog-inferred only.","localisation_and_range":"OSTN is flagged secreted [flag]; PTPRU is a membrane receptor [flag], so paracrine signalling is plausible but not tested.","caveats":"One paper only. PTPRJ ranked top by initial score but followed a negative trajectory across rounds, so ranking alone was not trusted [PMID:36178190]. SPR affinity value is not given in the excerpts. The mouse pair has no direct evidence.","key_references":[{"PMID":"36178190","why":"CRISPRa screen plus SPR validation of OSTN-PTPRU"}],"covers":["LR003048","LR006272"]},"LR003075":{"pair":"PCDHGA9 -> PCDHGA9","headline":"Homophilic trans binding of mouse gammaA9 shown by K562 aggregation assays; support is one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Homophilic (self-self) trans interaction, not a classical ligand-to-receptor signal; no agonist or antagonist effect is reported. The paper names gammaA9 as engaging strict trans homophilic specificity and not binding gammaA8 heterophilically [PMID:25171406].","molecular_requirements":"Surface delivery of Pcdh-alpha isoforms requires cis interactions with other Pcdhs via EC6, so the species meeting across the cleft is a multimer rather than a single isoform [PMID:25171406]. Specificity sits in the EC2-EC3 recognition domains [PMID:25171406].","affinity_potency":[],"species_and_systems":"Mouse proteins in K562 cell aggregation assays [PMID:25171406]; the human pair is ortholog-inferred.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; acts by cell-cell contact (juxtacrine).","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology. Two further papers were judged abstract-insufficient.","key_references":[{"PMID":"25171406","why":"Cell aggregation and biochemistry across clustered Pcdh isoforms; names gammaA9 as homophilic."}],"covers":["LR003075","LR006298"]},"LR006306":{"pair":"PCDHGC5 -> PCDHGC5","headline":"Mouse gammaC5 forms aggregates in K562 cells, indicating homophilic binding; single full-text paper.","interaction_type":"functional only","direction_and_effect":"gammaC5 forms cell aggregates when assayed individually, consistent with homophilic trans interaction [PMID:25171406]. No agonist/antagonist effect reported.","molecular_requirements":"Not reported in our evidence beyond the family-level need for cis partners for Pcdh-alpha delivery [PMID:25171406].","affinity_potency":[],"species_and_systems":"Mouse proteins, K562 cell aggregation assay [PMID:25171406]; human pair by orthology.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent.","caveats":"Isoform pairs sharing 91-97% identity in EC2-EC3 (including gammaA8-gammaA9) do not cross-react, so paralogue substitution is invalid for this family and results do not transfer to unnamed isoforms [PMID:25171406]. Human pair is projected from mouse by orthology. Evidence is an aggregation readout, not direct binding measurement. Four other papers were abstract-insufficient.","key_references":[{"PMID":"25171406","why":"Systematic aggregation of 58 Pcdhs; gammaC5 aggregates."}],"covers":["LR003083","LR006306"]},"LR003084":{"pair":"PCSK1N -> GPR171","headline":"The proSAAS-derived peptide BigLEN activates mouse GPR171; evidence is one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"BigLEN (not LittleLEN) activates the Galphai/o-coupled GPR171 (agonist); knockdown of hypothalamic GPR171 reduced BigLEN signalling and changed food intake [PMID:24043826].","molecular_requirements":"The bioactive ligand is the processed peptide BigLEN rather than full-length PCSK1N; its four C-terminal amino acids suffice to bind and activate GPR171 [PMID:24043826].","affinity_potency":[],"species_and_systems":"Mouse hypothalamus, Neuro2A cells and mice [PMID:24043826]; human pair ortholog-inferred.","localisation_and_range":"PCSK1N is annotated secreted [flag]; the peptide acts as a secreted neuropeptide (annotation only).","caveats":"Abstract only, and binding assays are described only as ligand-binding/receptor-activity assays [PMID:24043826]. Human data not reported in our evidence.","key_references":[{"PMID":"24043826","why":"Deorphanises GPR171 as BigLEN receptor with genetic and antibody loss-of-function."}],"covers":["LR003084","LR006307"]},"LR001932":{"pair":"PDCD1LG2 -> PDCD1","headline":"PD-L2 binds PD-1 (SPR, crystal structure); a separate paper shows an additional PD-1-independent PD-L2 receptor.","interaction_type":"direct binding","direction_and_effect":"PD-L2 binds PD-1 with affinity comparable to PD-L1 but different kinetics; PD-L1 and PD-L2 compete for PD-1, and an antagonist PD-1 mAb blocks both and enhances T-cell proliferation [PMID:20587542]. A crystal structure of the human PD-1/PD-L2 complex exists [PMID:31727844]. In mouse tumour work B7DC promoted CD8 T-cell tumour rejection [PMID:12810690].","molecular_requirements":"Not reported in our evidence. The structure used a high-affinity triple-mutant PD-1, and PD-L2 binding forms a pocket in PD-1 [PMID:31727844].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells (SPR, structure) [PMID:20587542][PMID:31727844]; mouse tumour and PD-1-knockout T-cell experiments [PMID:12810690]; mouse pair listed as not ortholog-inferred.","localisation_and_range":"PD-L2 annotated secreted [flag]; the interaction is between membrane proteins in the cited work.","caveats":"The structure is of a triple-mutant PD-1 [PMID:31727844]. PMID 12810690 shows B7DC binds PD-1-deficient cells and enhances killing through a PD-1-independent route, implying another receptor; PD-1 interaction there is background [PMID:12810690]. All papers abstract-only.","key_references":[{"PMID":"20587542","why":"SPR kinetics of PD-L1 and PD-L2 binding to PD-1."},{"PMID":"31727844","why":"Crystal structure of human PD-1/PD-L2 complex."},{"PMID":"12810690","why":"Shows non-PD-1 receptor for B7DC (caveat)."}],"covers":["LR001932","LR005270"]},"LR005271":{"pair":"PDCD1LG2 -> RGMB","headline":"PD-L2 binds RGMb directly (Kd 48.5 nM) in mouse and human proteins; blocking it impairs respiratory tolerance.","interaction_type":"direct binding","direction_and_effect":"PD-L2 binds RGMb, a second receptor besides PD-1; blocking the RGMb-PD-L2 interaction impaired respiratory tolerance development by interfering with initial T-cell expansion [PMID:24752301].","molecular_requirements":"PD-L2 and BMP-2/4 bind distinct sites on RGMb; PD-L2 does not bind RGMa or RGMc, and RGMb did not bind PD-L1 [PMID:24752301].","affinity_potency":[{"value":"Kd = 48.5 nM","assay":"Biacore, RGMb with PD-L2","system":"recombinant proteins (Fig. 1e)","cite":"PMID:24752301"}],"species_and_systems":"Mouse and human proteins bind each other by ELISA, plus mouse cell conjugation assays and mouse tolerance models [PMID:24752301]; the human pair is ortholog-inferred.","localisation_and_range":"PD-L2 annotated secreted [flag]; RGMs are GPI-anchored membrane proteins and cells conjugated by surface-to-surface binding [PMID:24752301].","caveats":"Abstract-level curation with full-text excerpts. For comparison, PD-1 bound PD-L2 with Kd = 58.8 nM in the same experiment [PMID:24752301].","key_references":[{"PMID":"24752301","why":"Identifies RGMb as PD-L2 receptor with binding and functional blockade."}],"covers":["LR001933","LR005271"]},"LR004605":{"pair":"PDGFB -> PDGFRA","headline":"PDGF-B-containing dimers bind cloned human PDGFRA with high affinity; databases add further support.","interaction_type":"direct binding","direction_and_effect":"The cloned human PDGF A-type receptor in COS cells bound 125I-labelled AA, AB and BB PDGF dimers with high affinity [PMID:2544881]; curated effect is Stimulatory. UniProt/IntAct hold competition-binding and cross-linking records [DB:IntAct].","molecular_requirements":"Binding was to BB homodimer and AB heterodimer forms; no other subunit requirement reported [PMID:2544881].","affinity_potency":[],"species_and_systems":"Human receptor in COS cells, radioligand binding [PMID:2544881]; mouse pair ortholog-inferred.","localisation_and_range":"PDGFB annotated secreted [flag].","caveats":"Single abstract-only paper; no Kd in our evidence. Four review-only rows are not shown.","key_references":[{"PMID":"2544881","why":"Radioligand binding of PDGF dimers to cloned PDGFRA."}],"covers":["LR001196","LR004605"]},"LR006315":{"pair":"PECAM1 -> ITGB3","headline":"CD31 binds integrin alpha v beta 3, which includes ITGB3, in human leukocyte adhesion and precipitation experiments.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD31 precipitated alpha v beta 3 from cell lysates and leukocyte adhesion through CD31's second Ig-like domain was inhibited by alpha v beta 3 antibodies [PMID:7542249]. Reactome has an integrin alphaVbeta3:PECAM1 complex [DB:Reactome]; BioGRID has a co-localization record [DB:BioGRID].","molecular_requirements":"The receptor is the alpha v beta 3 heterodimer, so ITGAV is also needed [PMID:7542249].","affinity_potency":[],"species_and_systems":"Human leukocytes and LAK lysates; abstract and some full text [PMID:7542249].","localisation_and_range":"PECAM1 is a membrane protein [flag]; recombinant soluble form used in vitro [PMID:7542249].","caveats":"No affinity in our evidence. The evidence concerns the heterodimer, not ITGB3 alone. Human pair is ortholog-inferred.","key_references":[{"PMID":"7542249","why":"CD31 binds integrin alpha v beta 3"}],"covers":["LR003092","LR006315"]},"LR003093":{"pair":"PECAM1 -> PECAM1","headline":"Homophilic PECAM1 self-binding mapped to Ig domains 1-2 in one abstract-only aggregation study; databases add reconstituted-complex records.","interaction_type":"direct binding","direction_and_effect":"PECAM1 binds itself (homophilic adhesion); the curator labels the effect agonist [PMID:8702505].","molecular_requirements":"Homophilic binding involves the first two extracellular Ig-like domains; the cytoplasmic domain (exons 9-10 for minimal length) and surface expression level shift aggregation between homophilic and heterophilic modes [PMID:8702505].","affinity_potency":[],"species_and_systems":"Cell aggregation assay in L-cells expressing human, murine and chimeric PECAM-1; experiments were in vitro [PMID:8702505]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound receptor, not secreted [flag]; homophilic contact between cells is implied by the aggregation assay [PMID:8702505].","caveats":"Single paper, read as abstract only. The same abstract reports heterophilic, calcium-dependent aggregation under some conditions. BioGRID, IntAct and Reactome records exist (reconstituted complex, solid phase assay, trans-homophilic interaction) [DB:BioGRID] [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"8702505","why":"Domain mapping of homophilic PECAM-1 binding"}],"covers":["LR003093","LR006316"]},"LR004614":{"pair":"PENK -> OGFR","headline":"One abstract-only paper: [Met5]-enkephalin (OGF) and OGFR form an inhibitory growth axis in human pancreatic cancer cells.","interaction_type":"functional only","direction_and_effect":"OGF is described as forming an inhibitory axis with OGFr; receptor overexpression and exogenous OGF reduced cell growth, and naltrexone or anti-OGF antibodies raised cell number [PMID:17332915].","molecular_requirements":"Not reported in our evidence beyond OGFr itself.","affinity_potency":[],"species_and_systems":"Human MIA PaCa-2 cells transfected with OGFr cDNA; OGFr overexpression raised OGF binding capacity 2.3- to 5.6-fold with comparable binding affinity [PMID:17332915]. Pair is human; mouse pair is ortholog-inferred.","localisation_and_range":"PENK is flagged secreted [flag]; the paper describes an autocrine loop [PMID:17332915].","caveats":"Single paper read as abstract only. The ligand is [Met5]-enkephalin, a PENK-derived peptide, not full-length proenkephalin. Effect is growth-inhibitory; the curator labels it antagonist. No database records.","key_references":[{"PMID":"17332915","why":"OGF/OGFr inhibitory axis in pancreatic cancer cells"}],"covers":["LR001205","LR004614"]},"LR006324":{"pair":"PLA2G1B -> PLA2R1","headline":"No curated papers; support is UniProt statements that PLA2R1 binds sPLA2-IB.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states PLA2R1 acts as a receptor for sPLA2-IB/PLA2G1B but not sPLA2-IIA [DB:UniProt Q13018], and that binding can regulate podocyte survival and glomerular homeostasis [DB:UniProt P04054][DB:UniProt Q13018].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental species or system in our evidence; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"PLA2G1B carries a secreted flag [flag]; paracrine or endocrine range is not otherwise reported.","caveats":"No papers were judged (two rows were classed different_entity), so this pair rests on database annotation alone. UniProt notes selectivity against PLA2G2A [DB:UniProt Q13018].","key_references":[],"covers":["LR003103","LR006324"]},"LR001941":{"pair":"PLA2G2A -> ITGB1","headline":"sPLA2-IIA binds and activates beta1 integrins (alpha4beta1, alpha5beta1) via site 2; beta1 is one chain of the heterodimer.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound alpha4beta1 and competed with VCAM-1 [PMID:18635536]. It activated alpha4beta1 and alpha5beta1 in a site 2-mediated manner; flow cytometry showed enhanced FN8-11 binding, blocked by an S2-beta1 peptide [PMID:25398877]. Agonist.","molecular_requirements":"Beta1 pairs with alpha4 or alpha5 here; a peptide from integrin beta1 site 2 specifically bound sPLA2-IIA and suppressed activation [PMID:25398877]. Beta1 alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"The 18635536 evidence sentence does not mention beta1; the curator labels it from the title. The 25398877 full-text read is marked unverified in notes. Species: human; mouse pair ortholog-inferred.","key_references":[{"PMID":"18635536","why":"Binds alpha4beta1, competes with VCAM-1"},{"PMID":"25398877","why":"Site 2 activation of beta1 integrins"}],"covers":["LR001941","LR005278"]},"LR004623":{"pair":"Plat -> Itgam","headline":"tPA signalling needs CD11b but via annexin A2; direct tPA-CD11b contact is not shown.","interaction_type":"functional only","direction_and_effect":"tPA induced aggregation and interaction of annexin A2 with CD11b, and CD11b ablation or anti-CD11b antibody abolished tPA-induced NF-kB activation [PMID:22677557]. Knockdown of integrin-linked kinase also blocked the effect [PMID:22677557].","molecular_requirements":"Needs annexin A2 as the proximal receptor and CD11b as a required relay [PMID:22677557]; ITGB2 partner: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; macrophages and tPA-knockout mice with reduced renal NF-kB signalling and fewer macrophages [PMID:22677557]. This row is mouse-only and ortholog-inferred.","localisation_and_range":"Secreted tPA per flag [flag].","caveats":"Abstract only. CD11b acts downstream of annexin A2, so this is not direct ligand binding [PMID:22677557].","key_references":[{"PMID":"22677557","why":"CD11b required for tPA-induced NF-kB signalling"}],"covers":["LR004623"]},"LR006333":{"pair":"PLAUR -> ITGA9","headline":"Direct cell-based binding of soluble uPAR to alpha9 (ITGA9) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Paired with beta1 in the paper [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (abstract only); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003112","LR006333"]},"LR004632":{"pair":"PLG -> F3","headline":"Direct binding of plasminogen to tissue factor is shown by biosensor; one paper plus a database record.","interaction_type":"direct binding","direction_and_effect":"Plasminogen bound the TF extracellular domain (amino acids 1-219) by optical biosensor; TF-expressing CHO cells bound 70% more plasminogen [PMID:9490681]. TF enhanced two-chain uPA activation of Glu-plasminogen (half-maximal at 59pmol/L) yet inhibited fibrinolysis ~74% (14nmol/L) [PMID:9490681].","molecular_requirements":"Kringles 1-3 bound; isolated kringle 4 and miniplasminogen did not; the site differs from the factor VII/VIIa site [PMID:9490681].","affinity_potency":[{"value":"half-maximal 59pmol/L","assay":"TF enhancement of uPA activation of plasminogen (potency of enhancement, not Kd)","system":"purified components","cite":"PMID:9490681"}],"species_and_systems":"Human proteins; CHO cells transfected with TF [PMID:9490681]. BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted; TF is membrane-bound.","caveats":"Abstract only. Effects on fibrinolysis are mixed (promotes activation yet inhibits fibrinolysis). No binding Kd reported.","key_references":[{"PMID":"9490681","why":"biosensor binding of plasminogen to TF"}],"covers":["LR001229","LR004632"]},"LR006342":{"pair":"PODXL -> SELE","headline":"Sialofucosylated PODXL on pancreatic cancer cells acts as a functional E-selectin ligand in flow adhesion assays; one paper, abstract only.","interaction_type":"functional only","direction_and_effect":"PODXL is the ligand and E-selectin the receptor on endothelium-type cells; depleting sialofucosylated PODXL from the cancer cell surface significantly interferes with selectin-dependent adhesion under flow [PMID:22814396].","molecular_requirements":"The functional ligand is the sialofucosylated glycoform of PODXL, not necessarily the bare protein [PMID:22814396]. The abstract treats E- and L-selectin together.","affinity_potency":[],"species_and_systems":"Human metastatic pancreatic cancer cells, immunodepletion, shRNA and flow-based adhesion assays [PMID:22814396]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged transmembrane, not secreted [flag]; contact-dependent (juxtacrine) adhesion.","caveats":"Only one paper, read as an abstract, with E- and L-selectin not separated. No direct binding affinity reported. IntAct holds a co-immunoprecipitation record for P16581-O00592 [DB:IntAct].","key_references":[{"PMID":"22814396","why":"sialofucosylated PODXL as functional E- and L-selectin ligand"}],"covers":["LR003121","LR006342"]},"LR001239":{"pair":"POMC -> MC1R","headline":"POMC-derived melanocortins (alpha-MSH, ACTH and others) bind and activate MC1R; well supported in human and mouse-related systems.","interaction_type":"direct binding","direction_and_effect":"POMC products act as agonists at MC1R. Alpha-MSH, beta-MSH, gamma-MSH and ACTH displace a labelled MSH analogue from MC1R-transfected COS-7 cells, while beta-endorphin does not [PMID:1516719]. Alpha-MSH and ACTH bind human MC1R with equal affinity and are equipotent in mitogenic and melanogenic effects on human melanocytes [PMID:11041375].","molecular_requirements":"The active ligand is a processed POMC peptide, not full-length POMC. MC1R alone binds in transfected cells [PMID:1516719]. MC1R has higher affinity for alpha-MSH than gamma-MSH and beta-MSH [PMID:7774675]. MC1R variants alter alpha-MSH responsiveness [PMID:11041375].","affinity_potency":[{"value":"Kd 85.1 +/- 8.0 pmol/l","assay":"[125I][Nle4,D-Phe7]alpha-MSH saturation binding (analogue, not native peptide)","system":"COS cells expressing MC1R","cite":"PMID:7774675"}],"species_and_systems":"Human receptor in COS-7/COS cells and human melanocytes [PMID:1516719][PMID:11041375][PMID:7774675]. The mouse pair is ortholog-inferred.","localisation_and_range":"POMC flagged secreted and MC1R transmembrane [flag]; secreted peptide acting on a cell-surface receptor.","caveats":"ACTH has a much lower affinity for MC1R than reported earlier once breakdown to alpha-MSH is blocked [PMID:7774675], which partly conflicts with equal-affinity claims [PMID:11041375]. All papers read as abstracts. The reported Kd is for an analogue radioligand.","key_references":[{"PMID":"1516719","why":"MC1R cloning; melanotropic POMC peptides displace binding"},{"PMID":"7774675","why":"ligand binding profile of MC1R, MC3R and MC5R"},{"PMID":"11041375","why":"alpha-MSH and ACTH at human MC1R"}],"covers":["LR001239","LR004641"]},"LR004641":{"pair":"POMC -> MC1R","headline":"POMC-derived melanocortins (alpha-MSH, ACTH and others) bind and activate MC1R; well supported in human and mouse-related systems.","interaction_type":"direct binding","direction_and_effect":"POMC products act as agonists at MC1R. Alpha-MSH, beta-MSH, gamma-MSH and ACTH displace a labelled MSH analogue from MC1R-transfected COS-7 cells, while beta-endorphin does not [PMID:1516719]. Alpha-MSH and ACTH bind human MC1R with equal affinity and are equipotent in mitogenic and melanogenic effects on human melanocytes [PMID:11041375].","molecular_requirements":"The active ligand is a processed POMC peptide, not full-length POMC. MC1R alone binds in transfected cells [PMID:1516719]. MC1R has higher affinity for alpha-MSH than gamma-MSH and beta-MSH [PMID:7774675]. MC1R variants alter alpha-MSH responsiveness [PMID:11041375].","affinity_potency":[{"value":"Kd 85.1 +/- 8.0 pmol/l","assay":"[125I][Nle4,D-Phe7]alpha-MSH saturation binding (analogue, not native peptide)","system":"COS cells expressing MC1R","cite":"PMID:7774675"}],"species_and_systems":"Human receptor in COS-7/COS cells and human melanocytes [PMID:1516719][PMID:11041375][PMID:7774675]. The mouse pair is ortholog-inferred.","localisation_and_range":"POMC flagged secreted and MC1R transmembrane [flag]; secreted peptide acting on a cell-surface receptor.","caveats":"ACTH has a much lower affinity for MC1R than reported earlier once breakdown to alpha-MSH is blocked [PMID:7774675], which partly conflicts with equal-affinity claims [PMID:11041375]. All papers read as abstracts. The reported Kd is for an analogue radioligand.","key_references":[{"PMID":"1516719","why":"MC1R cloning; melanotropic POMC peptides displace binding"},{"PMID":"7774675","why":"ligand binding profile of MC1R, MC3R and MC5R"},{"PMID":"11041375","why":"alpha-MSH and ACTH at human MC1R"}],"covers":["LR001239","LR004641"]},"LR001248":{"pair":"PPBP -> CXCR2","headline":"NAP-2 (PPBP) is a high-affinity, potent agonist of CXCR2 shown by binding and calcium-flux assays.","interaction_type":"direct binding","direction_and_effect":"CXCR2-transfected Jurkat cells bound all three chemokines with high affinity [PMID:8137938]. CXCR2 binds NAP-2 with equally high affinity as IL-8 [PMID:8195702]. In HEK293 calcium flux, NAP-2 acts as an agonist at IL8RB (CXCR2) with EC50 7 nM [PMID:8702798]. GtoPdb records a full agonist [DB:GtoPdb]. A CXCR1/2 inhibitor blocks CXCL7-driven ccRCC growth in nude mice [PMID:24335961].","molecular_requirements":"Not reported in our evidence beyond receptor chain CXCR2 alone being sufficient in transfected cells.","affinity_potency":[{"value":"EC50 7 nM","assay":"calcium flux","system":"HEK293 cells with IL8RB (CXCR2)","cite":"PMID:8702798"},{"value":"pIC50 6.3-9.3","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:8702798"}],"species_and_systems":"Human receptors in transfected Jurkat, COS-1 and HEK293 cells [PMID:8137938][PMID:8195702][PMID:8702798]; nude mice [PMID:24335961]. Mouse pair is ortholog-inferred. All read as abstracts.","localisation_and_range":"PPBP flagged secreted [flag]; chemoattractant (paracrine) action per assays [PMID:8702798].","caveats":"The in vivo paper uses a dual CXCR1/CXCR2 inhibitor and cannot attribute the effect to CXCR2 alone [PMID:24335961]. KD ~2 nM comes from a curator note rather than the abstract text shown [PMID:8195702]. The dossier does not give mouse experiments.","key_references":[{"PMID":"8702798","why":"CXCR2 agonist potency and competition binding for NAP-2"},{"PMID":"8195702","why":"High-affinity NAP-2 binding at CXCR2"},{"PMID":"8137938","why":"High-affinity binding in CXCR2 Jurkat transfectants"}],"covers":["LR001248","LR004649"]},"LR003129":{"pair":"PPIA -> BSG","headline":"Extracellular PPIA is an established BSG ligand per database records, with a 2012 cell paper showing BSG is involved but not the only receptor.","interaction_type":"direct binding","direction_and_effect":"UniProt describes BSG as a signalling receptor for cyclophilins, essential for PPIA-dependent signalling [DB:UniProt]; Reactome has a BSG:PPIA complex [DB:Reactome]; IntAct and BioGRID record co-IP, affinity capture and chromatography [DB:IntAct][DB:BioGRID]. In cell assays, extracellular PPIA signals via multiple receptors beyond BSG, and BSG knockdown affected some responses [PMID:22631225].","molecular_requirements":"BSG alone is not sufficient to explain PPIA activity; other unidentified receptors are implicated [PMID:22631225].","affinity_potency":[],"species_and_systems":"Human cell lines with recombinant PPIA [PMID:22631225]; mouse pair is ortholog-inferred. The paper was read as abstract with full-text excerpts.","localisation_and_range":"PPIA is flagged secreted and BSG transmembrane [flag]; extracellular PPIA acts on cells in culture [PMID:22631225].","caveats":"The one paper shown is background on BSG and shows it is not the sole receptor; no affinity reported. Binding support is mainly from databases.","key_references":[{"PMID":"22631225","why":"Extracellular PPIA signals through BSG and other receptors"}],"covers":["LR003129","LR006350"]},"LR004650":{"pair":"PPY -> NPY1R","headline":"Weak, indirect support: one abstract-only paper uses PP as a Y1 reference; UniProt says Y1 has virtually no affinity for PP.","interaction_type":"conflicting","direction_and_effect":"The one confirmed paper states PP is highly selective for Y4 while NPY has highest affinities for Y1, Y2 and Y5; no PP effect at Y1 is described [PMID:15966750]. UniProt states Y1 has virtually no affinity for PP at physiological concentrations [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptors per the curator; the work is chimeric-peptide structure-affinity studies [PMID:15966750]. Mouse pair is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY1R transmembrane [flag].","caveats":"Abstract-only evidence, and it is a selectivity statement rather than a measured PP-Y1 interaction. The paper's PP-segment chimeras show PP is a poor Y1 ligand [PMID:15966750]. Reactome only records a generic reaction that NPY receptors bind NPY-related peptides [DB:Reactome]. Treat as likely a negligible PP-Y1 interaction.","key_references":[{"PMID":"15966750","why":"PP/NPY chimera affinity study; PP selective for Y4"}],"covers":["LR001249","LR004650"]},"LR006351":{"pair":"PRG4 -> CD44","headline":"Direct binding of recombinant human PRG4 to CD44 by ELISA and SPR, competing with hyaluronan; one paper, antiproliferative effect depends on CD44.","interaction_type":"direct binding","direction_and_effect":"Recombinant human PRG4 bound CD44 and interfered with HMW hyaluronic acid binding to CD44 [PMID:25708025]. PRG4 suppressed IL-1beta- and TNFalpha-induced proliferation of RA synoviocytes, reversed by a CD44 antibody, so it acts as a competing ligand [PMID:25708025].","molecular_requirements":"Removing sialic acid and O-glycosylations increased CD44 binding by rhPRG4 (P < 0.001) [PMID:25708025]. Binding used recombinant CD44-IgG1Fc; no co-receptor is reported.","affinity_potency":[],"species_and_systems":"Recombinant human PRG4 (CHO-produced) and recombinant CD44; functional work in human RA fibroblast-like synoviocytes and in PRG4-/- mouse synoviocytes [PMID:25708025]. Mouse pair is projected.","localisation_and_range":"PRG4 is flagged secreted [flag]; the paper describes it as a mucinous glycoprotein secreted by synovial fibroblasts and chondrocytes [PMID:25708025]. CD44 is flagged transmembrane [flag].","caveats":"Single paper; the curator read the abstract and the full-text excerpts show methods but no affinity value in our evidence [PMID:25708025]. The effect is antagonist-like relative to hyaluronan, not a classic agonist.","key_references":[{"PMID":"25708025","why":"rhPRG4 binds CD44 by ELISA/SPR, competes with HA"}],"covers":["LR003130","LR006351"]},"LR005280":{"pair":"PRG4 -> TLR2","headline":"Direct binding of PRG4 to TLR2 by ELISA with inhibitory effect on TLR2 activation; one paper, human recombinant system.","interaction_type":"direct binding","direction_and_effect":"Recombinant and native human PRG4 showed concentration-dependent binding to TLR2 by ELISA, and nhPRG4 inhibited TLR2 activation by its agonist and by OA and RA synovial fluid; the paper classes PRG4 as an antagonist [PMID:26643105]. Immunodepleting PRG4 from synovial fluid increased TLR2 activation [PMID:26643105].","molecular_requirements":"Not reported in our evidence; binding used immobilised receptor protein, and activity was read in receptor-expressing HEK cells [PMID:26643105].","affinity_potency":[],"species_and_systems":"Human recombinant and native PRG4, TLR-overexpressing HEK cells and patient OA/RA synovial fluid [PMID:26643105]. Mouse pair is projected.","localisation_and_range":"PRG4 is flagged secreted [flag] and described as secreted by synovial fibroblasts and chondrocytes [PMID:26643105].","caveats":"One paper only; no affinity value reported in our evidence. Effect is inhibition of agonist-driven activation, not receptor activation.","key_references":[{"PMID":"26643105","why":"PRG4 binds TLR2 and TLR4 and reduces their activation"}],"covers":["LR001943","LR005280"]},"LR001257":{"pair":"PROK1 -> PROKR1","headline":"Well supported agonist-receptor pair: PROK1 binds and activates PROKR1 in transfected cells; evidence from abstracts only.","interaction_type":"direct binding","direction_and_effect":"PROK1 and PROK2 bound and activated the receptors, with nanomolar calcium responses in CHO cells expressing PK-R1 [PMID:12054613]. Activation mobilised calcium, stimulated phosphoinositide turnover and p44/p42 MAPK [PMID:11886876]. PK1 stimulated Ca2+ responses in PKR1 cells; PKRs also couple to Gq and Gi and induce cAMP accumulation [PMID:15772293]. GtoPdb lists PROK1 at PROKR1 as full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; single receptor chain used in heterologous expression [PMID:11886876].","affinity_potency":[],"species_and_systems":"Human protein experiments in heterologous cells (CHO, recombinant) [PMID:11886876][PMID:12054613][PMID:15772293]; mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Both PROK1 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"All three papers read as abstracts only. Receptor selectivity between PKR1 and PKR2 is not quantified in the abstract [PMID:12054613]. GtoPdb affinities are given as pIC50 ranges without a stated assay [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"Deorphanisation: high-affinity binding and calcium responses in CHO cells."},{"PMID":"11886876","why":"Receptors bind and are activated by nanomolar recombinant prokineticins."},{"PMID":"15772293","why":"PK1 Ca2+ responses in PKR1 cells as pharmacological reference."}],"covers":["LR001257","LR004657"]},"LR001266":{"pair":"PSPN -> GFRA1","headline":"Persephin was reported to signal through GFRalpha1/RET in reporter assays; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Persephin is identified as a novel ligand for the GFRalpha1/RET receptor complex, confirmed by several methods including neurite outgrowth [PMID:20350599].","molecular_requirements":"Functions with RET in the GFRalpha1/RET complex [PMID:20350599].","affinity_potency":[],"species_and_systems":"Reporter-gene system and neurite outgrowth from sympathetic ganglion explants; species not specified [PMID:20350599].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only; no binding measurement or affinity; species unspecified. The same paper treats GFRalpha4 as persephin's conventional receptor [PMID:20350599].","key_references":[{"PMID":"20350599","why":"Reporter-gene identification of PSPN as GFRalpha1/RET ligand."}],"covers":["LR001266","LR004666"]},"LR001275":{"pair":"PTN -> ALK","headline":"Reported high-affinity PTN-ALK binding and signalling, supported by databases, but the curators note the ligand role was later disputed.","interaction_type":"direct binding","direction_and_effect":"PTN binds the ALK extracellular domain and induces phosphorylation of ALK and of IRS-1, Shc, phospholipase C-gamma and phosphatidylinositol 3-kinase, so it acts as an activating ligand [PMID:11278720]. Reactome and UniProt record the binding [DB:Reactome R-HSA-201486] [DB:UniProt].","molecular_requirements":"The ALK extracellular domain is sufficient for binding; binding was blocked by excess ALK ECD [PMID:11278720]. Co-receptors are not reported in our evidence.","affinity_potency":[{"value":"Kd 32 +/- 9 pm","assay":"cell-free and intact-cell radioligand binding","system":"human PTN and ALK","cite":"PMID:11278720"}],"species_and_systems":"Human, recombinant and cell-line assays [PMID:11278720]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. ALK is flagged as transmembrane [flag].","caveats":"Two papers are confirmed (one shown) and two rows are review_only. The curator note says PTN as an ALK ligand was disputed by later work, with other ligands now considered physiological [PMID:11278720]; this note is not from the paper itself.","key_references":[{"PMID":"11278720","why":"Phage display, Kd and phosphorylation evidence for PTN-ALK"}],"covers":["LR001275","LR004675"]},"LR003147":{"pair":"PTN -> ITGB2","headline":"PTN directly binds the alphaM I domain of Mac-1 (alphaMbeta2); evidence concerns the ITGAM chain, so ITGB2 support is by complex.","interaction_type":"direct binding","direction_and_effect":"PTN engages Mac-1 (CD11b-CD18) as a receptor for macrophage adhesion and migration, with Erk1/2 phosphorylation [PMID:28939773].","molecular_requirements":"Direct binding was shown with the alphaMI domain, which is on the alphaM chain, not beta2 [PMID:28939773]. Mac-1 cooperates with cell-surface proteoglycans, since anti-Mac-1 mAb and heparin were both required to block adhesion [PMID:28939773].","affinity_potency":[],"species_and_systems":"Human; HEK293 cells expressing Mac-1 and recombinant proteins [PMID:28939773]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Abstract only; no affinity. The experimental contact is on ITGAM, so ITGB2 alone is not shown to bind PTN; CCC tools scoring ITGB2 should treat it as a subunit of Mac-1. No database records for this exact chain.","key_references":[{"PMID":"28939773","why":"PTN-Mac-1 adhesion and alphaMI binding"}],"covers":["LR003147","LR006368"]},"LR009060":{"pair":"PTN -> PTPRS","headline":"Database-only pair from a two-hybrid pooling screen; no papers confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; IntAct record only [DB:IntAct].","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. PTPRS is flagged as transmembrane [flag].","caveats":"One review_only row and a high-throughput two-hybrid IntAct record [DB:IntAct]; no validation or functional data.","key_references":[],"covers":["LR009060"]},"LR003156":{"pair":"PTPRD -> IL1RAP","headline":"Supported by trans-synaptic binding data and a crystal structure with PTPdelta; splice-variant dependent.","interaction_type":"direct binding","direction_and_effect":"PTPdelta binds IL-1RAcP across the synapse and bidirectionally induces pre- and postsynaptic differentiation [PMID:25908590]. IL-1RAcP interacted with PTPdelta through its extracellular domain in cultured cortical neurons [PMID:22357843].","molecular_requirements":"Specificity set by PTPdelta splice inserts; IL-1RAcP interacts via its Ig1 domain and the Ig3 domain does not contact PTPdelta in the complex [PMID:25908590]. Both IL-1RAcP isoforms differ in C-terminus [PMID:22357843].","affinity_potency":[],"species_and_systems":"Crystal structures and neuron assays [PMID:25908590]; cultured cortical neurons, species not specified [PMID:22357843].","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic, contact-dependent.","caveats":"Abstract-level curation; no affinity for IL-1RAcP in our evidence. Reactome and BioGRID records support the pair [DB:Reactome, DB:BioGRID].","key_references":[{"PMID":"25908590","why":"crystal structure of PTPdelta with IL-1RAcP and IL1RAPL1"},{"PMID":"22357843","why":"IL-1RAcP interacts with PTPdelta ectodomain"}],"covers":["LR003156","LR006377"]},"LR003165":{"pair":"PTPRG -> CNTN4","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN4 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN4 flagged secreted, PTPRG not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. The only co-complex structure in the abstract is CNTN4 with PTPRG, so this is the best-supported member.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003165","LR006386"]},"LR001950":{"pair":"PTPRM -> PTPRM","headline":"PTPRM binds itself (homophilic) in recombinant, bead and cell-surface assays; one primary paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"PTPmu mediates aggregation via a homophilic mechanism: PTPmu-coated beads bound endogenous PTPmu on MvLu cells and a GST fusion of the PTPmu extracellular segment, suggesting the ligand is another PTPmu molecule on an adjacent cell [PMID:8394372].","molecular_requirements":"Expression with or without the PTPase domains induced aggregation, but a chimera with the EGF receptor extracellular segment, or the soluble intracellular segment, did not, so the extracellular segment is required [PMID:8394372].","affinity_potency":[],"species_and_systems":"Human PTPmu expressed in Sf9 insect cells by baculovirus; MvLu cells for native PTPmu [PMID:8394372]. The mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound, contact-dependent trans-homophilic binding [PMID:8394372].","caveats":"Self-pair (one protein is both ligand and receptor). Paper read as abstract in the judged row; no affinity reported. IntAct co-IP and dimerization assay records exist [DB:IntAct].","key_references":[{"PMID":"8394372","why":"Homophilic PTPmu binding mediates cell aggregation"}],"covers":["LR001950","LR005286"]},"LR003174":{"pair":"PTPRZ1 -> CNTN2","headline":"Phosphacan (PTPRZ1) was found to bind TAG-1/axonin-1 (CNTN2) with high affinity in one 1996 abstract; no structure.","interaction_type":"direct binding","direction_and_effect":"Phosphacan/PTP-zeta/beta was a high-affinity ligand of TAG-1/axonin-1; binding fell by about 70% after chondroitinase treatment, so chondroitin sulfate chains contribute, but N-deglycosylation had no effect [PMID:8663515].","molecular_requirements":"The phosphacan form, a chondroitin sulfate proteoglycan, was tested; the chondroitin sulfate chains contribute to binding [PMID:8663515]. Whether full-length receptor-type PTPRZ1 binds is not reported.","affinity_potency":[{"value":"Kd 0.04 nM","assay":"binding of phosphacan to TAG-1/axonin-1 (reported as dissociation constant)","system":"nervous-tissue proteoglycan and TAG-1/axonin-1","cite":"PMID:8663515"}],"species_and_systems":"Species is not stated in the abstract; the curated row lists human, but the dossier shows no basis for that [PMID:8663515]. Both pairs are ortholog-inferred.","localisation_and_range":"PTPRZ1 is flagged secreted [flag]; phosphacan is the secreted proteoglycan form.","caveats":"Abstract-only evidence from one paper and the assay type is not stated beyond 'dissociation constants'. Phosphacan is a processed form, not the receptor-type isoform.","key_references":[{"PMID":"8663515","why":"Phosphacan binds TAG-1/axonin-1 with Kd 0.04 nM"}],"covers":["LR003174","LR006395"]},"LR001284":{"pair":"QRFP -> QRFPR","headline":"QRFP is the cognate agonist of QRFPR (GPR103), supported by binding, cryo-EM structure, and databases in human and mouse.","interaction_type":"direct binding","direction_and_effect":"QRFP selectively activates GPR103 [PMID:38897996]; it is a full agonist in GtoPdb [DB:GtoPdb]. In mice, central QRFP induced feeding behaviour, blocked by a Y1 antagonist [PMID:16648250].","molecular_requirements":"Cryo-EM complex of QRFP26 with GPR103 and G protein (mini-Gsqi\u03b21\u03b32); QRFP26 residues 3-26 were modelled [PMID:38897996]. The extended QRFP form was more active (P518) [PMID:12714592].","affinity_potency":[{"value":"EC50 = 7 nm","assay":"activation of receptor-transfected cells by extended peptide P518","system":"SP9155 (GPR103) transfected cells","cite":"PMID:12714592"}],"species_and_systems":"Human GPR103 (cryo-EM, deorphanisation) [PMID:38897996][PMID:12714592]; mouse GPR103A and GPR103B and rat-derived QRFP in transfected cells and mice [PMID:16648250]. PDB 8ZH8 and Reactome records exist [DB:PDB 8ZH8][DB:Reactome].","localisation_and_range":"QRFP is flagged secreted [flag]; mRNA in hypothalamus, with central actions [PMID:16648250].","caveats":"PMID:38897996 and PMID:16648250 abstract only; the structure abstract is truncated. PMID:16648250 gives nanomolar affinities without numbers. Three rows are pending and one review only.","key_references":[{"PMID":"12714592","why":"Deorphanisation; EC50 7 nm"},{"PMID":"16648250","why":"QRFP purified from rat brain; human and mouse receptors"},{"PMID":"38897996","why":"Cryo-EM structure of QRFP26-GPR103-G protein"}],"covers":["LR001284","LR004684"]},"LR001293":{"pair":"RELN -> VLDLR","headline":"Reelin binds VLDLR directly with a reported sub-nM to low-nM affinity and signals via Dab1; multiple primary papers.","interaction_type":"direct binding","direction_and_effect":"Reelin binds VLDLR and ApoER2 directly, calcium-dependently, and is internalised after VLDLR binding [PMID:10571240]. In a full-text paper, Reelin bound the VLDLR ectodomain, RAP and EDTA blocked binding, and blocking reduced Dab1 phosphorylation (agonist) [PMID:10571241]. Reactome has a VLDLR-RELN binding reaction [DB:Reactome R-HSA-8854466].","molecular_requirements":"Binding was to the receptor ectodomain; neither receptor bound the isolated N-terminal Reelin domain, so other parts of Reelin are needed [PMID:10571241]. ApoER2 is also a Reelin receptor [PMID:10571241].","affinity_potency":[{"value":"Kd ~500 pM","assay":"co-IP/pull-down with VLDLR ectodomain-Fc","system":"human VLDLR ectodomain","cite":"PMID:10571241"},{"value":"KD 1.2 nM","assay":"surface plasmon resonance","system":"human proteins","cite":"PMID:12899622"}],"species_and_systems":"Human VLDLR ectodomain with Reelin from culture supernatant [PMID:10571241]; mouse/human ligand with human receptor [PMID:10571240]; SPR, human [PMID:12899622].","localisation_and_range":"RELN is flagged secreted [flag]. VLDLR is flagged transmembrane [flag].","caveats":"Two of the three papers were read as abstracts. ApoER2 has about 6-fold higher affinity than VLDLR (0.2 vs 1.2 nM) [PMID:12899622]. Two further papers were abstract_insufficient and one is pending (outcome counts).","key_references":[{"PMID":"10571241","why":"Full-text direct binding to VLDLR ectodomain, Kd ~500 pM"},{"PMID":"12899622","why":"SPR KD 1.2 nM for VLDLR"},{"PMID":"10571240","why":"Direct binding to lipoprotein receptors"}],"covers":["LR001293","LR004692"]},"LR006405":{"pair":"RETN -> TLR4","headline":"Resistin competes with LPS for TLR4 and activates it in human cells; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Resistin co-precipitated with TLR4 and competes with LPS for binding; anti-TLR4 antibodies abolished resistin binding to leucocytes, and TLR4-transfected HEK293 cells responded (agonist) [PMID:19754671].","molecular_requirements":"TLR4-transfected but not MD2/CD14-, TLR2-, or untransfected HEK293 cells responded; TLR4/MyD88 signalling was involved [PMID:19754671].","affinity_potency":[],"species_and_systems":"Human myeloid/epithelial cells, PBMC and HEK293 with recombinant resistin [PMID:19754671]. The mouse pair is ortholog-inferred.","localisation_and_range":"RETN is flagged secreted [flag].","caveats":"Abstract-only reading; no affinity reported; a single paper.","key_references":[{"PMID":"19754671","why":"Resistin competes with LPS for TLR4 binding"}],"covers":["LR003185","LR006405"]},"LR012363":{"pair":"RNF43 -> FZD10:LRP6","headline":"RNF43 -> FZD10:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 2). ","key_references":[],"covers":["LR012363"]},"LR012147":{"pair":"RNF43 -> FZD5:LRP5","headline":"RNF43 -> FZD5:LRP5 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists RNF43-FZD5 affinity-capture or PCA records [DB:BioGRID]; UniProt notes RNF43 interacts with FZD5 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Only the FZD5 chain has database support; the LRP co-receptor part has none in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: pending 2). Two papers are still pending.","key_references":[],"covers":["LR012147"]},"LR003192":{"pair":"ROBO2 -> ROBO1","headline":"ROBO2 and ROBO1 ectodomains interact; reverse-direction row of the same abstract-only observation.","interaction_type":"direct binding","direction_and_effect":"Robo1 and Robo2 extracellular domains are homophilic adhesion molecules that can also interact with each other [PMID:12504588]. Direction is a formality; no agonist or antagonist effect reported.","molecular_requirements":"Blocked by an antibody against the first Ig domain of Robo1/2 or soluble Robo-Fc [PMID:12504588]; no further subunit data.","affinity_potency":[],"species_and_systems":"Human Robo1/Robo2 in transfected 3T3 cells with primary neurons [PMID:12504588]. Mouse pair projected from human.","localisation_and_range":"Robo2 secreted flag, Robo1 membrane flag [flag]; paper describes trans adhesion [PMID:12504588].","caveats":"Abstract only; same paper and evidence as ROBO1 -> ROBO2. IntAct record is a 'polymerization' entry from the same paper [DB:IntAct].","key_references":[{"PMID":"12504588","why":"Only paper"}],"covers":["LR003192","LR006412"]},"LR006414":{"pair":"ROBO3 -> ROBO1","headline":"ROBO3 to ROBO1 heterophilic binding, one abstract-only paper; reverse row of ROBO1 -> ROBO3.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind heterophilically to Robo1 [PMID:16226035]; no effect direction reported.","molecular_requirements":"Isoform Robo3A versus Robo3B involvement not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; orthologs expressed in mouse embryo [PMID:16226035]. Mouse pair listed as not ortholog-inferred, but the dossier shows only human experiments.","localisation_and_range":"Both membrane-bound per flags [flag].","caveats":"Abstract only; no database records.","key_references":[{"PMID":"16226035","why":"Robo3 binds Robo1"}],"covers":["LR003194","LR006414"]},"LR004722":{"pair":"RTN4 -> LINGO1","headline":"LINGO-1 is a component of the Nogo receptor complex; direct Nogo-LINGO-1 binding is not shown.","interaction_type":"functional only","direction_and_effect":"LINGO-1 is described as a component of the NgR1 complexes responding to myelin inhibitors including Nogo, leading to RhoA activation [PMID:15694322]; UniProt also describes it as a functional component of the Nogo receptor complex [DB:UniProt].","molecular_requirements":"LINGO-1 is a fixed component of p75/NgR1/LINGO-1 and TAJ/NgR1/LINGO-1 complexes [PMID:15694322]. NgR1 is required in the complex.","affinity_potency":[],"species_and_systems":"Curators record mouse ligand and receptor; the abstract reports mouse Taj-deficient neurons [PMID:15694322].","localisation_and_range":"RTN4 flagged non-secreted [flag]; LINGO-1 acts within a membrane receptor complex.","caveats":"Direct binding of Nogo to LINGO-1 is not shown; the confirmed row is background stated in the abstract of a TAJ paper. Four other papers had abstracts judged insufficient.","key_references":[{"PMID":"15694322","why":"LINGO-1 as a component of NgR1 complexes; TAJ substitutes for p75"}],"covers":["LR001325","LR004722"]},"LR006423":{"pair":"RTN4RL2 -> ADGRB1","headline":"Direct binding of RTN4RL2 to BAI1 shown by CRISPRa, AVEXIS and SPR, supported by two full-text papers.","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probes stained RTN4RL2-transfected HEK293 cells and the ectodomains interacted directly in both bait-prey orientations [PMID:30477585]. The Cell paper identifies RTN4R, RTN4RL1 and RTN4RL2 as high-affinity receptors/ligands for BAI1 and BAI3 [PMID:34758294]. Signalling effect is not reported; RTN4RL2 loss changed neuronal synapse and axon morphology [PMID:34758294].","molecular_requirements":"ADGRB1 TSR1-3 were sufficient for RTN4R-family binding [PMID:30477585]. ADGRB2 did not interact [PMID:30477585].","affinity_potency":[{"value":"Kd = 30.0 nM","assay":"surface plasmon resonance, BAI1-RTN4RL2 (lowest affinity of the pairs tested, still nanomolar)","system":"purified recombinant ectodomains","cite":"PMID:34758294"}],"species_and_systems":"HEK293 cells, recombinant ectodomains, human neurons [PMID:30477585][PMID:34758294].","localisation_and_range":"RTN4RL2 is described as a GPI-linked membrane protein, with trans-cellular adhesion shown, so juxtacrine; yet RTN4RL2 and ADGRB1 carry secreted flags in the dossier [PMID:30477585][flag].","caveats":"Single CRISPRa screen per bait; one RTN4R family member was not enriched in the screen [PMID:30477585]. Secreted flags conflict with the membrane description.","key_references":[{"PMID":"34758294","why":"SPR Kd and neuronal function"},{"PMID":"30477585","why":"CRISPRa and AVEXIS binding"}],"covers":["LR003203","LR006423"]},"LR006432":{"pair":"S100A4 -> ANXA2","headline":"S100A4 binds annexin A2 in structural and binding studies; annexin II acts as a plasminogen co-receptor scaffold rather than a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Extracellular S100A4 binds annexin II and accelerates tPA-mediated plasminogen activation to plasmin on endothelial cells [PMID:15788416]. In the crystal structure, S100A4 binding dislocates the ANXA2 N-terminal domain and unmasks the concave side [PMID:28669632].","molecular_requirements":"The binding site lies in the N-terminal region of annexin II; an N-terminal peptide blocked S100A4-induced plasmin formation [PMID:15788416]. Plasmin acceleration also needs S100A4 C-terminal lysines and plasminogen [PMID:15788416].","affinity_potency":[],"species_and_systems":"Human proteins; endothelial cell culture and crystal structure [PMID:15788416][PMID:28669632]. Structures PDB 5LPU and 6T58 contain both chains [DB:PDB 5LPU][DB:PDB 6T58]. UniProt lists the interaction [DB:UniProt].","localisation_and_range":"S100A4 and ANXA2 are both flagged secreted [flag]; the paper describes extracellular S100A4 acting at the endothelial surface [PMID:15788416].","caveats":"Both papers read as abstracts only. No affinity reported in our evidence. ANXA2 is a scaffold, not a signalling receptor.","key_references":[{"PMID":"15788416","why":"Direct S100A4-annexin II binding and plasmin formation"},{"PMID":"28669632","why":"ANXA2-S100A4 complex crystal structure"}],"covers":["LR003214","LR006432"]},"LR003219":{"pair":"S100A4 -> ERBB3","headline":"SPR and label transfer show S100A4 binds ErbB3 with Kd 58.0 nM; ErbB3 function is not established.","interaction_type":"direct binding","direction_and_effect":"S100A4 transferred label to ErbB3 and bound it in SPR; an anti-ErbB3 antibody did not significantly inhibit S100A4-induced neuroprotection (p = 0.15) [PMID:30083275].","molecular_requirements":"ErbB2 did not bind S100A4 but its knockdown abolished neuroprotection [PMID:30083275].","affinity_potency":[{"value":"Kd 58.0 \u00b1 30.0 nM","assay":"surface plasmon resonance, S100A4 on immobilized ErbB3","system":"recombinant proteins","cite":"PMID:30083275"}],"species_and_systems":"Cultured hippocampal neurons; species not stated in excerpts [PMID:30083275]. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"S100A4 is flagged secreted and ERBB3 transmembrane [flag].","caveats":"Binding only; functional dependence is on ErbB4, not ErbB3. Kd error is large. Abstract-level curation.","key_references":[{"PMID":"30083275","why":"S100A4-ErbB binding by SPR"}],"covers":["LR003219","LR006437"]},"LR006441":{"pair":"S100A8 -> ALCAM","headline":"ALCAM is reported as an S100A8/A9 receptor in melanoma by binding and NF-kappaB activation; abstract-only and complex-level.","interaction_type":"direct binding","direction_and_effect":"ALCAM and MCAM function as S100A8/A9 receptors like RAGE and induce melanoma progression via NF-kappaB activation and ROS formation; MCAM activates NF-kappaB more than ALCAM or RAGE [PMID:27151304].","molecular_requirements":"The paper concerns the S100A8/A9 complex [PMID:27151304].","affinity_potency":[],"species_and_systems":"Malignant melanoma cells; species not stated in the abstract [PMID:27151304]. Mouse pair is projected.","localisation_and_range":"S100A8 is flagged secreted and ALCAM transmembrane [flag].","caveats":"Abstract only; binding method and affinity not reported in our evidence. S100A8 not separated from S100A9.","key_references":[{"PMID":"27151304","why":"ALCAM/MCAM as S100A8/A9 receptors"}],"covers":["LR003224","LR006441"]},"LR003228":{"pair":"S100A8 -> LY96","headline":"S100A8 binds the TLR4-MD2 complex (SPR, abstract-only); LY96 alone is not tested separately.","interaction_type":"direct binding","direction_and_effect":"Mrp8 (S100A8) specifically interacts with the TLR4-MD2 complex by surface plasmon resonance and in HEK293 cells transfected with TLR4, CD14 and MD2, acting as an endogenous TLR4 ligand that activates MyD88/IRAK-1/NF-kappaB and TNF-alpha [PMID:17767165]. Reactome lists S100A8:S100A9 binding TLR4:LY96 [DB:Reactome].","molecular_requirements":"The evidence is for the TLR4-MD2 complex; whether MD2 (LY96) itself contacts S100A8 is not reported in our evidence [PMID:17767165]. CD14 was co-expressed in the HEK293 system [PMID:17767165].","affinity_potency":[],"species_and_systems":"Mouse phagocytes and HEK293 cells transfected with TLR4, CD14 and MD2 (species of constructs not stated in the abstract); mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Abstract only. Pair is a complex-level binding claim assigned to LY96; the receptor role of LY96 specifically is not isolated. Reactome rows cite the same and other papers (S100A8:S100A9 heterodimer).","key_references":[{"PMID":"17767165","why":"SPR and HEK293 evidence that Mrp8 binds TLR4-MD2"}],"covers":["LR003228","LR006445"]},"LR001329":{"pair":"S100A8 -> TLR4","headline":"S100A8 is an agonist of TLR4-MD2 with SPR, functional and in vivo knockout evidence; two papers, abstract-level binding.","interaction_type":"direct binding","direction_and_effect":"Mrp8 (S100A8) specifically interacts with the TLR4-MD2 complex by surface plasmon resonance, induces MyD88 translocation and IRAK-1/NF-kappaB activation and raises TNF-alpha; mice lacking Mrp8-Mrp14 were protected from endotoxin shock [PMID:17767165]. In the second paper, TLR4-deficient macrophages failed to respond to mMrp8 and an anti-TLR4 mAb almost completely blocked the hMrp8 TNF-alpha response [PMID:26329314]. Reactome records S100A8:S100A9 binding TLR4:LY96 [DB:Reactome]. The interaction record carries an Inhibitory modulatory flag, which conflicts with the agonist evidence.","molecular_requirements":"The binding evidence is for the TLR4-MD2 complex, and HEK293 reconstitution included CD14 [PMID:17767165]. Reactome models the S100A8:S100A9 heterodimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse phagocytes and knockout mice [PMID:17767165]; murine macrophages, human monocytes and HEK293-hTLR4 cells [PMID:26329314]. Human and mouse pairs both have direct evidence in this dossier.","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Binding paper was read as abstract only. Mrp8 pre-stimulation also induces tolerance to later challenges [PMID:26329314]. Modulatory effect 'Inhibitory' on the interaction record disagrees with agonist evidence.","key_references":[{"PMID":"17767165","why":"SPR binding to TLR4-MD2 and knockout mouse protection"},{"PMID":"26329314","why":"TLR4-dependence of Mrp8 responses, full text"}],"covers":["LR001329","LR004726"]},"LR006450":{"pair":"S100A9 -> ALCAM","headline":"ALCAM reported as an S100A8/A9 receptor in melanoma cells; abstract-only functional evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM and MCAM also function as S100A8/A9 receptors as RAGE does, inducing NF-kappaB activation and ROS formation in malignant melanoma; MCAM activates NF-kappaB more prominently than ALCAM [PMID:27151304].","molecular_requirements":"The ligand is the S100A8/A9 complex; S100A9 alone is not separated in our evidence [PMID:27151304].","affinity_potency":[],"species_and_systems":"Human melanoma cells per the abstract; mouse pair is ortholog-inferred.","localisation_and_range":"ALCAM is flagged both secreted and transmembrane [flag], so a soluble form may exist; ligand secreted [flag].","caveats":"Abstract only; no binding measurement or affinity; no database support.","key_references":[{"PMID":"27151304","why":"ALCAM and MCAM function as S100A8/A9 receptors in melanoma"}],"covers":["LR003233","LR006450"]},"LR003237":{"pair":"S100A9 -> CD36","headline":"S100A8/A9-arachidonic acid complex interacts with CD36 in vitro; evidence is about arachidonate uptake (abstract-only, 2001).","interaction_type":"direct binding","direction_and_effect":"Arachidonate uptake by HUVEC in the presence of S100A8/A9 was largely mediated by FAT/CD36, and kinetic studies indicated an interaction between the transporter and the S100A8/A9-AA complex, confirmed by an in vitro protein-protein interaction assay [PMID:11141076].","molecular_requirements":"The interacting species is the S100A8/A9-arachidonic acid complex, not S100A9 alone [PMID:11141076].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells, CD36-transfected COS-7 cells and an in vitro assay; species of the proteins in the assay is not stated in the abstract [PMID:11141076].","localisation_and_range":"Ligand secreted [flag]; CD36 transmembrane [flag].","caveats":"Abstract only. This is a transport/uptake context rather than a classical signalling receptor interaction; the effect on S100A8/A9 signalling is not reported. No affinity reported.","key_references":[{"PMID":"11141076","why":"S100A8/A9-AA complex interaction with FAT/CD36"}],"covers":["LR003237","LR006453"]},"LR003246":{"pair":"SCGB1A1 -> LCN1","headline":"Uteroglobin binds a lipocalin-1 receptor construct with Kd 18 nM, but the receptor label here looks mismatched.","interaction_type":"direct binding","direction_and_effect":"125I-human uteroglobin bound Lip-1R (lipocalin-1 receptor) in transfected COS-1 cells with high specificity, and in HTB-81 cells with high affinity [PMID:16423471]. The interaction inhibits migration and invasion (curated as antagonist) [PMID:16423471].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd = 18 nM","assay":"125I-hUG binding","system":"HTB-81 cells transfected with Lip-1R construct","cite":"PMID:16423471"}],"species_and_systems":"Human uteroglobin and Lip-1R in COS-1 and HTB-81 cells [PMID:16423471].","localisation_and_range":"LCN1 is flagged both secreted and receptor [flag].","caveats":"The binding partner in the paper is the lipocalin-1 receptor (Lip-1R), not lipocalin-1 itself. Single paper, full text.","key_references":[{"PMID":"16423471","why":"125I-uteroglobin binding to Lip-1R with Kd 18 nM"}],"covers":["LR003246"]},"LR004731":{"pair":"SCT -> SCTR","headline":"Secretin is a well-supported direct agonist of its receptor SCTR, with binding, cAMP and structural evidence.","interaction_type":"direct binding","direction_and_effect":"Secretin binds the human secretin receptor with high affinity and stimulates adenylyl cyclase and cAMP in a dose-dependent manner [PMID:7612008]. GtoPdb lists it as a full agonist [DB:GtoPdb]. A recombinant SCTR N-terminal ectodomain inhibited secretin-induced cAMP and PKA activity, acting as an antagonist [PMID:9440501].","molecular_requirements":"The N-terminal ectodomain is the main determinant of secretin versus VIP selectivity and the first loop contributes [PMID:7782300]. Lys173 in the first extracellular loop likely interacts with Asp3 of secretin [PMID:8579602]. Complex structures exist [DB:PDB 6WI9] [DB:PDB 6WZG] [DB:PDB 7D3S].","affinity_potency":[{"value":"IC50 2.2 nM","assay":"competitive binding, secretin at wild-type secretin receptor","system":"COS cells","cite":"PMID:7782300"},{"value":"EC50 1.5 nM","assay":"cAMP generation by secretin at wild-type secretin receptor","system":"COS cells","cite":"PMID:7782300"},{"value":"pEC50 9.699999809265137","assay":"affinity value recorded for secretin at the human receptor","system":"COS-7 cells","cite":"PMID:7612008"}],"species_and_systems":"Human receptor in COS-7 and COS cells [PMID:7612008] [PMID:7782300]; rat receptor loop work in CHO cells [PMID:8579602]. Mouse pair is projected from human.","localisation_and_range":"Secretin is flagged secreted and SCTR transmembrane [flag]; UniProt describes secretin acting through a receptor in the basolateral domain of several cells [DB:UniProt].","caveats":"All four cited papers were read as abstracts only. Several papers study receptor mutants or chimeras rather than the native pair.","key_references":[{"PMID":"7612008","why":"Cloning of human SCTR with high-affinity secretin binding and cAMP coupling"},{"PMID":"7782300","why":"Chimeric receptors; IC50 2.2 nM and domain mapping"},{"PMID":"9440501","why":"Ectodomain alone antagonises secretin signalling"}],"covers":["LR001335","LR004731"]},"LR003255":{"pair":"SECTM1 -> TNFRSF18","headline":"Sectm1a is reported to bind GITR on mouse macrophages and activate PI3K-Akt; one abstract-only paper, mapped to human by orthology.","interaction_type":"direct binding","direction_and_effect":"Sectm1a is described as a novel GITR ligand that binds GITR on macrophages and activates PI3K-Akt, boosting phagocytosis; phagocytosis was abolished by GITR knockout and rSectm1a protection in sepsis was negated in GITR knockout mice [PMID:32769121].","molecular_requirements":"Not reported in our evidence beyond GITR and PI3K-Akt dependence [PMID:32769121].","affinity_potency":[],"species_and_systems":"Mouse experiments (knockout mice, macrophages); the human pair is ortholog-inferred, not tested in human cells [PMID:32769121].","localisation_and_range":"SECTM1 is flagged secreted [flag]; the paper uses recombinant secreted Sectm1a [PMID:32769121].","caveats":"One paper, abstract only; the dossier lists species as human but the abstract describes mouse work. Binding method and affinity are not reported in our evidence.","key_references":[{"PMID":"32769121","why":"Sectm1a as a GITR ligand in macrophages and sepsis"}],"covers":["LR003255"]},"LR011526":{"pair":"SELL -> MADCAM1","headline":"No verified paper; only generic Reactome L-selectin ligand records support this pair.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes L-selectin interacting with known ligands [DB:Reactome]. Direction or effect for MADCAM1 not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; pair annotated human.","localisation_and_range":"Both partners are annotated transmembrane or membrane-bound (MADCAM1 is_transmembrane, SELL transmembrane) [flag].","caveats":"One paper was judged abstract_insufficient and none confirmed. Reactome examples are generic and do not name MADCAM1 [DB:Reactome].","key_references":[],"covers":["LR011526"]},"LR001338":{"pair":"SELPLG -> SELL","headline":"L-selectin binding to PSGL-1 is supported by several binding and adhesion papers, but one is glycan-conditional and most were read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"L-selectin binds PSGL-1 on leukocytes, at lower levels than P-selectin; binding was blocked by antibodies to either protein [PMID:8892633]. Neutrophil-neutrophil adhesion was inhibited by anti-PSGL-1 or anti-L-selectin antibodies [PMID:8896607]. Binding is a lectin-domain interaction with a PSGL-1 glycosulfopeptide site [PMID:18250165]. Effect direction is not reported in our evidence.","molecular_requirements":"Binding required appropriate glycosylation of PSGL-1 and Ca2+ [PMID:8892633]. On NK cells, a PEN5 lactosamine modification of PSGL-1 creates an L-selectin binding site independent of tyrosine sulfation [PMID:10725346], so binding may depend on cell type glycosylation.","affinity_potency":[],"species_and_systems":"All confirmed experiments are labelled human (cells, recombinant chimeras and glycosulfopeptide) [PMID:8892633][PMID:8896607][PMID:18250165][PMID:10725346]. The mouse pair is projected from human evidence (ortholog_inferred).","localisation_and_range":"Both partners are flagged membrane-bound [flag], so this is a juxtacrine, cell-contact interaction.","caveats":"Three of four shown papers were read as abstracts only. No affinity value is reported for L-selectin with PSGL-1. The NK-cell PEN5 result is conditional on a cell-restricted glycan [PMID:10725346]. Database records shown (Reactome, IntAct) concern P-selectin binding PSGL-1, not L-selectin [DB:Reactome R-HSA-202724] [DB:IntAct P14151-Q14242].","key_references":[{"PMID":"8892633","why":"L-selectin binds PSGL-1 on leukocytes; glycosylation and Ca2+ dependent"},{"PMID":"8896607","why":"Full-text neutrophil adhesion blocked by anti-PSGL-1 or anti-L-selectin"},{"PMID":"18250165","why":"L-selectin lectin domain binding to PSGL-1 glycosulfopeptide"}],"covers":["LR001338","LR004734"]},"LR004740":{"pair":"SEMA3A -> PLXNA3","headline":"PlexinA3 is genetically required for Sema3A-induced neuronal death in vitro; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"PlexinA3 is the key receptor subunit responsible for Sema3A-induced cell death; both PlexinA3 and PlexinA4 contribute in vitro, with PlexinA3 absolutely required and PlexinA4 contributing less [PMID:19020035].","molecular_requirements":"Plexins are described as Sema3A coreceptors [PMID:19020035]; whether NRP1 is needed is not reported in our evidence beyond Reactome's Nrp-1-bound-to-PlexinA record [DB:Reactome].","affinity_potency":[],"species_and_systems":"Knockout neurons (mouse implied; species fields empty in dossier) and PlexinA3-/- mice [PMID:19020035]; human pair is ortholog-inferred [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"One paper, with the key sentence browser-read and spot-check pending; evidence is a genetic requirement, not binding. Described as borderline by the curator.","key_references":[{"PMID":"19020035","why":"PlexinA3 required for Sema3A-induced neuronal apoptosis"}],"covers":["LR001344","LR004740"]},"LR003264":{"pair":"SEMA3B -> PLXNA2","headline":"Plexin-A2 is non-substitutably required for Sema3B signalling in cell silencing experiments (abstract only).","interaction_type":"functional only","direction_and_effect":"Plexin-A2 silencing completely abolished Sema3B signalling, unlike Sema3A signalling [PMID:25335892]. Plexin-A4 overexpression failed to restore Sema3B signalling in plexin-A2-silenced cells [PMID:25335892]. Effect agonist.","molecular_requirements":"Also requires plexin-A4 and one of the two neuropilins [PMID:25335892].","affinity_potency":[],"species_and_systems":"Endothelial and glioblastoma cells (labelled human) [PMID:25335892]; mouse pair is ortholog-inferred [flag].","localisation_and_range":"Sema3B is flagged secreted [flag].","caveats":"Single paper read as abstract only; functional dependence, not binding.","key_references":[{"PMID":"25335892","why":"Plexin-A2 silencing abolishes Sema3B signalling"}],"covers":["LR003264","LR006480"]},"LR008025":{"pair":"SEMA3C -> NRP1:PLXND1","headline":"SEMA3C acts through a NRP1:PlexinD1 complex to inhibit pathological retinal angiogenesis; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Sema3C is reported as an inhibitor: it induced VE-cadherin internalization and abrogated VEGF-induced AKT, FAK and p38MAPK activation, and inhibited pathological pre-retinal vascular tufts [PMID:26194913].","molecular_requirements":"Both Neuropilin-1 and PlexinD1 are named as the receptors, both strongly expressed on vascular tufts [PMID:26194913]. The paper's full text shows that a furin-cleaved Sema3Cp60 isoform had no effect on tube formation or sprouting, whereas full-length and the delta13 form inhibited [PMID:26194913]. Whether each subunit is individually required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cells and animals: HUVEC assays, a xenotransplantation assay in mice, and intravitreal recombinant Sema3C in newborn mouse retina [PMID:26194913].","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. The complex members are annotated transmembrane [flag].","caveats":"Receptor identification rests on the abstract only (read depth abstract_only); no binding measurement is reported in our evidence. No affinity data.","key_references":[{"PMID":"26194913","why":"Sema3C signals via NRP1 and PlexinD1 to inhibit pathological angiogenesis"}],"covers":["LR008025"]},"LR001356":{"pair":"SEMA3F -> PLXNA3","headline":"SEMA3F signalling via NRP2 is mediated principally by Plexin-A3 in mouse genetic studies; coreceptor evidence, both read as abstracts.","interaction_type":"functional only","direction_and_effect":"Neurons from Plexin-A3/A4 double-mutant mice were insensitive to Sema3F in vitro, with axon defects in vivo resembling Neuropilin-2 mutants [PMID:15721238]. Sema3F-Fc induced spine retraction in wild-type cortical neurons but not NrCAM-null ones [PMID:25143608].","molecular_requirements":"Signalling via NRP2 is mediated principally by Plexin-A3 [PMID:15721238]. NrCAM forms a complex with NRP2 and PlexA3 in brain and is required for Sema3F spine retraction [PMID:25143608].","affinity_potency":[],"species_and_systems":"Mouse neurons and brain [PMID:15721238][PMID:25143608]. The human pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond SEMA3F being flagged secreted [flag].","caveats":"Both papers read as abstracts only. Evidence is genetic and complex-level, not direct SEMA3F-PlexA3 binding.","key_references":[{"PMID":"15721238","why":"Plexin-A3 principally mediates NRP2/Sema3F responses"},{"PMID":"25143608","why":"NrCAM-NRP2-PlexA3 complex mediates Sema3F spine retraction"}],"covers":["LR001356","LR004752"]},"LR003273":{"pair":"SEMA3G -> PLXNA1","headline":"Weak evidence: one abstract-only paper on a SEMA3G mutation altering PlexinA receptor binding in GnRH neurons.","interaction_type":"functional only","direction_and_effect":"A SEMA3G variant from siblings with GnRH deficiency changed binding to PlexinA receptors in silico and in vitro and attenuated effects on GnRH neuron migration [PMID:32365351].","molecular_requirements":"Not reported in our evidence; the abstract-level text names PlexinA receptors generally, including PLXNA1 per the curator [PMID:32365351].","affinity_potency":[],"species_and_systems":"Human variant study with in silico, in vitro and in vivo models; the mouse pair is ortholog-inferred [PMID:32365351].","localisation_and_range":"SEMA3G is flagged secreted [flag].","caveats":"Abstract only; wild-type SEMA3G-PLXNA1 binding is not directly shown, and PLXNA1 is not named in the abstract text we have.","key_references":[{"PMID":"32365351","why":"SEMA3G mutation alters PlexinA receptor selectivity in GnRH deficiency"}],"covers":["LR003273","LR006489"]},"LR001365":{"pair":"SEMA5A -> PLXNB3","headline":"Plexin-B3 is reported as a high-affinity, Sema5A-specific receptor; evidence is one abstract-only paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Plexin-B3 is described as a high-affinity receptor specific for Sema5A, and Sema5A activation of plexin-B3 mediates functional responses in plexin-B3-expressing fibroblasts, epithelial and primary endothelial cells (agonist) [PMID:15218527]. Sema5A also triggers Met signalling when Met is complexed with plexin-B3 [PMID:15218527].","molecular_requirements":"Met associated with plexin-B3 is needed for the Met transactivation response [PMID:15218527]; whether plexin-B3 alone suffices for other responses is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells per the curator fields; the mouse pair is not ortholog-inferred in the dossier, but no mouse experiment is shown.","localisation_and_range":"Ligand is flagged membrane-bound and receptor transmembrane [flag]. Reactome lists the SEMA5A:PLXNB3 complex at the plasma membrane [DB:Reactome].","caveats":"Abstract only; no affinity value is given in our evidence. Database support is Reactome, citing the same paper [DB:Reactome].","key_references":[{"PMID":"15218527","why":"Identifies plexin-B3 as the high-affinity Sema5A receptor"}],"covers":["LR001365","LR004761"]},"LR003282":{"pair":"SEMA6B -> PLXNA4","headline":"Supported only by a single abstract-only sentence that plexin-A4 bound Sema6B; no Sema6B-specific data are shown.","interaction_type":"direct binding","direction_and_effect":"Plexin-A4 bound the class 6 semaphorins Sema6A and Sema6B and mediated their axon-repulsive activities independently of neuropilin-1 [PMID:15814794].","molecular_requirements":"Neuropilin-1 is not required [PMID:15814794].","affinity_potency":[],"species_and_systems":"Plexin-A4 null mice and neurons; curator species fields say human, but the abstract describes mutant mice. Mouse pair is not ortholog-inferred in the dossier.","localisation_and_range":"Not reported in our evidence.","caveats":"One paper read as abstract only; the Sema6B result is a single clause, the abstract is truncated, and the study focuses on Sema3A. Other judged rows were abstract_insufficient or pending.","key_references":[{"PMID":"15814794","why":"States plexin-A4 bound Sema6A and Sema6B"}],"covers":["LR003282","LR006498"]},"LR006504":{"pair":"SERPIND1 -> LRP1","headline":"Heparin cofactor II-thrombin complex binds purified LRP1 and is internalised; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Heparin cofactor II-thrombin bound purified LRP, with binding inhibited by RAP; LRP-expressing fibroblasts internalised and degraded the complexes and LRP-deficient fibroblasts did not [PMID:8626456].","molecular_requirements":"The complex, not the free inhibitor, is the ligand: native or modified inhibitor forms were unable to bind [PMID:8626456].","affinity_potency":[],"species_and_systems":"Human proteins as labelled; purified LRP, mouse fibroblasts, HepG2 cells [PMID:8626456]. Mouse pair is ortholog-projected.","localisation_and_range":"SERPIND1 is flagged secreted [flag]; clearance by endocytosis.","caveats":"One paper, abstract only; the rat in vivo clearance data in the abstract concern ATIII-thrombin, not this complex.","key_references":[{"PMID":"8626456","why":"HCII-thrombin binding to LRP and cellular clearance"}],"covers":["LR003288","LR006504"]},"LR001374":{"pair":"SERPINE1 -> LRP1","headline":"PAI-1 and its uPA complexes bind LRP1; complexes bind about 100-fold tighter, and PAI-1 drives LRP1-dependent migration signalling.","interaction_type":"direct binding","direction_and_effect":"uPA:PAI-1 complexes bind LRP1 with about 100-fold increased affinity over PAI-1 alone [PMID:31792055]. Both active and cleaved PAI-1 activate Jak/Stat and stimulate migration; anti-LRP antibodies and RAP block this, and PAI-1 had no chemotactic effect on LRP-deficient cells [PMID:15001579]. Thrombin-PAI-1 endocytosis was blocked by LRP antibodies and RAP [PMID:8626514].","molecular_requirements":"Lysines 80, 88 and 207 of PAI-1 are implicated, with a bivalent binding model, and uPA:PAI-1 complex binds through three regions to LDLa repeats [PMID:31792055]. Motogenic action needs an LRP-binding PAI-1 but not protease-inhibitory activity [PMID:15001579]. In the myogenic-cell paper, LRP acts on the assembled [uPAR:uPA:PAI-1] complex [PMID:10896774].","affinity_potency":[],"species_and_systems":"Human proteins as labelled; surface plasmon resonance with recombinant proteins [PMID:31792055]; pneumocytes and migration assays [PMID:8626514, PMID:15001579]; human myogenic cells [PMID:10896774]. Mouse pair is ortholog-projected. BioGRID lists an affinity-capture-western record [DB:BioGRID].","localisation_and_range":"Both clearance (endocytic) and signalling roles are reported [PMID:8626514, PMID:15001579]; secreted and matrix PAI-1 is not annotated beyond the secreted flag [flag].","caveats":"All four papers abstract only. Free PAI-1 binding was described in the literature as controversial [PMID:31792055]. One functional paper concerns the whole complex and has no binding measurement [PMID:10896774]. UniProt describes LRP1 binding to tPA alone or with SERPINE1 [DB:UniProt].","key_references":[{"PMID":"31792055","why":"Mutational and SPR mapping of PAI-1 and uPA:PAI-1 binding to LRP1"},{"PMID":"15001579","why":"LRP1-dependent motogenic signalling by PAI-1"},{"PMID":"8626514","why":"LRP-mediated thrombin-PAI-1 endocytosis"}],"covers":["LR001374","LR004769"]},"LR003291":{"pair":"SERPINF1 -> PNPLA2","headline":"PEDF co-immunoprecipitates with ATGL and lowers hepatocyte triglyceride in an ATGL-dependent way; supported by databases too.","interaction_type":"direct binding","direction_and_effect":"PEDF co-immunoprecipitated with ATGL in hepatic and HCC lysates; rPEDF decreased triglyceride in PEDF-null hepatocytes and this depended on ATGL, blocked by the inhibitor (R)-bromoenol lactone [PMID:18191271]. GtoPdb lists an Activator, Binding record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond ATGL dependence of the effect [PMID:18191271].","affinity_potency":[],"species_and_systems":"PEDF-null and control hepatocytes and liver, and HCC lysates; the abstract does not state the species, and the dossier labels it human [PMID:18191271]. BioGRID lists reconstituted-complex and two-hybrid records [DB:BioGRID].","localisation_and_range":"ATGL is an intracellular lipase localised to adiposomes in hepatocytes [PMID:18191271]; PEDF is flagged secreted [flag]. How secreted PEDF reaches ATGL is not reported in our evidence.","caveats":"Co-immunoprecipitation does not prove direct binding; abstract-only read; one further row is pending. An intracellular lipase as a receptor for a secreted ligand is unusual for cell-cell communication scoring.","key_references":[{"PMID":"18191271","why":"PEDF-ATGL co-IP and ATGL-dependent triglyceride lowering"}],"covers":["LR003291","LR006507"]},"LR006513":{"pair":"SFTPD -> LRP1","headline":"SP-D collagenous tails bind a calreticulin/CD91 complex per one abstract-level paper; LRP1 alone not shown.","interaction_type":"direct binding","direction_and_effect":"Collagenous tails of SP-A/SP-D stimulate proinflammatory mediator production and phagocytosis via the calreticulin/CD91 complex; agonist-like [PMID:14531999].","molecular_requirements":"The curator notes calreticulin may be an obligate co-receptor partner, so LRP1 alone may not be the direct binding partner [PMID:14531999].","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; both species pairs ortholog-inferred [PMID:14531999].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only, covering SP-A and SP-D together; binding is to a complex, not LRP1 alone.","key_references":[{"PMID":"14531999","why":"Collectin tails bind calreticulin/CD91"}],"covers":["LR003298","LR006513"]},"LR001383":{"pair":"SFTPD -> LY96","headline":"SP-D binds soluble MD-2 directly via its CRD, confirmed by several assays; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"The curator labels the effect agonist, but our evidence only shows binding; functional effect on signalling is not reported in our evidence [PMID:18991397].","molecular_requirements":"Binding is concentration- and Ca2+-dependent, localised to the carbohydrate recognition domain, and independent of MD-2 N-glycosylation [PMID:18991397]. Reactome lists the TLR4:LY96 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Soluble recombinant human MD-2 and SP-D (microtiter-well, co-sedimentation, BIAcore, pulldown); mouse pair is ortholog-inferred [PMID:18991397].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no affinity values reported.","key_references":[{"PMID":"18991397","why":"SP-D binds MD-2 through the CRD"}],"covers":["LR001383","LR004778"]},"LR005307":{"pair":"SIGLEC1 -> SPN","headline":"Sialoadhesin (SIGLEC1) binds CD43 (SPN) on mouse T cells in a sialic acid dependent manner.","interaction_type":"direct binding","direction_and_effect":"Sialoadhesin-Fc precipitated CD43 (130 kDa) from murine T cells; CD43 expressed in COS cells supported increased binding to immobilized sialoadhesin, identifying CD43 as a T cell counterreceptor [PMID:11238599].","molecular_requirements":"Binding is sialic acid dependent and abolished by the R97A mutation in the sialic acid binding site of sialoadhesin; it binds core-1 and core-2 O-linked glycoforms [PMID:11238599]. A single chain suffices.","affinity_potency":[],"species_and_systems":"Murine T cell line TK-1, COS cells and CHO cells [PMID:11238599]. Human pair is ortholog-inferred.","localisation_and_range":"Both are membrane proteins (receptor flagged transmembrane [flag]); cell-cell contact interaction between macrophages and T cells [PMID:11238599].","caveats":"Abstract-only. One more paper was abstract-insufficient. IntAct has a solid phase assay record [DB:IntAct]. No affinity.","key_references":[{"PMID":"11238599","why":"Sialoadhesin binds CD43 on T cells"}],"covers":["LR001977","LR005307"]},"LR006522":{"pair":"Siglece -> Muc1","headline":"Mouse pair projected from human; the only paper concerns human Siglec-9 and MUC1, not mouse Siglece.","interaction_type":"functional only","direction_and_effect":"The cited paper shows human MUC1-ST engaging Siglec-9 transmits activating signals, not SHP-1/SHP-2 recruitment [PMID:27595232]. Nothing is reported for mouse Siglece.","molecular_requirements":"Sialic acid on MUC1 was required for binding in the paper; Siglec-9 gave the greatest binding among Siglecs-3, 7, 9 and 10 [PMID:27595232].","affinity_potency":[],"species_and_systems":"Human primary monocytes/macrophages and T47D cells [PMID:27595232]. Mouse pair is ortholog-inferred, with no mouse experiment in our evidence.","localisation_and_range":"Both entities are flagged secreted [flag]; the paper does not address range.","caveats":"The mouse assertion rests wholly on ortholog projection. The paper's Siglec-9 is the human protein; whether Siglece is the intended mouse counterpart is not stated in our evidence. One other judged row was marked a different entity.","key_references":[{"PMID":"27595232","why":"Human MUC1-ST engages Siglec-9; source of the projection"}],"covers":["LR006522"]},"LR003309":{"pair":"SLAMF8 -> SLAMF8","headline":"Mouse homophilic SLAMF8 binding shown in two papers; human row is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Slamf8-Fc bound Slamf8-transfected 293 cells but not Slamf1 transfectants [PMID:25799045]. A pulldown showed SLAMF8-Fc binds SLAMF8-His, and homophilic interaction promoted FDC-induced monocytic cell differentiation [PMID:35953458].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse Slamf8 on HEK293 transfectants [PMID:25799045]; mouse FDC line FL-Y and recombinant proteins [PMID:35953458]. No human experiment shown.","localisation_and_range":"Not flagged secreted; surface receptor, but Fc fusion forms were used [PMID:25799045].","caveats":"Second paper abstract only. Two further rows were judged a different entity. IntAct holds a solid phase assay record [DB:IntAct]. No affinity.","key_references":[{"PMID":"25799045","why":"Slamf8-Fc binds Slamf8 cells, not Slamf1"},{"PMID":"35953458","why":"SLAMF8-Fc pulldown of SLAMF8-His"}],"covers":["LR003309","LR006523"]},"LR001392":{"pair":"SLIT1 -> GPC1","headline":"One abstract-only rat-brain affinity purification supports SLIT1 binding glypican-1; heparan sulfate dependent.","interaction_type":"direct binding","direction_and_effect":"Glypican-1-Fc affinity chromatography of rat brain extract recovered Slit-1 and Slit-2 peptide sequences in a 200-kDa band [PMID:10364234]. Signalling effect is not reported in our evidence.","molecular_requirements":"Binding requires the heparan sulfate chains on glypican [PMID:10364234].","affinity_potency":[],"species_and_systems":"Rat brain extract and recombinant glypican-1-Fc from 293 cells [PMID:10364234]. Human and mouse rows are ortholog-inferred or not shown.","localisation_and_range":"SLIT1 is flagged secreted and GPC1 secreted/receptor [flag]; a heparan sulfate proteoglycan interaction.","caveats":"Abstract only; one paper, no affinity. Slit-1 and Slit-2 were isolated together, and one further row is pending.","key_references":[{"PMID":"10364234","why":"Slits isolated on glypican-1-Fc, heparan sulfate dependent"}],"covers":["LR001392","LR004787"]},"LR005316":{"pair":"SLIT3 -> ROBO4","headline":"SLIT3 promotes endothelial motility via Robo4 in mouse; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"Slit3 stimulates endothelial proliferation, motility and chemotaxis via interaction with Robo4, and promotes vascular network formation with specific activity comparable with VEGF; Slit3 knockout mice show disrupted angiogenesis [PMID:19741192].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse endothelial cells, ex vivo sprouting and in vivo; mouse knockout [PMID:19741192].","localisation_and_range":"Secreted by endothelial and vascular smooth muscle cells, acting in paracrine and autocrine ways [PMID:19741192].","caveats":"Single abstract-only paper; physical binding not reported in our evidence. No affinity.","key_references":[{"PMID":"19741192","why":"Slit3 angiogenesis via Robo4"}],"covers":["LR001987","LR005316"]},"LR007404":{"pair":"SLITRK4 -> OLR1","headline":"SLITRK4-OLR1 has only an IntAct surface plasmon resonance record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"SLITRK4 flagged transmembrane [flag].","caveats":"Support is a single IntAct surface plasmon resonance record [DB:IntAct]; the one judged paper was abstract-insufficient, so no curator-verified evidence exists.","key_references":[],"covers":["LR007404"]},"LR005325":{"pair":"SLPI -> PLSCR1","headline":"SLPI binds phospholipid scramblase 1 directly in several in vitro assays; it competes with CD4 for the PLSCR1 cytoplasmic domain.","interaction_type":"direct binding","direction_and_effect":"SLPI is the ligand and acts as an antagonist: it disrupts the PLSCR1-CD4 association and the authors propose this explains inhibition of HIV-1 infection [PMID:19333378].","molecular_requirements":"The mature SLPI form (residues 26-132) was needed; the full-length form with signal peptide did not interact in yeast two-hybrid. Each WAP motif alone recruited PLSCR1 more weakly than mature SLPI. SLPI binds PLSCR1 residues 155-233 of the cytoplasmic domain, the same region CD4 uses [PMID:19333378].","affinity_potency":[],"species_and_systems":"Human proteins; yeast two-hybrid, ELISA with GST-PLSCR1, pull-downs from transfected cells, Jurkat T cells and primary T lymphocytes [PMID:19333378]. Mouse pair is projected from human evidence.","localisation_and_range":"SLPI is flagged secreted [flag]. PLSCR1 is a type II membrane protein whose SLPI-binding region is cytoplasmic; the authors state secreted SLPI would need to cross the plasma membrane to bind it [PMID:19333378].","caveats":"The binding site is intracellular, so the route by which secreted SLPI reaches it is unresolved in our evidence. The curator read the paper at abstract level only. A weak pull-down interaction was also seen with elafin [PMID:19333378]. BioGRID lists affinity-capture-Western and two-hybrid records [DB:BioGRID].","key_references":[{"PMID":"19333378","why":"Shows SLPI binds PLSCR1 directly and displaces CD4"}],"covers":["LR001996","LR005325"]},"LR003318":{"pair":"SLURP2 -> CHRM3","headline":"SLURP-2 allosterically interacts with M3 muscarinic receptor in CHO cells; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"SLURP-2 allosterically interacts with human M1 and M3 muscarinic receptors overexpressed in CHO cells [PMID:27485575]. Direction of effect (agonist or antagonist) at M3 is not reported; in keratinocytes the effect via muscarinic receptors could not be unambiguously characterised [PMID:27485575]. UniProt also lists the interaction as probably allosteric [DB:UniProt].","molecular_requirements":"No co-receptor or subunit requirement reported in our evidence.","affinity_potency":[],"species_and_systems":"Human M3 overexpressed in CHO cells; recombinant SLURP-2; keratinocyte data are indirect [PMID:27485575].","localisation_and_range":"SLURP2 is flagged as secreted [flag]; the receptor is flagged as a receptor [flag]. Range is not discussed in our evidence.","caveats":"Single paper. No affinity reported for M3. The UniProt record rests on the same paper [DB:UniProt]. Biological relevance in keratinocytes is described only as probable [PMID:27485575].","key_references":[{"PMID":"27485575","why":"Recombinant SLURP-2 pharmacology and binding to acetylcholine receptors"}],"covers":["LR003318"]},"LR006531":{"pair":"SMOC2 -> FZD6","headline":"One cancer-cell paper reports SMOC-2 co-immunoprecipitating with FZD6 and enhancing WNT signalling; support rests on a co-IP.","interaction_type":"direct binding","direction_and_effect":"By co-culture IP, SMOC-2 directly interacted with the WNT receptors Fzd6 and LRP6, enhanced ligand-receptor interaction with canonical WNT ligands (Wnt3a and Wnt10b) and activated the WNT/beta-catenin pathway in endometrial cancer [PMID:30594556]. This acts as a positive facilitator, not a classical WNT ligand, per the curator note.","molecular_requirements":"Fzd6 and LRP6 were both reported as interactors, so a FZD-LRP complex may be involved; whether FZD6 alone is sufficient is not reported [PMID:30594556].","affinity_potency":[],"species_and_systems":"Species: not stated for the co-culture IP in our excerpts; endometrial cancer cell lines (AN3CA, Ishikawa, HEC-1A, ECC-1) and mouse xenografts were used elsewhere in the paper [PMID:30594556]. The mouse pair is projected from human evidence.","localisation_and_range":"SMOC2 is flagged as secreted and as a receptor [flag]; FZD6 is flagged as a receptor [flag]. Paracrine or autocrine range is not tested in our evidence.","caveats":"Evidence is a co-culture IP in cancer cells; 'directly' is the authors' wording and affinity is not reported. The excerpts available to us are mostly general statements. Only one paper.","key_references":[{"PMID":"30594556","why":"Co-IP of SMOC-2 with Fzd6 and LRP6 and WNT pathway activation in endometrial cancer"}],"covers":["LR003324","LR006531"]},"LR003327":{"pair":"SPARC -> ENG","headline":"SPARC directly binds endoglin and reduces its interaction with alphaV integrin; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"SPARC interacted directly with endoglin and reduced endoglin interaction with alphaV integrin, lowering TGF-beta1 activity and promoting pericyte migration [PMID:21708981]. Antagonist-like dampening of an accessory receptor, not a conventional agonist.","molecular_requirements":"Endoglin is a TGF-beta1 accessory receptor; endoglin and alphaV integrin were both needed for TGF-beta inhibition of migration [PMID:21708981].","affinity_potency":[],"species_and_systems":"Mouse pericytes and 10T1/2 cells: SPARC coprecipitated with endoglin, and solid-phase binding assays were used with SPARC and endoglin [PMID:21708981]. Human pair is ortholog-inferred.","localisation_and_range":"SPARC is flagged secreted [flag]; acts on the cell surface of pericytes.","caveats":"Single paper; no affinity reported; the excerpts do not say whether the solid-phase proteins were human or mouse. No database records.","key_references":[{"PMID":"21708981","why":"SPARC binds endoglin, reduces alphaV integrin association"}],"covers":["LR003327","LR006534"]},"LR005334":{"pair":"SPON2 -> ITGA4","headline":"Mindin (SPON2) engages alpha4 integrin in neutrophil, dendritic cell and macrophage assays; antibody blocking evidence, no isolated alpha4 binding.","interaction_type":"functional only","direction_and_effect":"Neutrophil adhesion to mindin was blocked by anti-integrin alpha4 antibodies and HEK-293 cells expressing the integrins bound mindin more [PMID:16105980]. DC adhesion to mindin was blocked by anti-alpha4, alpha5 and beta1 antibodies [PMID:16917498]. SPON2-alpha4beta1 signalling activated RhoA and Rac1 and promoted M1-like macrophage recruitment [PMID:29440144].","molecular_requirements":"Evidence involves alpha4 with beta1 [PMID:29440144]; alpha4 together with alphaM and beta2 antibodies also blocked neutrophil adhesion [PMID:16105980].","affinity_potency":[],"species_and_systems":"Human neutrophils and HEK-293 [PMID:16105980]; mouse DCs [PMID:16917498]; HCC tumour microenvironment [PMID:29440144]. Both species are represented.","localisation_and_range":"Mindin is an extracellular matrix protein, immobilised matrix binding [PMID:16105980].","caveats":"Abstracts only; antibody blocking is indirect; neutrophil binding was to a mixed integrin set. No affinity.","key_references":[{"PMID":"16105980","why":"Mindin matrix binds neutrophils via alpha4, alphaM, beta2"},{"PMID":"16917498","why":"DC adhesion to mindin blocked by anti-alpha4/alpha5/beta1"},{"PMID":"29440144","why":"SPON2-alpha4beta1 signals RhoA/Rac1"}],"covers":["LR002006","LR005334"]},"LR004803":{"pair":"SPP1 -> ITGAV","headline":"Osteopontin binds alphaV integrins (alphavbeta1, beta3, beta5, beta6); nanomolar affinities reported for beta1 and beta5.","interaction_type":"direct binding","direction_and_effect":"Osteopontin is a receptor ligand for alphavbeta1 and alphavbeta5 in adhesion assays [PMID:7592829]; alphavbeta6 is an additional receptor [PMID:16005200]; PC3 cell adhesion and migration on osteopontin are alphavbeta3-dependent and activate PI 3-kinase/AKT [PMID:10835423].","molecular_requirements":"alphaV pairs with different beta chains; alphavbeta3, beta5 and beta6 bind the RGD site, with thrombin cleavage not needed; alphavbeta5/beta6 adhesion also depends on two aspartates upstream of RGD [PMID:16005200]. Mg2+ and Mn2+ support binding, Ca2+ does not [PMID:7592829].","affinity_potency":[{"value":"18 nM","assay":"GST-OPN binding to alphavbeta1 in Mn2+","system":"HEK293 cells, human recombinant OPN","cite":"PMID:7592829"},{"value":"48 nM","assay":"GST-OPN binding to alphavbeta5 in Mn2+","system":"HEK293 cells transfected with beta5","cite":"PMID:7592829"}],"species_and_systems":"Human cells and recombinant human OPN [PMID:7592829]; prostate cancer PC3 and LNCaP cells [PMID:10835423].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGAV is a receptor [flag].","caveats":"All three papers are abstract-only. Affinity is for alphavbeta1 and alphavbeta5, not alphavbeta3. Binding to beta3 in LNCaP required EGF activation [PMID:10835423]. Reactome lists the alphaVbeta3:SPP1 complex [DB:Reactome].","key_references":[{"PMID":"7592829","why":"Affinities for alphavbeta1 and alphavbeta5"},{"PMID":"16005200","why":"alphavbeta6 and RGD dependence"},{"PMID":"10835423","why":"alphavbeta3-dependent migration on osteopontin"}],"covers":["LR001408","LR004803"]},"LR007413":{"pair":"SPX -> GALR2:GPR151","headline":"Spexin acts through GALR2 in functional studies; the GALR2:GPR151 complex itself is not directly tested.","interaction_type":"functional only","direction_and_effect":"SPX effects on porcine luteal cells depend on GALR2 by pharmacological inhibition [PMID:42322877]. In mice, SPX shows G-protein-biased agonism at GALR2 and the SPX-GALR2-Gq axis drives anti-colitis effects, using Galr2-/- mice [PMID:42635078].","molecular_requirements":"Only GALR2 is functionally tested; GPR151 is not individually named in either paper (per curator notes), so a requirement for the GPR151 partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Porcine luteal cells (SPX 0.1-10 nM) [PMID:42322877]; mouse colitis model with knockouts [PMID:42635078].","localisation_and_range":"SPX flagged secreted [flag].","caveats":"Abstract-only reading. Evidence supports GALR2 alone, so the complex is supported by one subunit only. No database records.","key_references":[{"PMID":"42635078","why":"Galr2 knockout establishes SPX-GALR2-Gq axis"},{"PMID":"42322877","why":"GALR2 inhibition blocks SPX effects"}],"covers":["LR007413"]},"LR006540":{"pair":"SRPX2 -> PLAUR","headline":"SRPX2 was pulled down as a uPAR ligand in endothelial cells; single abstract-level paper, no database records.","interaction_type":"direct binding","direction_and_effect":"Pulldown experiments identified Srpx2 as a ligand for vascular uPAR; Srpx2 silencing attenuates endothelial migration and delays sprout formation [PMID:19667118]. Activating effect on uPAR signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells; curators record human species, but the abstract does not state it [PMID:19667118].","localisation_and_range":"SRPX2 is flagged secreted [flag]; Srpx2 and uPAR are coexpressed on vascular endothelium [PMID:19667118].","caveats":"Single paper, abstract only; no database records. Pulldown shows association but not affinity or mechanism. The mouse pair is a separate entry; the human pair is ortholog-inferred.","key_references":[{"PMID":"19667118","why":"Pulldown identifies Srpx2 as uPAR ligand"}],"covers":["LR003333","LR006540"]},"LR003336":{"pair":"SVEP1 -> ITGA9","headline":"SVEP1 (polydom) is a direct ligand of integrin alpha9beta1, supported by two papers and databases.","interaction_type":"direct binding","direction_and_effect":"Polydom/SVEP1 binds directly to recombinant integrin alpha9beta1 and mediates alpha9beta1-dependent cell adhesion [PMID:22654117]. In vascular smooth muscle, inhibiting SVEP1/alpha4beta1/alpha9beta1 enhanced intracellular calcium to Gq/11 vasoconstrictors, so the axis restrains contraction [PMID:35802072][DB:UniProt].","molecular_requirements":"Receptor is the alpha9beta1 heterodimer; ITGB1 is needed in addition to ITGA9 [PMID:22654117][DB:UniProt]. Polydom mapped integrin-binding site with N-terminal deletion constructs (site not detailed in our evidence) [PMID:22654117].","affinity_potency":[],"species_and_systems":"Recombinant integrin and cell adhesion assays (species not stated in dossier) [PMID:22654117]; human iPSC-derived VSMCs and Svep1+/- mouse vessels [PMID:35802072].","localisation_and_range":"SVEP1 is flagged secreted [flag]; described as an extracellular matrix protein [PMID:22654117].","caveats":"Both papers read as abstracts only. The abstract says the affinity far exceeds that of other alpha9beta1 ligands but no value is given in our evidence [PMID:22654117]. GtoPdb records binding with no affinity [DB:GtoPdb].","key_references":[{"PMID":"22654117","why":"polydom/SVEP1 binds integrin alpha9beta1 directly"},{"PMID":"35802072","why":"SVEP1-integrin axis in vasoregulation"}],"covers":["LR003336","LR006543"]},"LR004812":{"pair":"TAC1 -> TACR3","headline":"Neurokinin A (TAC1) is a low-affinity agonist of the NK3 receptor (TACR3); one abstract-only paper plus GtoPdb and UniProt.","interaction_type":"direct binding","direction_and_effect":"Agonist with low receptor affinity per UniProt [DB:UniProt]; GtoPdb lists a full agonist [DB:GtoPdb]. Binding and Ca2+ mobilisation were similar in HEK293 cells expressing murine or human NK3 receptor, with substance P and neurokinin A more potent in the murine NK3 cells [PMID:11226387].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 5.5-6.3","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"HEK293 cells expressing murine or human NK3 receptor [PMID:11226387]. The mouse pair is projected from human evidence.","localisation_and_range":"TAC1 is flagged secreted and TACR3 transmembrane [flag]; range not otherwise reported.","caveats":"Abstract only. The curators note NK3's preferred ligand is neurokinin B (TAC3) and this is cross-reactivity [PMID:11226387]. The paper's affinity numbers for NKA are not in the abstract.","key_references":[{"PMID":"11226387","why":"Binding and Ca2+ responses to tachykinin agonists at murine and human NK3"}],"covers":["LR001417","LR004812"]},"LR001419":{"pair":"TAC3 -> TACR2","headline":"NKB (TAC3) to NK2 (TACR2) has minimal support: one abstract-only mutagenesis paper showing a minor role of one residue.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists a full agonist [DB:GtoPdb]. In the mutagenesis paper, Leu292 appears to play a minor role in binding of substance P and NKB to the human NK2 receptor; the Leu292-Ser mutant binds NKB and SP with approximately a 5-fold greater affinity than wild type [PMID:7961636].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 5.0-7.7","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human NK2 receptor mutants [PMID:7961636].","localisation_and_range":"TAC3 flagged secreted and TACR2 transmembrane [flag].","caveats":"Abstract only; the paper focuses on NKA and gives no NKB affinity for the wild-type receptor. Evidence is a mutant effect, not an agonist assay.","key_references":[{"PMID":"7961636","why":"Leu292 mutation alters NKB binding at human NK2"}],"covers":["LR001419"]},"LR003345":{"pair":"TAFA2 -> KIR2DL5A","headline":"TAFA2 stained KIR2DL5A-expressing K562 cells in a screening paper; binding, not signalling, is shown.","interaction_type":"direct binding","direction_and_effect":"Direction and effect are not reported in our evidence; only binding was tested [PMID:36178190].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human TAFA2:SA-647 tetramers at 200 nM on K562 cells transduced with FLAG-tagged KIR2DL5A, by flow cytometry [PMID:36178190].","localisation_and_range":"TAFA2 is flagged secreted; KIR2DL5A is flagged a transmembrane receptor [flag].","caveats":"The source table lists this pair as a phylogenetic homology analysis (PHA) prediction tested by cell surface staining only, with no SPR [PMID:36178190]. No affinity and no functional readout; KIR2DL5A was not a CRISPRa screen hit.","key_references":[{"PMID":"36178190","why":"CRISPRa screen of orphan ligands including TAFA2 with KIR staining"}],"covers":["LR003345"]},"LR003354":{"pair":"TAFA5 -> RNF167","headline":"TAFA5 binds the RNF167 ectodomain by SPR in one screening paper; no affinity or function reported.","interaction_type":"direct binding","direction_and_effect":"SPR sensorgrams showed human TAFA-5 binding to RNF167-ECD, as did TAFA-2, PTN and MDK [PMID:36178190]. RNF167 was a shared hit across PTN, TAFA-2 and TAFA-5 CRISPRa screens [PMID:36178190]. Effect on RNF167 is not reported in our evidence.","molecular_requirements":"The RNF167 ectodomain alone was used [PMID:36178190].","affinity_potency":[],"species_and_systems":"Recombinant human proteins, SPR [PMID:36178190]. Mouse pair projected by orthology.","localisation_and_range":"TAFA5 annotated secreted [flag]; RNF167 annotated receptor [flag].","caveats":"Single screening paper. The authors state RING E3 ligase interactions typically show weak affinity and fast kinetics [PMID:36178190]. Receptor role for an E3 ligase is not demonstrated.","key_references":[{"PMID":"36178190","why":"SPR binding of TAFA-5 to RNF167-ECD after CRISPRa screen"}],"covers":["LR003354","LR006557"]},"LR007422":{"pair":"TAX1BP3 -> ADGRB2","headline":"Database-asserted interaction only; likely an intracellular adaptor-receptor contact rather than a secreted ligand.","interaction_type":"database-asserted only","direction_and_effect":"No paper in our evidence confirms a ligand-receptor effect; UniProt states that TAX1BP3 interacts with ADGRB2 and that ADGRB2 interacts via its carboxy-terminus with TAX1BP3 [DB:UniProt, PMID:21787750].","molecular_requirements":"Interaction is via the carboxy-terminus of ADGRB2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the underlying experiments not reported in our evidence.","localisation_and_range":"TAX1BP3 is annotated as not secreted [flag].","caveats":"Judged papers were classed review_only or different_entity, so no curator-verified paper exists. Support is UniProt subunit annotation only [DB:UniProt].","key_references":[],"covers":["LR007422"]},"LR003363":{"pair":"TENM4 -> ADGRL3","headline":"Cell-aggregation evidence that teneurin-4 cells adhere to latrophilin-expressing cells; no binding data for ADGRL3 specifically.","interaction_type":"functional only","direction_and_effect":"Cells expressing Lphn1/2/3 formed large aggregates with cells expressing Ten2 or Ten4, indicating intercellular adhesion [PMID:24273166].","molecular_requirements":"Binding is mapped to the lectin-like domain of latrophilins in the abstract; ADGRL3 specific requirements are not reported in our evidence [PMID:24273166].","affinity_potency":[],"species_and_systems":"HEK293T cell aggregation assay; species unspecified. The human pair and the mouse pair are both ortholog-inferred [PMID:24273166].","localisation_and_range":"Both partners have transmembrane flags [flag]; the adhesion assay is consistent with contact-dependent interaction.","caveats":"The aggregation assay does not distinguish ADGRL3 from the other latrophilins in the abstract-level evidence. Pulldown binding in the same paper is described in our evidence for Lphn1 only. The curator quote is a browser read, unverifiable, spot-check pending.","key_references":[{"PMID":"24273166","why":"Latrophilin cells aggregate with Ten4 cells"}],"covers":["LR003363","LR006566"]},"LR005343":{"pair":"TFF2 -> CXCR4","headline":"TFF2 activates CXCR4 signalling in several cell systems (Ca2+, MAPK/ERK, proliferation); direct binding not measured in our evidence.","interaction_type":"functional only","direction_and_effect":"TFF2 acts as a CXCR4 agonist: both mouse and human TFF2 (approximately 0.5 microM) activate Ca2+ signalling in Jurkat cells, blocked by SDF-1alpha desensitization, AMD3100 or anti-CXCR4 antibody, and TFF2 reduces subsequent SDF-1alpha Ca2+ rise and chemotaxis [PMID:19064997]. CXCR4-negative AGS cells respond only after CXCR4 expression [PMID:19064997]. A CXCR4 antagonist prevented TFF2-peptide-induced ERK1/2 phosphorylation and BrdU incorporation in MIN6 cells [PMID:23183167].","molecular_requirements":"CXCR4 is necessary for the responses shown; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse TFF2 proteins in Jurkat, AGS, KATO III and AsPC-1 cells [PMID:19064997]; INS-1 cells, MIN6 cells and mouse islets [PMID:23183167].","localisation_and_range":"TFF2 is annotated secreted [flag]; paracrine action is implied but not tested.","caveats":"Both papers were read as abstracts only. No binding assay or affinity is in our evidence; evidence is functional/pharmacological. TFF2 is a noncognate ligand relative to SDF-1alpha per curator notes.","key_references":[{"PMID":"19064997","why":"TFF2 activates CXCR4 in Jurkat, AGS and cancer lines"},{"PMID":"23183167","why":"CXCR4 antagonist blocks TFF2 effects in beta-cells"}],"covers":["LR002015","LR005343"]},"LR004830":{"pair":"TGFA -> EGFR","headline":"Well supported: co-crystal structure of TGFalpha with the EGFR ectodomain, plus kinase activation by the TGFalpha precursor.","interaction_type":"direct binding","direction_and_effect":"TGFalpha binds EGFR; a 17-19 kDa TGFalpha precursor binds EGF/TGF-alpha receptors and activates receptor-associated tyrosine kinase activity in intact cells [PMID:3018723].","molecular_requirements":"In the 2.5 A structure, a 2:2 TGFalpha:sEGFR501 complex, each ligand contacts one receptor molecule via L1 and L2 domains; the back-to-back dimer is favoured as biologically relevant [PMID:12297049].","affinity_potency":[],"species_and_systems":"Truncated human EGFR ectodomain crystal structure [PMID:12297049]; retrovirus-transformed rat cells for the precursor [PMID:3018723]. Mouse pair is ortholog-inferred. PDB 1MOX is listed [DB:PDB 1MOX].","localisation_and_range":"Ligand is annotated both secreted and transmembrane [flag]; the precursor was released as a soluble protein from transformed rat cells [PMID:3018723].","caveats":"Abstracts only. No affinity value is in our evidence; GtoPdb has a binding record with pKi units but no value shown [DB:GtoPdb].","key_references":[{"PMID":"12297049","why":"Crystal structure of TGFalpha bound to EGFR ectodomain"},{"PMID":"3018723","why":"TGFalpha precursor binds and activates EGFR"}],"covers":["LR001435","LR004830"]},"LR001437":{"pair":"TGFA -> ERBB4","headline":"Co-IP of TGF-alpha precursor splice forms with ERBB4 in CHO cells; an intracellular, isoform-specific interaction, not classic extracellular signalling.","interaction_type":"conflicting","direction_and_effect":"Co-immunoprecipitation was seen for the wild-type precursor but not the others; precursor-ErbB signalling effect is not reported in our evidence [PMID:10918572].","molecular_requirements":"Interaction is mediated by the precursor's cytoplasmic C-terminal region, shown with chimeras and mutants [PMID:10918572].","affinity_potency":[],"species_and_systems":"CHO cells overexpressing human TGF-alpha precursors (WT, VaI, VaII); mouse pair is ortholog-inferred [PMID:10918572].","localisation_and_range":"Membrane-anchored precursor with intracellular C-terminal interaction [PMID:10918572]; ligand also annotated secreted [flag].","caveats":"VaI and VaII did not co-immunoprecipitate with ErbB4, so the interaction is splice-variant specific. Co-IP cannot exclude a bridging partner. Abstract only.","key_references":[{"PMID":"10918572","why":"Co-IP of TGFalpha precursor forms with ErbBs"}],"covers":["LR001437","LR004832"]},"LR001446":{"pair":"TGFB2 -> ACVR1","headline":"TGF-beta2 triggers ALK2 phosphorylation and ALK2-dependent endothelial reprogramming in HUVEC; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"TGF-beta2 or BMP4 for 15 min induced ALK2 phosphorylation in HUVECs, and ALK2 siRNA blocked the TGF-beta2-induced rise in FSP-1 and STRO-1 [PMID:21102460].","molecular_requirements":"Not reported in our evidence; whether ALK2 acts alone or with a type II or TGFBR1 partner is not tested in the excerpts.","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC, HCMEC) with recombinant ligand; mouse models were used for the ALK2 mutation work, not for this ligand [PMID:21102460]. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand secreted [flag]; range follows from that flag only.","caveats":"Single paper with functional readout; no binding assay. Other judged papers were review-only, abstract-insufficient or a different entity.","key_references":[{"PMID":"21102460","why":"TGF-beta2-induced ALK2 phosphorylation and ALK2-dependent EndMT"}],"covers":["LR001446","LR004841"]},"LR007431":{"pair":"TGFB2 -> TGFBR1:TGFBR2","headline":"TGF-beta2 cross-links to type I and II receptors in Rat-1 cells, supporting a complex-level contact with TGFBR1:TGFBR2.","interaction_type":"direct binding","direction_and_effect":"Radioiodinated TGF-beta2 (and beta1) bound and was cross-linked to type I and II receptors, plus type III receptors, in Rat-1 cells [PMID:7693660]. Annotated stimulatory [flag].","molecular_requirements":"Antibodies to the type II receptor precipitated labelled type I and III receptors as well as type II after cross-linking, consistent with hetero-oligomeric complexes [PMID:7693660].","affinity_potency":[],"species_and_systems":"Rat-1 fibroblasts with radioiodinated ligand, so receptor species is rat [PMID:7693660]. Human pair in our database.","localisation_and_range":"Ligand secreted, receptors transmembrane [flag].","caveats":"Abstract-only, single 1993 paper; cross-linking does not give affinity or distinguish isoform specificity.","key_references":[{"PMID":"7693660","why":"Cross-linking of TGF-beta to type I/II/III receptors in Rat-1 cells"}],"covers":["LR007431"]},"LR003372":{"pair":"TGFB3 -> ITGA8","headline":"Integrin alpha8 chain: cells expressing alpha8 adhere to LAP-TGF-beta3 in an RGD-dependent manner; chain-only evidence.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cells adhered to LAP-TGFbeta3 better than mock cells; adhesion was RGD-dependent [PMID:12415008].","molecular_requirements":"The binder is the alpha8beta1 heterodimer; the alpha8 chain alone is not shown to suffice [PMID:12415008].","affinity_potency":[],"species_and_systems":"Transfected cell lines, adhesion and spreading assays; species not reported in our evidence [PMID:12415008]. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; adhesion is matrix/contact-type.","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Abstract-only; RGD site role is from curator notes.","key_references":[{"PMID":"12415008","why":"alpha8beta1 adhesion to LAP-TGFbeta3"}],"covers":["LR003372","LR006573"]},"LR001455":{"pair":"TGM2 -> ITGA4","headline":"Cell adhesion to tTG through integrin alpha4beta1 in MOLT-3 cells; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"MOLT-3 cells adhere to tTG through alpha(4)beta(1) [PMID:10816592]. Adhesion was blocked by anti-integrin antibodies in the curator's assay description [PMID:10816592].","molecular_requirements":"The functional receptor is the alpha4beta1 heterodimer, so ITGB1 is also required [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human cell lines (MOLT-3, G-361) with tTG [PMID:10816592]. Mouse pair is ortholog-inferred.","localisation_and_range":"tTG is flagged secreted [flag]; the assay is cell adhesion to tTG [PMID:10816592].","caveats":"Cell-adhesion and blocking antibody data only, not direct binding; another integrin judgement was abstract_insufficient.","key_references":[{"PMID":"10816592","why":"tTG as ligand of alpha9beta1 and alpha4beta1"}],"covers":["LR001455","LR004850"]},"LR003381":{"pair":"THBS1 -> ITGA1","headline":"Single recent paper supports a THBS1-ITGA1 interaction by co-IP in osteosarcoma cells; thin evidence.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation confirmed THBS1 interacts with ITGA1 (and ITGA6) in human 143B and MG-63 osteosarcoma cells; THBS1 promoted ITGA1 accumulation on the cell membrane, FAK/MLC2 phosphorylation and cytoskeleton remodeling, i.e. a stimulatory outcome [PMID:40083708].","molecular_requirements":"Not reported in our evidence which beta chain pairs with ITGA1. ITGA6 was also implicated, and colocalisation with THBS1 occurred only in the early sphere-formation phase [PMID:40083708].","affinity_potency":[],"species_and_systems":"Human osteosarcoma lines; metastasis models in nude mice used tumour cells with THBS1 manipulations [PMID:40083708]. The mouse pair is ortholog-inferred, not tested.","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"One paper only. The paper's own text describes direct interactions between THBS1 and ITGA1 as already shown in a network analysis, with co-IP as its confirmation; co-IP does not prove direct binding. No affinity reported. No database record.","key_references":[{"PMID":"40083708","why":"Co-IP of THBS1 with ITGA1/ITGA6 in osteosarcoma cells (full text)"}],"covers":["LR003381","LR006582"]},"LR001464":{"pair":"THBS1 -> ITGA2B","headline":"Weak platelet GPIIb-IIIa binding to THBS1 plus a CD47-dependent activation route; evidence is older and abstract-level.","interaction_type":"direct binding","direction_and_effect":"GPIIb-IIIa (alphaIIbbeta3) from human platelets bound a thrombospondin column and was eluted with GRGDSP peptide, but it bound 'relatively weakly' [PMID:2478219]. Separately, THBS1 activates alphaIIbbeta3 through CD47 (agonist), as a secreted costimulator [PMID:9169439]. Reactome records the alphaIIbbeta3:THBS1 interaction [DB:Reactome].","molecular_requirements":"The beta3 chain partners ITGA2B in this binding [PMID:2478219]. The activation route requires CD47 engagement, with alphaIIb, beta3 and c-Src co-precipitating with CD47 [PMID:9169439].","affinity_potency":[],"species_and_systems":"Human platelet membrane proteins for binding [PMID:2478219]; the activation paper is recorded as mouse in this row, though its abstract does not name a species [PMID:9169439].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"Both papers read as abstracts. The 1997 paper shows indirect activation via CD47 rather than direct alphaIIbbeta3 binding. One further paper was judged abstract-insufficient. No affinity reported.","key_references":[{"PMID":"2478219","why":"THBS1-Sepharose retains platelet GPIIb-IIIa, eluted by RGD peptide"},{"PMID":"9169439","why":"THBS1 activates alphaIIbbeta3 via CD47"}],"covers":["LR001464","LR004859"]},"LR001473":{"pair":"THBS2 -> ITGA4","headline":"Alpha4beta1 mediates venous endothelial cell adhesion to THBS2 N-terminal regions; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Alpha4beta1 supports adhesion and chemotaxis to N-terminal regions of thrombospondin-1 and thrombospondin-2, not in microvascular endothelial cells [PMID:14699013].","molecular_requirements":"Alpha4beta1 heterodimer; ITGA4 pairs with beta1 [PMID:14699013].","affinity_potency":[],"species_and_systems":"Endothelial cells with recombinant N-terminal regions; the dossier labels species unspecified, though the companion curation shows mouse [PMID:14699013].","localisation_and_range":"Immobilised matrix substrate; THBS2 flagged secreted [flag].","caveats":"Abstract only; the evidence sentence mentions THBS1 first and THBS2 only as recombinant N-terminal region. Direct binding not measured.","key_references":[{"PMID":"14699013","why":"alpha4beta1 mediates responses to N-terminal THBS regions"}],"covers":["LR001473"]},"LR003390":{"pair":"THBS4 -> NOTCH1","headline":"Thbs4 binds Notch1 directly in pull-downs and IP and drives Notch activation in mouse brain; one paper, full text read.","interaction_type":"direct binding","direction_and_effect":"Agonist: Thbs4 binding and endocytosis of Notch1 raises NICD and downstream Nfia, supporting injury-induced astrogenesis; Thbs4-knockout mice show defective SVZ astrogenesis [PMID:23615612].","molecular_requirements":"Recombinant Notch1-Fc containing the first 13 extracellular EGF-like repeats pulled down purified Thbs4; Thbs2 did not [PMID:23615612]. Thbs4 effects needed Notch activity (not rescued with DAPT or DBZ) [PMID:23615612].","affinity_potency":[],"species_and_systems":"Mouse experiments: primary SVZ neural stem cell cultures, mouse Notch1-Fc, injured mouse brain. Human pair is ortholog-inferred; the mouse interaction is the one tested [PMID:23615612].","localisation_and_range":"Thbs4 is a secreted homopentameric glycoprotein [PMID:23615612] and is flagged secreted [flag]; Notch1 is flagged transmembrane [flag]. Paracrine action on Notch1-bearing cells.","caveats":"IP from freshly isolated SVZ tissue did not detect Thbs4 pull-down; the interaction appeared 3 days post-injury [PMID:23615612]. No affinity reported.","key_references":[{"PMID":"23615612","why":"Direct Thbs4-Notch1 binding and Notch activation in SVZ astrogenesis"}],"covers":["LR003390","LR006591"]},"LR006603":{"pair":"TIMP1 -> LRP1","headline":"TIMP-1 binds LRP1 directly (SPR) and engages it on macrophages; effect varies by context and some evidence is via MMP complexes.","interaction_type":"direct binding","direction_and_effect":"SPR showed that all TIMP family members bind LRP1 directly [PMID:32702237]. TIMP-1 alone binds LRP1, while in a glioblastoma model tumour-derived TIMP1 engaged LRP1 on macrophages, increased AKT Ser473 phosphorylation and shifted macrophages toward an immunosuppressive state [PMID:42874178]. The MMP-9/TIMP-1 complex is internalised by LRP, with the binding determinant on MMP-9 [PMID:11279011].","molecular_requirements":"Lysine residues on TIMP-1 are needed: alkylated TIMP-1 failed to bind LRP1 [PMID:32702237]. LRP1 may also take up TIMP-1 as part of MMP complexes [PMID:11279011].","affinity_potency":[{"value":"KD 23 nM to 33 nM","assay":"SPR equilibrium binding of TIMPs (TIMP-1 to TIMP-4) to LRP1","system":"purified proteins","cite":"PMID:32702237"}],"species_and_systems":"SPR with purified proteins [PMID:32702237]; mouse embryonic fibroblasts for the MMP-9/TIMP-1 work [PMID:11279011]; human glioblastoma specimens and murine glioma models [PMID:42874178].","localisation_and_range":"LRP1 is flagged as a receptor and TIMP1 as secreted [flag]; the macrophage action is paracrine [PMID:42874178].","caveats":"The older paper (read as abstract) concerns the MMP-9/TIMP-1 complex, not free TIMP-1 [PMID:11279011]. The glioblastoma paper is an abstract read and does not show direct binding [PMID:42874178]. Three further papers were abstract_insufficient and two were a different entity.","key_references":[{"PMID":"32702237","why":"SPR showing direct TIMP-1 binding to LRP1"},{"PMID":"42874178","why":"TIMP1-LRP1 signalling in macrophages"},{"PMID":"11279011","why":"LRP-mediated uptake of MMP-9/TIMP-1 complex"}],"covers":["LR003402","LR006603"]},"LR003408":{"pair":"TMPRSS6 -> HJV","headline":"Matriptase-2 (TMPRSS6) binds and cleaves hemojuvelin, inhibiting hepcidin activation; one abstract-read paper plus database co-IP records.","interaction_type":"direct binding","direction_and_effect":"Matriptase-2 cleaved membrane HJV, inhibiting the hepcidin response; it interacted with HJV through its ectodomain, and this was preserved in the protease-dead matriptase-2 MASK mutant, so binding is separable from cleavage [PMID:18976966]. The effect is inhibitory. IntAct and UniProt record the interaction [DB:IntAct][DB:UniProt].","molecular_requirements":"The ectodomain mediates binding; cleavage needs the serine protease domain, and the R774C mutant gave partial cleavage and partial inhibition [PMID:18976966].","affinity_potency":[],"species_and_systems":"Human Hep3B cells with human constructs and zebrafish expression of mutants [PMID:18976966]; mouse pair is ortholog-inferred.","localisation_and_range":"TMPRSS6 is flagged non-secreted and HJV as secreted [flag]; cleavage occurs on the plasma membrane [PMID:18976966].","caveats":"Flags label HJV as the receptor, but the paper shows HJV is the substrate of the protease. Binding was assessed in an abstract-read paper; no affinity reported.","key_references":[{"PMID":"18976966","why":"Matriptase-2 ectodomain interacts with and cleaves HJV"}],"covers":["LR003408","LR006609"]},"LR001482":{"pair":"TNC -> CNTN1","headline":"Tenascin-C binds F3/contactin-1 directly in a mouse brain study; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C was affinity-isolated from developing mouse brain extracts with F3IgFc, and the authors showed that tenascin-C can bind directly to F3, possibly exclusively with PTPzeta/RPTPbeta [PMID:10103110].","molecular_requirements":"not reported in our evidence. Binding was to Ig-like domains of an F3IgFc chimera [PMID:10103110].","affinity_potency":[],"species_and_systems":"Mouse brain extracts and F3IgFc chimera; the curated row lists species as unspecified. The human pair is ortholog-inferred [PMID:10103110].","localisation_and_range":"TNC is flagged secreted and non-transmembrane; CNTN1 is flagged membrane-bound receptor [flag].","caveats":"Abstract-only; affinity for the tenascin-C interaction is not given, only that it is lower than that of PTPzeta/RPTPbeta.","key_references":[{"PMID":"10103110","why":"F3/contactin affinity isolation of tenascin-C"}],"covers":["LR001482"]},"LR007071":{"pair":"TNC -> ITGAV:ITGB3","headline":"Tenascin-C engages alphavbeta3 on human smooth muscle cells, promoting EGFR clustering and growth; abstract-only.","interaction_type":"functional only","direction_and_effect":"TN-C interactions with alpha v beta 3 integrins modify SMC shape and EGF-dependent growth, with EGF receptor clustering and increased tyrosine phosphorylation; cross-linking beta3 reproduced the effect [PMID:9314546]. Reactome records an alphaVbeta3:tenascin interaction [DB:Reactome].","molecular_requirements":"Heterodimer alphaVbeta3 [PMID:9314546].","affinity_potency":[],"species_and_systems":"Human per curator record; vascular smooth muscle cells [PMID:9314546].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Functional, abstract-only; binding itself not shown. Curator notes this is a duplicate subunit ordering of ITGB3:ITGAV from the same paper. Other rows: two abstract_insufficient, one review_only.","key_references":[{"PMID":"9314546","why":"TN-C/alphavbeta3 and EGF-R activation in SMCs"}],"covers":["LR007071"]},"LR006612":{"pair":"TNC -> ITGB6","headline":"Integrin beta6 (with alphav) bound tenascin-C immobilised on beads in MCF-7 breast cancer cell lysates; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Integrin subunits alphav, beta1 and beta6, but not alpha2, bound to TNC immobilized on agarose beads in a divalent cation-dependent manner [PMID:23958855]. TNC treatment increased beta6 protein and alphavbeta6 in focal adhesions [PMID:23958855].","molecular_requirements":"Beta6 pairs with alphav [PMID:23958855].","affinity_potency":[],"species_and_systems":"Human MCF-7 cells [PMID:23958855].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-level; the antibody result needed combined anti-beta1 and anti-alphavbeta6 [PMID:23958855]. UniProt record concerns fibronectin [DB:UniProt].","key_references":[{"PMID":"23958855","why":"TNC pulldown of alphav, beta1, beta6"}],"covers":["LR003411","LR006612"]},"LR001491":{"pair":"TNC -> PTPRZ1","headline":"Direct binding of tenascin-C to the PTPRZ1 ectodomain is supported by structural and binding work, mostly in recombinant and mouse systems; one paper is abstract-only.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C is the ligand and PTPRZ1 (RPTP-zeta) the receptor. RPTP-zeta forms a complex with tenascin-C that is structurally the same as its complex with tenascin-R [PMID:37356715]. A soluble RPTPbeta FNIII fragment blocked adhesion and spreading of astrocytoma cells on tenascin C, so the binding is functional in adhesion [PMID:11313993]. Signalling direction (agonist or inhibitor) is not reported in our evidence.","molecular_requirements":"The C-terminal fibrinogen-like (Fg) region (FN1-Fg) of tenascin-C bound RPTP-zeta, and binding mapped to the single FN repeat of the RPTP-zeta ectodomain; it did not bind the homolog RPTP-gamma [PMID:37356715]. An earlier study mapped binding to alternatively spliced repeats A1,2,4 [PMID:11313993]. Only one chain per partner is described.","affinity_potency":[],"species_and_systems":"Full-text work used human tenascin-C fusion proteins on HEK293 cells expressing RPTP-zeta, plus structural analysis in a mouse perineuronal-net context [PMID:37356715]. The adhesion study used human glial tumour cells [PMID:11313993]. A PDB record of the two proteins exists [DB:PDB 8FN8].","localisation_and_range":"Tenascin-C is flagged secreted and PTPRZ1 flagged secreted and transmembrane [flag]. Tenascin-C is described as an extracellular matrix protein, so signalling is likely juxtacrine or matrix-contact [PMID:37356715].","caveats":"The first structural paper was read as abstract plus excerpts only. One confirming paper is an expression-profiling study that calls tenascin-C a high-affinity ligand as background and did not test binding itself [PMID:20689858]. The adhesion paper uses the name 'RPTPbeta', which may be ambiguous with PTPRB, and it was read as abstract only [PMID:11313993].","key_references":[{"PMID":"37356715","why":"Binding and structure of PTPRZ1 ectodomain with tenascin-C, FN1-Fg domains"},{"PMID":"11313993","why":"RPTPbeta FNIII binds tenascin C and mediates glial tumour cell adhesion"}],"covers":["LR001491","LR004886"]},"LR005352":{"pair":"TNFRSF14 -> CD160","headline":"HVEM (TNFRSF14) binds CD160, supported by crystal structures and a T-cell study plus database records; CD160 engagement is inhibitory.","interaction_type":"direct binding","direction_and_effect":"HVEM is the receptor engaged by CD160 (the pair is stored with HVEM as 'ligand'). CD160 crosslinking inhibits CD3/CD28-driven activation of human CD4+ T cells, and HVEM acts as a 'bidirectional switch' depending on which ligand engages it [PMID:18193050]. Knockin mice with HVEM muteins that lose BTLA/CD160 binding support a role for the Ig ligands (BTLA/CD160) in limiting liver inflammation [PMID:34709351].","molecular_requirements":"HVEM can bind CD160 and LIGHT at the same time in a human HVEM-LIGHT-CD160 ternary complex [PMID:34709351]. The structures used a single-chain CD160-HVEM fusion because the CD160-HVEM interaction is weak [PMID:34709351]. Inhibition of CD4+ T cells by HVEM-transfected cells depended on both CD160 and BTLA, and on HVEM cysteine-rich domain 1 [PMID:18193050]. PDB 6NG3 and 7MSG contain both chains [DB:PDB 6NG3].","affinity_potency":[],"species_and_systems":"Human proteins and human CD4+ T cells [PMID:18193050]; human structures plus mouse HVEM mutants and knockin mice [PMID:34709351]. Both papers were read as abstracts by curators, though excerpts from the 2021 full text are available.","localisation_and_range":"CD160 is membrane-anchored; the paper discusses GPI-linked and transmembrane forms [PMID:34709351]. HVEM is flagged membrane-bound [flag]. The CD160 entity also carries a secreted flag [flag].","caveats":"Mouse HVEM results use BTLA/CD160 double-loss muteins, so CD160-specific effects cannot be separated from BTLA [PMID:34709351]. The CD4+ T-cell inhibition also needs BTLA [PMID:18193050]. A weak affinity is described but its value is attributed to earlier work in the excerpt.","key_references":[{"PMID":"18193050","why":"HVEM identified as CD160 ligand; inhibitory in human CD4+ T cells"},{"PMID":"34709351","why":"HVEM-LIGHT-CD160 ternary structure and selective mutants"}],"covers":["LR002024","LR005352"]},"LR007440":{"pair":"TNFSF14 -> TNFRSF6B","headline":"LIGHT is bound by soluble decoy DcR3; evidence is functional and the stored direction is inverted.","interaction_type":"functional only","direction_and_effect":"DcR3 is a receptor for FasL and LIGHT and neutralises their cytotoxic effects in tumours [PMID:11994433]; binding to membrane ligands triggers reverse signalling into monocytes, enhancing adhesion [PMID:14697332].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells, DcR3.Fc on monocytes and dendritic cells; abstracts only [PMID:11994433][PMID:14697332].","localisation_and_range":"DcR3 is soluble [PMID:14697332]; LIGHT is a membrane ligand [flag].","caveats":"DcR3 acts as a decoy and, via reverse signalling, LIGHT is functionally the receptor. Both papers abstract only. Binding support from BioGRID, IntAct, PDB, Reactome [DB:BioGRID][DB:PDB 4J6G][DB:Reactome].","key_references":[{"PMID":"14697332","why":"Reverse signalling by DcR3 binding to LIGHT"},{"PMID":"11994433","why":"DcR3 neutralises LIGHT"}],"covers":["LR007440"]},"LR001509":{"pair":"TNFSF18 -> TNFRSF18","headline":"GITRL-GITR is supported by two abstract-only functional papers and structures.","interaction_type":"functional only","direction_and_effect":"The ligand for AITR was found to be an undescribed TNF family member expressed in endothelial cells [PMID:10037686]. Cotransfection of hGITRL and hGITR in HEK293 cells activated NF-kappaB and inhibited antigen-receptor-induced death in Jurkat [PMID:10074428].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, HEK293 and Jurkat cells [PMID:10074428].","localisation_and_range":"TNFSF18 flagged transmembrane, not secreted; TNFRSF18 transmembrane [flag].","caveats":"Abstracts only; functional co-transfection, not a binding measurement. SPR in IntAct and PDB structures exist [DB:IntAct][DB:PDB 7KHD].","key_references":[{"PMID":"10074428","why":"NF-kappaB activation by GITRL-GITR"},{"PMID":"10037686","why":"Identification of AITRL"}],"covers":["LR001509","LR004899"]},"LR004902":{"pair":"TNFSF9 -> TNFRSF9","headline":"4-1BBL binds 4-1BB with high affinity in two abstract-read papers, plus structures and pathway records; costimulatory.","interaction_type":"direct binding","direction_and_effect":"Agonist: 4-1BB-L-transfected cells and anti-4-1BB antibody induced strong proliferation in mitogen-costimulated primary T cells, while ligation on T-cell clones enhanced activation-induced cell death after TCR/CD3 engagement [PMID:8088337]. GtoPdb lists the pair without type or action [DB:GtoPdb].","molecular_requirements":"Receptor 4-1BB alone; the intact murine protein was required for 4-1BBL binding [PMID:9045669]. Subunit stoichiometry not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human 4-1BB.Fc fusion protein with native and recombinant human 4-1BB-L [PMID:8088337]; murine m4-1BB/m4-1BBL binding, and human h4-1BB bound only h4-1BBL, in the second paper [PMID:9045669]. PDB structures exist with chains of both proteins [DB:PDB 6A3V].","localisation_and_range":"Both entity flags mark the ligand as secreted and transmembrane [flag]; the receptor as transmembrane [flag]. Papers do not describe the range directly.","caveats":"Both papers were read as abstracts only. Affinity is described as high by Scatchard analysis but no value is given [PMID:8088337]. Murine 4-1BB also binds laminin; 4-1BBL binding blocked laminin binding, and this was not conserved in human [PMID:9045669].","key_references":[{"PMID":"8088337","why":"Cloning of human 4-1BB-L; Scatchard high-affinity binding of hu4-1BB.Fc"},{"PMID":"9045669","why":"Murine 4-1BBL/4-1BB binding and laminin competition; human comparison"}],"covers":["LR001512","LR004902"]},"LR003417":{"pair":"TNR -> CNTN1","headline":"Tenascin-R binds contactin 1 in a sandwich-binding assay; one abstract-read paper, projected to mouse by orthology.","interaction_type":"direct binding","direction_and_effect":"Tenascin-R interacts with contactin 1 as its neuronal receptor; aggrecan, brevican and neurocan compete for this binding and block TN-R effects on microprocess formation and growth cone size [PMID:16899820].","molecular_requirements":"Aggrecan interaction with TN-R fibronectin type III domains 4-A is needed for its inhibition of TN-R binding to contactin 1; chondroitin sulfate chains are not involved [PMID:16899820].","affinity_potency":[],"species_and_systems":"Tectal cells and a sandwich-binding assay; the species is not stated in the abstract. Both listed interactions (human, mouse) are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor flagged transmembrane and not secreted [flag]. The paper describes extracellular matrix TN-R acting on neurites.","caveats":"Abstract read only; the curator notes the interaction was first described in an earlier paper [PMID:16899820]. The primary assay is competition, so affinity not reported in our evidence.","key_references":[{"PMID":"16899820","why":"Sandwich-binding assay for TN-R/contactin 1 and lectican competition"}],"covers":["LR003417","LR006618"]},"LR006621":{"pair":"TREM2 -> CSF1R","headline":"TREM2 and CSF1R co-immunoprecipitate in HEK293T cells; this is a receptor-receptor association, not a classical ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"TREM2 interacted with CSF1R by co-immunoprecipitation, and they mutually modulate expression: CSF1R knockdown increased Trem2 mRNA and CSF1R was increased in Trem2-deficient microglia. TREM2 was not necessary for CSF1-mediated CSF1R and Akt phosphorylation [PMID:33841415].","molecular_requirements":"Full-length TREM2 bound the CSF1R carboxyl-terminal fragment (514-972 aa, with the transmembrane domain), not the amino-terminal fragment; CSF1R bound both TREM2 fragments [PMID:33841415].","affinity_potency":[],"species_and_systems":"HEK293T transfection for co-IP; mouse primary microglia and Trem2-/-;5XFAD mice for function [PMID:33841415].","localisation_and_range":"TREM2 is flagged secreted and receptor, CSF1R transmembrane [flag]; the paper describes transmembrane-domain interaction on the cell surface of microglia.","caveats":"Evidence is co-IP of overexpressed tagged proteins, not purified binding. TREM2 is itself a receptor, so direction is unclear; the curator-assigned agonist label is not shown by the paper's text, which says TREM2 is not needed for CSF1R signalling [PMID:33841415].","key_references":[{"PMID":"33841415","why":"Co-IP of TREM2 with CSF1R and fragment mapping"}],"covers":["LR003420","LR006621"]},"LR003426":{"pair":"TULP1 -> MERTK","headline":"Tulp1 binds MerTK, the best-characterised TAM target, and induces its activation and phagocytosis; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Tulp1 interacts with Tyro3, Axl and MerTK of the TAM subfamily [PMID:20978472]. Both ligands induced MerTK activation with receptor phosphorylation and signalling, and excess soluble MerTK extracellular domain blocked Tulp1-mediated phagocytosis. [PMID:20978472]","molecular_requirements":"Five minimal phagocytic determinants (K/R(X)1-2KKK) in the Tulp1 N-terminus are essential for MerTK binding, receptor phosphorylation and phagocytosis; the C-terminal region binds phagocytic prey [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. One of the human/mouse pairs is ortholog-inferred.","localisation_and_range":"Unconventionally secreted, no classical signal peptide [PMID:20978472]; ligand flagged secreted and not transmembrane [flag].","caveats":"Abstract read only; no affinity value. Evidence for each TAM receptor shares the same sentence, so receptor-specific binding strength not reported in our evidence. Detailed motif mapping is for MerTK.","key_references":[{"PMID":"20978472","why":"Tulp1 interacts with Tyro3, Axl and MerTK"}],"covers":["LR003426","LR006627"]},"LR010653":{"pair":"TYROBP -> SEMA6D","headline":"Database-asserted only: Reactome complex of SEMA6D with PLXNA1:TREM2:DAP12; no confirmed papers.","interaction_type":"database-asserted only","direction_and_effect":"Reactome has SEMA6D binding to PLXNA1:TREM2:DAP12 [DB:Reactome R-HSA-416725]. Effect not reported in our evidence.","molecular_requirements":"The Reactome complex includes PLXNA1, TREM2 and DAP12 [DB:Reactome R-HSA-416720]; TYROBP alone not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system not reported in our evidence.","localisation_and_range":"TYROBP flagged receptor, transmembrane; SEMA6D flagged transmembrane, not secreted [flag].","caveats":"Interaction class is Receptor-Receptor. Of the judged rows, two were abstract_insufficient and one different_entity; none confirmed. Direct TYROBP-SEMA6D binding is not shown.","key_references":[],"covers":["LR010653"]},"LR010941":{"pair":"UBC -> RIPK1","headline":"Database-asserted only: BioGRID affinity-capture-Western records; ubiquitin conjugation to RIPK1, not a signalling ligand.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID: Affinity Capture-Western records (three) [DB:BioGRID].","localisation_and_range":"Entity flags give no localisation [flag].","caveats":"No papers confirmed; nine rows were different_entity and one abstract_insufficient. The dossier does not show ligand-like signalling.","key_references":[],"covers":["LR010941"]},"LR001518":{"pair":"UCN2 -> CRHR1","headline":"Database-asserted only: GtoPdb lists urocortin 2 as a weak agonist at CRF1; no paper in our evidence confirms the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a full agonist [DB:GtoPdb]; no paper in our dossier tests direction or effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 5.3 to 5.4","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:15450949"}],"species_and_systems":"Species and system not reported in our evidence. The dossier covers human and mouse pairs.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag].","caveats":"No papers were confirmed: 11 were judged abstract_insufficient and 2 concerned a different entity. The only record is one GtoPdb entry, and the pKd of 5.3 to 5.4 is low, so interaction is weak at best.","key_references":[],"covers":["LR001518","LR004908"]},"LR004911":{"pair":"UCN3 -> CRHR2","headline":"Urocortin 3 is a selective CRF2 receptor ligand per two abstract-level papers; GtoPdb lists a full agonist.","interaction_type":"direct binding","direction_and_effect":"Agonist: urocortin III is selective for type 2 CRF receptors [PMID:11416224]; stresscopin binding and activation of type 2 CRH receptor [PMID:11329063]; GtoPdb full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 7.9 to 8.0","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:15450949"}],"species_and_systems":"Urocortin III was cloned from human and mouse and tested on the human receptor [PMID:11416224]; the stresscopin study used human peptides and receptor [PMID:11329063]. Both human and mouse pairs are listed, neither ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; expressed in brain and peripheral tissue by mRNA mapping [PMID:11416224].","caveats":"Both papers read as abstracts only. Mapping stresscopin in PMID:11329063 to UCN3 comes from the curator, since the abstract uses protein names. The PNAS evidence is functional_in_vitro and no binding constant is reported in the abstract.","key_references":[{"PMID":"11416224","why":"Identification of urocortin III as type 2-selective CRF ligand"},{"PMID":"11329063","why":"Stresscopin binding and activation of CRH receptor type 2"}],"covers":["LR001521","LR004911"]},"LR006630":{"pair":"UNC5A -> FLRT1","headline":"UNC5A and FLRT1 bind strongly in a high-throughput extracellular screen; direction and signalling effect for this pair are not shown.","interaction_type":"direct binding","direction_and_effect":"Direction is not determined: binding is reciprocal between proteins that are both cell-surface, and the paper reports neurite attraction/repulsion for FLRT1 stripes (16% attractive, 5% repulsive of 375) but not for UNC5A [PMID:26633812].","molecular_requirements":"Not reported in our evidence beyond the pairing itself; all 12 FLRT1-3 and Unc5A-D combinations bound in the screen [PMID:26633812].","affinity_potency":[],"species_and_systems":"Extracellular biochemical screen with purified proteins in an ELISA format (mean Abs650nm value = 2.14, near saturation) and mouse retina context; species of recombinant proteins not reported in the excerpts [PMID:26633812]. The mouse pair is direct; the human pair is ortholog-inferred.","localisation_and_range":"Both partners are annotated transmembrane [flag]; the paper tested trans interaction between opposing cell surfaces in aggregation assays [PMID:26633812]. FLRT1 also carries a secreted flag [flag].","caveats":"Single paper, full text. Binding is semi-quantitative with a saturated signal; no Kd is given in our evidence. Prior literature described some FLRT-Unc5 pairs, but this pair was among the eight reported as new [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Screen reporting binding of all FLRT-Unc5 pairs"}],"covers":["LR003429","LR006630"]},"LR003435":{"pair":"UNC5B -> ROBO4","headline":"Robo4 extracellular domain binds UNC5B and activates it to counter VEGF signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"A protein-protein interaction screen with the Robo4 extracellular domain found specific binding to UNC5B [PMID:21238923]. Robo4 activates UNC5B, which inhibits signalling downstream of VEGF; so Robo4 acts on UNC5B, the reverse of the listed direction [PMID:21238923]. Function-blocking antibodies against either protein increase angiogenesis and disrupt vessel integrity [PMID:21238923].","molecular_requirements":"Soluble Robo4 rescues barrier defects in Robo4-/- mice but not in mice treated with anti-UNC5B, so functional UNC5B is required [PMID:21238923]. Other subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curators tag both partners as human; the abstract itself describes endothelial cells and Robo4-/- mice, so in vivo work is murine [PMID:21238923].","localisation_and_range":"Both are endothelial membrane guidance receptors; ROBO4 has only a receptor annotation [flag]. Soluble Robo4 protein was active in vivo [PMID:21238923].","caveats":"Read from the abstract only; no affinity, and the binding assay format is not specified. This is a receptor-receptor pairing, and the ligand/receptor labels are conventional.","key_references":[{"PMID":"21238923","why":"Robo4 binds and activates UNC5B to maintain vessel integrity"}],"covers":["LR003435","LR006636"]},"LR001527":{"pair":"VCAM1 -> ITGA4","headline":"VCAM1 engages integrin alpha4 (as alpha4beta1/alpha4beta7); confirmed in adhesion assays, but evidence is abstract-level and chain-ambiguous.","interaction_type":"functional only","direction_and_effect":"Adhesion-mediated: alpha4beta7 on lymphocytes binds VCAM-1 depending on chemokine priming; CCL25 lowered and CXCL10 raised adhesion to VCAM-1 [PMID:29789438]. alpha4beta1 binds VCAM-1 and the VCAM-1 domain 2 forms an accessory binding site [PMID:9235944].","molecular_requirements":"The functional receptor is the alpha/beta heterodimer, not ITGA4 alone: alpha4beta1 and alpha4beta7 are both named [PMID:9235944]. The alpha4 blocking antibody HP2/1 abolished adhesion to both ligands [PMID:29789438].","affinity_potency":[],"species_and_systems":"Human lymphocyte (RPMI 8866-CXCR3) adhesion and single-cell force assays [PMID:29789438]; species unspecified for [PMID:9235944]. Mouse pair is ortholog-inferred.","localisation_and_range":"VCAM1 is flagged secreted and transmembrane [flag]; adhesion assays used immobilised or soluble VCAM-1 and cells, consistent with contact-mediated binding [PMID:29789438].","caveats":"Single integrin chain stored; scoring should use heterodimer. PMID 9235944 read as abstract only and is a chimera/mutagenesis study. BioGRID affinity capture-MS record [DB:BioGRID].","key_references":[{"PMID":"29789438","why":"alpha4beta7 conformers select VCAM-1 versus MAdCAM-1; full text read"},{"PMID":"9235944","why":"alpha4beta1/alpha4beta7 binding footprints on VCAM-1"}],"covers":["LR001527","LR004916"]},"LR008223":{"pair":"VCAM1 -> ITGAM:ITGB2","headline":"No verified paper; the only listed database record concerns ITGAD:ITGB2, not ITGAM.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"VCAM1 flagged secreted and transmembrane [flag].","caveats":"Judged rows were 'different_entity' and 'abstract_insufficient'; no papers shown. The UniProt record names ITGAD:ITGB2 rather than ITGAM:ITGB2 [DB:UniProt].","key_references":[],"covers":["LR008223"]},"LR004920":{"pair":"VCAM1 -> ITGB2","headline":"Evidence is for the alphaDbeta2 heterodimer binding VCAM-1; ITGB2 is the shared chain, abstract only.","interaction_type":"direct binding","direction_and_effect":"Recombinant soluble alphaDbeta2 and the alphaD I-domain bind VCAM-1; mutation of VCAM-1 D40 abrogates binding [PMID:10438935].","molecular_requirements":"beta2 pairs with alphaD for VCAM-1; LFA-1 and Mac-1 are noted in the abstract as binding ICAM-1, not VCAM-1, so ITGB2 alone does not imply binding [PMID:10438935].","affinity_potency":[],"species_and_systems":"Human transfectants and recombinant proteins [PMID:10438935]. Mouse pair is ortholog-inferred.","localisation_and_range":"VCAM1 flagged secreted and transmembrane [flag].","caveats":"Chain-only entry; one abstract-level paper. UniProt lists ITGAD:ITGB2 as VCAM1 receptor [DB:UniProt].","key_references":[{"PMID":"10438935","why":"alphaDbeta2 binds VCAM-1"}],"covers":["LR001531","LR004920"]},"LR001536":{"pair":"VCAN -> TLR2","headline":"Versican activates TLR2 in myeloid and dendritic cells; human data come from DC studies, with mouse co-IP, direct binding not shown.","interaction_type":"functional only","direction_and_effect":"Versican from Lewis lung carcinoma medium activates macrophages via TLR2 with TLR6 and CD14, inducing TNF-alpha [PMID:19122641]. Tumour-derived versican activates TLR2 in DCs, driving IL-6/IL-10 immunosuppressive DCs [PMID:26711349].","molecular_requirements":"TLR2 with co-receptors TLR6 and CD14; the versican antibody co-precipitated TLR2 and CD14 but not TLR4 [PMID:19122641].","affinity_potency":[],"species_and_systems":"Mouse macrophages (Raw264.7) and LLC [PMID:19122641]; human and mouse DCs, TLR2 knockout mice and anti-TLR2 antibody [PMID:26711349]. Human pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted [flag]; acts as a soluble factor on DCs [PMID:26711349].","caveats":"Co-IP does not establish direct binding. PMID 19122641 quote is browser-read and unverified. Full-text read for PMID 26711349 only.","key_references":[{"PMID":"19122641","why":"versican activates TLR2:TLR6 in macrophages"},{"PMID":"26711349","why":"versican activates TLR2 in DCs"}],"covers":["LR001536","LR004925"]},"LR009321":{"pair":"VEGFA -> ITGAV","headline":"Only database records, and these describe integrin alphaVbeta3 binding VEGFR2, not VEGFA directly.","interaction_type":"database-asserted only","direction_and_effect":"No papers were verified for this pair. Reactome has a complex of VEGFA, phosphorylated VEGFR2 and integrin alphaVbeta3 [DB:Reactome].","molecular_requirements":"Entity is named integrin alphaVbeta3 [flag]; the Reactome binding reaction is alphaVbeta3 binding phospho-VEGFR2 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human Reactome annotation; experimental system not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on database records alone. Curator judgements were review-only or abstract-insufficient, so no paper verifies direct VEGFA-integrin binding here.","key_references":[],"covers":["LR009321"]},"LR003444":{"pair":"VEGFA -> PDGFRB","headline":"Cross-family VEGF-A binding to PDGFR-beta measured by SPR with high affinity; single abstract-level paper, no independent replication in our evidence.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-A bound PDGFR-beta in surface plasmon resonance; curators label the effect agonist, but the paper reports binding kinetics, not signalling [PMID:29180757].","molecular_requirements":"Not reported in our evidence (no subunit or co-receptor requirements); receptor is a single chain.","affinity_potency":[{"value":"KD = 340 pM","assay":"surface plasmon resonance (BIAcore)","system":"recombinant human proteins","cite":"PMID:29180757"}],"species_and_systems":"Human ligand and receptor, purified recombinant proteins in vitro [PMID:29180757]. The mouse pair is inferred from human evidence (ortholog projection).","localisation_and_range":"VEGFA is flagged secreted and PDGFRB transmembrane [flag]; this implies paracrine action on receptor-bearing cells.","caveats":"Only one paper; curator read depth is abstract only, although full-text excerpts describe the SPR method and chi2-to-Rmax cut-off. The paper calls the interaction recent/previously reported but quantified here for the first time. IntAct lists a cross-linking record (PMID 17470632) [DB:IntAct]. No cell-based functional test in our evidence.","key_references":[{"PMID":"29180757","why":"SPR kinetics of VEGF-A:PDGFR-beta, KD = 340 pM"}],"covers":["LR003444","LR006645"]},"LR001545":{"pair":"VEGFB -> NRP1","headline":"VEGF-B167 and VEGF-B186 bind NRP1 in one abstract-level study, with UniProt and a PDB structure supporting.","interaction_type":"direct binding","direction_and_effect":"Both VEGF-B splice isoforms bind specifically to NRP1; binding was competed by excess VEGF165 [PMID:10409677]. Agonist/antagonist effect not reported in our evidence.","molecular_requirements":"VEGF-B167 binding is mediated by its heparin-binding domain; VEGF-B186 binds NRP1 only after proteolytic processing exposes a short C-terminal proline-rich peptide [PMID:10409677].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; abstract-only reading [PMID:10409677]. Both interactions listed are ortholog-inferred, so the human pair itself was projected rather than separately tested.","localisation_and_range":"VEGFB flagged secreted; NRP1 flagged both secreted and transmembrane [flag].","caveats":"Single paper read as an abstract; no affinity reported. UniProt lists VEGFB among NRP1 binding partners [DB:UniProt] and BioGRID lists a reconstituted complex [DB:BioGRID]. A PDB entry exists [DB:PDB 6TKK]. NRP1 lacks intrinsic kinase signalling in our evidence, so co-receptor role is not established here.","key_references":[{"PMID":"10409677","why":"VEGF-B isoform binding to NRP1"}],"covers":["LR001545","LR004934"]},"LR001554":{"pair":"VIP -> SCTR","headline":"No curator-verified paper supports this pair; it rests on a single GtoPdb record.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists VIP at SCTR as agonist, action partial agonist [DB:GtoPdb VIP-SCTR].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human and mouse pairs are both ortholog-inferred.","localisation_and_range":"VIP is flagged secreted and SCTR transmembrane [flag].","caveats":"No papers were judged confirmed: seven were abstract_insufficient and two concerned a different entity. The GtoPdb record cites PMID:1646711 with pIC50 units, but the value is not shown in our evidence [DB:GtoPdb].","key_references":[],"covers":["LR001554","LR004943"]},"LR007080":{"pair":"VTN -> ITGA2B:ITGB3","headline":"No paper supports this complex pair; it rests on database records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. Databases record physical association or binding: BioGRID lists a reconstituted complex for VTN-ITGA2B [DB:BioGRID], IntAct lists a solid phase assay [DB:IntAct], and Reactome lists vitronectin binding alphaV integrins [DB:Reactome].","molecular_requirements":"The receptor is a two-chain complex (ITGA2B and ITGB3) [flag]. Whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence beyond the human entity labels.","localisation_and_range":"Vitronectin is flagged as secreted [flag]; the complex is flagged transmembrane [flag].","caveats":"No curator-verified papers: of the papers judged, 3 were a different entity, 1 abstract was insufficient and 1 was review only. The Reactome examples shown name alphaVbeta3, alphaVbeta5 and alphaVbeta8, not alphaIIbbeta3 [DB:Reactome].","key_references":[],"covers":["LR007080"]},"LR001563":{"pair":"VTN -> ITGB5","headline":"AlphaVbeta5 is a vitronectin-selective integrin in purified and hESC systems; three abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Purified placental alphaVbeta5 bound preferentially to vitronectin, unlike alphaVbeta3 [PMID:1694173]. In FG-2 lysates alphaVbeta5 bound exclusively to vitronectin and was eluted by RGD peptide [PMID:1532572]. In hESCs, blocking antibodies showed alphaVbeta5 mediates adhesion to vitronectin [PMID:18599809].","molecular_requirements":"ITGB5 acts with the alphaV chain as alphaVbeta5 [PMID:1694173].","affinity_potency":[],"species_and_systems":"Human purified protein, cell lysates and hESCs [PMID:1694173] [PMID:1532572] [PMID:18599809]. Mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Chain-only entry; all three papers abstract only. No affinity reported. One further paper was review only. Reactome also asserts the pair [DB:Reactome].","key_references":[{"PMID":"1694173","why":"Purification of alphaVbeta5 as a vitronectin receptor"},{"PMID":"1532572","why":"alphaVbeta5 binds vitronectin exclusively in FG-2 lysates"},{"PMID":"18599809","why":"alphaVbeta5 mediates hESC adhesion to vitronectin"}],"covers":["LR001563","LR004952"]},"LR003453":{"pair":"VWF -> ITGA9","headline":"The VWF propolypeptide promotes alpha9beta1-mediated cell adhesion; one paper, functional only.","interaction_type":"functional only","direction_and_effect":"pp-vWF promoted adhesion of G-361 cells via alpha9beta1; SW480 cells transfected with alpha9beta1, but not mock transfectants, adhered to pp-vWF and T2-15/BSA [PMID:10816592].","molecular_requirements":"alpha9beta1 is the integrin; the binding site is a 15 residue segment, T2-15, shared with alpha4beta1 [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human cells (G-361, SW480 transfectants) [PMID:10816592]. Mouse and human pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only read. The ligand is the propolypeptide cleaved from the VWF precursor, not mature VWF. Cell adhesion only, no affinity.","key_references":[{"PMID":"10816592","why":"pp-vWF is a ligand for alpha9beta1"}],"covers":["LR003453","LR006653"]},"LR003462":{"pair":"WFIKKN2 -> PRTG","headline":"WFIKKN2 binds PRTG (protogenin) by SPR and is named as an axon-guidance ligand for it; binding evidence is full text, function is abstract only.","interaction_type":"direct binding","direction_and_effect":"WFIKKN2 ECD-Fc with PRTG analyte-Fc was observed in the apECIA screen and SPR-validated [PMID:32822567]. A preprint names Prtg among the DCC-family receptors for WFIKKN2; its Prtg-specific function is not delineated in the abstract [PMID:37398498].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human ECD-Fc proteins by SPR and apECIA [PMID:32822567]; mouse axon work from abstract [PMID:37398498].","localisation_and_range":"WFIKKN2 is flagged secreted [flag]; PRTG is flagged as a receptor [flag].","caveats":"The SPR legend notes PRTG:WFIKKN2 was run at 512 nM because of incomplete chip regeneration at higher concentrations [PMID:32822567]. No affinity value is reported in our evidence. The preprint was read as abstract only [PMID:37398498].","key_references":[{"PMID":"32822567","why":"SPR-validated WFIKKN2-PRTG binding"},{"PMID":"37398498","why":"WFIKKN2 as ligand for Punc/Nope/Prtg (abstract only)"}],"covers":["LR003462","LR006662"]},"LR001572":{"pair":"WNT1 -> FZD1","headline":"WNT1 acts through FZD1 in mouse-neuron functional work (abstract only); UniProt supports the pairing.","interaction_type":"functional only","direction_and_effect":"Exogenous Wnt1 was neuroprotective for dopaminergic neurons, and silencing Fzd-1 or beta-catenin in neurons counteracted astrocyte-induced neuroprotection, supporting a Wnt1/Fzd-1/beta-catenin loop [PMID:21752258]. UniProt states FZD1 is activated by WNT3A, WNT3, WNT1 and less by WNT2 [DB:UniProt].","molecular_requirements":"Beta-catenin dependence is shown functionally [PMID:21752258]. Co-receptor requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse midbrain dopaminergic neuron and astrocyte cultures plus mouse in vivo experiments; the human pair is listed with an ortholog-inferred human interaction [PMID:21752258].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence. The paper describes an astrocyte-to-neuron paracrine loop [PMID:21752258].","caveats":"No binding assay. Paper read as abstract only; Reactome lists WNT:FZD complex records with 13 entries [DB:Reactome]. The human interaction is ortholog-inferred.","key_references":[{"PMID":"21752258","why":"Wnt1/Fzd-1/beta-catenin loop in dopaminergic neuron survival"}],"covers":["LR001572","LR004961"]},"LR011238":{"pair":"WNT1 -> FZD6:LRP5","headline":"WNT1 to FZD6:LRP5 has no verified evidence; only a UniProt note on LRP5.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt notes an LRP5 interaction enhanced by WNT1 or WNT3A [DB:UniProt]; FZD6 is not mentioned.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"No verified paper; four rows were abstract_insufficient and one review_only.","key_references":[],"covers":["LR011238"]},"LR005361":{"pair":"WNT10A -> FZD5","headline":"WNT10A signals through FZD5 in a human reporter-cell knockout panel; functional, not binding.","interaction_type":"functional only","direction_and_effect":"Wnt10a, with Wnt1, Wnt8a, Wnt7b and Wnt8b, induced signalling via FZD5 and FZD8 in an FZD knockout panel [PMID:28733458].","molecular_requirements":"FZD8 was also responsive; co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells, full text [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Functional inference only; binding is not shown.","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR002035","LR005361"]},"LR011247":{"pair":"WNT10B -> FZD10:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR011247"]},"LR001581":{"pair":"WNT2 -> FZD5","headline":"Mouse Fzd5 synergises with Wnt2 in Xenopus axis assays; a functional readout only.","interaction_type":"functional only","direction_and_effect":"Fzd5 specifically synergised with Wnt2, Wnt5a and Wnt10b in ectopic axis induction in Xenopus embryos [PMID:11092808].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse Fzd5 and Wnt2 expressed in Xenopus embryos, abstract only [PMID:11092808]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"No binding assay. The authors name Wnt5a and Wnt10b, not Wnt2, as likely physiological yolk sac ligands [PMID:11092808]. One abstract_insufficient and one review-only row. No affinity.","key_references":[{"PMID":"11092808","why":"Fzd5 synergy with Wnt2 in Xenopus axis induction"}],"covers":["LR001581","LR004970"]},"LR003480":{"pair":"WNT2B -> FZD5","headline":"Direct pull-down: Wnt2b-Fc pulled down Fzd5-CRD (and Fzd4-CRD) in a browser-read full text.","interaction_type":"direct binding","direction_and_effect":"Wnt2b-Fc pulled down Flag-tagged Fzd4-CRD and Fzd5-CRD, and also LRP5 extracellular domain [PMID:21856951].","molecular_requirements":"Cysteine-rich domain of Fzd5 was enough for pull-down; LRP5 extracellular domain also bound Wnt2b-Fc [PMID:21856951].","affinity_potency":[],"species_and_systems":"Recombinant tagged proteins; species not stated in the excerpt [PMID:21856951]. UniProt also notes FZD5 interacts with WNT2B [DB:UniProt].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Quote is browser-read and marked unverified in the curation notes. The paper is mainly about Fzd4 [PMID:21856951]. Mouse and human pairs are ortholog-inferred.","key_references":[{"PMID":"21856951","why":"Wnt2b-Fc pulls down Fzd5-CRD"}],"covers":["LR003480","LR006680"]},"LR010806":{"pair":"WNT2B -> FZD5:LRP6","headline":"No paper evidence; UniProt notes FZD5 interacts with WNT2B.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that FZD5 interacts with WNT2B [DB:UniProt].","molecular_requirements":"Nothing reported on LRP6 or the complex in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated [DB:UniProt].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Database assertion only, with no verified paper; it supports the FZD5 subunit, not the LRP6 complex [DB:UniProt].","key_references":[],"covers":["LR010806"]},"LR008034":{"pair":"WNT3 -> FZD1:LRP6","headline":"Functional Wnt3-FZD1 signalling in HEK293T is supported, but nothing in our evidence tests the FZD1:LRP6 complex itself.","interaction_type":"functional only","direction_and_effect":"The single curated paper reports that FZD1, FZD2 and FZD7 \"specifically induce signaling after binding of Wnt3 and Wnt3a\" [PMID:28733458]; this is a statement in the Discussion, and the paper's tested readout was TCF4/Wnt reporter signalling.","molecular_requirements":"FZD1 is the evidence-bearing subunit; the paper's excerpts do not test LRP6 as a partner, so whether the full complex or FZD1 alone is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; HEK293T cells with CRISPR FZD mutations [PMID:28733458].","localisation_and_range":"WNT3 carries a secreted annotation flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Complex-level support is inferred from a single-chain Frizzled result; the paper is a functional map, not a binding study. A database record exists (IntAct, surface plasmon resonance, accession pair O75581-P56703) [DB:IntAct], but it does not name the Frizzled member. UniProt notes a Frizzled entry (Q9UP38) activated by WNT3A, WNT3, WNT1 and less by WNT2 [DB:UniProt].","key_references":[{"PMID":"28733458","why":"Functional Wnt-FZD map in FZD-mutant HEK293T cells"}],"covers":["LR008034"]},"LR010851":{"pair":"WNT3 -> FZD6:LRP6","headline":"No curated paper supports WNT3 -> FZD6:LRP6; the only record is a database interaction entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the complex name.","affinity_potency":[],"species_and_systems":"Species of the database experiment not reported in our evidence; the pair is annotated human.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"No paper was confirmed for this pair (outcomes: review_only, abstract_insufficient, different_entity). The one IntAct record is a surface plasmon resonance entry for accession pair O75581-P56703 [DB:IntAct] and does not identify the Frizzled member [PMID:31036956].","key_references":[],"covers":["LR010851"]},"LR005370":{"pair":"WNT3A -> FZD10","headline":"FZD10 interacts with WNT3A by proximity ligation and mediates WNT3A signalling when LRP6 is present.","interaction_type":"direct binding","direction_and_effect":"In the presence of LRP6, FZD10 promoted WNT3A signalling in an 8xSuperTopFlash assay [PMID:24599775]. Without LRP6, FZD10 co-expression inhibited WNT3A signalling [PMID:24599775]. A CRISPR rescue map reports Wnt3/Wnt3a signalling via all FZDs [PMID:28733458].","molecular_requirements":"LRP6 co-expression was needed to turn FZD10 into a signal-promoting receptor; PLA signal for WNT3A-FZD10 occurred with or without exogenous LRP6, with slightly fewer punctae without it [PMID:24599775].","affinity_potency":[],"species_and_systems":"In situ proximity ligation in transfected COS7 cells, reporter assay in HEK293T cells and chick embryo spinal cord expression [PMID:24599775]; HEK293T FZD1/2/7 mutant rescue [PMID:28733458]. Curators label the constructs human.","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"Proximity ligation shows closeness within 40 nm, not direct binding or affinity. Overexpressed FZD10 alone suppressed signalling. The second paper's sentence is generic across FZDs [PMID:28733458]. Mouse interaction is ortholog-inferred.","key_references":[{"PMID":"24599775","why":"PLA interaction and LRP6-dependent WNT3A signalling via FZD10"},{"PMID":"28733458","why":"functional FZD-Wnt rescue map"}],"covers":["LR002044","LR005370"]},"LR001590":{"pair":"WNT3A -> FZD8","headline":"WNT3A binds FZD8 directly in several purified and cell-based binding studies.","interaction_type":"direct binding","direction_and_effect":"Purified mouse Fz8 CRD and human LRP6 ectodomain inhibited Wnt/beta-catenin signaling, and the Fz8 CRD.Wnt3a.LRP6 complex was reconstituted in vitro [PMID:20093360]. WNT-3A showed strong binding (++++, KD < 10 nm) to FZD4/5/7/8 CRDs [PMID:25605717]. WNT3A bound sFZD8-Fc [PMID:30304675].","molecular_requirements":"Wnt3a binds a region of LRP6 comprising the third and fourth beta-propeller domains, and a Fz8 CRD.Wnt3a.LRP6 complex forms [PMID:20093360]. Whether FZD8 alone suffices is not reported in our evidence.","affinity_potency":[{"value":"KD < 10 nm","assay":"Bio-layer interferometry, purified WNT-3A on FZD CRD-Fc, FZD4/5/7/8 grouped","system":"purified proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse Fz8 CRD with human LRP6 [PMID:20093360]; mouse per curation [PMID:25605717]; human, HEK293 cells [PMID:30304675]. Human and mouse versions are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"PMID:20093360 was read as abstract only and affinity values are not in our excerpt. The PMID:25605717 quote is flagged as browser-read, unverifiable. The KD bound covers several FZDs. In PMID:30304675 FZD8 binding was a positive control.","key_references":[{"PMID":"20093360","why":"Reconstituted Fz8 CRD.Wnt3a.LRP6 complex from purified proteins"},{"PMID":"25605717","why":"Bio-layer interferometry of WNT-3A and FZD CRDs"},{"PMID":"30304675","why":"WNT3A bound sFZD8-Fc in HEK293 cell studies"}],"covers":["LR001590","LR004979"]},"LR006702":{"pair":"WNT4 -> LRP5","headline":"One co-IP result in mouse cells shows a Wnt4-LRP5 complex; other papers were abstract-insufficient.","interaction_type":"direct binding","direction_and_effect":"Co-IP revealed a Wnt4-LRP5 binding complex [PMID:31216173].","molecular_requirements":"Wnt4-Fzd1/Fzd2/Fzd6 complexes and LRP-Fzd complexes were also found, so a Frizzled may bridge the interaction [PMID:31216173].","affinity_potency":[],"species_and_systems":"Co-IP in MC3T3 (mouse) cells, per curator note [PMID:31216173]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and LRP5 flagged transmembrane [flag].","caveats":"Single browser-read result, not spot-checked; co-IP does not show direct binding. No affinity in our evidence.","key_references":[{"PMID":"31216173","why":"co-IP of Wnt4 with LRP in MC3T3 cells"}],"covers":["LR003502","LR006702"]},"LR001608":{"pair":"WNT5A -> LRP5","headline":"Functional support that LRP5 acts as a co-receptor with a Frizzled for WNT5A activation of beta-catenin signalling; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"With mFz4, LRP5 coexpression lets Wnt5a protein activate the STF luciferase reporter in 293Fz4 cells; without LRP5 it does not [PMID:16602827]. In human endometrial stem-like cells, DKK1 reduced WNT5A binding and the WNT5A-induced increase in active beta-catenin [PMID:35295855].","molecular_requirements":"Requires a Frizzled partner: Fz4 [PMID:16602827] or FZD5 [PMID:35295855]. LRP6 did not substitute in 293Fz4 cells [PMID:16602827].","affinity_potency":[],"species_and_systems":"293 and 293Fz4 cells with mouse Fz4 [PMID:16602827]; human endometrial mesenchymal stem-like cells, plus mouse endometrial staining [PMID:35295855].","localisation_and_range":"Ligand flagged secreted, LRP5 transmembrane [flag].","caveats":"No direct binding assay. DKK1 inhibits LRP5 and LRP6, so specificity to LRP5 is indirect [PMID:35295855]. LRP6 data in 293Fz4 cells are 'unpublished data' in the paper [PMID:16602827]. The same paper shows Wnt5a inhibiting canonical signalling in other receptor contexts.","key_references":[{"PMID":"16602827","why":"Wnt5a activates TCF signalling with Fz4 plus LRP5"},{"PMID":"35295855","why":"WNT5A with FZD5 and LRP5 in endometrial stem-like cells"}],"covers":["LR001608","LR004997"]},"LR003507":{"pair":"WNT5A -> PTK7","headline":"WNT5A co-immunoprecipitates with PTK7 in human cells and PTK7 is needed for Wnt5a signalling in Xenopus; PTK7 also associates with ROR2.","interaction_type":"direct binding","direction_and_effect":"PTK7 and ROR2 physically and functionally interact with WNT5A, leading to JNK activation and cell movements; Ptk7 is required for Wnt5a-induced papc activation in Xenopus [PMID:26499793]. Curated agonist.","molecular_requirements":"The entire PTK7 extracellular region is required for WNT5A interaction; loops 4-7 are needed for optimal binding. WNT5A binding persisted after ROR2 depletion, so it is not mediated by ROR2 [PMID:26499793].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in HEK 293T cells, MEFs and Xenopus embryos [PMID:26499793].","localisation_and_range":"PTK7 is flagged secreted [flag], but the paper treats it as a membrane receptor with an intracellular domain released after Wnt5a stimulation [PMID:26499793].","caveats":"Co-immunoprecipitation of overexpressed tagged proteins; no affinity measured. Does not distinguish direct binding fully, though ROR2 depletion did not impair it.","key_references":[{"PMID":"26499793","why":"WNT5A-PTK7 co-IP and PCP signalling in Xenopus"}],"covers":["LR003507","LR006707"]},"LR006711":{"pair":"WNT5A -> VANGL2","headline":"Wnt5a induces a Ror2-VANGL2 complex and VANGL2 phosphorylation in mouse; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Agonist: Wnt ligands including Wnt5a strongly induced Ror2-Vangl2 complex formation and dose-dependent Vangl2 phosphorylation [PMID:21316585]. Reactome lists a WNT5A:ROR2:VANGL2 plasma-membrane complex [DB:Reactome R-HSA-4551543].","molecular_requirements":"VANGL2 acts together with ROR2; Ror2 and Vangl2 double knockouts resemble Wnt5a knockouts [PMID:21316585]. VANGL2 alone as a binder is not shown.","affinity_potency":[],"species_and_systems":"Mouse embryos, limb bud, mouse embryonic fibroblasts [PMID:21316585]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Direct Wnt5a-Vangl2 binding is not shown; VANGL2 works as part of a Wnt5a-ROR2 complex [PMID:21316585]. Curated from the abstract; excerpts available. Ror family members mediate only part of Wnt5a signalling in vivo [PMID:21316585].","key_references":[{"PMID":"21316585","why":"Wnt-induced Ror2-Vangl2 complex and Vangl2 phosphorylation"}],"covers":["LR003511","LR006711"]},"LR008160":{"pair":"WNT5B -> FZD6:LRP5","headline":"Only a FZD6 docking study exists; LRP5 is not addressed.","interaction_type":"computational prediction only","direction_and_effect":"Direction not reported; in silico docking of hWnt5b to hFzd isoforms only [PMID:31285641].","molecular_requirements":"The abstract mentions FZD CRD docking, not LRP5; complex requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human homology models, docking only [PMID:31285641].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Computational and abstract only; evidence concerns FZD6 alone. Others were review-only or insufficient.","key_references":[{"PMID":"31285641","why":"docking of hWnt5b against hFzd isoforms"}],"covers":["LR008160"]},"LR003516":{"pair":"WNT5B -> ROR2","headline":"Wnt5b is stated to bind Ror2 in zebrafish; the paper shows cytoneme transfer of Wnt5b-Ror2 complexes.","interaction_type":"functional only","direction_and_effect":"Agonist: Wnt5b with Ror2 triggers Wnt-PCP signalling; active Wnt5b-Ror2 complexes form in the producing cell and are handed over via cytonemes [PMID:38123680].","molecular_requirements":"Receiving cells can start PCP signalling irrespective of their own Ror2 status [PMID:38123680].","affinity_potency":[],"species_and_systems":"Zebrafish embryo [PMID:38123680]; the human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only. Transfer along cytonemes is paracrine contact-based [PMID:38123680].","caveats":"Direct binding is cited as background, not shown in this abstract. Abstract-only reading [PMID:38123680].","key_references":[{"PMID":"38123680","why":"cytoneme transfer of Wnt5b-Ror2 complexes in zebrafish"}],"covers":["LR003516","LR006716"]},"LR008016":{"pair":"WNT7A -> ADGRA2:FZD5:LRP6:RECK","headline":"Only the RECK-WNT7 half of this four-chain complex is supported, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Gpr124 and Reck enable brain endothelial cells to respond selectively to Wnt7, an agonist effect [PMID:30026314]. Reck-bound Wnt7 is made available to Frizzled signalling via Gpr124-Dishevelled, which recruits Wnt7 into Wnt/Frizzled/Lrp5/6 signalosomes [PMID:30026314].","molecular_requirements":"Complex-level: the abstract-only paper shows Reck binds the Wnt7 linker region and Gpr124 plus Reck confer Wnt7 selectivity; FZD5 and the LRP6 co-receptor are not named in the abstract [PMID:30026314]. PDB 8TZP holds a structure with chains of O00755 and O95980 [DB:PDB 8TZP].","affinity_potency":[{"value":"low micromolar","assay":"Reck binding to the Wnt7 linker region (abstract)","system":"brain endothelial cells","cite":"PMID:30026314"}],"species_and_systems":"Human proteins and brain endothelial cells per the curator row [PMID:30026314].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; ADGRA2 and LRP6 are flagged transmembrane [flag]; signalling is cell-surface.","caveats":"Abstract only. FZD5 and LRP6 are not shown as bound; UniProt notes ADGRA2 interacts with FZD5-related partners and RECK selectivity for Wnt7 [DB:UniProt]. A complex needs all four chains to be expressed.","key_references":[{"PMID":"30026314","why":"Reck binds Wnt7 with low micromolar affinity; Gpr124:Reck decode Wnt7"}],"covers":["LR008016"]},"LR002049":{"pair":"WNT7A -> FZD1","headline":"No paper evidence; UniProt states FZD1 is apparently not activated by WNT7A.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper confirms this pair. UniProt says FZD1 is activated by WNT3A, WNT3, WNT1 and less by WNT2, but apparently not by WNT4, WNT5A, WNT5B, WNT6, WNT7A or WNT7B [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; FZD1 is flagged as a receptor [flag].","caveats":"The only record argues against the pair. Eight abstracts were judged insufficient or about a different entity, so no positive evidence exists in our dossier. Treat as unsupported.","key_references":[],"covers":["LR002049","LR005375"]},"LR008043":{"pair":"WNT7A -> FZD10:LRP6","headline":"Complex rests on a Wnt7a-Fzd10 co-IP; the LRP6 chain is not tested in the paper.","interaction_type":"direct binding","direction_and_effect":"Wnt7a coimmunoprecipitates with Fzd10 in Ishikawa cells [PMID:18567805]; Fzd10-mediated Wnt7a signalling was noncanonical and JNK-responsive [PMID:18567805].","molecular_requirements":"LRP6 is not mentioned in the evidence shown; the complex is inferred from the FZD10 result.","affinity_potency":[],"species_and_systems":"Human Ishikawa cells [PMID:18567805].","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP6 is flagged transmembrane [flag].","caveats":"Abstract only; evidence concerns FZD10 alone, so it is chain-only support for this complex.","key_references":[{"PMID":"18567805","why":"Wnt7a co-IPs with Fzd10 in Ishikawa cells"}],"covers":["LR008043"]},"LR006720":{"pair":"WNT7A -> FZD4","headline":"Weak: WNT7A bound FZD4 only at trace level in one paper; a second shows functional G-protein dissociation.","interaction_type":"conflicting","direction_and_effect":"In a full-text paper, full-length cell-surface FZD4 and recombinant sFZD4-Fc did not detectably bind WNT7A and only trace binding was seen with sFZD4-His; STF activity with Lrp5 was modestly increased by Fzd4, suggesting low-affinity binding [PMID:30304675]. WNT-7A stimulation dissociated a FZD4-Galpha12/13 complex, an agonist effect [PMID:27458145].","molecular_requirements":"FZD4 co-expressed with Galpha12/13 for the G-protein readout; FZD8 bound WNT7A far better in the first paper [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins; HEK293 cells in both papers [PMID:30304675][PMID:27458145]; the mouse pair is projected from human evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; signalling at the cell surface.","caveats":"The binding paper is largely negative for FZD4. The second paper is abstract only and functional.","key_references":[{"PMID":"27458145","why":"WNT-7A dissociates FZD4-Galpha12/13 complex"},{"PMID":"30304675","why":"FZD4 binds WNT7A only weakly"}],"covers":["LR003520","LR006720"]},"LR003525":{"pair":"WNT7A -> RECK","headline":"WNT7A binds RECK directly; the best-supported pair here, with a structure and UniProt support.","interaction_type":"direct binding","direction_and_effect":"WNT7A directly binds purified soluble RECK and cell-surface RECK; RECK is described as a selective WNT7 receptor that stabilises active WNT7A, supporting GPR124/FZD/LRP-dependent canonical signalling [PMID:30304675]. A PDB structure has WNT7A and RECK chains [DB:PDB 8TZP]. UniProt records RECK conferring Wnt7 selectivity in brain endothelial cells [DB:UniProt].","molecular_requirements":"RECK and WNT7A associate with 1:1 stoichiometry [PMID:30304675]. WNT7A signalling also needs GPR124, FZD and LRP co-receptors; WNT3A does not bind RECK [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins, HEK293 cells; RECK also tested in rat brain vessels [PMID:30304675]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. RECK is a GPI-anchored protein per the abstract [PMID:30304675].","caveats":"Curated row read from abstract only, though the same paper is full-text verified for other pairs. No affinity reported in our evidence.","key_references":[{"PMID":"30304675","why":"Direct WNT7A-RECK binding, 1:1 stoichiometry"}],"covers":["LR003525","LR006725"]},"LR001617":{"pair":"WNT7B -> FZD1","headline":"WNT7B binds FZD1 on the cell surface in an abstract-level study, but UniProt says FZD1 is apparently not activated by WNT7B.","interaction_type":"conflicting","direction_and_effect":"Wnt7b bound Fzd1 on the cell surface and cooperatively activated canonical Wnt signalling with it when LRP5 was present [PMID:15923619]. UniProt for FZD1 says it is apparently not activated by WNT7A or WNT7B [DB:UniProt].","molecular_requirements":"LRP5 co-expression is needed for cooperative canonical activation [PMID:15923619].","affinity_potency":[],"species_and_systems":"Human per curator fields, cell transfection; mouse pair is listed as not ortholog-inferred [PMID:15923619].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Conflicting UniProt statement on activation [DB:UniProt]. Fzd1 is mostly in lung mesenchyme, unlike Fzd10 in epithelium [PMID:15923619].","key_references":[{"PMID":"15923619","why":"Wnt7b binds Fzd1 and Fzd10 on the cell surface"}],"covers":["LR001617","LR005006"]},"LR008124":{"pair":"WNT7B -> FZD10:LRP5","headline":"WNT7B with FZD10 and LRP5 has only UniProt subunit annotations; no paper confirms it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt notes FZD10-related interaction text and an LRP5-side interaction with WNT7B by similarity [DB:UniProt].","molecular_requirements":"Complex subunits FZD10 and LRP5 are asserted together; no paper in our evidence supports the combination.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"No confirmed papers; one review-only and one abstract-insufficient. Support is database annotation, partly by similarity [DB:UniProt].","key_references":[],"covers":["LR008124"]},"LR008070":{"pair":"WNT7B -> FZD5:LRP6","headline":"WNT7B-FZD5:LRP6 rests on an ovarian cancer abstract naming only WNT7B/FZD5.","interaction_type":"functional only","direction_and_effect":"The WNT7B/FZD5 pair positively modulated an LGR4-ELF3 regulatory loop in high-grade serous ovarian cancer cells [PMID:32980127].","molecular_requirements":"LRP6 is not named in the evidence.","affinity_potency":[],"species_and_systems":"HGSOC cells; species not stated [PMID:32980127].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only; functional context, not binding. Co-receptor is unsupported.","key_references":[{"PMID":"32980127","why":"WNT7B/FZD5 pair modulates LGR4-ELF3 loop"}],"covers":["LR008070"]},"LR008151":{"pair":"WNT8A -> FZD5:LRP5","headline":"WNT8A signalling via FZD5:LRP5 supported by one functional paper; LRP5 co-receptor is not tested.","interaction_type":"functional only","direction_and_effect":"Wnt8a induced signalling via FZD5 and FZD8 in reporter cells [PMID:28733458].","molecular_requirements":"Evidence concerns the Frizzled chain only; LRP5 involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293-type reporter cells with FZD knockouts [PMID:28733458]; species not stated in this record.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"The complex pair rests on a FZD-only result, so it is chain-only evidence; other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map"}],"covers":["LR008151"]},"LR008061":{"pair":"WNT9A -> FZD4:LRP6","headline":"WNT9A signals through FZD4 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD4 plus LRP6; the paper's statement names only the Frizzled, and a requirement for LRP6 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008061"]},"LR003543":{"pair":"WNT9A -> LRP6","headline":"WNT9A signalling through LRP6 supported by antibody-blocking data in a reporter assay; one paper.","interaction_type":"functional only","direction_and_effect":"Wnt1-class anti-LRP6 Fab fragments (A1-Fab, A2-Fab) inhibited Wnt9a signalling, so LRP6 acts as a co-receptor for Wnt9a; antibodies act as antagonists of the interaction [PMID:20713706].","molecular_requirements":"Antibodies binding LRP6 propeller 1 block Wnt9a, placing its requirement at the first propeller region; Wnt9a is grouped in the Wnt1 class [PMID:20713706].","affinity_potency":[],"species_and_systems":"SuperTopFlash reporter in HEK293 cells; human ligand and receptor [PMID:20713706]; mouse version is projected from human evidence.","localisation_and_range":"WNT9A/WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor chains are membrane receptors [flag].","caveats":"Inference is indirect (antibody blockade); no direct binding or affinity of Wnt9a to LRP6 is reported. Curator read the full text in a browser, but the dossier shows abstract only and the quote is flagged as unverifiable and awaiting spot-check.","key_references":[{"PMID":"20713706","why":"Wnt1-class anti-LRP6 Fabs inhibit Wnt9a signalling"}],"covers":["LR003543","LR006743"]},"LR002058":{"pair":"WNT9B -> FZD10","headline":"WNT9B activates canonical signalling through FZD10 in a human reporter-cell rescue map; one functional study.","interaction_type":"functional only","direction_and_effect":"Wnt9b induced canonical signalling with FZD4 and FZD10 as well as FZD5 and FZD8; effect is activating [PMID:28733458].","molecular_requirements":"FZD10 was tested as a single receptor in rescue; FZD4 and FZD10 cluster together by signalling profile; co-receptor not reported in the evidence for this pair [PMID:28733458].","affinity_potency":[],"species_and_systems":"HEK293 Wnt reporter cells (human; TCF4 luciferase) with FZD knockout and rescue [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Functional reporter only; no binding data. Reads as 'induced signalling with' rather than demonstrated direct binding.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR002058","LR005384"]},"LR010743":{"pair":"WNT9B -> FZD3:LRP6","headline":"Database-asserted WNT9B to FZD3:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD3 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR010743"]},"LR010707":{"pair":"WNT9B -> FZD6:LRP6","headline":"Database-asserted WNT9B to FZD6:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD6 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR010707"]},"LR010860":{"pair":"WNT9B -> FZD7:LRP6","headline":"Database-asserted WNT9B to FZD7:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD7 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR010860"]},"LR001626":{"pair":"ZG16B -> TLR6","headline":"Co-immunoprecipitation only: PAUF associated with TLR6 in HEK293T cells; no functional or affinity data.","interaction_type":"direct binding","direction_and_effect":"PAUF associated with TLR2, 5 and 6 but not TLR3, 8, 9 or 10 in co-immunoprecipitation, indicating binding to a subset of TLR family proteins [PMID:20802527]. Effect on TLR6 signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins overexpressed in HEK293T cells; the data are in a supplementary figure [PMID:20802527].","localisation_and_range":"ZG16B (PAUF) is flagged secreted [flag] and the paper treats it as a soluble ligand acting on cell-surface receptors [PMID:20802527].","caveats":"Co-immunoprecipitation does not show whether binding is direct or via TLR2, which PAUF binds directly. Supplementary data only; no replicate or affinity details in our evidence.","key_references":[{"PMID":"20802527","why":"PAUF co-immunoprecipitates with TLR2, 5 and 6"}],"covers":["LR001626"]},"LR012381":{"pair":"ZNRF3 -> FZD5:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; FZD5 - ZNRF3: Proximity Label-MS; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD5 partner is named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012381"]},"LR004713":{"pair":"RSPO3 -> LGR4","headline":"R-spondins, including RSPO3, bind LGR4 and potentiate Wnt signalling; well supported, though papers are read as abstracts and are family-level.","interaction_type":"direct binding","direction_and_effect":"Agonist: LGR4 and LGR5 bind R-spondins with high affinity and mediate potentiation of Wnt/beta-catenin signalling by enhancing Wnt-induced LRP6 phosphorylation [PMID:21693646]. R-spondins bind LGR4 and LGR5 by their Furin domains [PMID:21909076].","molecular_requirements":"LGR4 associates with the Frizzled/Lrp Wnt receptor complex [PMID:21727895]. Neither receptor couples to heterotrimeric G proteins or beta-arrestin when stimulated [PMID:21693646]. RSPO2 can also act through RNF43 and ZNRF3 independently of LGR4/5/6 [PMID:29769720].","affinity_potency":[],"species_and_systems":"Human and mouse pairs, neither ortholog-inferred. Mammalian cells and Xenopus embryos [PMID:21909076]; mouse gut deletion [PMID:21727895]. Species in the binding assays are partly unspecified.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"The papers address R-spondins as a family and not RSPO3 by name in the abstracts. All were read as abstracts only. Curator notes say the relationship is a modulator of Wnt, not an independent signalling axis [PMID:21693646]. Databases also list the pair [DB:GtoPdb][DB:BioGRID].","key_references":[{"PMID":"21693646","why":"R-spondins as ligands of LGR4 and LGR5"},{"PMID":"21909076","why":"R-spondin Furin domains bind LGR4/5"},{"PMID":"21727895","why":"Lgr4/5 associate with Frizzled/Lrp and mediate R-spondin signalling"}],"covers":["LR001316","LR004713"]},"LR000780":{"pair":"IAPP -> RAMP1","headline":"Amylin acts as an agonist at RAMP1-containing amylin receptors; supported by two abstract-read papers plus databases.","interaction_type":"direct binding","direction_and_effect":"Rat amylin binding was induced by cotransfecting RAMP1 with the human calcitonin receptor in COS-7 cells [PMID:10385705]. Human and rat amylin activate the calcitonin receptor alone and the AMY complexes, measured by cAMP [PMID:24169554]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"RAMP1 does not act alone: it pairs with the calcitonin receptor (CALCR) to form the AMY1 complex [PMID:10385705][PMID:24169554][DB:UniProt]. A CCC score should include CALCR.","affinity_potency":[],"species_and_systems":"COS-7 and HEK293S cells; recombinant human calcitonin receptor with rat amylin radioligand [PMID:10385705][PMID:24169554]. Mouse pair is projected from human evidence.","localisation_and_range":"Amylin is annotated as secreted [flag]; RAMP1 is a receptor component [flag].","caveats":"Both papers were read as abstracts only. GtoPdb potency values are database-reported and not quoted here. The binding paper also shows a second paper-level abstract was insufficient. Structures with both chains exist (e.g. PDB 9BLW) [DB:PDB 9BLW].","key_references":[{"PMID":"10385705","why":"RAMP1 or RAMP3 with CT receptor induces amylin binding"},{"PMID":"24169554","why":"Amylin activates calcitonin receptor and AMY1-3 complexes by cAMP"}],"covers":["LR000780","LR004238"]},"LR001194":{"pair":"PDGFA -> PDGFRA","headline":"Well supported direct binding: cloned PDGFRA binds PDGF A-chain dimers with high affinity; database support is extensive.","interaction_type":"direct binding","direction_and_effect":"Stimulatory ligand-receptor pair. The expressed receptor bound 125I-labelled AA, AB and BB PDGF dimers with high affinity [PMID:2544881].","molecular_requirements":"PDGFA acts as a dimer (AA, or AB with B chain). Reactome describes a PDGF:PDGF receptor dimer complex [DB:Reactome]. Whether PDGFRA alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor cDNA expressed in COS cells [PMID:2544881]. Mouse pair is ortholog-inferred.","localisation_and_range":"PDGFA is annotated secreted and PDGFRA transmembrane [flag]; paracrine signalling.","caveats":"Only one paper judged, abstract only; a numerical affinity is not reported in our evidence. BioGRID lists reconstituted complex and affinity capture-MS records [DB:BioGRID]; IntAct lists cross-linking and ELISA [DB:IntAct]. The binding result covers AB and BB dimers too, so is not specific to the A chain.","key_references":[{"PMID":"2544881","why":"Cloning of PDGFRA and radioligand binding of PDGF dimers."}],"covers":["LR001194","LR004603"]},"LR004704":{"pair":"RSPO1 -> LGR4","headline":"Well supported: R-spondin 1 binds LGR4 and potentiates Wnt signalling through the Frizzled/LRP complex, with consistent database records.","interaction_type":"direct binding","direction_and_effect":"RSPOs act as agonist ligands of LGR4/LGR5 and potentiate Wnt/beta-catenin signalling by enhancing Wnt-induced LRP6 phosphorylation [PMID:21693646]. LGR4 removal abrogates RSPO1 enhancement of WNT3A signalling and re-expressing LGR4, -5 or -6 rescues it [PMID:21727895]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 associates with the Frizzled/Lrp Wnt receptor complex by mass spectrometry; it is facultative, not needed for WNT3A signalling alone [PMID:21727895]. Neither receptor couples to G proteins or beta-arrestin [PMID:21693646].","affinity_potency":[{"value":"pEC50 10.699999809265137","assay":"GtoPdb/curated affinity field, Wnt reporter assay","system":"intestinal crypts; Wnt reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human ligand and receptor in HEK293 cells [PMID:21727895]; mouse gut and crypt cultures with Lgr4/5 deletion [PMID:21727895].","localisation_and_range":"RSPO1 is flagged secreted and LGR4 transmembrane [flag], so paracrine action on LGR4-expressing cells.","caveats":"Both papers were read as abstracts. LGR4 acts as a modulator of Wnt signalling rather than an independent axis, so ligand-receptor scoring should consider Frizzled/LRP expression. Many database records (BioGRID, IntAct, Reactome, PDB) agree.","key_references":[{"PMID":"21693646","why":"R-spondins as ligands of LGR4 and LGR5"},{"PMID":"21727895","why":"RSPO1 binds LGR4; LGR4 needed for enhancement"}],"covers":["LR001307","LR004704"]}};